/* Create tables ------------------------------------------------------------ */

/* AccountingDocHeaders */
CREATE TABLE "AccountingDocHeaders"
  STORAGE ENGINE 'Variable'
(
  "IDX" AUTOINC,
  "HeaderText" CLOB,
  "HeaderType" BYTE DESCRIPTION 'TAccountsDocumentHeaderType',

  CONSTRAINT "MainIDX" PRIMARY KEY("IDX")
);

CREATE INDEX "TypeIDX" ON "AccountingDocHeaders"("HeaderType");

/* AccountsIntegration */
CREATE TABLE "AccountsIntegration"
(
  "IDX" AUTOINC,
  "AccountPackageID" BYTE DESCRIPTION ' TAccountsIntegrationType = ({aitNone,} aitSage, aitZapier {, aitQuickBooks, 
aitZero}) - note aitNone retired for 263',
  "AccountPackageName" SHORTSTRING(30),
  "PackageSettings" CLOB DESCRIPTION 'Delphi class that inherits from TAccountIntegrationSettings',
  "xQBEInvoiceExport" INT,
  "xQBEOrdersExport" INT,
  "xQBECustomerExport" INT,
  "xQBECustomerImport" INT,
  "xQBECustomerCompare" INT,
  "xQBECustomerUpdate" INT,
  "IsDefault" BOOLEAN DEFAULT FALSE DESCRIPTION 'Legacy. Superceded by "IntegrationCombinination"',
  "xAccountStatusForOnHold" INT,
  "IntegrationCombinination" BYTE DEFAULT 0 DESCRIPTION 'TAccountsIntegrationCombinination = (aicNone, aicInvoicesOnly, aicOrdersOnly, 
aicInvoicesAndOrders)',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("IDX")
);

/* AccountStatus */
CREATE TABLE "AccountStatus"
  STORAGE ENGINE 'Variable'
(
  "IDX" AUTOINC,
  "StatusName" SHORTSTRING(100),
  "StatusText" CLOB,
  "Colour" INT,
  "Warning" BOOLEAN DEFAULT TRUE,
  "xAccountStatusForOnHold" INT,

  CONSTRAINT "MainIDX" PRIMARY KEY("IDX")
);

CREATE INDEX "byName" ON "AccountStatus"("StatusName");

/* Addons */
CREATE TABLE "Addons"
  STORAGE ENGINE 'Variable'
(
  "IDX" AUTOINC,
  "Module_name" SHORTSTRING(128) DESCRIPTION 'Module_name',
  "Form" VARCHAR(50),

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("IDX")
);

CREATE INDEX "FormIdx" ON "Addons"("Form");

/* AddressLogs */
CREATE TABLE "AddressLogs"
  STORAGE ENGINE 'Variable'
(
  "IDX" AUTOINC,
  "ChangeNarrative" SHORTSTRING(255),
  "ChangedTableName" SHORTSTRING(25),
  "ChangeAction" BYTE NOT NULL DESCRIPTION 'TTableAction = (taInsert, taUpdate, taDelete)',
  "ChangedRecordID" INT,
  "ChangeInfo" CLOB,
  "ChangeDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "LogGroup" BYTE NOT NULL DESCRIPTION 'TAddressLogGroup(alCompany, alPerson, alContacts....)',
  "xUser" INT,
  "ChangeMeaning" BYTE DESCRIPTION ' TAddressLogMeaning = (almCreated, almCompanyNameChanged...)',

  CONSTRAINT "MainIDX" PRIMARY KEY("IDX")
);

CREATE INDEX "SearchIDX" ON "AddressLogs"("ChangedRecordID", "ChangedTableName", "ChangeAction");
CREATE INDEX "DateIDX" ON "AddressLogs"("ChangeDate");

/* ai_inv */
CREATE TABLE "ai_inv"
  STORAGE ENGINE 'Variable'
(
  "Counter" AUTOINC DESCRIPTION 'Counter',
  "Inv_type" BYTE DESCRIPTION 'TAccountsDocument',
  "xInvNo" INT DESCRIPTION 'looks up either Rental or Sales Invoice',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Counter")
);

CREATE INDEX "byxInvNo" ON "ai_inv"("xInvNo", "Inv_type");

/* ai_purc */
CREATE TABLE "ai_purc"
  STORAGE ENGINE 'Variable'
(
  "Counter" AUTOINC DESCRIPTION 'Counter',
  "Inv_type" BYTE DESCRIPTION 'TAccountsDocument',
  "xInvNo" INT,

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Counter")
);

CREATE INDEX "byxInvNo" ON "ai_purc"("xInvNo", "Inv_type");

/* aieqlist */
CREATE TABLE "aieqlist"
  STORAGE ENGINE 'Variable'
(
  "Eql_no" AUTOINC DESCRIPTION 'Eql_no',
  "Jobno" INT DESCRIPTION 'Jobno',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Eql_no")
);

CREATE INDEX "jobidx" ON "aieqlist"("Jobno");

/* AntiFraudActions */
CREATE TABLE "AntiFraudActions"
(
  "IDX" AUTOINC,
  "Description" SHORTSTRING(50) DEFAULT 'Ignore until',
  "Meaning" BYTE DEFAULT 3 DESCRIPTION 'TAntiFraudAction = (aaNotActive, aaCheckingAlwaysActive, aaWarningActive,

aaCheckingLimitedActive, aaNeverActive)',
  "MaxLimit" MONEY,

  CONSTRAINT "$SQL$PRIMARYKEY$INDEX#0" PRIMARY KEY("IDX")
);

CREATE INDEX "UserOrderIdx" ON "AntiFraudActions"("Meaning", "MaxLimit");

/* APIs */
CREATE TABLE "APIs"
(
  "Idx" AUTOINC,
  "API_Name" SHORTSTRING(50),
  "Constants" CLOB,

  CONSTRAINT "$SQL$PRIMARYKEY$INDEX#0" PRIMARY KEY("Idx")
);

CREATE INDEX "Name" ON "APIs"("API_Name");

/* API_Requests */
CREATE TABLE "API_Requests"
(
  "Idx" AUTOINC,
  "xAPIs" INT,
  "RequestName" VARCHAR(50),
  "RequestStructure" CLOB,
  "RequestParams" CLOB,
  "DetailArrayDescriptor" VARCHAR(50),

  CONSTRAINT "$SQL$PRIMARYKEY$INDEX#0" PRIMARY KEY("Idx"),
  CONSTRAINT "FK_API" FOREIGN KEY("xAPIs")
    REFERENCES "APIs"("Idx")
      ON UPDATE RESTRICT ON DELETE RESTRICT
);

CREATE INDEX "Name" ON "API_Requests"("RequestName");

/* API_Responses */
CREATE TABLE "API_Responses"
(
  "Idx" AUTOINC,
  "xAPI_Request" INT,
  "TimeStamp" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "StatusCode" INT,
  "ResponseURL" CLOB,
  "ResponseStats" CLOB,
  "ResponseHeaders" CLOB,
  "ResponseContent" CLOB,

  CONSTRAINT "$SQL$PRIMARYKEY$INDEX#0" PRIMARY KEY("Idx"),
  CONSTRAINT "Fk_Request" FOREIGN KEY("xAPI_Request")
    REFERENCES "API_Requests"("Idx")
      ON UPDATE RESTRICT ON DELETE CASCADE
);


/* BespokeSettings */
CREATE TABLE "BespokeSettings"
  STORAGE ENGINE 'Variable'
(
  "Idx" AUTOINC,
  "Settings" SHORTSTRING(255),
  "Value" SHORTSTRING(255),

  CONSTRAINT "ByIdx" PRIMARY KEY("Idx")
);

CREATE INDEX "BySetting" ON "BespokeSettings"("Settings" IGNORE CASE);

/* CaseCodeReturns */
CREATE TABLE "CaseCodeReturns"
(
  "IDX" AUTOINC,
  "xLineRef" INT,
  "CaseCode" SHORTSTRING(20),

  CONSTRAINT "$SQL$PRIMARYKEY$INDEX#0" PRIMARY KEY("IDX")
);

CREATE INDEX "LineRefIDX" ON "CaseCodeReturns"("xLineRef");

/* Company */
CREATE TABLE "Company"
  STORAGE ENGINE 'Variable'
(
  "CompanyCounter" AUTOINC DESCRIPTION 'CompanyCounter',
  "CompanyName" SHORTSTRING(50) DESCRIPTION 'Customer',
  "Address1" SHORTSTRING(50) DESCRIPTION 'Address1',
  "Address2" SHORTSTRING(50) DESCRIPTION 'Address2',
  "Address3" SHORTSTRING(50) DESCRIPTION 'Address3',
  "Town" SHORTSTRING(50) DESCRIPTION 'Town',
  "County" SHORTSTRING(50) DESCRIPTION 'County',
  "PostCode" SHORTSTRING(50) DESCRIPTION 'PostCode',
  "Country" SHORTSTRING(50) DESCRIPTION 'Country',
  "MainTelephone" SHORTSTRING(50) DESCRIPTION 'MainTelephone',
  "MainFax" SHORTSTRING(50) DESCRIPTION 'MainFax',
  "InvAdd1" SHORTSTRING(50) DESCRIPTION 'InvAdd1',
  "InvAdd2" SHORTSTRING(50) DESCRIPTION 'InvAdd2',
  "InvAdd3" SHORTSTRING(50) DESCRIPTION 'InvAdd3',
  "Invtown" SHORTSTRING(50) DESCRIPTION 'Invtown',
  "Invcounty" SHORTSTRING(50) DESCRIPTION 'Invcounty',
  "InvPostcode" SHORTSTRING(50) DESCRIPTION 'InvPostcode',
  "InvCountry" SHORTSTRING(50) DESCRIPTION 'InvCountry',
  "DelAdd1" SHORTSTRING(50) DESCRIPTION 'DelAdd1',
  "DelAdd2" SHORTSTRING(50) DESCRIPTION 'DelAdd2',
  "DelAdd3" SHORTSTRING(50) DESCRIPTION 'DelAdd3',
  "DelTown" SHORTSTRING(50) DESCRIPTION 'DelTown',
  "DelPostCode" SHORTSTRING(50) DESCRIPTION 'DelPostCode',
  "DelCounty" SHORTSTRING(50) DESCRIPTION 'DelCounty',
  "Delcountry" SHORTSTRING(50) DESCRIPTION 'Delcountry',
  "RegAdd1" SHORTSTRING(50) DESCRIPTION 'RegAdd1',
  "RegAdd2" SHORTSTRING(50) DESCRIPTION 'RegAdd2',
  "RegAdd3" SHORTSTRING(50) DESCRIPTION 'RegAdd3',
  "RegTown" SHORTSTRING(50) DESCRIPTION 'RegTown',
  "RegCounty" SHORTSTRING(50) DESCRIPTION 'RegCounty',
  "RegpostCode" SHORTSTRING(50) DESCRIPTION 'RegpostCode',
  "RegCountry" SHORTSTRING(50) DESCRIPTION 'RegCountry',
  "RegNumber" SHORTSTRING(20) DESCRIPTION 'RegNumber',
  "VatNumber" SHORTSTRING(50) DESCRIPTION 'VatNumber',
  "Notes" CLOB DESCRIPTION 'Notes',
  "Object" BLOB DESCRIPTION 'Object',
  "EmailAddress" SHORTSTRING(50) DESCRIPTION 'EmailAddress',
  "URL" SHORTSTRING(100) DESCRIPTION 'URL',
  "AccountsTelephone" SHORTSTRING(50) DESCRIPTION 'AccountsTelephone',
  "RegOfficeTelephone" SHORTSTRING(50) DESCRIPTION 'RegOfficeTelephone',
  "AccountsFax" SHORTSTRING(50) DESCRIPTION 'AccountsFax',
  "RegOfficeFax" SHORTSTRING(50) DESCRIPTION 'RegOfficeFax',
  "PaymentTerms" INT DEFAULT 1 DESCRIPTION 'PaymentTerms',
  "PurchaseTerms" INT DEFAULT 1 DESCRIPTION 'PurchaseTerms',
  "PriceDataBase" SHORTSTRING(35) DESCRIPTION 'PriceDataBase',
  "OurDiscount" SMALLINT DEFAULT 0 DESCRIPTION 'OurDiscount',
  "SaleDiscount" SMALLINT DEFAULT 0 DESCRIPTION 'SaleDiscount',
  "HireDiscount" SMALLINT DEFAULT 0 DESCRIPTION 'HireDiscount',
  "CrewDiscount" SMALLINT DEFAULT 0 DESCRIPTION 'CrewDiscount',
  "TransportDiscount" SMALLINT DEFAULT 0 DESCRIPTION 'TransportDiscount',
  "Hold" BOOLEAN DEFAULT FALSE DESCRIPTION 'Hold',
  "Accref" SHORTSTRING(12) DESCRIPTION 'Account Ref',
  "AccountLimit" MONEY DESCRIPTION 'AccountLimit',
  "InsuranceLimit" MONEY DESCRIPTION 'InsuranceLimit',
  "InsuranceExpire" TIMESTAMP DESCRIPTION 'InsuranceExpire',
  "Cellular" SHORTSTRING(25) DESCRIPTION 'Cellular',
  "Archived" BOOLEAN DEFAULT FALSE,
  "xAccountStatus" SMALLINT,
  "xRecordStatus" BYTE DEFAULT 0 DESCRIPTION 'TRecordStatus = (rsIntended, rsPending, rsAccepted,rsDeleted)',
  "xAntiFraudAction" BYTE,
  "RentalVenueCommission" REAL DEFAULT 0,
  "CrewVenueCommission" REAL DEFAULT 0,
  "TransportVenueCommission" REAL DEFAULT 0,
  "MiscVenueCommission" REAL DEFAULT 0,
  "SalesOrderDiscount" SMALLINT DEFAULT 0,
  "CreatedDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "ModifiedDate" TIMESTAMP,
  "xModifiedBy" INT,
  "AccountsEmail" VARCHAR(50),
  "DeliveryTelephone" VARCHAR(50),
  "DeliveryEmail" VARCHAR(50),
  "RegisteredEmail" VARCHAR(50),
  "DeliveryFax" VARCHAR(20),
  "DeliveryWhat3Words" VARCHAR(255),

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("CompanyCounter"),
  CONSTRAINT "CompanyAccStatusIdx" FOREIGN KEY("xAccountStatus")
    REFERENCES "AccountStatus"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT
);

CREATE INDEX "AccRefNo" ON "Company"("Accref" IGNORE CASE);
CREATE INDEX "Town1" ON "Company"("Town" IGNORE CASE);
CREATE INDEX "ComapanyName1" ON "Company"("CompanyName" IGNORE CASE);

/* CompanyAntiFraud */
CREATE TABLE "CompanyAntiFraud"
(
  "IDX" AUTOINC,
  "xCompany" INT,
  "DataOrigin" BYTE DESCRIPTION 'TDataOrigin = (doExternal,doHireTrack)',
  "FirstJobDate" DATE,
  "LastJobDate" DATE,
  "ConfirmedJobsToDate" INT,
  "MaxConfirmedStockValueToDate" MONEY,
  "AvConfirmedStockValueToDate" MONEY,

  CONSTRAINT "$SQL$PRIMARYKEY$INDEX#0" PRIMARY KEY("IDX"),
  CONSTRAINT "fk_Company" FOREIGN KEY("xCompany")
    REFERENCES "Company"("CompanyCounter")
      ON UPDATE CASCADE ON DELETE CASCADE
);


/* compfilt */
CREATE TABLE "compfilt"
  STORAGE ENGINE 'Variable'
(
  "CompanyFilterCounter" AUTOINC DESCRIPTION 'CompanyFilterCounter',
  "CompanyFilterDescription" SHORTSTRING(50) DESCRIPTION 'CompanyFilterDescription',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("CompanyFilterCounter")
);

CREATE INDEX "desc" ON "compfilt"("CompanyFilterDescription" IGNORE CASE);

/* compfllk */
CREATE TABLE "compfllk"
  STORAGE ENGINE 'Variable'
(
  "IDX" AUTOINC,
  "Company" INT DESCRIPTION 'Company',
  "Filter" INT DESCRIPTION 'Filter',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("IDX"),
  CONSTRAINT "compfllkFilter1" FOREIGN KEY("Filter")
    REFERENCES "compfilt"("CompanyFilterCounter")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "compfllkcompany1" FOREIGN KEY("Company")
    REFERENCES "Company"("CompanyCounter")
      ON UPDATE RESTRICT ON DELETE CASCADE
);


/* CorrespondenceTypes */
CREATE TABLE "CorrespondenceTypes"
(
  "IDX" AUTOINC,
  "Description" VARCHAR(50),
  "SystemRecord" BOOLEAN,

  CONSTRAINT "pkIDX" PRIMARY KEY("IDX")
);

/* CostsDetail */
CREATE TABLE "CostsDetail"
  STORAGE ENGINE 'Variable'
(
  "IDX" AUTOINC,
  "xCost" INT,
  "Quantity" INT DEFAULT 1,
  "ReceivedToDate" INT DEFAULT 0,
  "Description" SHORTSTRING(255),
  "PartNumber" SHORTSTRING(30),
  "UnitPrice" MONEY DEFAULT 0,
  "GrossTotal" MONEY DEFAULT 0,
  "Discount" FLOAT DEFAULT 0,
  "NetTotal" MONEY DEFAULT 0,
  "Invoiced" BOOLEAN DEFAULT FALSE,
  "xNominal" INT,

  CONSTRAINT "MainIDX" PRIMARY KEY("IDX")
);

CREATE INDEX "CostIDX" ON "CostsDetail"("xCost");

/* creditcard */
CREATE TABLE "creditcard"
  STORAGE ENGINE 'Variable'
(
  "Orderlink" INT NOT NULL DESCRIPTION 'Orderlink',
  "Cardnumber" SHORTSTRING(40) DESCRIPTION 'Cardnumber',
  "Cardtype" SMALLINT DESCRIPTION 'Cardtype',
  "Details" CLOB DESCRIPTION 'Details',
  "Companylink" INT DESCRIPTION 'Companylink',
  "Checkcode" SMALLINT DESCRIPTION 'Checkcode',
  "Authcode" SMALLINT DESCRIPTION 'Authcode',
  "Expiration" TIMESTAMP DESCRIPTION 'Expiration',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Orderlink")
);

CREATE INDEX "company" ON "creditcard"("Companylink");

/* Crew_Function */
CREATE TABLE "Crew_Function"
  STORAGE ENGINE 'Variable'
(
  "Idx" AUTOINC DESCRIPTION 'Idx',
  "Function" SHORTSTRING(50) DESCRIPTION 'Function',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Idx")
);

/* CrewAttributes */
CREATE TABLE "CrewAttributes"
(
  "IDX" AUTOINC,
  "Description" VARCHAR(50),
  "Expires" BOOLEAN DEFAULT FALSE,

