/* Crew */
CREATE TABLE "Crew"
  STORAGE ENGINE 'Variable'
(
  "Idx" AUTOINC DESCRIPTION 'Idx',
  "Job_no" INT DESCRIPTION 'Job_no',
  "Header" INT DESCRIPTION 'Header',
  "Type" INT DESCRIPTION 'Type',
  "xStatus" SMALLINT DEFAULT 1,
  "xSite" BYTE DESCRIPTION 'Site supplying crew',
  "Out" TIMESTAMP DESCRIPTION 'Out',
  "Back" TIMESTAMP DESCRIPTION 'Back',
  "Notes" CLOB DESCRIPTION 'Notes',
  "Quantity" INT DEFAULT 0 DESCRIPTION 'Quantity',
  "Allocated" INT DEFAULT 0 DESCRIPTION 'Allocated',
  "SingleCrewRef" INT DESCRIPTION 'SingleCrewRef',
  "DailyCharge" MONEY DEFAULT 0 DESCRIPTION 'DailyCharge',
  "Total" MONEY DEFAULT 0 DESCRIPTION 'The total charged for this crew request. For Enhanced Cewing this is the total 
of LabourChargeForBilling, PDChargeForBilling, TravelChargeForBilling, 
OvertimeChargeForBilling,AccommodationChargeForBilling',
  "LastQuotedTotal" MONEY DEFAULT 0 DESCRIPTION 'For legacy crewing this amount is taken from Total; for Enhanced it is taken 
from QuotationChargeTotal',
  "TaxTotal" MONEY DEFAULT 0 DESCRIPTION 'Tax amount on Total',
  "TotalIncTax" MONEY DEFAULT 0 DESCRIPTION 'Total + TaxTotal',
  "InvoicedTotal" MONEY DEFAULT 0,
  "Invoiced" BOOLEAN DEFAULT FALSE,
  "TotalPay" MONEY DEFAULT 0 DESCRIPTION 'The total labour costs for this crew request. For new crewing this is the total 
of LabourPay, PDPay, TravelPay, OvertimePay',
  "SortPosition" FLOAT DEFAULT 0 DESCRIPTION 'SortPosition',
  "CreatedBy" INT,
  "CreatedDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "ModifiedBy" INT,
  "ModifiedDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "Selected" BOOLEAN DEFAULT TRUE DESCRIPTION 'For reporting',
  "EqlistsAllocated" INT DEFAULT 0,
  "xCrewTask" INT,
  "Active" BOOLEAN DEFAULT TRUE,
  "QuoteCount" INT DEFAULT 0,
  "RequestDefaults" CLOB DESCRIPTION 'default values for shifts stored as JSON',
  "LabourCharge" MONEY DEFAULT 0 DESCRIPTION 'Summary of the "for quotation" Labour charges for all Shifts with BookingState 
= 0 (sbsIncQuote)',
  "PDCharge" MONEY DEFAULT 0 DESCRIPTION 'Summary of the "for quotation" PD charges for all Shifts with BookingState = 0 
(sbsIncQuote)',
  "TravelCharge" MONEY DEFAULT 0 DESCRIPTION 'Summary of the "for quotation" Travel charges for all Shifts with BookingState 
= 0 (sbsIncQuote)',
  "OvertimeCharge" MONEY DEFAULT 0 DESCRIPTION 'Summary of the "for quotation" Overtime charges for all Shifts with 
BookingState = 0 (sbsIncQuote)',
  "AccommodationCharge" MONEY DEFAULT 0 DESCRIPTION 'Summary of the "for quotation" Accommodation charges for all Shifts with 
BookingState = 0 (sbsIncQuote)',
  "PDChargeTax" MONEY DEFAULT 0 DESCRIPTION 'Tax estimate for PDCharge for quoting purposes',
  "TravelChargeTax" MONEY DEFAULT 0 DESCRIPTION 'Tax estimate for TravelCharge for quoting purposes',
  "OvertimeChargeTax" MONEY DEFAULT 0 DESCRIPTION 'Tax estimate for OvertimeCharge for quoting purposes',
  "AccommodationChargeTax" MONEY DEFAULT 0 DESCRIPTION 'Tax estimate for AccommodationCharge for quoting purposes',
  "RecType" BYTE DEFAULT 0 DESCRIPTION 'TCrewRecordType = (crtOld, crtUpgrading, crtUpgraded, crtNew)',
  "UpgradeMasterRec" INT DESCRIPTION 'Source record ID that is "atomised" during the New Crewing Upgrade',
  "TotalPayTax" MONEY DEFAULT 0 DESCRIPTION 'The tax amount on the TotalPay',
  "LabourPay" MONEY DEFAULT 0 DESCRIPTION 'Summary of the labour (only) payments for all Shifts linked to a Crew Request',
  "PDPay" MONEY DEFAULT 0 DESCRIPTION 'Summary of the PD Payments for all Shifts linked to a Crew Request',
  "TravelPay" MONEY DEFAULT 0 DESCRIPTION 'Summary of the Travel Payments for all Shifts linked to a Crew Request',
  "OvertimePay" MONEY DEFAULT 0 DESCRIPTION 'Summary of the Overtime Payments for all Shifts linked to a Crew Request',
  "AccommodationPay" MONEY DEFAULT 0 DESCRIPTION 'Summary of the Accommodation Payments for all Shifts linked to a Crew Request',
  "PDPayTax" MONEY DEFAULT 0 DESCRIPTION 'Tax for the PD Payments for all Shifts linked to a Crew Request',
  "TravelPayTax" MONEY DEFAULT 0 DESCRIPTION 'Tax for the Travel Pays for all Shifts linked to a Crew Request',
  "OvertimePayTax" MONEY DEFAULT 0 DESCRIPTION 'Tax forthe Overtime Pays for all Shifts linked to a Crew Request',
  "AccommodationPayTax" MONEY DEFAULT 0 DESCRIPTION 'Tax for the Accomodation Pays for all Shifts linked to a Crew Request',
  "TotalPayIncTax" MONEY DEFAULT 0 DESCRIPTION 'New Crewing uses this field for summing all 5 Payments and their 5 Taxes',
  "LabourChargeForBilling" MONEY DEFAULT 0 DESCRIPTION 'Summary of the billable Labour charges for all Shifts with BookingState < 2 
(not Cancelled nor Blackout)',
  "PDChargeForBilling" MONEY DEFAULT 0 DESCRIPTION 'Summary of the billable  PD charges for all Shifts with BookingState < 2 (not 
Cancelled nor Blackout)',
  "TravelChargeForBilling" MONEY DEFAULT 0 DESCRIPTION 'Summary of the billable Travel charges for all Shifts with BookingState < 2 
(not Cancelled nor Blackout)',
  "OvertimeChargeForBilling" MONEY DEFAULT 0 DESCRIPTION 'Summary of the billable Overtime charges for all Shifts with BookingState < 2 
(not Cancelled nor Blackout)',
  "AccommodationChargeForBilling" MONEY DEFAULT 0 DESCRIPTION 'Summary of the billable Accommodation charges for all Shifts with BookingState 
< 2 (not Cancelled nor Blackout)',
  "QuotationChargeTotal" MONEY DEFAULT 0 DESCRIPTION 'Sum of LabourCharge, PDCharge, TravelCharge, OvertimeCharge, AccommodationCharge',
  "LabourChargeTax" MONEY DEFAULT 0 DESCRIPTION 'Tax estimate for LabourCharge for quoting purposes',
  "QuotationChargeTotalTax" MONEY DEFAULT 0 DESCRIPTION 'Tax estimate for QuotationChargeTotal for quoting purposes',
  "QuotationChargeTotalTaxInc" MONEY DEFAULT 0 DESCRIPTION 'QuotationChargeTotal + QuotationChargeTotalTax',
  "LabourPayTax" MONEY DEFAULT 0 DESCRIPTION 'Tax for the Labour Pay for all Shifts linked to a Crew Request',
  "xRepeatLink" INT DESCRIPTION 'Link back to the crew task record that provided the logic for generating a 
record with this column assigned a value. This linked list design allows for 
deleting repeated tasks forward from any given point',
  "TaskRepeatOptions" BYTE DEFAULT 0 DESCRIPTION 'TTaskRepeatOptions = (troNever, troDaily, troWeekly, troMonthly, troAnnually)',
  "TaskRepeatEndType" BYTE DEFAULT 0 DESCRIPTION 'TTaskRepeatEndType = (tretNever, tretAfterDate, tretAfterOccurrences)',
  "TaskRepeatEndDate" DATE DESCRIPTION 'No records of TaskRepeatOptions > troNever will be created after this date',
  "TaskRepeatOccurances" BYTE DEFAULT 0 DESCRIPTION 'Number records of TaskRepeatOptions > troNever will be created if 
TaskRepeatEndType = tretAfterOccurrences',
  "TaskRepeatInterval" BYTE DESCRIPTION 'e.g every  2 days, or every 2 weeks',

  CONSTRAINT "ck_Nulls"
    CHECK(' NOT ( Header IS NULL AND Job_no IS NOT NULL AND CreatedBy IS NOT NULL)'),

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Idx"),
  CONSTRAINT "CrewheadIdx" FOREIGN KEY("Header")
    REFERENCES "Crew_header"("Idx")
      ON UPDATE RESTRICT ON DELETE CASCADE,
  CONSTRAINT "CrewbyType" FOREIGN KEY("Type")
    REFERENCES "CREWTYPE"("Crewindex")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "CrewTaskIdx" FOREIGN KEY("xCrewTask")
    REFERENCES "CrewTasks"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "CrewbyStatus" FOREIGN KEY("xStatus")
    REFERENCES "defcon"("Defcon_idx")
      ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE INDEX "back1" ON "Crew"("Back");
CREATE INDEX "out1" ON "Crew"("Out");
CREATE INDEX "jobidx" ON "Crew"("Job_no");
CREATE INDEX "IdxRepeatLink" ON "Crew"("xRepeatLink");

