  "MsgID" VARCHAR(999) DESCRIPTION 'MsgID - RFC sets max length to 998 characters',
  "InReplyTo" VARCHAR(999) DESCRIPTION 'Use for threading - see MSGID for size',
  "IsPrivate" BOOLEAN DEFAULT FALSE DESCRIPTION 'If Private email isn''''''''t automatically assigned',
  "MatchNarrative" CLOB DESCRIPTION 'What the user sees as a synopsis of the matches',
  "ReceivedDate" TIMESTAMP DEFAULT CURRENT_TIMESTAMP DESCRIPTION 'Date and Time record was created',

  CONSTRAINT "$SQL$PRIMARYKEY$INDEX#0" PRIMARY KEY("Idx")
);

