/* CrewShifts */
CREATE TABLE "CrewShifts"
(
  "IDX" AUTOINC,
  "xActivity" INT NOT NULL DESCRIPTION 'link to CrewActivities.idx',
  "xPosition" INT NOT NULL DESCRIPTION 'link to CrewPositions.idx',
  "BookingState" BYTE DEFAULT 0 DESCRIPTION 'TShiftBookingState = (sbsIncQuote, sbsExcQuote, sbsCancelled, sbsBlackout)',
  "Status" BYTE DEFAULT 0 DESCRIPTION 'TShiftStatus = (ssUnprocessed, ssInProgress, ssPencilled, ssBooked)',
  "OrderStatus" BYTE DEFAULT 0 DESCRIPTION 'TShiftOrderStatus = (sosNone, sosPartial, sosFullfilled, sosOver)',
  "ShiftType" BYTE DEFAULT 0 DESCRIPTION 'TShiftType = (stUnknown, stNormal, stBlackout)',
  "Shift1Start" TIME DEFAULT TIME '00:00:00.000',
  "Shift1End" TIME DEFAULT TIME '00:00:00.000',
  "Shift2Start" TIME DEFAULT TIME '00:00:00.000',
  "Shift2End" TIME DEFAULT TIME '00:00:00.000',
  "AccommodationStatus" BYTE DEFAULT 0 DESCRIPTION 'TAccommodationStatus = (asNotRequired, asClientProvides, asWeProvide)',
  "AccommodationCharge" MONEY DEFAULT 0 NOT NULL,
  "ChargeRate" MONEY DEFAULT 0,
  "ChargeMethod" INT DESCRIPTION 'link to Price_Dat.idx',
  "ChargeAmount" MONEY DEFAULT 0 NOT NULL,
  "ChargePDsAmount" MONEY DEFAULT 0 NOT NULL,
  "ChargeTravelAmount" MONEY DEFAULT 0 NOT NULL,
  "ChargeOvertimeAmount" MONEY DEFAULT 0 NOT NULL,
  "PayRate" MONEY DEFAULT 0,
  "PayMethod" INT DESCRIPTION 'link to Price_Dat.idx',
  "PayAmount" MONEY DEFAULT 0 NOT NULL,
  "PayPDsAmount" MONEY DEFAULT 0 NOT NULL,
  "PayTravelAmount" MONEY DEFAULT 0 NOT NULL,
  "PayOvertimeAmount" MONEY DEFAULT 0 NOT NULL,
  "Notes" NCLOB,
  "IntegrityIssues" BOOLEAN,
  "AccommodationDays" BYTE DEFAULT 2 DESCRIPTION 'TAccommodationDays = Set of TAccommodationDay;TAccommodationDay = 
(adBeforeShift, adOnShift, adAfterShift); So values between 1 and 7 represent 
all the configurations of user choices',
  "OrderDetails" CLOB DESCRIPTION 'JSON formatted data that stores the order amounts and the shift date and times',

  CONSTRAINT "pkIDX" PRIMARY KEY("IDX"),
  CONSTRAINT "fkActivity" FOREIGN KEY("xActivity")
    REFERENCES "CrewActivities"("IDX")
      ON UPDATE RESTRICT ON DELETE CASCADE,
  CONSTRAINT "fkPosition" FOREIGN KEY("xPosition")
    REFERENCES "CrewPositions"("IDX")
      ON UPDATE RESTRICT ON DELETE CASCADE
);


