/* Audit */
CREATE TABLE "Audit"
  STORAGE ENGINE 'Variable'
(
  "Auditkey" AUTOINC DESCRIPTION 'Auditkey',
  "Type" INT DESCRIPTION 'Type',
  "StockPool" BYTE DEFAULT 0 DESCRIPTION 'TStockPool',
  "Quantity" INT DESCRIPTION 'Quantity',
  "DisposedQty" INT DEFAULT 0 DESCRIPTION 'A total of how many have been stocked out against a stock IN',
  "LinkedBarcodesQty" INT DEFAULT 0 DESCRIPTION 'A total of how many barcodes have been linked to stock IN',
  "Date" DATE DEFAULT CURRENT_DATE DESCRIPTION 'Date',
  "UnitPrice" MONEY DEFAULT 0 DESCRIPTION 'UnitPrice',
  "Notes" CLOB DESCRIPTION 'Notes',
  "Reference" SHORTSTRING(50) DESCRIPTION 'Reference',
  "Site" SMALLINT DESCRIPTION 'Owner',
  "Currency" SMALLINT DEFAULT 0 DESCRIPTION 'Currency',
  "StockManageOperation" BYTE DESCRIPTION 'see TStockManageOperation',
  "xStockIn" INT DESCRIPTION 'Link back to AuditKey for a StockOut or TransferOut',
  "xTransferTo" INT DESCRIPTION 'Link to Receiver transfer IN record',
  "xTransferFrom" INT DESCRIPTION 'Link to Donor transfer OUTrecord',
  "xUser" INT,
  "ResidualValue" MONEY DEFAULT 0,
  "xWarehouseOpLine" INT DESCRIPTION 'For Sales Dispatch/Stock In or Stock Out for Unreturned kit (see 
Disposal
Reason column)',
  "xSalesAllocationLine" INT,
  "xSalesAllocationQty" INT,
  "DisposalReason" BYTE DEFAULT 0 DESCRIPTION 'TDisposalReason = (drUnspecified, drClassTransfer, drBeyondRepair, drEndOfLife,

drLost, drStolen, dsSold)',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Auditkey"),
