    REFERENCES "Hetype"("Type")
      ON UPDATE RESTRICT ON DELETE CASCADE,
  CONSTRAINT "FK_AuditSales" FOREIGN KEY("xWarehouseOpLine")
    REFERENCES "OperationsDetail"("IDX")
      ON UPDATE RESTRICT ON DELETE CASCADE
);

