  "CrewPayTravelNominal" INT DESCRIPTION 'Nominal code for enhanced crewing Travel Pay',
  "CrewPayOvertimeNominal" INT DESCRIPTION 'Nominal code for enhanced crewing Overtime Pay',
  "CrewPayAccomNominal" INT DESCRIPTION 'Nominal code for enhanced crewing Accommodation costs',
  "OpsNoteEqlistFieldVisiblity" BYTE DEFAULT 5 DESCRIPTION 'TOpsNoteEqlistFieldVisiblities = set of TOpsNoteEqlistFieldVisiblity 
=(oefvHeaderNotes1, oefvHeaderNotes2, oefvLineNotes)',
  "StandAloneScanningAutoReturnWithFeedback" BYTE DEFAULT 3 DESCRIPTION 'TStandAloneScanningAutoReturnWithFeedbacks = set of 
TStandAloneScanningAutoReturnWithFeedback =(sasawfPrePackMaster, 
sasawfWarehouseMismatch)',
  "SMTP_Provider" BYTE DEFAULT 0 DESCRIPTION 'TEmailProvider = (epCustom, epGoogle, epMicrosoft, epHotmail, epYahoo); // 
Hotmail & Yahoo are domestic services and not supported by HT NX',
  "IMAP_Provider" BYTE DEFAULT 0 DESCRIPTION 'TEmailProvider = (epCustom, epGoogle, epMicrosoft, epHotmail, epYahoo); // 
Hotmail & Yahoo are domestic services and not supported by HT NX',
  "XMLInvoicing" BYTE DEFAULT 0 DESCRIPTION 'TXMLInvoicing = (xiNone, xiZugFerd); // extensible, e.g might need xiXRechnung 
(i.e. pure XML file send, not PDF hybrid, which is xiZugFerd)',
  "StrictLocationScanning" BYTE DEFAULT 3 DESCRIPTION 'TStrictLocationScanning = (slsRelaxed, slsStrict, slsTransfer, slsUserSelects)',
  "JobCommissionMode" BYTE DEFAULT 0 DESCRIPTION 'TJobCommissionMode = (jcmAsInvoiceDiscount, jcmAsVenuePurchaseCost, 
jcmAsClientPurchaseCost)',
  "AddressCountryRequired" BOOLEAN DEFAULT FALSE DESCRIPTION 'forces user to fill in, but not via table "constraint"',
  "ReadyPreppedOptions" BYTE DEFAULT 0 DESCRIPTION 'set of TPrePackOption = (ppoPrePackEditorOnCheckIn, ppoCloseCaseOnPrepScan, 
ppoEmptyCaseOnDispatch)',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("SiteId"),
  CONSTRAINT "RulesNX$FOREIGN$SiteId" FOREIGN KEY("SiteId")
    REFERENCES "Sites"("IDX")
      ON UPDATE RESTRICT ON DELETE CASCADE,
  CONSTRAINT "FK_RentalTax" FOREIGN KEY("xDefaultRentalTax")
    REFERENCES "taxcodes"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "FK_SalesTax" FOREIGN KEY("xDefaultSalesTax")
    REFERENCES "taxcodes"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "FK_CrewTax" FOREIGN KEY("xDefaultCrewTax")
    REFERENCES "taxcodes"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "FK_CostsTax" FOREIGN KEY("xDefaultCostsTax")
    REFERENCES "taxcodes"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "FK_TransportTax" FOREIGN KEY("xDefaultTransportTax")
    REFERENCES "taxcodes"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT
);


