/* Item */
CREATE TABLE "Item"
  STORAGE ENGINE 'Variable'
(
  "Barcode" SHORTSTRING(20) NOT NULL DESCRIPTION 'Barcode',
  "Type" INT DESCRIPTION 'Equipment Type',
  "Lasttest" SHORTSTRING(20) DESCRIPTION 'Stock #',
  "Notes" CLOB,
  "Int1" INT DEFAULT 1 DESCRIPTION 'Owner Site (for audit purposes only, not stocklevels)',
  "Homelocation" INT DESCRIPTION 'Warehouse where the item lives (related to stocklevels for that warehouse)',
  "Lastservice" INT DESCRIPTION 'Warehouse where the item currently is (relates to loans)',
  "LastSpass" BOOLEAN DESCRIPTION 'LastSpass',
  "LastSdate" TIMESTAMP DESCRIPTION 'LastSdate',
  "SerialNo" SHORTSTRING(50) DESCRIPTION 'SerialNo',
  "PurchPrice" MONEY DESCRIPTION 'PurchPrice',
  "PurchDate" DATE DESCRIPTION 'PurchDate',
  "CurrentJob" INT DEFAULT 1 DESCRIPTION 'Last eqlist ID that item was dispatched on',
  "Itemref" AUTOINC DESCRIPTION 'Unique ID field for record',
  "Incase" INT DESCRIPTION 'Consignment Owner',
  "Lcurrent" INT DEFAULT 1 DESCRIPTION 'Last eqlist line that item was dispatched on',
  "Ret" BOOLEAN DEFAULT TRUE DESCRIPTION 'Legacy - to be removed',
  "Deleted" BOOLEAN DEFAULT FALSE DESCRIPTION 'Legacy - to be removed',
  "BarcodeType" BYTE DEFAULT 0 DESCRIPTION '0 = Owned, 1 = Floating, 2 = Consigned',
  "CommissionStatus" BYTE DEFAULT 0 DESCRIPTION '0 = Available, 1=Cannot Find, 2 = In Repair, 3 = Retired, 4 = Disposed',
  "Costcentre" INT DESCRIPTION 'Stock In Audit Link',
  "HoursUsed" INT DESCRIPTION 'Stock Out Audit Link',
  "xStockIn" INT DESCRIPTION 'WHAudit IN link - will change when HomeLocation is changed',
  "xStockOut" INT DESCRIPTION 'WHAudit OUTlink - will change when HomeLocation is changed',
  "Currency" SMALLINT DEFAULT 0 DESCRIPTION 'Currency',
  "LastOperation" INT DESCRIPTION 'Last Warehouse operation doc ID',
  "LastOpType" BYTE DEFAULT 0 DESCRIPTION 'TWarehouseOp ',
  "LastWarehouseBay" BYTE DEFAULT 0 DESCRIPTION 'TWarehouseBay',
  "NoIndependentScans" BOOLEAN DEFAULT FALSE,
  "xLoanExchange" INT DESCRIPTION 'Has an empheral value that links a barcode kept with a barcode it was swapped 
with.It should be cleared when a barcode is scanned on it''''s next task',
  "OnLoan" BOOLEAN DEFAULT FALSE,
  "Created" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "xBatch" INT DESCRIPTION '(Link to Batch Table for Sales)',
  "xLocation" INT,
  "ManufactureDate" DATE,
  "xDisposedItem" INT,
  "xTransferredToItem" INT,
  "LastOpScan" INT DESCRIPTION 'Last scan ID that is not a Carnet',
  "PrePackMode" BYTE DEFAULT 0 DESCRIPTION 'TPrePackMode = (ppmEmpty, ppmFreeForm, ppmTemplate)',
  "PrePackCompletion" BYTE DEFAULT 0 DESCRIPTION 'TPrePackCompletion = (ppcNotApplicable, ppcNone, ppcPartial, ppcFull)',
  "xTemplateType" INT DESCRIPTION 'looks up PrePackTemplatesTypes  if PrePackMode = ppmTemplate (2)',
  "xBatchDisposal" INT DESCRIPTION 'link to BatchItemDisposals',

  CONSTRAINT "NX$PRIMARY" PRIMARY KEY("Barcode"),
  CONSTRAINT "itemindex" FOREIGN KEY("Itemref")
    REFERENCES "alloc"("Itemref2"),
  CONSTRAINT "ItemTypes" FOREIGN KEY("Type")
    REFERENCES "Hetype"("Type")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "ItembyDefaultWH" FOREIGN KEY("Homelocation")
    REFERENCES "Warehouses"("IDX")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "FK_Batch" FOREIGN KEY("xBatch")
    REFERENCES "ItemsBatch"("Idx")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "FK_Location" FOREIGN KEY("xLocation")
    REFERENCES "location"("LocationId")
      ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT "fkBatchDisposal" FOREIGN KEY("xBatchDisposal")
    REFERENCES "BatchItemDisposals"("Idx")
      ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE INDEX "curline" ON "Item"("Lcurrent");
CREATE INDEX "incaseidx" ON "Item"("Incase");
CREATE INDEX "byEqlist" ON "Item"("CurrentJob");
CREATE INDEX "byOperation" ON "Item"("LastOperation");
CREATE INDEX "byAcquisitionLink" ON "Item"("Costcentre");
CREATE INDEX "byDisposalLink" ON "Item"("HoursUsed");
CREATE INDEX "Idx_StockIn" ON "Item"("xStockIn");
CREATE INDEX "$SQL$FOREIGNKEY$DETAIL$INDEX#0$Item" ON "Item"("xDisposedItem");
CREATE INDEX "SerialNumber" ON "Item"("SerialNo" IGNORE CASE);

