/* Create views, stored procedures/functions and triggers ------------------- */

/* vBarcodesByType */
CREATE VIEW vBarcodesByType AS (
SELECT H."Description", I.Barcode, I.ItemRef , H."Type", H.Virt Composite, (S.MasterItem IS NOT NULL) AND H.Virt AS CompositeBarcodeMaster
FROM Item I
INNER JOIN HeType H
on H."type" = I."Type"
LEFT OUTER JOIN Subcode S
ON I.ItemRef = S.MasterItem
ORDER BY
H."Description",
I.Barcode);

/* vComponentBarcodesByType */
CREATE VIEW vComponentBarcodesByType AS (
SELECT H2.Description as Composite, H."Description" AS Component ,  I.Barcode, I.ItemRef , H."Type",H.Virt
FROM Item I
INNER JOIN HeType H
on H."type" = I."Type"
INNER JOIN Composit C
ON I.Type = C.ComponentType
INNER Join Hetype H2
ON C.MasterType = H2.Type
ORDER BY
H.Virt,
H2."Description",
I.Barcode);

/* vExt_Orders */
CREATE VIEW vExt_Orders
AS
(
SELECT Invoice_Count as Order_Ref, job as Job_Ref, U.UserName as CreatedBy, Inv_Date as "CreationDate" , MainContact, DelAddress,DelContact,CollAddress,
CollContact, Authorised, U2.UserName as AuthorisedBy
from pOrder
left outer join Users U
on CreatedBy = U.UID
left outer join Users U2
on xAuthorisedBy = U2.UID

);

/* vFutureConsumableUsage */
CREATE VIEW vFutureConsumableUsage  AS (
SELECT Sum(S.Quant - S.Back) as ConsumablesBookingsTotal, S."Type", S.SLink1
/*S.LineRef,
S."Type",
S.D1,
S.D2,
S.Quant*/
from "sort" S
where S.D1 > Current_Timestamp and S.xCat < 0
group by S.Slink1, S."Type" );

/* vHandler */
CREATE VIEW vHandler AS (
SELECT UID as NameRef, UserName as FullName FROM Users);

/* vItemCountPerType */
CREATE VIEW vItemCountPerType AS (
 SELECT
    COUNT(CASE WHEN CommissionStatus IN (0,1,2,3,4) THEN CommissionStatus END)
     AS CompleteTotal,
    COUNT(CASE WHEN CommissionStatus IN (0,1,2) THEN CommissionStatus END)
     AS InCommissionTotal,
    COUNT(CASE WHEN CommissionStatus IN (3,4) THEN CommissionStatus END)
     AS OutOfCommissionTotal,
    I.Type,
    I.HomeLocation AS HomeWarehouseID
 FROM Item I
 WHERE
 I.BarcodeType <> 1
 GROUP BY
 I.Type, I.HomeLocation
 ORDER BY
 I.Type);

/* vLateReturns */
CREATE VIEW vLateReturns AS
(
SELECT
  CASE
     WHEN T.RecType = 0 THEN F.fText
     ELSE H."Description"
     END AS "Description",
	COALESCE(H.Virt,FALSE) AS Composite,
  T.*
FROM
(SELECT  CASE
		WHEN S.Back < S."Out"
			THEN S."Out" - S.Back
		WHEN S.CheckedInQty < S.Back
			THEN S.Back - S.CheckedInQty
		END AS Quant,
	S.Virt AS Component,
	S."Type" AS TypeID,
  S.Slink1,
  S.xCat,
  S.RecType,
  S.xFreeText,
  S.ListType,
	CASE
		WHEN S.Back < S."Out"
			THEN CASE
       WHEN E.ListType = 0
					THEN 'Not Returned'
				WHEN E.ListType = 1
					THEN 'Subhire Not Packed'
				WHEN E.ListType = 2
					THEN 'Subhire Not Packed'
				WHEN E.ListType = 3
					THEN 'Job Loan Not Returned'
				WHEN E.ListType = 4
					THEN 'Global Loan Not Returned'
				WHEN E.ListType = 5
					THEN 'Virtual Warehouse Loan Not Returned'
          END
	  	WHEN S.CheckedInQty < S.Back
          THEN CASE
           WHEN E.ListType = 0
					THEN 'Not Checked In'
				WHEN E.ListType = 1
					THEN 'Subhire Not Returned'
				WHEN E.ListType = 2
					THEN 'Subhire Not Returned'
				WHEN E.ListType = 3
					THEN 'Job Loan Not Received Back'
				WHEN E.ListType = 4
					THEN 'Global Loan Not Received Back'
				WHEN E.ListType = 5
					THEN 'Virtual Warehouse Loan Not Received Back'
          END

		END AS Reason,
	CASE
		WHEN S.Back < S."Out"
			THEN 0
		WHEN S.CheckedInQty < S.Back
			THEN 1
		END AS ReasonID,  --TNotBackReason
        S.LineRef,
	E.DateBack AS DueBack,
	E.Eql_No,
	E.Eql_Name AS EqRef,
	E.Eql_Title AS EqTitle,
	CASE
		WHEN E.ListType = 0
			THEN 'Rental'
		WHEN E.ListType = 1
			THEN 'Job Subhire'
		WHEN E.ListType = 2
			THEN 'Global Subhire'
		WHEN E.ListType = 3
			THEN 'Job Loan'
		WHEN E.ListType = 4
			THEN 'Global Loan'
		WHEN E.ListType = 5
			THEN 'Virtual Warehouse Build'
		END AS Activity,
	J.Job_Ref,
	J.Job_Title,
	J."Name" AS Client,
	W.WarehouseName
 FROM "Sort" S
 INNER JOIN Eqlists E
	ON E.Eql_No = S.EqlNo
 INNER JOIN Jobs J
	ON J.Jobno = E.Job_no
 INNER JOIN Warehouses W
	ON W.Idx = S.Slink1
 WHERE
  S.d2 < CURRENT_TIMESTAMP
	AND S.NotBack = TRUE
	AND S.defcon > 2
	AND S.xCat > 0
  AND S.ListType <> 6 -- no Stock Transfers
  ) AS T
 LEFT OUTER JOIN Hetype H ON T.TypeID = H.Type
 LEFT OUTER JOIN Freetext F ON T.xFreeText = F.IDX
);

/* vLocation */
CREATE VIEW vLocation AS (
SELECT IDX as LocationID, SiteName as LocationDescription from Sites);

/* vMarkups */
CREATE VIEW vMarkups AS (
SELECT
  H."Type" AS MarkupID,
	H."Description",
	H.MaxDiscount AS Rate,
	H.UserT3 AS MarkupKind,
  H.Visibility = 0 AS Active  --TEquipmentVisibility = (evAlwaysVisible, evOptionalVisibility, evNeverVisible);
FROM Hetype H
WHERE
H.EquipmentType = 4
ORDER BY
H."Description" );

/* vOrderno */
CREATE VIEW vOrderno AS (
SELECT JobNo as Jobnumber, OrderNumber, U.UserName as User2,  CreatedDate  as User5 , ConfirmedDate as Hire, Locked as User6

from Jobs
inner join Users U on
CreatedBy = U.UID
order by JobNo
);

/* vPictureNames */
CREATE VIEW vPictureNames AS (
SELECT H."Description", H."Type", P."Image"
FROM Hetype H
inner join TypePics P
 on H."Type" = P.TypeID
 ORDER BY H."Description");

/* vPrePacks */
CREATE VIEW vPrePacks AS (
SELECT
H.Type AS TypeID, H.Description AS TypeDescription, T.Idx AS TemplateID, COALESCE(T.Description, 'Free Form') AS TemplateName,
I.Barcode AS MasterBarcode, I.ItemRef AS BarcodeID, CAST(I.Notes AS VARCHAR(255)) AS PrePackDescription, I.PrePackMode, I.PrePackCompletion, I.Homelocation AS PrePackWarehouseID
FROM
Hetype H
INNER JOIN Item I
ON H.Type = I.Type
LEFT OUTER JOIN PrePackTemplatesTypes T
ON I.xTemplateType = T.Idx
WHERE
H.PrePack = True
AND I.PrePackMode > 0
);

/* vRepairsList */
CREATE VIEW vRepairsList AS (
SELECT *
FROM "sort"
WHERE
eqlno = 0);

/* vRoadCases */
CREATE VIEW vRoadCases AS (
SELECT * FROM
Hetype
WHERE
Category = 1
OR Roadcase <> FALSE);

/* vSitesAndWarehouses */
CREATE VIEW vSitesAndWarehouses AS (
SELECT
W.Idx as WarehouseID, W.WarehouseName, W.ISDefault, S.SiteID, S.SiteName
from Warehouses W
inner join (SELECT SYSTEM_ROW# AS SortedBy ,Idx AS SiteID, SiteName   FROM Sites ORDER BY SortOrder) S
On S.SiteID = W.xSite
where W.Virtual = False
Order by S.SortedBy, W.SortOrder

);

/* vStockSummary */
CREATE VIEW "vStockSummary"
AS
SELECT
  T.Description, T."Type" as TypeID,
  T.Category,
  T.SortOrder AS TypeSortOrder,
  C.Description AS CatDescription,
  C.SortOrder AS CatSorder,
  M.McDescription,
  M.McatId,
  M.MCSortOrder
FROM
  Hetype T
  INNER JOIN Category C ON C.category = T.Category
  INNER JOIN MasterCat M ON M.McatId = C.MasterCat
ORDER BY
M.McDescription, C.Description, T.Description;

