/* vUniqueTags */
CREATE  VIEW vUniqueTags AS (
SELECT Distinct
CASE
WHEN (Position('=!' IN Tag) > 0) THEN TAG
WHEN (Position('=>!' IN Tag) > 0) THEN TAG
WHEN (Position('=QBE:' IN Upper(Tag)) > 0) THEN TAG
WHEN (Position('=' IN Tag) > 0)  THEN SUBSTRING(Tag FROM 1 FOR (Position('=' IN Tag)))
ELSE  TAG
END As Tag  FROM "SmartTags" WHERE Original = TRUE
);

/* CalcCrewAccomodationOrderStatus */
CREATE FUNCTION CalcCrewAccomodationOrderStatus
(aCrewAccommodationID INT,
 aCharge MONEY)
RETURNS TINYINT
READS SQL DATA
BEGIN

   SELECT
   SUM(CASE WHEN SubCostCentre = 5 THEN LineTotal ELSE 0 END) AS TotalOrdered, aCharge AS TotalCost,
   COUNT(*) AS TotalOrderRecords,
   SUM(ABS(LineTotal)) AS AbsTotal,
   SUM(LineTotal) AS NetTotal,
   SortLink AS MasterRecord
   INTO #OrderTotals
   FROM POData
   WHERE
   SortLink = aCrewAccommodationID
   AND xGeneralCostCentre = 1
   AND SubCostCentre IN (5)
   GROUP BY
   SortLink;


   DECLARE vOrderStatus TINYINT;

   SET vOrderStatus = COALESCE((SELECT CASE
                         WHEN (D.TotalOrdered > 0) AND (D.TotalCost - D.TotalOrdered < 0) THEN 3 -- over ordered
                         WHEN (D.TotalCost > 0) AND (D.TotalCost - D.TotalOrdered = 0) THEN 2 -- fully ordered
                         WHEN ((D.TotalCost > 0) AND (D.TotalCost - D.TotalOrdered > 0)) OR
                              ((D.TotalCost = 0) AND  (D.TotalOrderRecords > 0) /*AND (D.AbsTotal = 0)*/)  THEN 1 -- partially ordered
                         WHEN D.TotalOrderRecords = 0 THEN 0 -- no orders yet
                         END
                  FROM #OrderTotals D
                  WHERE
                  D.MasterRecord = aCrewAccommodationID),0);

   RETURN vOrderStatus;

END;

/* CloneCost */
CREATE FUNCTION CloneCost (
		aCostsID INT,
                aJobID INT
		)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN

DECLARE vNewCostsID INT;
DECLARE vOldJobID INT;
DECLARE vStatus INT;

SET vOldJobID = (SELECT xJob FROM Costs WHERE IDX = aCostsID);

IF vOldJobID <> aJobID THEN
 SET vStatus = (SELECT Status FROM Jobs WHERE Jobno = aJobID);
ELSE
 SET vStatus = (SELECT xStatus FROM Costs WHERE IDX = aCostsID);
END IF;

INSERT INTO Costs (
	xJob,
	xInternalCostCentre,
	xGeneralCostCentre,
	xCostCentreID,
	xStatus,
	IsList,
	Title,
	IsCompanySupplier,
	xSupplier,
	xPaymentType,
	SupplierRef,
	OurRef,
	IsExpenditure,
	IsIncome,
	AnticipatedPrice,
	ActualPrice,
	InvoiceOnPrice,
	InvoiceOnTax,
	InvoiceOnIncTax,
	xNominal,
  LastQuotedTotal
	)
SELECT
  aJobID,
	xInternalCostCentre,
	xGeneralCostCentre,
	xCostCentreID,
	vStatus,
	IsList,
  CASE
    WHEN vOldJobID <> aJobID THEN Title
  ELSE TOSTRINGLEN(Title,245)|| ' (CLONE)'
  END,
	IsCompanySupplier,
	xSupplier,
	xPaymentType,
	SupplierRef,
	OurRef,
	IsExpenditure,
	IsIncome,
	AnticipatedPrice,
	CASE
    WHEN (SELECT P.PaymentMode FROM PaymentTypes P WHERE P.Idx = xPaymentType) <> 2  THEN ActualPrice
  ELSE 0
  END,
	InvoiceOnPrice,
	InvoiceOnTax,
	InvoiceOnIncTax,
	xNominal,
  0
FROM Costs
WHERE IDX = aCostsID;

SET vNewCostsID = LASTAUTOINC;

-- now the Cost details lines
INSERT INTO CostsDetail (
	xCost,
	Quantity,
	"Description",
	PartNumber,
	UnitPrice,
	GrossTotal,
	Discount,
	NetTotal
	)
SELECT
  vNewCostsID ,
  Quantity,
	"Description",
	PartNumber,
	UnitPrice,
	GrossTotal,
	Discount,
	NetTotal
FROM CostsDetail
WHERE xCost = aCostsID;

RETURN vNewCostsID;

END;

/* CloneCrew */
CREATE FUNCTION CloneCrew (
		aCrewID INT,
    aJobID INT,
		aOldHeaderID INT,
    aNewHeaderID INT,
		aDaysAdd INT
		)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN

	DECLARE vDaysAdd INT;
	SET vDaysAdd = COALESCE(aDaysAdd ,0);

	DECLARE vNewCrewing BOOL;
	SET vNewCrewing = (SELECT COALESCE(NewCrewing,True) FROM Jobs WHERE Jobno = aJobID) AND
	                  (SELECT RecType > 1 FROM Crew WHERE IDX = aCrewID);  -- TCrewRecordType = (crtOld, crtUpgrading, crtUpgraded, crtNew);

	IF vNewCrewing THEN
	   SIGNAL 'The CloneEnhancedCrew SP should be used instead of CloneCrew';
	END IF;

-- if aNewHeaderID is NULL then we are cloning only aCrewID, otherwise we clone all crew entries for aNewHeaderID
	IF aNewHeaderID IS NULL THEN
		  SELECT aJobID,
			Header,
			"Type",
			xStatus,
			xSite,
      CAST(CAST("Out" AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS "Out",
      CAST(CAST("Back" AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS "Back",
			Quantity,
			SingleCrewRef,
			DailyCharge,
			Total,
			TaxTotal,
			TotalIncTax,
      0 AS LastQuotedTotal,
      SortPosition,
      RecType
		INTO #Crew
		FROM Crew
		WHERE IDX = aCrewID;
	ELSE
 	    SELECT aJobID,
			aNewHeaderID,
			"Type",
			xStatus,
			xSite,
      CAST(CAST("Out" AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS "Out",
      CAST(CAST("Back" AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS "Back",
			Quantity,
			SingleCrewRef,
			DailyCharge,
			Total,
			TaxTotal,
			TotalIncTax,
      0 AS LastQuotedTotal,
      SortPosition,
      RecType
		INTO #Crew
		FROM Crew
		WHERE Header = aOldHeaderID;
  END IF ;

	-- now the real data
	INSERT INTO Crew (
		Job_no,
		Header,
		"Type",
		xStatus,
		xSite,
		"Out",
		Back,
		Quantity,
		SingleCrewRef,
		DailyCharge,
		Total,
		TaxTotal,
		TotalIncTax,
    LastQuotedTotal,
    SortPosition,
    RecType
		)
	SELECT *
	FROM #Crew;

UPDATE Crew SET RecType = 0 WHERE Job_no = aJobID;

RETURN LASTAUTOINC;

END;

/* CloneCrewEnhanced */
CREATE FUNCTION CloneCrewEnhanced (
		aCrewID INT,
    aJobID INT,
		aOldHeaderID INT,
    aNewHeaderID INT,
    aJobClone BOOLEAN)
RETURNS INT
MODIFIES SQL DATA
BEGIN

	DECLARE vOldCrewID INT;
  DECLARE vTrackOldCrewID INT;
	DECLARE vNewCrewID INT;
  DECLARE vSortOrder INT;
	DECLARE vOldCrewPositionID INT;
	DECLARE vNewCrewPositionID INT;
  DECLARE vJobID INT;
	DECLARE vHeaderID INT;
	DECLARE vStatus INT;
  DECLARE vCrewType INT;
	DECLARE vRecType TINYINT;
	DECLARE vRequestDefaults TEXT;

	 IF aNewHeaderID IS NULL THEN
		DECLARE aCursor CURSOR FOR SELECT C.IDX, C.Header, C.Job_no, C.Type, C.xStatus, C.RequestDefaults, C.SortPosition, P.IDX AS xPosition
	                               FROM Crew C
                                 INNER JOIN CrewPositions P
                                 ON C.Idx = P.xCrewRequest
	                               WHERE
                                 C.IDX = aCrewID
                                 ORDER BY
                                 C.SortPosition, P.IDX ASC;
	 ELSE

		DECLARE aCursor CURSOR FOR SELECT C.IDX, aNewHeaderID, aJobID, C.Type,  C.xStatus, C.RequestDefaults, C.SortPosition, P.IDX AS xPosition
	                               FROM Crew C
                                 INNER JOIN CrewPositions P
                                 ON C.Idx = P.xCrewRequest
	                               WHERE
                                 C.Header = aOldHeaderID
                                 ORDER BY
                                 C.SortPosition, P.IDX ASC;
	 END IF;

	 OPEN aCursor;
   TRY
   SET vTrackOldCrewID = -1;

	 FETCH FIRST FROM aCursor INTO vOldCrewID, vHeaderID, vJobID, vCrewType, vStatus, vRequestDefaults, vSortOrder, vOldCrewPositionID;
	 WHILE @@FETCH_STATUS = 0 DO
	    -- first the new crew (Role) record
     IF vOldCrewID <> vTrackOldCrewID THEN
	    INSERT INTO CREW   -- set the RecType to 1 so that trCrewTotalsAFTER doesn't fire. The job finances table will be updated by the
	    (Header,   Job_no,   Type,     xStatus,                                    Quantity, RecType, SortPosition, RequestDefaults)
	    VALUES
	    (vHeaderID, vJobID, vCrewType, CASE WHEN aJobClone THEN 1 ELSE vStatus END, 1,       1,        vSortOrder, vRequestDefaults);

	    SET vNewCrewID = LASTAUTOINC;
      SET vTrackOldCrewID = vOldCrewID;
     END IF;
	    -- Crew Position
	    INSERT INTO CrewPositions
	    (xCrewRequest, Description)
	    SELECT vNewCrewID, Description FROM CrewPositions WHERE IDX = vOldCrewPositionID;

	    SET vNewCrewPositionID = LASTAUTOINC;

	    -- Crew Shifts
      IF aNewHeaderID IS NOT NULL THEN

		    INSERT INTO CrewShifts
		    (xActivity,xPosition,ShiftType,Shift1Start,Shift1End,Shift2Start,Shift2End,AccommodationStatus,AccommodationCharge,ChargeRate,ChargeMethod,ChargeAmount,
		    ChargePDsAmount,ChargeTravelAmount,ChargeOvertimeAmount,PayRate,PayMethod,PayAmount,PayPDsAmount,PayTravelAmount,PayOvertimeAmount,Notes,IntegrityIssues,AccommodationDays)
		    SELECT
		    (SELECT A.IDX FROM CrewActivities A WHERE A.xClonedFrom = S.xActivity AND A.xArea = aNewHeaderID),
        vNewCrewPositionID, S.ShiftType, S.Shift1Start, S.Shift1End, S.Shift2Start, S.Shift2End, S.AccommodationStatus, S.AccommodationCharge, S.ChargeRate, S.ChargeMethod, S.ChargeAmount,
	      S.ChargePDsAmount, S.ChargeTravelAmount, S.ChargeOvertimeAmount, S.PayRate, S.PayMethod, S.PayAmount, S.PayPDsAmount, S.PayTravelAmount, S.PayOvertimeAmount, S.Notes, S.IntegrityIssues, S.AccommodationDays
	      FROM CrewPositions P
	      INNER JOIN CrewShifts S
	      ON S.xPosition = P.Idx
		    WHERE
		    P.IDX = vOldCrewPositionID
        AND S.BookingState <> 2 -- cancelled
        AND (SELECT A.IDX FROM CrewActivities A WHERE A.xClonedFrom = S.xActivity AND A.xArea = aNewHeaderID) IS NOT NULL;
      ELSE

		    INSERT INTO CrewShifts
		    (xActivity,xPosition,ShiftType,Shift1Start,Shift1End,Shift2Start,Shift2End,AccommodationStatus,AccommodationCharge,ChargeRate,ChargeMethod,ChargeAmount,
		    ChargePDsAmount,ChargeTravelAmount,ChargeOvertimeAmount,PayRate,PayMethod,PayAmount,PayPDsAmount,PayTravelAmount,PayOvertimeAmount,Notes,IntegrityIssues,AccommodationDays)
		    SELECT
		    S.xActivity,vNewCrewPositionID, S.ShiftType, S.Shift1Start, S.Shift1End, S.Shift2Start, S.Shift2End, S.AccommodationStatus, S.AccommodationCharge, S.ChargeRate, S.ChargeMethod, S.ChargeAmount,
	      S.ChargePDsAmount, S.ChargeTravelAmount, S.ChargeOvertimeAmount, S.PayRate, S.PayMethod, S.PayAmount, S.PayPDsAmount, S.PayTravelAmount, S.PayOvertimeAmount, S.Notes, S.IntegrityIssues, S.AccommodationDays
	      FROM CrewPositions P
	      INNER JOIN CrewShifts S
	      ON S.xPosition = P.Idx
		    WHERE
		    P.IDX = vOldCrewPositionID
        AND S.BookingState <> 2; -- cancelled
      END IF;


	 FETCH NEXT FROM aCursor INTO vOldCrewID, vHeaderID, vJobID, vCrewType, vStatus, vRequestDefaults, vSortOrder, vOldCrewPositionID;
	 END WHILE;

	 CLOSE aCursor;

  CATCH TRUE
  CLOSE aCursor;
  SIGNAL ERROR_MESSAGE;
END;

 UPDATE Crew SET RecType = 3 WHERE Job_no = aJobID;

 CALL TotalizeShiftsForRolesOnJob(aJobID,'');

 RETURN vNewCrewID;

END;

/* CloneCrewHeader */
CREATE FUNCTION CloneCrewHeader (
		aHeaderID INT,
    aJobID INT,
		aDaysAdd INT,
		aCloneCrewDetails BOOLEAN,
    aJobClone BOOLEAN
		)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN

	DECLARE vNewCrewing BOOL;
	SET vNewCrewing = (SELECT COALESCE(NewCrewing,True) FROM Jobs WHERE Jobno = aJobID);

  DECLARE vSortOrder DOUBLE PRECISION;
  IF NOT aJobClone THEN
    SET vSortOrder = (SELECT COALESCE(MAX(Sort_Order),0) + 1 FROM Crew_Header WHERE xJob = (SELECT xJob FROM Crew_Header WHERE IDX = aHeaderID));
  ELSE
    SET vSortOrder = (SELECT COALESCE(MAX(Sort_Order),0) + 1 FROM Crew_Header WHERE xJob = aJobID);
  END IF;

	DECLARE vNewHeader INT;

  IF vNewCrewing THEN
     INSERT INTO Crew_Header
     (XJob, Title,Sort_Order)
     SELECT
     aJobID,
		 CAST(CASE
	        WHEN aJobClone THEN H.Title
	        ELSE  H.Title + ' - CLONE'
	        END AS SHORTSTRING(100)),
     vSortOrder
     FROM Crew_Header H
	   WHERE
     H.IDX = aHeaderID;
  ELSE
		INSERT INTO Crew_Header
			("Function",
			ScheduleStart,
			ScheduleEnd,
			PriceStart,
			PriceEnd,
			XJob,
			Title,
			xStatus,
			ChargeMode)
		SELECT "Function",
			CAST(CAST("ScheduleStart" AS DOUBLE PRECISION) + aDaysAdd AS TIMESTAMP) AS "ScheduleStart",
			CAST(CAST("ScheduleEnd" AS DOUBLE PRECISION) + aDaysAdd AS TIMESTAMP) AS "ScheduleEnd",
			CAST(CAST("PriceStart" AS DOUBLE PRECISION) + aDaysAdd AS TIMESTAMP) AS "PriceStart",
			CAST(CAST("PriceEnd" AS DOUBLE PRECISION) + aDaysAdd AS TIMESTAMP) AS "PriceEnd",
			aJobID,
			CAST(CASE
		        WHEN aJobClone THEN Title
		        ELSE  Title + ' - CLONE'
		        END AS SHORTSTRING(100)),
		 	CASE
		        WHEN aJobClone THEN (SELECT Status FROM Jobs WHERE Jobno = aJobID)
		        ELSE  xStatus
		        END,
			ChargeMode
		FROM Crew_Header
		WHERE
	  IDX = aHeaderID;

  END IF;

	SET vNewHeader = LASTAUTOINC;

  IF vNewCrewing THEN   -- CrewActivities
     INSERT INTO CrewActivities
     (xArea, ActivityDate, ActivityType, Description, xClonedFrom)
     SELECT
     vNewHeader, CAST(CAST(ActivityDate AS DWORD)  + aDaysAdd AS DATE), ActivityType, Description, IDX
     FROM CrewActivities
	   WHERE
     xArea = aHeaderID;
  END IF;

	-- now the crew lines
	IF aCloneCrewDetails THEN
     IF vNewCrewing THEN
        CloneCrewEnhanced(CAST(NULL AS INT),aJobID, aHeaderID, vNewHeader, aJobClone);
     ELSE
     	  CloneCrew(CAST(NULL AS INT),aJobID, aHeaderID, vNewHeader, aDaysAdd);
     END IF;
	END IF;

	RETURN vNewHeader;

END;

/* CloneCrewPosition */
CREATE FUNCTION CloneCrewPosition
(aCrewPositionID INT,
 aCloneShifts BOOL)
RETURNS INT
MODIFIES SQL DATA
BEGIN
  DECLARE vNewPositionID INT;

  INSERT INTO CrewPositions
  (xCrewRequest,Description)
  SELECT xCrewRequest,Description
  FROM CrewPositions
  WHERE
  IDX = aCrewPositionID;

  SET vNewPositionID = LASTAUTOINC;

  IF aCloneShifts THEN

     INSERT INTO CrewShifts
     (xActivity, xPosition, ShiftType,Shift1Start, Shift1End, Shift2Start, Shift2End, AccommodationStatus, AccommodationCharge,
     ChargeRate, ChargeMethod, ChargeAmount, ChargePDsAmount, ChargeTravelAmount, ChargeOvertimeAmount,
     PayRate, PayMethod, PayAmount, PayPDsAmount, PayTravelAmount, PayOvertimeAmount,
     Notes, IntegrityIssues,AccommodationDays)
     SELECT
     xActivity, vNewPositionID, ShiftType,Shift1Start, Shift1End, Shift2Start, Shift2End, AccommodationStatus, AccommodationCharge,
     ChargeRate, ChargeMethod, ChargeAmount, ChargePDsAmount, ChargeTravelAmount, ChargeOvertimeAmount,
     PayRate, PayMethod, PayAmount, PayPDsAmount, PayTravelAmount, PayOvertimeAmount,
     Notes, IntegrityIssues,AccommodationDays
     FROM CrewShifts
     WHERE
     xPosition =  aCrewPositionID;

  END IF;

  RETURN vNewPositionID;
END;

/* CloneDiary */
CREATE FUNCTION CloneDiary (
		aSourceID INT,
    aEventOwnerID INT,
		aDaysAdd INT
		)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN
     DECLARE vNewRecordID INT;

     INSERT INTO Diary
     (EventType,
     xEventOwnerID,
     Description,
     xEventCategory,
     Priority,
     DueDate,
     ReminderType,
     Status,
     Notes)
     SELECT
     EventType,
     aEventOwnerID,
     Description,
     xEventCategory,
     Priority,
     CAST(CAST("DueDate" AS DOUBLE PRECISION) + aDaysAdd AS TIMESTAMP) AS "DueDate",
     ReminderType,
     Status,
     Notes
     FROM Diary
     WHERE
     Idx = aSourceID;

     SET vNewRecordID = LASTAUTOINC;

     INSERT INTO DiaryUsers
     (xDiary, xUser)
     SELECT
     vNewRecordID, xUser
     FROM
     DiaryUsers
     WHERE
     xDiary = aSourceID;

     RETURN vNewRecordID;
END;

/* CloneEqlist */
CREATE FUNCTION CloneEqlist
( aEqlistID INT,
  aNewJobID INT,
  aDaysAdd INT,
  aNewVenueID INT,
  aEqlistLineIDs TEXT,
  aHeaderOnly BOOLEAN,
  aTitleReset BOOLEAN,
  aExtensionType TINYINT)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN

 DECLARE vEqlno INT;
 DECLARE vDaysAdd INT;
 DECLARE vDynamicSQL TEXT;
 DECLARE vOldLookupField INT;
 DECLARE vNewLookupField INT;
 DECLARE vSortOrder INT;
 DECLARE vTextField VARCHAR(255);
 DECLARE vSortWhereClause TEXT;
 DECLARE vEqRef VARCHAR(30);
 DECLARE vEqTitle VARCHAR(50);
 DECLARE vClientID INT;
 DECLARE vNewVenueID INT;
 DECLARE vStatus INT;
 DECLARE vWarehouseID INT;
 DECLARE vEqlistClass TINYINT;
 DECLARE vTransferToLineFieldValueText VARCHAR(40);
 DECLARE vHeaderNarrative CLOB;

 IF aExtensionType IN (1,2,3) THEN
    SET vTransferToLineFieldValueText = 'LineRef AS xTransferToLine';
 ELSE
    SET vTransferToLineFieldValueText = 'xTransferToLine';
 END IF;

 SET vDaysAdd = COALESCE(aDaysAdd, 0);


 IF aEqlistLineIDs = '' THEN
   SET vSortWhereClause = 'WHERE Eqlno = ' + CAST(aEqlistID AS VARCHAR(10)) + ' AND Virt = FALSE AND RecType <> 17 AND xSubhireEarmarkFor IS NULL'; --etCompositePrepModified = 17
 ELSE
   IF aExtensionType IN (2,3) THEN -- Late Extensions
      SET vSortWhereClause = 'WHERE LineRef IN (' +  aEqlistLineIDs + ') AND RecType <> 17 AND xSubhireEarmarkFor IS NULL'; --etCompositePrepModified = 17  ;
   ELSE
      SET vSortWhereClause = 'WHERE LineRef IN (' +  aEqlistLineIDs + ') AND Virt = FALSE AND RecType <> 17 AND xSubhireEarmarkFor IS NULL'; --etCompositePrepModified = 17  ;
   END IF;
 END IF;


 -- Eqlists first

 SELECT * INTO #Eqlists
 FROM Eqlists
 WHERE Eql_No = aEqlistID;

  -- handle null values which may have been passed deliberately
 SET vNewVenueID = COALESCE(aNewVenueID,(SELECT Venue_no FROM #Eqlists));
 SET vClientID = (SELECT Client FROM Jobs WHERE JobNo = aNewJobID);
 SET vWarehouseID = (SELECT MainSite FROM #Eqlists);
 SET vEqlistClass = (SELECT EqlistClass FROM #Eqlists);

 -- get eql_no value
 IF (SELECT ListType FROM #Eqlists) IN (0,1) THEN

   INSERT INTO aiEqlist
   (Jobno)
   SELECT Job_no FROM #Eqlists;

   SET vEqlNo = LASTAUTOINC;
 ELSE

  SET vEqlNo = GetNonJobEqlistID;

 END IF;


 SET vEqRef = TOSTRINGLEN(GetNewEqlistRef(aNewJobID, vEqlNo, (SELECT ListType FROM #Eqlists), vEqlistClass),30);

 -- only set title to old title + 'CLONE' if cloning to existing job
 IF aNewJobID  = (SELECT Job_no FROM #Eqlists) THEN
   SET vStatus = (SELECT Defcon FROM #Eqlists);
 ELSE
   SET vStatus = (SELECT Status FROM Jobs WHERE Jobno = aNewJobID);
   UPDATE #Eqlists SET Defcon = vStatus;

 END IF;

 IF aTitleReset THEN
   SET vEqTitle = TOSTRINGLEN((SELECT Job_Title FROM Jobs WHERE JobNo = aNewJobID)  || ':' || vEqRef,50) ;
 ELSE
   IF aNewJobID  = (SELECT Job_no FROM #Eqlists) THEN
     SET vEqTitle = TOSTRINGLEN((SELECT Eql_Title FROM #Eqlists)  || ' (CLONE)',50) ;
   ELSE
     SET vEqTitle = (SELECT Eql_Title FROM #Eqlists);
   END IF;
 END IF;

 UPDATE #Eqlists
 SET
 Eql_no = vEqlNo,
 Job_no = aNewJobID,
 Eql_Name = vEqRef,
 Eql_Title =  vEqTitle,
 Venue_no = vNewVenueID,
 Client_no = vClientID,
 ITotal = 0,
 LastQuotedTotal = 0,
 ExtensionType = aExtensionType,
 CreatedDate = CURRENT_TIMESTAMP,
 -- Early Returns have no warehouse ops so fake completion
 PrepStatus = CASE WHEN aExtensionType = 1 THEN 2 ELSE 0 END,
 DelStatus = CASE WHEN aExtensionType = 1 THEN 2 ELSE 0 END,
 ReturnedStatus = CASE WHEN aExtensionType = 1 THEN 2 ELSE 0 END,
 CheckedInStatus = CASE WHEN aExtensionType = 1 THEN 2 ELSE 0 END,
 xPrepBay = CAST (NULL AS INT),
 Upgraded = CASE
              WHEN aHeaderOnly THEN FALSE
            ELSE TRUE
            END;

 INSERT INTO Eqlists
 SELECT * FROM
 #Eqlists;

 IF NOT aHeaderOnly THEN

 -- DELETE any Section headers that have been auto created by custom triggers
 DELETE FROM EqSections WHERE xEqlno = vEqlNo;

  --do Markups
 SELECT
 xEqlno,
 xMarkupID,
 xMarkupKind,
 Rate,
 Amount,
 SalesTax
 INTO #EqlistMarkups
 FROM EqlistMarkups
 WHERE xEqlno  = aEqlistID;

 UPDATE #EqlistMarkups
  SET xEqlno = vEqlNo;

 INSERT INTO EqlistMarkups
 ( xEqlno,
 xMarkupID,
 xMarkupKind,
 Rate,
 Amount,
 SalesTax)
 SELECT * FROM #EqlistMarkups;


 --Get Section headers
 IF aEqlistLineIDs = '' THEN
   SET vDynamicSQL = 'SELECT * INTO #EqSections FROM EqSections  WHERE xEqlno = ' + CAST(aEqlistID AS VARCHAR(10));
 ELSE
   SET vDynamicSQL = 'SELECT * INTO #EqSections FROM EqSections  WHERE Idx IN (SELECT DISTINCT SectionID FROM "SORT" ' + vSortWhereClause + ');';
 END IF;

 EXECUTE IMMEDIATE  vDynamicSQL;

 --Get FreeText
 SET vDynamicSQL = 'SELECT * INTO #FreeText FROM FreeText  WHERE Idx IN (SELECT xFreeText FROM "SORT" ' + vSortWhereClause + ');';
 EXECUTE IMMEDIATE  vDynamicSQL;

 --Get the data for Sort.nx1, resetting some fields. Note how the originator LineRef is stored in Sort.OldLineRef. This allows, among other things, trSortBEFORE to ingore syncing ChargeQuantity with Quant on Insert
 -- Note how if the Rectype is a split or Prep Modified composite we have to reset to normal, set the Qty for the original and not clone the Prep Modified
 SET vDynamicSQL =
 'SELECT
 "Type",
	CASE WHEN RecType IN (16,17) THEN ChargeQuantity ELSE Quant END AS Quant,
	Xcat,' +
	CAST(vEqlNo AS VARCHAR(10)) + ' AS Eqlno,
	--Virt,
	D1,
	D2,
	Alloc,'+
	CAST(vStatus AS VARCHAR(10)) + ' AS Eqlno,
	Subhire,
	ListType,
  ChargeQuantity,
	Daily,
	DailyMultiplier,
	PreDiscount,
	Discount,
	Price,
	0 InvoicedTotal,
	False AS Invoiced,
	Notes,
	Slink1,
	Slink2,
	sectionID,
	xFreeText,
	SortOrder,
	CASE WHEN RecType IN (16,17) THEN 10 ELSE RecType END AS RecType,
	CASE WHEN RecType IN (7,9,13) THEN xGUID ELSE NEWGUID END AS xGUID,
	0 AS LoansInQty,
	0 AS SubHiredQty,
	0 AS CarnetQty,
	0 AS PreppedQty,
	0 AS "Out",
	0 AS Back,
	0 AS CheckedInQty,
	UnitWeight,
	UnitValue,
	LineRef AS oldLineRef,
	FALSE NotBack,
  CurrentCostPrice,
  AnticipatedCostPrice,
	0 AS xLateEqlno,
	xTransferInWarehouse,' +
 vTransferToLineFieldValueText +  -- for Extension lists point to the original rental line.
 ' INTO #Sort
  FROM "SORT" ' +
 vSortWhereClause;

 EXECUTE IMMEDIATE  vDynamicSQL;

 --make sure WarehouseID in correct in case of cloning old Eclipse job
 UPDATE #Sort SET
 SLink1  = vWarehouseID;

 -- sort out sync'd Priced Alias GUIDs
 DECLARE vOldGUID, vNewGUID GUID;

 DECLARE cGUIDs CURSOR FOR
 SELECT xGUID
 FROM #Sort
 WHERE
 Rectype = 13;

 OPEN cGUIDs;

 TRY
 FETCH FIRST FROM cGUIDs INTO vOldGUID;

 WHILE @@FETCH_STATUS = 0 DO
       SET vNewGUID = NEWGUID;

       UPDATE #Sort SET
       xGUID = vNewGUID
       WHERE
       xGUID = vOldGUID;

FETCH NEXT  FROM cGUIDs INTO vOldGUID;
END WHILE;

CLOSE cGUIDs;

CATCH TRUE
  CLOSE cGUIDs;
  SIGNAL ERROR_MESSAGE;
END;

 -- new Section headers
 DECLARE cEqSections CURSOR FOR SELECT IDX, SectionText, SortOrder, Notes FROM #EqSections;
 OPEN cEqSections;
 TRY

 FETCH FIRST FROM cEqSections INTO vOldLookupField, vTextField, vSortOrder, vHeaderNarrative ;
 WHILE @@FETCH_STATUS = 0 DO

  INSERT INTO EqSections
  (SectionText,xEqlno, SortOrder, Notes)
  VALUES
  (vTextField,vEqlNo,vSortOrder, vHeaderNarrative);

  SET vNewLookupField = LASTAUTOINC;

  UPDATE "#Sort" SET
  sectionID = vNewLookupField
  WHERE sectionID = vOldLookupField;

  FETCH NEXT FROM cEqSections INTO vOldLookupField, vTextField, vSortOrder, vHeaderNarrative;

 END WHILE;
 CLOSE cEqSections;

 CATCH TRUE
  CLOSE cEqSections;
  SIGNAL ERROR_MESSAGE;
END;


 -- new FreeText lines
 DECLARE cFreeText CURSOR FOR SELECT * FROM #FreeText;
 OPEN cFreeText;
 TRY

 FETCH FIRST FROM cFreeText INTO vOldLookupField, vTextField ;
 WHILE @@FETCH_STATUS = 0 DO

  INSERT INTO FreeText
  (fText)
  VALUES
  (vTextField);

  SET vNewLookupField = LASTAUTOINC;

  UPDATE "#Sort" SET
  xFreetext = vNewLookupField
  WHERE xFreetext = vOldLookupField;

  FETCH NEXT FROM cFreeText INTO vOldLookupField, vTextField;

 END WHILE;
 CLOSE cFreeText;

 CATCH TRUE
  CLOSE cFreeText;
  SIGNAL ERROR_MESSAGE;
END;

 -- Finally create actual new lines
 INSERT INTO "Sort" (
	"Type",
	Quant,
	Xcat,
	Eqlno,
	--Virt,
	D1,
	D2,
	Alloc,
	Defcon,
	Subhire,
	ListType,
  ChargeQuantity,
	Daily,
	DailyMultiplier,
	PreDiscount,
	Discount,
	Price,
	InvoicedTotal,
	Invoiced,
	Notes,
	Slink1,
	Slink2,
	sectionID,
	xFreeText,
	SortOrder,
	RecType,
	xGUID,
	LoansInQty,
	SubHiredQty,
	CarnetQty,
	PreppedQty,
	"Out",
	Back,
	CheckedInQty,
	UnitWeight,
	UnitValue,
	oldLineRef,
	NotBack,
  CurrentCostPrice,
  AnticipatedCostPrice,
	xLateEqlno,
	xTransferInWarehouse,
	xTransferToLine
	)
 SELECT *
 FROM "#Sort";

 END IF;

 -- do the dates last as these will propagate to Sort.nx1 via an intelligent trigger.
   UPDATE Eqlists E SET
   E.DateOut = CAST(CAST(E.DateOut AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP),
   E.DateBack = CAST(CAST(E.DateBack AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP),
   E.GetInDate = CAST(CAST(E.GetInDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP),
   E.ShowDate = CAST(CAST(E.ShowDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP),
   E.GetOutDate = CAST(CAST(E.GetOutDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP),
   E.ShowEndDate = CAST(CAST(E.ShowEndDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP),
   E.PrepDate = CAST(CAST(E.PrepDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP),
   E.CheckInDate = CAST(CAST(E.CheckInDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP)
   WHERE
   E.Eql_no = vEqlNo;

 CALL SetEqlistWeightsAndValues(vEqlNo, FALSE);

 RETURN vEqlNo;
END;

/* CloneJob */
CREATE FUNCTION CloneJob(
		aJobID INT,
    aNewClientID INT,
    aNewStatus INT,
    aDaysAdd INT,
    aNewJobTitle VARCHAR(50),
    aDoNotes BOOL)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN

DECLARE vOldClient INT;
DECLARE vNewJobID INT;
DECLARE vSiteID INT;
DECLARE vCurencyID INT;
DECLARE vStart TIMESTAMP;
DECLARE vEnd TIMESTAMP;
DECLARE vDaysAdd INT;

SET vDaysAdd = COALESCE(aDaysAdd, 0);

SELECT * INTO #Jobs
FROM Jobs
WHERE
Jobno = aJobID;

SET vOldClient = (SELECT Client FROM #Jobs);

SET vSiteID = (SELECT PrimarySite FROM #Jobs);
SET vCurencyID = (SELECT Currency FROM #Jobs);
SET vStart = (SELECT J."Due Out" FROM #Jobs J);
SET vStart = CAST(CAST(vStart AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP);
SET vEnd = (SELECT J."Due Back"  FROM #Jobs J);
SET vEnd = CAST(CAST(vEnd AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP);

SET vNewJobID = CreateNewJob(aNewClientID,vSiteID,vCurencyID, vStart,vEnd);

UPDATE Jobs SET
 Status = aNewStatus,
 Job_Title = aNewJobTitle,
 "Type" = (SELECT "Type" FROM #Jobs),
 Handler = (SELECT "Handler" FROM #Jobs),
 SalesPerson = (SELECT "SalesPerson" FROM #Jobs),
 Cellular = (SELECT "Cellular" FROM #Jobs),
 WarehouseSites = (SELECT "WarehouseSites" FROM #Jobs),
 Handler = (SELECT "Handler" FROM #Jobs),
 NewCrewing =  COALESCE((SELECT "NewCrewing" FROM #Jobs),TRUE),
 xCrewManager =  (SELECT "xCrewManager" FROM #Jobs),
 xCrewCoordinator =  (SELECT "xCrewCoordinator" FROM #Jobs),
 xTaxAddress =(SELECT "xTaxAddress" FROM #Jobs),
 xMainVenue = (SELECT xMainVenue FROM #Jobs),
 Notes = CASE WHEN aDoNotes THEN (SELECT Notes FROM #Jobs) ELSE '' END
WHERE
Jobno = vNewJobID;

-- in case user changed address fields
IF EQUIVALENT(vOldClient, aNewClientID) THEN
  UPDATE Jobs SET
  Address1 = (SELECT Address1 FROM #Jobs),
  Address2 = (SELECT Address2 FROM #Jobs),
  Address3 = (SELECT Address3 FROM #Jobs),
  Town = (SELECT Town FROM #Jobs),
  County = (SELECT County FROM #Jobs),
  Postcode = (SELECT Postcode FROM #Jobs),
  Country = (SELECT Country FROM #Jobs),
  Telephone = (SELECT Telephone FROM #Jobs),
  Facsimile = (SELECT Facsimile FROM #Jobs),
  Cellular = (SELECT Cellular FROM #Jobs)
  WHERE
  Jobno = vNewJobID;
END IF;

RETURN vNewJobID;

END;

/* CloneTransport */
CREATE FUNCTION CloneTransport (
		aTransportID INT,
                aJobID INT,
		aOldHeaderID INT,
                aNewHeaderID INT,
		aDaysAdd INT
		)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN

DECLARE vDaysAdd INT;

SET vDaysAdd = COALESCE(aDaysAdd ,0);

-- if aNewHeaderID is NULL then we are cloning only aTransportID, otherwise we clone all Transport entries for aNewHeaderID
	IF aNewHeaderID IS NULL THEN
		SELECT
      aJobID,
			xHeader,
			Vehicle_Type,
			xStatus,
			Qty,
      TripMode,
      CAST(CAST(StartDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS StartDate,
      CAST(CAST(EndDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS EndDate,
      Period,
      PeriodUnitPrice,
      Distance,
      DistanceUnitPrice,
      DistanceChargeMode,
			CollectAddress,
			Charge,
			TaxCharge,
			ChargeIncTax,
      DeliveryAddress,
      Supplier,
      Cost,
      0 AS LastQuotedTotal
		INTO #Transport
		FROM Tranplan
		WHERE TransportCounter = aTransportID;
	ELSE
 	    SELECT
      aJobID,
			aNewHeaderID,
			Vehicle_Type,
			xStatus,
			Qty,
      TripMode,
      CAST(CAST(StartDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS StartDate,
      CAST(CAST(EndDate AS DOUBLE PRECISION) + vDaysAdd AS TIMESTAMP) AS EndDate,
      Period,
      PeriodUnitPrice,
      Distance,
      DistanceUnitPrice,
      DistanceChargeMode,
			CollectAddress,
			Charge,
			TaxCharge,
			ChargeIncTax,
      DeliveryAddress,
      Supplier,
      Cost,
      0 AS LastQuotedTotal
		INTO #Transport
		FROM Tranplan
		WHERE xHeader = aOldHeaderID;
 END IF ;

	-- now the real data
	INSERT INTO Tranplan (
                        Job_number,
			                  xHeader,
			                  Vehicle_Type,
	                    	xStatus,
		                  	Qty,
                        TripMode,
                        StartDate,
                        EndDate,
                        Period,
                        PeriodUnitPrice,
                        Distance,
                        DistanceUnitPrice,
                        DistanceChargeMode,
		                  	CollectAddress,
			                  Charge,
			                  TaxCharge,
			                  ChargeIncTax,
                        DeliveryAddress,
                        Supplier,
                        Cost,
                        LastQuotedTotal)
	SELECT *
	FROM #Transport;

RETURN LASTAUTOINC;

END;

/* CloneTransportHeader */
CREATE FUNCTION CloneTransportHeader (
		aHeaderID INT,
                aJobID INT,
		aDaysAdd INT,
		aCloneTransportDetails BOOLEAN,
                aJobClone BOOLEAN
		)
RETURNS INTEGER
MODIFIES SQL DATA
BEGIN

DECLARE vDaysAdd INT;
DECLARE vCloneTransportDetails BOOLEAN;
DECLARE vNewHeader INT;

SET vDaysAdd = COALESCE(aDaysAdd, 0);
SET vCloneTransportDetails = COALESCE(aCloneTransportDetails, FALSE);

INSERT INTO TranplanHeader (
	xJob,
	xTranplanFunction,
	"Description",
	xStatus
	)
SELECT 	aJobID,
	xTranplanFunction,
 	CAST(CASE
        WHEN aJobClone THEN "Description"
        ELSE  "Description" + ' - CLONE'
        END AS SHORTSTRING(100)),
 	CASE
        WHEN aJobClone THEN (SELECT Status FROM Jobs WHERE Jobno = aJobID)
        ELSE  xStatus
        END
FROM TranplanHeader
WHERE IDX = aHeaderID;

SET vNewHeader = LASTAUTOINC;

-- now the Transport lines
IF vCloneTransportDetails THEN
  CloneTransport(CAST(NULL AS INT),aJobID,aHeaderID,vNewHeader,vDaysAdd);
END IF;


RETURN vNewHeader;

END;

/* CloneType */
CREATE FUNCTION CloneType
( aSourceTypeID INT,
  aNewDescriptSuffix SHORTSTRING (20),
  aNoReminders BOOL,
  aDestClass TINYINT) --  TEquipmentClass = (ecRental, ecConsumable, ecSalesNew, ecSalesExRental);
RETURNS INT
MODIFIES SQL DATA

BEGIN

  DECLARE vSQLString TEXT;
  DECLARE vFields TEXT;
  DECLARE vFieldName VARCHAR(50);
  DECLARE vNewTypeID INT;
  DECLARE vLineEnd VARCHAR(3);

  SET vFields = '';
  SET vLineEnd = chr(13) || chr(10);
  SET vNewTypeID = - 1;

  IF aDestClass IS NULL THEN
     DECLARE cTypes CURSOR
     FOR
     SELECT Field_Name
     FROM #fields
     WHERE
     UPPER(table_name) = 'HETYPE'
	   AND Field_Name NOT IN ('Type','aGUID','Shortcode','ToRental','ToConsumable','ToNewSales','ToExRentalSales');
  ELSE
     DECLARE cTypes CURSOR
     FOR
     SELECT Field_Name
     FROM #fields
     WHERE
     UPPER(table_name) = 'HETYPE'
	   AND Field_Name NOT IN ('Type','aGUID','Shortcode','ToRental','ToConsumable','ToNewSales','ToExRentalSales','Daily','Daily2','Daily3','Daily4');
  END IF;

  OPEN cTypes;
  TRY

  FETCH FIRST
  FROM cTypes
  INTO vFieldName;

  WHILE @@FETCH_STATUS = 0 DO
	      SET vFields = vFields || '"' || vFieldName || '"';

        FETCH NEXT
        FROM cTypes
        INTO vFieldName;

        IF @@FETCH_STATUS = 0 THEN
	         SET vFields = vFields || ',';
        END IF ;
  END WHILE ;

  CLOSE cTypes;

  CATCH TRUE
  CLOSE cTypes;
  SIGNAL ERROR_MESSAGE;
  END;


  SET vSQLString = 'Insert into Hetype' || vLineEnd;
  SET vSQLString = vSQLString + '(' || vFields || ')' || vLineEnd;
  SET vSQLString = vSQLString + 'Select ' || vFields || ' from HeType where "Type" = ' || CAST(aSourceTypeID AS VARCHAR(10));

--CREATE the new type

  EXECUTE IMMEDIATE vSQLString;

  SET vNewTypeID = LASTAUTOINC;

-- change the Description
   IF aNewDescriptSuffix <> '' THEN
      UPDATE Hetype SET
      "description" = "description" || ' [' || aNewDescriptSuffix || ']'
      WHERE
      "Type" = vNewTypeID;
   END IF;

--Do composite components
   INSERT INTO Composit (
   	Mastertype,
	  Componenttype,
	  Quantity,
	  Sortid,
	  Ratio1,
	  Ratio2,
    NoAutoCountOut
   	)
    SELECT vNewTypeID,
    Componenttype,
    Quantity,
	  Sortid,
	  Ratio1,
	  Ratio2,
    NoAutoCountOut
    FROM Composit
    WHERE
    Mastertype = aSourceTypeID
    ORDER BY
    Sortid;

--do reminder / alias components
  IF NOT aNoReminders THEN
     INSERT INTO Related (
     Mastertype,
     Subtype,
	   Quantity,
	   Ratio1,
	   Ratio2,
	   ExcInc,
	   Charge,
	   Required,
	   SortOrder
	   )
    SELECT vNewTypeID,
	  Subtype,
	  Quantity,
	  Ratio1,
	  Ratio2,
	  ExcInc,
	  Charge,
	  Required,
	  SortOrder
    FROM Related
    WHERE
    Mastertype = aSourceTypeID
    ORDER BY
    SortOrder;

  END IF; -- of NOT aNoReminders

-- do Locations
   INSERT INTO TypeLocations
   (xWarehouse,
    xType,
    xLocation	)
    SELECT xWarehouse,
	  vNewTypeID,
	  xLocation
   FROM TypeLocations
   WHERE
   xType = aSourceTypeID;

--do ExtendedPricing
  IF aDestClass IS NULL THEN -- not changing class
   INSERT INTO Ext_PriceMode
	 ("Type",
	 PriceMode,
	 Currency,
   Weekly,
   Rate	)
   SELECT vNewTypeID,
	 PriceMode,
   Currency,
	 Weekly,
	 Rate
   FROM Ext_PriceMode
   WHERE
   "Type" = aSourceTypeID;
  END IF;

  RETURN vNewTypeID;

END;

/* ColumnExists */
CREATE FUNCTION ColumnExists (
	aTableName VARCHAR(50),
	aFieldName VARCHAR(50)
	)
RETURNS BOOLEAN READS SQL DATA
BEGIN
 RETURN
   (SELECT COUNT(*) > 0
    FROM #Fields
    WHERE
    UPPER(Table_Name) = UPPER(aTableName)
    AND
    UPPER(Field_Name) = UPPER(aFieldName));
END;

/* CompositeBookingsNeedChanging */
CREATE FUNCTION CompositeBookingsNeedChanging
( aTypeID INT)
RETURNS BOOL
READS SQL DATA
BEGIN

 RETURN (SELECT COUNT(*) > 0
         FROM "Sort" S
         WHERE
         S."Type" = aTypeID
         AND EXISTS (SELECT S2.LineRef
                     FROM "Sort" S2
                     WHERE
                     S2.LineCode = S.LineRef
                     AND PreppedQty = 0
                     AND D2 > CURRENT_TIMESTAMP));

END;

/* CompositeCanChange */
CREATE FUNCTION CompositeCanChange
( aTypeID INT)
RETURNS TINYINT
READS SQL DATA
-- Return of 0 means Can Change, 1 that composites are still out on Jobs, 2 that composites are allocated to subhires, 3 means 1 and 2 are true
BEGIN

DECLARE vStillOut BOOL;
DECLARE vStillSubhireAllocated BOOL;

  -- 256 to allow users to change composites while they are still out on jobs. Leave old code in here though.
 /*
 SET vStillOut =
        (SELECT COUNT(*) > 0
         FROM "Sort" S
         WHERE
         S."Type" = aTypeID
         AND (SELECT (SUM(S2.PreppedQty) > 0) AND ((SUM(S2.PreppedQty) < SUM(S2.Quant)) OR (SUM(S2.CheckedInQty) < SUM(S2.PreppedQty)))
                         FROM "Sort" S2
                         WHERE
                         S2.LineCode = S.LineRef));
 */

 SET vStillOut = FALSE;

 SET vStillSubhireAllocated =
        (SELECT COUNT(*) > 0
         FROM "Sort" S
         INNER JOIN SubData D
         ON S.LineRef = D.EqlLine
         INNER JOIN Eqlists E
         ON S.Eqlno = E.Eql_no
         WHERE
         S."Type" = aTypeID
         AND S.D2 > CURRENT_TIMESTAMP);

 IF (NOT vStillOut) AND (NOT vStillSubhireAllocated) THEN
    RETURN 0;
 ELSEIF  (vStillOut) AND (NOT vStillSubhireAllocated)  THEN
    RETURN 1;
 ELSEIF  (NOT vStillOut) AND (vStillSubhireAllocated) THEN
    RETURN 2;
 ELSEIF  (vStillOut) AND (vStillSubhireAllocated) THEN
    RETURN 3;
 END IF;

END;

/* CompositeOnListIsOutOfDate */
CREATE FUNCTION CompositeOnListIsOutOfDate
(aMasterType INT,  aLineRef INT )
RETURNS BOOL
READS SQL DATA
BEGIN

 DECLARE vMasterLineQty INT;
 SET vMasterLineQty = (SELECT Quant FROM Sort WHERE LineRef = aLineRef);

 SELECT aMasterType,  S1."Type" AS ComponentType, CAST(S1.Quant / vMasterLineQty AS INT) AS Quantity
 INTO #SortComposites
 FROM "Sort" S1
 WHERE
 S1.LineCode = aLineRef
 AND S1.LineRef <> aLineRef
 ORDER BY S1."Type";

 SELECT aMasterType, ComponentType, Quantity
 INTO #RealComposites
 FROM Composit
 WHERE
 Mastertype = aMasterType
 ORDER BY ComponentType;

 DECLARE vResult BOOL DEFAULT FALSE;

 TRY

 ASSERT TABLE #SortComposites = TABLE #RealComposites;

 CATCH TRUE

 SET vResult = TRUE;

 END;

 RETURN vResult;

END;

/* CreateAuditRecord */
CREATE FUNCTION CreateAuditRecord
(
  pType INT,
  pQuantity INT,
  pDate DATE,
  pUnitPrice MONEY,
  pNotes TEXT ,
  pRef VARCHAR(50),
  pCurrency INT,
  pStockManageOperation TINYINT,
  pSite TINYINT,
  pxStockIn INT,
  pxTransferTo INT,
  pxTransferFrom INT,
  pxWarehouseOpLine INT,
  pDisposalReason TINYINT
)

RETURNS INTEGER

MODIFIES SQL DATA
BEGIN

DECLARE vNewAuditID INT;

INSERT INTO Audit
("Type", Quantity, "Date", UnitPrice,  Notes, Reference, Site,  Currency, StockManageOperation,  xStockIn, xTransferTo, xTransferFrom, xWarehouseOpLine, DisposalReason)
VALUES
(pType,pQuantity, pDate ,pUnitPrice,  pNotes, pRef, pSite,  pCurrency, pStockManageOperation, pxStockIn, pxTransferTo, pxTransferFrom, pxWarehouseOpLine, pDisposalReason);

SET vNewAuditID = LASTAUTOINC;

RETURN vNewAuditID;

END;

/* CreateNewEqlist */
CREATE FUNCTION CreateNewEqlist
--    TWarehouseActivity = (waHire, waJobSubhire, waGlobalSubhire, waJobLoan, waGlobalLoan, waVirtualWarehouseBuild, waStockTransfer, waClassTransfer);
(
aJobNo INT, -- 0 for fake job lists ( waGlobalSubhires, waJobTransfers,  waGlobalTransfers, waVirtualWarehouse )
aStartDate TIMESTAMP,
aEndDate TIMESTAMP,
aStatus SMALLINT, -- -1 for real jobs
aListType SMALLINT, --   cf.. TWarehouseActivity
aSourceWarehouse INT, -- If 0 and real job then get default WH; otherwise it will be <0 for waVirtualWarehouse or >0 for real job with specified WH or transfer donor WH
aDestWarehouse INT, -- only waJobTransfers,  waGlobalTransfers,   , waVirtualWarehouse, otherwise 0
aBorrowingList INT, --  only for waJobTransfers
aEqlistClass TINYINT -- TEqlistClass;
 )

RETURNS INTEGER
 MODIFIES SQL DATA

BEGIN

DECLARE vEqlNo INT;
DECLARE vJobNo INT;
DECLARE vSite INT;
DECLARE vSourceWarehouse SMALLINT;
DECLARE vDestWarehouse SMALLINT;
DECLARE vJobTitle NULLSTRING (50);
DECLARE vClientID INT;
DECLARE vVenueID INT;
DECLARE vClientName NULLSTRING (50);
DECLARE vOut TIMESTAMP;
DECLARE vBack TIMESTAMP;
DECLARE vDonorOutDate TIMESTAMP;
DECLARE vDonorBackDate TIMESTAMP;
DECLARE vMinMinutes INT;
DECLARE vHireDays INT;
DECLARE vCurrency SMALLINT;
DECLARE vPriceScheme INT;
DECLARE vDiscount FLOAT;
DECLARE vStatus INT;
DECLARE vEqlRef VARCHAR(30);
DECLARE vEqlTitle NULLSTRING (50);
DECLARE vSubhire BOOL;
DECLARE vJobNo INT;
DECLARE vSingleDayHire BOOL;
DECLARE vBorrowingList INT;
DECLARE vEqlistClass TINYINT;
DECLARE vPreserveLineDiscounts BOOL;
DECLARE vEqlistCommission DOUBLE PRECISION;
DECLARE vVenueForFinances BOOL;


SET vEqlistCommission = 0;
SET vEqlistClass = COALESCE(aEqlistClass,0);
SET vJobNo = aJobNo;

IF aListType IN (0,1) THEN -- eqlist or subhire for REAL job

  START TRANSACTION;

  TRY
  INSERT INTO aiEqlist (jobno) values (aJobNo);

  SET vEqlNo = (SELECT LASTAUTOINC FROM #Dummy);

  COMMIT;
  CATCH TRUE
   ROLLBACK;
   SIGNAL ERROR_MESSAGE;
  END; --TRY

ELSE -- FAKE job list
  SET vEqlNo = GetNonJobEqlistID;
END IF;

SET vSubhire = aListType in (1,2) ;

SET vSourceWarehouse = aSourceWarehouse;
-- initialize FAKE job list values

SET vStatus = aStatus;
SET vDestWarehouse = aDestWarehouse;
SET vOut = aStartDate;
SET vBack = aEndDate;


-- eqlist or subhire for REAL job
IF aListType IN (0,1) THEN

  SELECT * INTO #Jobs FROM Jobs WHERE jobno = aJobno;

  SET vSite = (SELECT PrimarySite FROM #Jobs);

  -- check is this is a list is NOT booking from a virtual Warehouse or has a specified WH before settting vSourceWarehouse
  IF vSourceWarehouse = 0 THEN
    SET vSourceWarehouse = GetDefaultWarehouseForSite(vSite);
  END IF;

  SET vJobTitle = (SELECT Job_Title FROM #Jobs);

  IF  aListType = 0 THEN
    SET vClientID = (SELECT Client FROM #Jobs);
    SET vVenueID = (SELECT xMainVenue FROM #Jobs);
    SET vClientName = (SELECT "Name" FROM #Jobs);
	  SET vVenueForFinances = (SELECT JobCommissionFromVenue FROM #Jobs);

     IF (SELECT xVenueCommission FROM RULES WHERE SiteID = vSite) IN (3,4) THEN  --  TVenueCommissionApplication = (vcaNever, vcaManual, vcaAutomatic, vcaPromptForJob, vcaAdvancedForJob);

       DECLARE vCompanyForCommission INT;

       IF vVenueForFinances THEN
          SET vCompanyForCommission = vVenueID;
       ELSE
          SET vCompanyForCommission = vClientID;
       END IF;

       SELECT RentalVenueCommission,CrewVenueCommission,TransportVenueCommission, MiscVenueCommission
       INTO #DefaultCommissions
       FROM Company
       WHERE
       CompanyCounter = vCompanyForCommission;

       SET vEqlistCommission = COALESCE((SELECT RentalVenueCommission FROM Company WHERE CompanyCounter = vCompanyForCommission),0);

     END IF;

  END IF;

  SET vCurrency = COALESCE((SELECT Currency FROM #Jobs),0);

  SET vEqlRef = TOSTRINGLEN(GetNewEqlistRef(aJobNo, vEqlNo, aListType, vEqlistClass),30);
  SET vEqlTitle = TOSTRINGLEN(vJobTitle  || ':' || vEqlRef,50) ;

	IF FunctionExists('CustomEqlistStart') THEN
		SET vOut = CustomEqlistStart(aJobno, vOut, aListType, aEqlistClass);
	ELSEIF vOut < CURRENT_TIMESTAMP  then
		SET vOut = CURRENT_TIMESTAMP;
	END IF;

	IF FunctionExists('CustomEqlistEnd') THEN
		SET vBack = CustomEqlistEnd(aJobno, vBack, aListType, aEqlistClass);
	ELSEIF vBack < CURRENT_TIMESTAMP THEN
		SET vBack = DATEADD('dd', CURRENT_TIMESTAMP, 1);
	END IF;

  IF vOut = vBack THEN
   SET vBack = DATEADD('dd', vBack, 1);
  END IF;

  -- now Virtual jobs in the ELSEIFs
ELSEIF  aListType in (2) THEN -- global subhire
   SET vEqlRef = TOSTRINGLEN(GetNewEqlistRef(aJobNo, vEqlNo, aListType, vEqlistClass),30);
   IF vEqlistClass = 0 THEN
      SET vEqlTitle = 'Global Subhire List'  ;
   ELSE
      SET vEqlTitle = 'Global Sales Order List'  ;
   END IF;

ELSEIF  aListType in (3) THEN -- Job Loan
   SET vEqlRef = GetJobLoanEqRef(aBorrowingList) ;
   SET vEqlTitle = 'Job Loans List'  ;
   SET vBorrowingList = aBorrowingList;

ELSEIF aListType in (4) THEN  -- Global Loan
   SET vEqlRef = TOSTRINGLEN(GetNewEqlistRef(aJobNo, vEqlNo, aListType, vEqlistClass),30);
   SET vEqlTitle = 'Global Loans List'  ;

ELSEIF aListType in (5) THEN -- Virtual Warehouse
   SET vEqlRef = TOSTRINGLEN(GetNewEqlistRef(aJobNo, vEqlNo, aListType, vEqlistClass),30);
   SET vEqlTitle = 'Virtual Warehouse List'  ;

ELSEIF aListType in (6) THEN -- Warehouse Transfer List
   SET vEqlRef = TOSTRINGLEN(GetNewEqlistRef(aJobNo, vEqlNo, aListType, vEqlistClass),30);
   IF vEqlistClass = 0 THEN
      SET vEqlTitle = 'Rental Warehouse Transfer List'  ;
   ELSE
      SET vEqlTitle = 'Sales Warehouse Transfer List'  ;
   END IF;
ELSEIF aListType in (7) THEN -- Class Transfer List
   SET vEqlRef = TOSTRINGLEN(GetNewEqlistRef(aJobNo, vEqlNo, aListType, vEqlistClass),30);
   IF vEqlistClass = 0 THEN
      SET vEqlTitle = 'Rental Class Transfer List'  ;
   ELSE
      SET vEqlTitle = 'Sales Class Transfer List'  ;
   END IF;
END IF;

-- bit more on Virtual job lists
IF aListType > 1 THEN
  SET vCurrency = GetCurrencyForSite(GetSiteIDFROMWarehouseID(vSourceWarehouse));
END IF;

IF aListType IN (3,4) THEN -- loans

  SET vMinMinutes = COALESCE((SELECT Hours * 60
                     FROM
                     WarehouseTransitTimes
                     WHERE
                     WarehouseFrom =  aSourceWarehouse
                     AND WarehouseTo = aDestWarehouse),10);

  IF vMinMinutes = 0 THEN
    SET vMinMinutes = 10; -- need some value > 0 time for availability checking to work
  END IF;

  -- is a loan list then the dates params passed to this routine will come from PrepDate/CheckIn Date and the transit time will have
  -- already been taken into account. So cancel out transit time so that the Out and Back dates reflect the RequiredBy and RequiredUntil for borrowing list.
  SET vDonorOutDate = vOut;

  IF aListType IN (3,4) THEN
     SET vDonorBackDate = vBack;
  END IF;

  SET vOut = CAST(CAST(vOut AS DOUBLE PRECISION) + CAST(vMinMinutes / 1440 AS DOUBLE PRECISION) AS DATETIME);

  IF aListType IN (3,4) THEN
     SET vBack = CAST(CAST(vBack AS DOUBLE PRECISION) - CAST(vMinMinutes / 1440 AS DOUBLE PRECISION) AS DATETIME);
  END IF;

END IF;

SET vHireDays = DATEDIFF('dd',CAST(vOut AS DATE),CAST(vBack AS DATE));
SET vSingleDayHire = DATEDIFF('mi',vOut ,vBack ) <=1440 ;

IF vHireDays = 0 THEN
 SET vHireDays = 1;
END IF;

-- more REAL job eqlist stuff
IF  aListType = 0 THEN

  IF GetAddExtraHireDay(vSite) AND NOT vSingleDayHire THEN
    SET vHireDays = vHireDays + 1;
  END IF;

  IF vVenueForFinances THEN
	   SET vPriceScheme = GetClientPriceScheme(vVenueID,vSite,vCurrency);
	   SET vDiscount = GetClientDiscount(vVenueID, vSubhire, aEqlistClass);
  ELSE
	    SET vPriceScheme = GetClientPriceScheme(vClientID,vSite,vCurrency);
	    SET vDiscount = GetClientDiscount(vClientID, vSubhire, aEqlistClass);
  END IF;

-- else Virtual job
ELSE
  SET vPriceScheme = 0;
  SET vDiscount = 0;
END IF;

IF vSite IS NULL THEN
   SET vSite = 1;
END IF;

SET vPreserveLineDiscounts = COALESCE((SELECT PreserveLineDiscounts FROM Rules WHERE SiteID = vSite),FALSE);

INSERT INTO Eqlists (
	eql_no,
	job_no,
	eql_title,
	Venue_no,
	DateOut,
	DateBack,
	PrepDate,
	CheckInDate,
	DefCon,
	Eql_name,
	Client_No,
	Client_Name,
	Discount,
	Subhire,
	HireDays,
	StartDays,
	Venue_Name,
	MainSite,
	xTransferInWarehouse,
	PriceMode,
	ListType,
  PrepAvail,
  CheckInAvail,
	xTransferToList,
  PreserveLineDiscounts,
  Selected,
  EqlistClass,
  IncomeCommission,
  ExpenditureCommission
	)
VALUES (
	vEqlNo,
	vJobNo,
	vEqlTitle,
	vVenueID,
	vOut,
	vBack,
	vDonorOutDate,
	vDonorBackDate,
	vStatus,
	vEqlRef,
	vClientID,
	vClientName,
	vDiscount,
	vSubhire,
	vHireDays,
	vPriceScheme,
	vClientName,
	vSourceWarehouse,
	vDestWarehouse,
	vCurrency,
	aListType,
  (aListType IN (3,4)), -- loans use PrepAvail
  (aListType IN (3,4)), -- loans use CheckInAvail
	vBorrowingList,
  vPreserveLineDiscounts,
  (aListType = 0),
  vEqlistClass,
  vEqlistCommission,
  vEqlistCommission
	);

RETURN (vEqlNo);

END;

/* CreateNewInvoice */
CREATE FUNCTION CreateNewInvoice
(aJobNo INT,
 aDocType BYTE, -- 0 or 1 (cf TAccountsDocument)
 aInvoiceOptions TEXT ,
 aXInvoice INT,
 aSite BYTE,
 aClient INT
 )
RETURNS INT
 MODIFIES SQL DATA
BEGIN

DECLARE vNewInvID  INT;
DECLARE vSiteID BYTE;
DECLARE vCurrency BYTE;
DECLARE vClient INT;

SELECT * INTO #Jobs FROM Jobs WHERE Jobno = aJobNo;

IF aJobNo IS NULL THEN
 SET vSiteID = aSite ;
 SET vCurrency = (SELECT xCurrency FROM Sites WHERE IDX = vSiteID);
 SET vClient = aClient;
ELSE
 SET vSiteID =  (SELECT PrimarySite FROM #Jobs);
 SET vCurrency =  (SELECT Currency FROM #Jobs);
 IF  (SELECT JobCommissionFromVenue FROM #Jobs) THEN
     SET vClient = (SELECT xMainVenue FROM #Jobs);
 ELSE
     SET vClient = (SELECT Client FROM #Jobs);
 END IF;
END IF;

-- first, the invoice

INSERT INTO Invoice
(Job, DocType, Our_Ref, Your_Ref, Client, Currency, PrimarySite,InvoicingOptions, xInvoice)
VALUES
(aJobNo,
 aDocType,
 (SELECT COALESCE(Job_Ref,'') FROM #Jobs),
 (SELECT COALESCE(OrderNumber,'') FROM #Jobs),
  vClient,
  vCurrency,
  vSiteID,
  aInvoiceOptions,
  aXInvoice
 );

SET vNewInvID = (Select LASTAUTOINC from #Dummy);

-- set the invoice ref/number
IF ProcedureExists('SetMultiSiteInvoiceNumber') THEN
  CALL SetMultiSiteInvoiceNumber(vNewInvID, vSiteID, aDocType);
ELSE

 UPDATE Invoice I SET
  I.Inv_No = GetNewInvoiceNumber(vNewInvID,aDocType,vSiteID)
 WHERE
 I.Invoice_count = vNewInvID;

END IF;

-- finally return value
RETURN vNewInvID;

END;

/* CreateNewJob */
CREATE FUNCTION CreateNewJob
( aClient integer,
  aSite integer,
  aCurrency integer,
  aStartDate TimeStamp,
  aEndDate TimeStamp
  )
RETURNS INTEGER MODIFIES SQL DATA

BEGIN
	DECLARE vStatus INTEGER;
	DECLARE vName VARCHAR(50);
	DECLARE vAddress1 VARCHAR(50);
	DECLARE vAddress2 VARCHAR(50);
	DECLARE vAddress3 VARCHAR(50);
	DECLARE vTown VARCHAR(50);
	DECLARE vCounty VARCHAR(50);
	DECLARE vCountry VARCHAR(50);
	DECLARE vTelephone VARCHAR(50);
	DECLARE vFacsimilie VARCHAR(50);
	DECLARE vPostCode VARCHAR(50);
	DECLARE vCellular VARCHAR(50);
	DECLARE vWarehouseSites BIGINT;

	SET vStatus = GetDefaultJobStatus(aSite);

	SET vWarehouseSites = (
			SELECT WarehouseSites
			FROM Sites
			WHERE IDX = aSite
			);
	SET vName = (
			SELECT CompanyName
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vAddress1 = (
			SELECT Address1
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vAddress2 = (
			SELECT Address2
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vAddress3 = (
			SELECT Address3
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vTown = (
			SELECT Town
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vCounty = (
			SELECT County
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vCountry = (
			SELECT Country
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vTelephone = (
			SELECT MainTelephone
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vFacsimilie = (
			SELECT MainFax
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vPostCode = (
			SELECT PostCode
			FROM Company
			WHERE CompanyCounter = aClient
			);
	SET vCellular = (
			SELECT Cellular
			FROM Company
			WHERE CompanyCounter = aClient
			);

	INSERT INTO Jobs (
		client,
		"Name",
		STATUS,
		Job_Title,
		"Due Out",
		"Due Back",
		Venue,
		Address1,
		Address2,
		Address3,
		Town,
		County,
		Country,
		Telephone,
		Facsimile,
		PostCode,
		Cellular,
		PrimarySite,
		Currency,
		WarehouseSites
		)
	VALUES (
		CASE
			WHEN aClient > 0
				THEN aClient
			ELSE NULL
			END,
		vName,
		vStatus,
		'New Job',
		aStartDate,
		aEndDate,
		aClient,
		vAddress1,
		vAddress2,
		vAddress3,
		vTown,
		vCounty,
		vCountry,
		vTelephone,
		vFacsimilie,
		vPostCode,
		vCellular,
		aSite,
		aCurrency,
		vWarehouseSites
		);

	RETURN LASTAUTOINC;


END;

