/* CreateNewOrder */
CREATE FUNCTION CreateNewOrder
(aJobNo INT, -- null if raised for a Global list
 aDocType BYTE, --(cf TAccountsDocument)
 aSupplier INT,
 isCompany BOOL,
 aInvoiceOptions TEXT ,
 aXOrder INT,
 aSite BYTE,
 aCurrency BYTE -- null if raised for a Job
 )
RETURNS INT
 MODIFIES SQL DATA
BEGIN

DECLARE vNewOrdID  INT;
DECLARE vSiteID BYTE;
DECLARE vCurrency BYTE;
DECLARE vOurRef VARCHAR(30);

SELECT * INTO #Jobs FROM Jobs WHERE Jobno = aJobNo;

IF aJobNo IS NULL THEN
 SET vSiteID = aSite ;
 SET vCurrency = aCurrency;
 SET vOurRef = '';
ELSE
 SET vSiteID =  (SELECT PrimarySite FROM #Jobs);
 SET vCurrency =  (SELECT Currency FROM #Jobs);
 SET vOurRef = (SELECT Job_Ref FROM #Jobs);
END IF;

-- first, the Order

INSERT INTO POrder
(Job, DocType, Our_Ref, Client, Company, Currency, PrimarySite, InvoicingOptions, xOrder )
VALUES
(aJobNo,
 aDocType,
 vOurRef,
 aSupplier,
 isCompany,
