-- set the Order ref/number
UPDATE POrder I
SET I.Inv_No = GetNewOrderNumber(vNewOrdID, aDocType, vSiteID)
WHERE I.Invoice_count = vNewOrdID;

-- finally return value
RETURN vNewOrdID;

