/* CreateNewRepair */
CREATE FUNCTION CreateNewRepair
(aType INT, aOwnerWarehouseID INT, aRepairingWarehouseID INT, aCurrency TINYINT, aItem INT, aIsActive BOOL)
RETURNS INT
MODIFIES SQL DATA
BEGIN

 START TRANSACTION;

 TRY

 DECLARE vLastEqlist INT;
 DECLARE vRepairDays INT;
 DECLARE vSiteID INT;
 DECLARE vRepairID INT;
 DECLARE vSortStatus TINYINT;
 DECLARE vCommissionStatus TINYINT; --   TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bscDisposed, bscLoggedForRepair);

 SET vSiteID = GetSiteIDFromWarehouseID(aRepairingWarehouseID);
 SET vRepairDays = (SELECT DefaultRepairDays FROM Rules WHERE SiteID = vSiteID);

 IF aIsActive THEN
    SET vSortStatus = 4; --Active
    SET vCommissionStatus = 2; -- bcsInRepair
 ELSE
    SET vSortStatus = 1; --Quote
    SET vCommissionStatus = 5; -- bscLoggedForRepair
 END IF;

 IF aItem IS NOT NULL THEN
    SET vLastEqlist = COALESCE((SELECT CurrentJob FROM Item WHERE ItemRef  = aItem),1);

    IF vLastEqlist IN (0,1) THEN -- repair or never been on job
       SET vLastEqlist = NULL;
    END IF;
 END IF;


 INSERT INTO "Sort"
 (Eqlno, Quant, Type, xCat, D1, D2, Defcon, Slink1, Slink2, xRepairStatus, ListType)
 VALUES
 (0,1,aType,
 (SELECT Category FROM Hetype WHERE Type = aType),
  CURRENT_TIMESTAMP, CAST(CAST(CURRENT_TIMESTAMP AS REAL) + vRepairDays AS TIMESTAMP),
  vSortStatus, aOwnerWarehouseID, aRepairingWarehouseID, 0, 0);

 SET vRepairID = LASTAUTOINC;

 -- make it possible to appear in the Late Returns View. The "update" causes trigger to set Sort.NotBack
 IF aIsActive THEN
    UPDATE "SORT" SET PreppedQty = 1, "Out" = 1 WHERE LineRef = vRepairID;
 END IF;


 CreateNewService(aType, aCurrency, vRepairID, aItem, vLastEqlist, 1); --TServiceType = (stService, stRepair)

 IF aItem IS NOT NULL THEN
    UPDATE "Item" SET CommissionStatus = vCommissionStatus, Lastservice = aOwnerWarehouseID WHERE ItemRef = aItem;
 END IF;

 COMMIT;

 CATCH TRUE
 ROLLBACK;
 SIGNAL ERROR_MESSAGE;
 END;

 RETURN vRepairID;

END;

/* CreateNewService */
CREATE FUNCTION CreateNewService
(aType INT,
 aCurrency TINYINT,
 aRepairLineRef INT,
 aItem INT,
 aLastEqlistID INT,
 aServiceType TINYINT)
RETURNS INT
MODIFIES SQL DATA
BEGIN

 INSERT INTO "servdata"
 (xType, Service_date, itemRef, xRepairLineRef, Currency, xBadEqlno, Estimate, ServiceType)
 VALUES
 (aType,CURRENT_TIMESTAMP, aItem, aRepairLineRef, aCurrency, aLastEqlistID,
  CASE
      WHEN aLastEqlistID IS NULL THEN 0.00
  ELSE
  COALESCE((SELECT CASE
          WHEN aCurrency = 0 THEN Replacement
          WHEN aCurrency = 1 THEN Replacement2
          WHEN aCurrency = 2 THEN Replacement3
          WHEN aCurrency = 3 THEN Replacement4
          END
          FROM Hetype
          WHERE
          Type = aType),0)
          END,
          aServiceType );

 RETURN LASTAUTOINC;

END;

/* CreatePAT_Data_asstring */
CREATE FUNCTION CreatePAT_Data_asstring
(TestType BYTE,
TestResult BCD,
Status BYTE,
UserTestUnits VarChar(16),
UserTestResult VarChar(31)
)
RETURNS VarChar(255)
// Generates the PAT test results string
BEGIN
DECLARE TestString VARCHAR(255);
DECLARE StatusString VARCHAR(255);
DECLARE UnitsString VARCHAR(10);
DECLARE vTestType VARCHAR(3);

SET vTestType = NumberToHex(TestType);

   SET UnitsString = (
   CASE
   WHEN  vTestType = '#01' THEN ''
   WHEN  vTestType = '#0E' THEN 'ohms'
   WHEN  vTestType = '#0F' THEN 'ohms'
   WHEN  vTestType = '#11' THEN 'ohms'
   WHEN  vTestType = '#12' THEN 'ohms'
   WHEN  vTestType = '#16' THEN 'ohms'
   WHEN  vTestType = '#17' THEN 'ohms'
   WHEN  vTestType = '#18' THEN 'ohms'
   WHEN  vTestType = '#20' THEN 'Megaohms'
   WHEN  vTestType = '#21' THEN 'Megaohms'
   WHEN  vTestType = '#22' THEN 'Megaohms'
   WHEN  vTestType = '#53' THEN 'mA'
   WHEN  vTestType = '#54' THEN 'mA'
   WHEN  vTestType = '#40' THEN 'mA'
   WHEN  vTestType = '#83' THEN 'mA'
   WHEN  vTestType = '#90' THEN 'kVA'
   WHEN  vTestType = '#91' THEN ''
   WHEN  vTestType = '#92' THEN 'volts'
   WHEN  vTestType = '#96' THEN 'amps'
   WHEN  vTestType = '#93' THEN 'volts'
   WHEN  vTestType = '#94' THEN 'volts'
   WHEN  vTestType = '#97' THEN 'ohms'
   WHEN  vTestType = '#98' THEN 'milliseconds'
   WHEN  vTestType = '#99' THEN 'milliseconds'
   WHEN  vTestType = '#9A' THEN 'milliseconds'
   WHEN  vTestType = '#9B' THEN 'milliseconds'
   WHEN  vTestType = '#9C' THEN ''
   WHEN  vTestType = '#FC' THEN ''
   WHEN  vTestType = '#FD' THEN ''
   ELSE 'UNKNOWN'
   END
   );

   IF vTestType = '#FD' THEN SET UnitsString = UserTestUnits;
   END IF;

   IF vTestType = '#FC' THEN SET UnitsString = UserTestUnits;
   END IF;

   SET StatusString = '';

   IF NOT STATUS IS NULL THEN
   IF UnitsString <> '' THEN
   // BIT 7 & BIT 6
   IF BITAND(STATUS, 196) = 196 THEN SET StatusString = 'Reversed';
   ELSEIF BITAND(STATUS, 128) = 128 THEN SET StatusString = 'DC-Only';
   ELSEIF BITAND(STATUS, 64) = 64 THEN SET StatusString = 'AC-Only';
   ELSE SET StatusString = ''; //'AC-DC';
   END IF;

   // IF BIT 2 SET THEN Value is Null
   IF BITAND(STATUS, 4) = 0 THEN
      IF BITAND(STATUS, 32) = 32 THEN SET StatusString = StatusString + ' >'; //BIT 5
      ELSEIF BITAND(STATUS, 16) = 16 THEN SET StatusString = StatusString + ' <'; //BIT 4
      ELSE SET StatusString = StatusString + ' ';
      END IF;


      IF BITAND(STATUS, 8) = 8 THEN SET StatusString = StatusString + ' -'; // BIT 3
      END IF;

      IF vTestType = '#FC' THEN
      SET StatusString = StatusString + UserTestResult;
      SET StatusString = StatusString + ' '+ UserTestUnits;
      ELSE
      SET StatusString = StatusString + CAST(TestResult as VarChar(10));
      SET StatusString = StatusString + ' '+ UnitsString;
      END IF;
   END IF;

   END IF;


   END IF; //status = null (test 9C


   IF vTestType = '#91' THEN SET StatusString =(
   CASE
//   WHEN TestResult = 1 THEN 'PASS'
   WHEN TestResult = 2 THEN 'Live Open'
   WHEN TestResult = 3 THEN 'Live / Neutral reversed'
   WHEN TestResult = 4 THEN 'Live / Neutral short'
   WHEN TestResult = 5 THEN 'Neutral open'
   WHEN TestResult = 6 THEN 'Live / Neutral Open'
   WHEN TestResult = 0 THEN 'Test not complete'
   END
   );
   END IF;


   IF vTestType = '#9C' THEN SET StatusString =(
   CASE
//   WHEN TestResult = 1 THEN 'PASS'
   WHEN TestResult = 2 THEN 'Missing Earth'
   WHEN TestResult = 3 THEN 'Voltage Out of range'
   WHEN TestResult = 4 THEN 'Reversed Polarity'
   WHEN TestResult = 5 THEN 'No voltage detected'
   END
   );
   END IF;


RETURN  StatusString;
END;

