/* CreatePATResults_asboolean */
CREATE FUNCTION CreatePATResults_asboolean
(TestType BYTE,
TestResult BCD,
Status BYTE
)
RETURNS Boolean

BEGIN
DECLARE PASS boolean;
DECLARE vTestType VARCHAR(3);
SET vTestType = NumberToHex(TestType);
SET PASS = null;


   IF NOT STATUS IS NULL THEN

   IF BITAND(STATUS, 3) <> 0 THEN // IF BIT 1 & BIT 0 are 0 then INFO only
      IF BITAND(STATUS, 2) = 2 THEN
       SET PASS = FALSE;
      ELSEIF BITAND(STATUS, 1) = 1 THEN
        SET PASS = TRUE;
      END IF;
   END IF;
   END IF; //status = null (test 9C


   IF vTestType = '#91' THEN
      IF TestResult = 1 THEN SET PASS = TRUE; ELSE SET PASS = FALSE; END IF;
   END IF;


   IF vTestType = '#9C' THEN
      IF TestResult = 1 THEN SET PASS = TRUE; ELSE SET PASS = FALSE; END IF;
   END IF;



RETURN  PASS;
END;

