/* DayOfWeek */
CREATE FUNCTION DayOfWeek(aDate Date)
RETURNS SmallInt
BEGIN
DECLARE vResult SmallInt;
DECLARE vYear INT;
DECLARE vSpecialMonth INT;

/*
-- Sunday = 0
-- Saturday = 6
*/

SET vSpecialMonth = CASE
WHEN EXTRACT(MONTH FROM aDate) = 1 THEN 0
WHEN EXTRACT(MONTH FROM aDate) = 2 THEN 3
WHEN EXTRACT(MONTH FROM aDate) = 3 THEN 3
WHEN EXTRACT(MONTH FROM aDate) = 4 THEN 6
WHEN EXTRACT(MONTH FROM aDate) = 5 THEN 1
WHEN EXTRACT(MONTH FROM aDate) = 6 THEN 4
WHEN EXTRACT(MONTH FROM aDate) = 7 THEN 6
WHEN EXTRACT(MONTH FROM aDate) = 8 THEN 2
WHEN EXTRACT(MONTH FROM aDate) = 9 THEN 5
WHEN EXTRACT(MONTH FROM aDate) = 10 THEN 0
WHEN EXTRACT(MONTH FROM aDate) = 11 THEN 3
WHEN EXTRACT(MONTH FROM aDate) = 12 THEN 5

END;

SET vYear = EXTRACT(YEAR FROM aDate);
SET vResult = vYear   + CAST(vYear / 4 as INT);
SET vResult = vResult - CAST(vYear / 100 as INT);
SET vResult = vResult + CAST(vYear / 400 as INT);
SET vResult = vResult + EXTRACT(DAY FROM aDate);
SET vResult = vResult + vSpecialMonth;
SET vResult = vResult -1;
SET vResult = MOD(vResult, 7);

RETURN vResult;

END;

