/* F_FORMATDATE */
CREATE FUNCTION F_FORMATDATE(IN_DATE Date)
   RETURNS ShortString(20)
   DETERMINISTIC
begin
   // Format as DD-MMM-YY
   DECLARE S ShortString(20);
   DECLARE N INTEGER;
   SET N = EXTRACT(DAY FROM IN_DATE);
   IF N < 10 THEN
     SET S = '0' || TOSTRING(N) || '-';
   ELSE
     SET S = TOSTRING(N) || '-';
   END IF;
   SET N = EXTRACT(MONTH FROM IN_DATE);
   SET S = S ||
     CASE N
       WHEN 1 THEN 'Jan'
       WHEN 2 THEN 'Feb'
       WHEN 3 THEN 'Mar'
       WHEN 4 THEN 'Apr'
       WHEN 5 THEN 'May'
       WHEN 6 THEN 'Jun'
       WHEN 7 THEN 'Jul'
       WHEN 8 THEN 'Aug'
       WHEN 9 THEN 'Sep'
       WHEN 10 THEN 'Oct'
       WHEN 11 THEN 'Nov'
       WHEN 12 THEN 'Dec'
     END || '-';
   SET N = EXTRACT(YEAR FROM IN_DATE);
   SET N = N - (N / 100) * 100;
   IF N < 10 THEN
     SET S = S || '0' || TOSTRING(N);
   ELSE
     SET S = S || TOSTRING(N);
   END IF;
   RETURN S ;
end;

/* FormatCurrency */
CREATE FUNCTION FormatCurrency(Value REAL, SchemeParam  SMALLINT)

RETURNS SHORTSTRING(50)
READS SQL DATA
BEGIN
  DECLARE CurrencyString SHORTSTRING(5);
  DECLARE CurrencyFormat SMALLINT;
  DECLARE NegCurrFormat SMALLINT;
  DECLARE ThousandSep SHORTSTRING;
  DECLARE DecimalSep SHORTSTRING;
  DECLARE Decimals SMALLINT;
  DECLARE IsNegative SMALLINT;
  DECLARE AbsValue REAL;
  DECLARE IntPart INT;
  DECLARE DecPart SHORTSTRING(30);
  DECLARE FormattedInt SHORTSTRING(30);
  DECLARE Result SHORTSTRING(50);
  DECLARE Temp SHORTSTRING(30);
  DECLARE Len INT;
  DECLARE i INT;
  DECLARE Counter INT;
  DECLARE iTemp INT;

  -- Get currency formatting details from CURRENCY table
  -- NOTE: the column Crystal is used as the Currency lookup values in all the core tables like Jobs.Currency etc are 0 based, e.g. 0..3 as the range.
  -- So when passing a SchemeParam to this function you would be using Jobs.Curency, or Invoice.Currency and so the Crystal 0,1,2 or 3 possible values will be searched on
  SET CurrencyString = (SELECT CurrencyString FROM CURRENCY WHERE Crystal = SchemeParam);
  SET CurrencyFormat = (SELECT CurrencyFormat FROM CURRENCY WHERE Crystal = SchemeParam);
  SET NegCurrFormat = (SELECT NegCurrFormat FROM CURRENCY WHERE Crystal = SchemeParam);
  SET ThousandSep = (SELECT ThousandSeparator FROM CURRENCY WHERE Crystal = SchemeParam);
  SET DecimalSep = (SELECT DecimalSeparator FROM CURRENCY WHERE Crystal = SchemeParam);
  SET Decimals = (SELECT CurrencyDecimals FROM CURRENCY WHERE Crystal = SchemeParam);


  -- Check if currency scheme exists
  IF CurrencyString IS NULL THEN
    RETURN CAST(Value AS SHORTSTRING);
  END IF;

  -- Determine if value is negative
  IF Value < 0 THEN
    SET IsNegative = 1;
    SET AbsValue = Value * -1;
  ELSE
    SET IsNegative = 0;
    SET AbsValue = Value;
  END IF;

 -- Round to specified decimal places
  IF Decimals = 2 THEN
    SET AbsValue = ROUND(AbsValue * 100) / 100;
  ELSEIF Decimals = 3 THEN
    SET AbsValue = ROUND(AbsValue * 1000) / 1000;
  END IF;


  -- Split into integer and decimal parts
  SET IntPart = FLOOR(AbsValue);

  IF Decimals = 2 THEN
  SET iTemp = ROUND((AbsValue - IntPart) * 100);
    SET DecPart = CAST(iTemp AS SHORTSTRING(30));
  ELSEIF Decimals = 3 THEN
    SET DecPart = CAST((ROUND((AbsValue - IntPart) * 1000)) AS SHORTSTRING(30));
  END IF;
  -- Pad decimal part with leading zeros if necessary
  WHILE CHAR_LENGTH (DecPart) < Decimals DO
    SET DecPart = '0' || DecPart;
  END WHILE;

  -- Format integer part with thousand separators
  SET Temp = CAST(IntPart AS SHORTSTRING(30));
  SET Len = CHAR_LENGTH (Temp);
  SET FormattedInt = '';
  SET Counter = 0;
  SET i = Len;

  WHILE i > 0 DO
    IF Counter = 3 AND i > 0 THEN
      SET FormattedInt = ThousandSep || FormattedInt;
      SET Counter = 0;
    END IF;
    SET FormattedInt = SUBSTRING(Temp FROM i FOR 1) || FormattedInt;
    SET Counter = Counter + 1;
    SET i = i - 1;
  END WHILE;

  -- Combine integer and decimal parts
  IF Decimals > 0 THEN
    SET Result = FormattedInt || DecimalSep || DecPart;
  ELSE
    SET Result = FormattedInt;
  END IF;

  -- Apply currency formatting for positive values
  IF IsNegative = 0 THEN
    IF CurrencyFormat = 0 THEN
      -- $1.1
      SET Result = CurrencyString || Result;
    ELSEIF CurrencyFormat = 1 THEN
      -- 1.1$
      SET Result = Result || CurrencyString;
    ELSEIF CurrencyFormat = 2 THEN
      -- $ 1.1
      SET Result = CurrencyString || ' ' || Result;
    ELSE
      -- 1.1 $ (format 3 or default)
      SET Result = Result || ' ' || CurrencyString;
    END IF;
  ELSE
    -- Apply negative currency formatting
    IF NegCurrFormat = 0 THEN
      -- ($1.1)
      SET Result = '(' || CurrencyString || Result || ')';
    ELSEIF NegCurrFormat = 1 THEN
      -- -$1.1
      SET Result = '-' || CurrencyString || Result;
    ELSEIF NegCurrFormat = 2 THEN
      -- $-1.1
      SET Result = CurrencyString || '-' || Result;
    ELSEIF NegCurrFormat = 3 THEN
      -- $1.1-
      SET Result = CurrencyString || Result || '-';
    ELSEIF NegCurrFormat = 4 THEN
      -- (1.1$)
      SET Result = '(' || Result || CurrencyString || ')';
    ELSEIF NegCurrFormat = 5 THEN
      -- -1.1$
      SET Result = '-' || Result || CurrencyString;
    ELSEIF NegCurrFormat = 6 THEN
      -- 1.1-$
      SET Result = Result || '-' || CurrencyString;
    ELSEIF NegCurrFormat = 7 THEN
      -- 1.1$-
      SET Result = Result || CurrencyString || '-';
    ELSEIF NegCurrFormat = 8 THEN
      -- -1.1 $
      SET Result = '-' || Result || ' ' || CurrencyString;
    ELSEIF NegCurrFormat = 9 THEN
      -- -$ 1.1
      SET Result = '-' || CurrencyString || ' ' || Result;
    ELSEIF NegCurrFormat = 10 THEN
      -- 1.1 $-
      SET Result = Result || ' ' || CurrencyString || '-';
    ELSEIF NegCurrFormat = 11 THEN
      -- $ 1.1-
      SET Result = CurrencyString || ' ' || Result || '-';
    ELSEIF NegCurrFormat = 12 THEN
      -- $ -1.1
      SET Result = CurrencyString || ' -' || Result;
    ELSEIF NegCurrFormat = 13 THEN
      -- 1.1- $
      SET Result = Result || '- ' || CurrencyString;
    ELSEIF NegCurrFormat = 14 THEN
      -- ($ 1.1)
      SET Result = '(' || CurrencyString || ' ' || Result || ')';
    ELSE
      -- (1.1 $) (format 15 or default)
      SET Result = '(' || Result || ' ' || CurrencyString || ')';
    END IF;
  END IF;

  RETURN Result;
END;

/* FormatTime */
CREATE FUNCTION FormatTime
(aTime Time, a24h boolean, aAM varchar(10), aPM varchar(10))
RETURNS varchar(20)
READS SQL DATA
BEGIN

	IF (a24h = TRUE) THEN
		RETURN(
		CASE
		WHEN EXTRACT(HOUR FROM aTime) > 9
		THEN TOSTRING(EXTRACT(HOUR FROM aTime))
		ELSE '0' || TOSTRING(EXTRACT(HOUR FROM aTime))
		END
		+ ':'
		+
		CASE
		WHEN EXTRACT(MINUTE FROM aTime) > 9
		THEN TOSTRING(EXTRACT(MINUTE FROM aTime))
		ELSE '0' || TOSTRING(EXTRACT(MINUTE FROM aTime))
		END);

		ELSE

		RETURN (
		CASE
		WHEN EXTRACT(HOUR FROM aTime) > 12
		THEN TOSTRING(EXTRACT(HOUR FROM (aTime - INTERVAL '12' HOUR)))
		ELSE
		TOSTRING(EXTRACT(HOUR FROM aTime))
		END
		+ ':'
		+
		CASE
		WHEN EXTRACT(MINUTE FROM aTime) > 9
		THEN TOSTRING(EXTRACT(MINUTE FROM aTime))
		ELSE '0' || TOSTRING(EXTRACT(MINUTE FROM aTime))
		END
		+
		CASE
		WHEN EXTRACT(HOUR FROM aTime) > 12
		THEN
		aPM ELSE aAM
		END);

	END IF;

END;

