/* GenerateAddressMemo */
CREATE FUNCTION GenerateAddressMemo
(Add1 VARCHAR(50),
 Add2 VARCHAR(50),
 Add3 VARCHAR(50),
 Town VARCHAR(50),
 County VARCHAR(50),
 PostCode VARCHAR(50),
 Country VARCHAR(50))
RETURNS Text
READS SQL DATA
BEGIN
 DECLARE vResult Text;
 DECLARE vCRLF VARCHAR(2);

 SET vResult = '';
 SET vCRLF = chr(13) + chr(10);

 IF COALESCE(Add1,'') <> '' THEN
  SET vResult = vResult + Add1 + vCRLF ;
 END IF;

 IF COALESCE(Add2,'') <> '' THEN
  SET vResult = vResult + Add2 + vCRLF ;
 END IF;

 IF COALESCE(Add3,'') <> '' THEN
  SET vResult = vResult + Add3 + vCRLF ;
 END IF;

 IF COALESCE(Town,'') <> '' THEN
  SET vResult = vResult + Town + vCRLF ;
 END IF;

 IF COALESCE(County,'') <> '' THEN
  SET vResult = vResult + County + vCRLF ;
 END IF;

 IF COALESCE(PostCode,'') <> ''  THEN
  SET vResult = vResult + PostCode + vCRLF ;
  END IF;

 IF COALESCE(Country,'') <> ''THEN
  SET vResult = vResult + Country + vCRLF ;
 END IF;

  RETURN vResult;
END;

