/* GET_SESSION_VARIABLE */
CREATE FUNCTION GET_SESSION_VARIABLE(VAR_NAME VARCHAR(40))
RETURNS VARCHAR(40)
READS SQL DATA
BEGIN
	DECLARE RET_VAR VARCHAR(40);

	TRY
	SET RET_VAR = (SELECT VARIABLE_VALUE FROM
                ##SESSION_VARIABLES
                WHERE
                VARIABLE_NAME = VAR_NAME);

	CATCH POSITION('Unable to open table' IN ERROR_MESSAGE) > 0
	      SET RET_VAR = NULL;
	END;

	RETURN RET_VAR;
END;

/* GetAccountsDataIDsFromDetailLine */
CREATE FUNCTION GetAccountsDataIDsFromDetailLine
(aDocID INT,
 aInvoice BOOL,
 aMasterGUID GUID,
 aList TEXT) -- pass CAST(NULL AS Text) for this param; its there for the recursive calls
 RETURNS Text
READS SQL DATA
BEGIN
  DECLARE vFoundID TEXT;
  DECLARE vNextGUID GUID;

  IF COALESCE(aList,'') = '' THEN
     IF aInvoice THEN
        SET vFoundID = (SELECT LIST(CAST(InvKey AS VARCHAR(10))) FROM InvData WHERE InvNo = aDocID AND xMasterRow = aMasterGUID);
     ELSE
        SET vFoundID = (SELECT LIST(CAST(InvKey AS VARCHAR(10))) FROM POData WHERE InvNo = aDocID AND xMasterRow = aMasterGUID);
     END IF;

     SET vFoundID = vFoundID + ',';
     SET aList = COALESCE(aList,'') + vFoundID;

     IF vFoundID IS NOT NULL THEN
        RETURN GetAccountsDataIDsFromDetailLine(aDocID, aInvoice, aMasterGUID, aList);
     END IF;
  ELSE
     IF aInvoice THEN
        SET vFoundID = (SELECT LIST(CAST(InvKey AS VARCHAR(10))) FROM InvData WHERE InvNo = aDocID AND MasterRowGUID = aMasterGUID);
     ELSE
        SET vFoundID = (SELECT LIST(CAST(InvKey AS VARCHAR(10))) FROM POData WHERE InvNo = aDocID AND MasterRowGUID = aMasterGUID);
     END IF;

     SET vFoundID = vFoundID + ',';

     IF (vFoundID IS NOT NULL) AND (POSITION( vFoundID IN aList) = 0) THEN
        SET aList = COALESCE(aList,'') + vFoundID;

        IF aInvoice THEN
           SET vNextGUID = (SELECT xMasterRow FROM InvData WHERE InvNo = aDocID AND MasterRowGUID = aMasterGUID);
        ELSE
           SET vNextGUID = (SELECT xMasterRow FROM POData WHERE InvNo = aDocID AND MasterRowGUID = aMasterGUID);
        END IF;

        RETURN GetAccountsDataIDsFromDetailLine(aDocID, aInvoice, vNextGUID, aList);
     END IF;
  END IF;

  SET aList =  TRIM(TRAILING ',' FROM aList);

  RETURN aList;

END;

/* GetAccountsDataIDsFromMasterLine */
CREATE FUNCTION GetAccountsDataIDsFromMasterLine
(aDocID INT,
 aInvoice BOOL,
 aMasterGUID GUID,
 aList TEXT) -- pass CAST(NULL AS Text) for this param; its there for the recursive calls
 RETURNS Text
READS SQL DATA
