/* GetBandedTransportDistanceRate */
CREATE FUNCTION GetBandedTransportDistanceRate
(aJobID integer,
 aVehicleID integer,
 aDistance integer )
RETURNS Money
READS SQL DATA
BEGIN
  DECLARE vCurrency INTEGER;
  DECLARE vDistance Money;
  SET vCurrency = (select Currency from Jobs where Jobno = aJobID);

  SET vDistance = CASE
   WHEN vCurrency = 0 THEN  (select Top 1 DistanceA from TransDistancePriceBands where xVehicleType =aVehicleID  and Distance >= aDistance order by Distance Asc)
   WHEN vCurrency = 1 THEN  (select Top 1 DistanceB from TransDistancePriceBands where xVehicleType =aVehicleID  and Distance >= aDistance order by Distance Asc)
   WHEN vCurrency = 2 THEN  (select Top 1 DistanceC from TransDistancePriceBands where xVehicleType =aVehicleID  and Distance >= aDistance order by Distance Asc)
   WHEN vCurrency = 3 THEN  (select Top 1 DistanceD from TransDistancePriceBands where xVehicleType =aVehicleID  and Distance >= aDistance order by Distance Asc)
   END;

 RETURN vDistance;

END;

/* GetClientDiscount */
CREATE FUNCTION GetClientDiscount
( aCompanyID INT,
  aCost BOOL,
  aEqlistClass TINYINT
)
RETURNS SMALLINT
READS SQL DATA
BEGIN
 IF aEqlistClass = 0 THEN --Rental
    IF aCost THEN
       RETURN COALESCE((SELECT OurDiscount FROM Company WHERE CompanyCounter = aCompanyID),0);
    ELSE
       RETURN COALESCE((SELECT HireDiscount FROM Company WHERE CompanyCounter = aCompanyID),0);
    END IF;
 ELSE
    IF aCost THEN
       RETURN COALESCE((SELECT SalesOrderDiscount FROM Company WHERE CompanyCounter = aCompanyID),0);
    ELSE
       RETURN COALESCE((SELECT SaleDiscount FROM Company WHERE CompanyCounter = aCompanyID),0);
    END IF;
 END IF;
END;

