/* GetFullDocumentPath */
CREATE FUNCTION GetFullDocumentPath
( ID Integer)
RETURNS Varchar(255)
READS SQL DATA
BEGIN
  declare query varchar(500);
  declare parent Integer;
  declare mypath varchar(255);
  set query = 'select * into #tmp from documentFolders where Idx = ' + cast(ID as VarChar(10));
  EXECUTE IMMEDIATE query ;
  set parent = (select top 1 parent from #tmp);
  set mypath = (select top 1 "name" from #tmp);
  if (parent <> -1) then
  return  GetFullDocumentPath(parent) + '\' +  mypath;
  else
  return mypath;
  end if;
END;

/* GetHexChar */
CREATE FUNCTION GetHexChar(number INT)
RETURNS VarChar(1)
BEGIN
    RETURN CASE
        WHEN number BETWEEN 0 AND 9 THEN CHR(number + 48) -- 48 is ASCII for '0'
        WHEN number BETWEEN 10 AND 15 THEN CHR(number + 55) -- 55 = ASCII for 'A' - 10
        ELSE '?'
    END;
END;

/* GetIncomeProportionForComponent */
CREATE FUNCTION GetIncomeProportionForComponent
(aLineRef INT,
 aLineCode INT,
 aCurrency TINYINT)
RETURNS MONEY
READS SQL DATA
BEGIN
 DECLARE vMasterType INT;
 DECLARE vComponentType INT ;
 DECLARE vMultiplier NUMERIC(10,2);
 DECLARE vChargeAmount MONEY;
 DECLARE vMasterIsInPricedAlias BOOL;
 DECLARE vGUID GUID;

 SET vMasterIsInPricedAlias =  (SELECT S.RecType = 9
                                FROM "Sort" S
                                WHERE
                                 S.LineRef = aLineCode);
 IF vMasterIsInPricedAlias THEN
  SET vGUID = (SELECT xGUID FROM "Sort" WHERE LineRef = aLineCode);

  SET vChargeAmount = GetIncomeProportionForPricedAlliasPart(aLineCode, vGUID, aCurrency);
 ELSE
  SET vChargeAmount = COALESCE(
         (SELECT CASE
         WHEN S.ChargeQuantity > 0 THEN (S.Price/S.ChargeQuantity)
         ELSE 0
         END
         FROM "Sort" S
         INNER JOIN Eqlists E
         ON S.Eqlno = E.Eql_no
         WHERE
         S.LineRef = aLineCode
         AND E.PriceMode = aCurrency),0);
 END IF;

 SET vMasterType = (SELECT S.Type
                    FROM "Sort" S
                    WHERE
                    S.LineRef = aLineCode);
 SET vComponentType = (SELECT S.Type
                       FROM "Sort" S
                       WHERE
                       S.LineRef = aLineRef);
 SET vMultiplier = COALESCE(
 (SELECT CAST(CASE
               WHEN M.Daily > 0 THEN (C.Quantity * S.Daily) /  M.Daily
               ELSE
               0
               END AS NUMERIC(10,2))
  FROM Composit C
  INNER JOIN Hetype M
  ON M.Type = C.MasterType
  INNER JOIN Hetype S
  ON S.Type = C.ComponentType
  WHERE
  C.MasterType = vMasterType
  AND
  C.ComponentType = vComponentType),0);


 RETURN vChargeAmount * vMultiplier;

END;

/* GetIncomeProportionForPricedAlliasPart */
CREATE FUNCTION GetIncomeProportionForPricedAlliasPart
(aLineRef INT,
 aGUID GUID,
 aCurrency TINYINT)
RETURNS MONEY
READS SQL DATA
BEGIN
 DECLARE vMasterType INT;
 DECLARE vComponentType INT ;
 DECLARE vMultiplier NUMERIC(10,2);
 DECLARE vChargeAmount MONEY;

 SET vChargeAmount = COALESCE(
         (SELECT CASE
         WHEN S.ChargeQuantity > 0 THEN (S.Price/S.ChargeQuantity)
         ELSE 0
         END
         FROM "Sort" S
         INNER JOIN Eqlists E
         ON S.Eqlno = E.Eql_no
         WHERE
         S.xGUID = aGUID
         AND S.RecType = 13
         AND E.PriceMode = aCurrency),0);


 SET vMasterType = (SELECT S.Type
                    FROM "Sort" S
                    WHERE
                    S.xGUID = aGUID
                    AND S.RecType = 13);
 SET vComponentType = (SELECT S.Type
                       FROM "Sort" S
                       WHERE
                       S.LineRef = aLineRef);
 SET vMultiplier = COALESCE(
 (SELECT CAST(CASE
               WHEN M.Daily > 0 THEN (R.Quantity * S.Daily) /  M.Daily
               ELSE
               0
               END AS NUMERIC(10,2))
  FROM Related R
  INNER JOIN Hetype M
  ON M.Type = R.MasterType
  INNER JOIN Hetype S
  ON S.Type = R.SubType
  WHERE
  R.MasterType = vMasterType
  AND
  R.SubType = vComponentType),0);

 RETURN vChargeAmount * vMultiplier;

END;

