/* GetMAXINT */
CREATE FUNCTION GetMAXINT
( aINT1 INT,
  aINT2 INT)
RETURNS INT
BEGIN
  IF aINT1 > aINT2 THEN
    RETURN aINT1;
  ELSE
    RETURN aINT2;
  END IF;
END;

/* GetMININT */
CREATE FUNCTION GetMININT
( aINT1 INT,
  aINT2 INT)
RETURNS INT
BEGIN
  IF aINT1 < aINT2 THEN
    RETURN aINT1;
  ELSE
    RETURN aINT2;
  END IF;
END;

/* GetMySites */
CREATE FUNCTION GetMySites
(aUserID INT)
RETURNS TABLE
MODIFIES SQL DATA
BEGIN
DECLARE vMaxSite INT;
DECLARE vUserSites BIGINT;
DECLARE vPowerSite BIGINT;
DECLARE vCounter TINYINT;

SET vMaxSite = (SELECT MAX(IDX) FROM Sites) - 1;

IF aUserID IS NULL THEN
	SET vUserSites = (
			SELECT UserSites
			FROM Users
			WHERE CAST(ServerLoginID AS VARCHAR(50)) = USER
			);
ELSE
	SET vUserSites = (
			SELECT UserSites
			FROM Users
			WHERE UID = aUserID
			);
END IF ;

SET vCounter = 0;

DROP TABLE IF EXISTS #Tmp;
CREATE TABLE #Tmp
(SiteID INT NOT NULL PRIMARY KEY);

WHILE vCounter <= vMaxSite DO

SET  vPowerSite = CAST(POWER(2,vCounter) + 0.5 AS BIGINT);

IF BITAND(vUserSites ,vPowerSite ) = vPowerSite THEN
 INSERT INTO #Tmp
 (SiteID)
 Values
 (vCounter + 1);
 END IF;

SET vCounter = vCounter + 1;

END WHILE;

RETURN SELECT SiteID FROM #Tmp;
END;

/* GetNewEqlistRef */
CREATE FUNCTION GetNewEqlistRef (
		aJobID INT,
		aEqlistID INT,
		aListType TINYINT,  -- TWarehouseActivity = (waHire, waJobSubhire, waGlobalSubhire, waJobTransfer, waGlobalTransfer, waVirtualWarehouseBuild, waStockTransfer, waClassTransfer);
		aEqlistClass TINYINT)  -- TEqlistClass = (emRentalClass, emSalesClass);
RETURNS VARCHAR(30)
READS SQL DATA

BEGIN

	DECLARE vResetCountForJob BOOL;
	DECLARE vJobRef NULLSTRING (50);
	DECLARE vEqRef NULLSTRING (50);
	DECLARE vEqlJobCount INT;
	DECLARE vSubhireStart INT;
	DECLARE vEqlistStart INT;
	DECLARE vEqlPrefix NULLSTRING (10);
	DECLARE vEqlSuffix NULLSTRING (10);
	DECLARE vCounter INT;
	DECLARE vEqNumber NULLSTRING (10);
	DECLARE vSiteID TINYINT;

IF aListType IN (0,1) THEN  -- Rental, Job Subhire, Sales or Job Sales Order

  SET vSiteID = (SELECT PrimarySite
	             	 FROM jobs
	             	 WHERE
                 Jobno = aJobID);

  IF aListType = 0 THEN  -- Rental Or Sales
    IF aEqlistClass = 0 THEN  -- Rental
      SET vResetCountForJob = (SELECT appendJob
		                         	 FROM Config1
		                        	 WHERE
                               link = 1);

      SET vEqlPrefix = COALESCE((SELECT eqlhead
                                 FROM Config1
                                 WHERE
                                 link = vSiteID), '');

      SET vEqlSuffix = COALESCE((SELECT EqlTrail
                                 FROM Config1
			                           WHERE
                                 link = vSiteID), '');
    ELSE  -- Or Sales
      SET vResetCountForJob = (SELECT SalesNumberRestart
		                         	 FROM Config1
		                        	 WHERE
                               link = 1);

      SET vEqlPrefix = COALESCE((SELECT SalesHead
                                 FROM Config1
                                 WHERE
                                 link = vSiteID), '');

      SET vEqlSuffix = COALESCE((SELECT SalesTrail
                                 FROM Config1
			                           WHERE
                                 link = vSiteID), '');

    END IF;
  ELSEIF aListType = 1 THEN  -- Subhire or Job Sales Order
    IF aEqlistClass = 0 THEN   -- Subhire
       SET vResetCountForJob = (SELECT SubhireNumberRestart
				                        FROM Config1
				                        WHERE
                                Link = 1);

       SET vEqlPrefix = COALESCE((SELECT Subhead
 				                          FROM Config1
 			                            WHERE
                                  link = vSiteID), '');
       SET vEqlSuffix = COALESCE((SELECT SubTrail
 				                          FROM Config1
 				                          WHERE
                                  link = vSiteID), '');
    ELSE  --Job Sales Order
       SET vResetCountForJob = (SELECT SalesOrderNumberRestart
 				                        FROM Config1
 				                        WHERE
                                Link = 1);

       SET vEqlPrefix = COALESCE((SELECT SalesOrderHead
 				                          FROM Config1
 			                            WHERE
                                  link = vSiteID), '');
       SET vEqlSuffix = COALESCE((SELECT SalesOrderTrail
 				                          FROM Config1
 				                          WHERE
                                  link = vSiteID), '');

    END IF;

  END IF ;

  IF vResetCountForJob THEN -- this IS the norm
    SET vCounter = 0;

    SET vJobRef = COALESCE((SELECT Job_Ref
 		                      	FROM jobs
 		                      	WHERE
                            jobno = aJobID), '');


    SET vEqlJobCount = COALESCE((SELECT COUNT(*)
 			                           FROM eqlists
 			                           WHERE
                                  (job_no = aJobID)
					                        AND ListType = aListType
                                  AND EqlistClass = aEqlistClass), 0);

   REPEAT
     SET vCounter = vCounter + 1;

     IF  vEqlJobCount + vCounter < 10 THEN
      SET vEqNumber = '0' || CAST(vEqlJobCount + vCounter AS VARCHAR(10));
     ELSE
      SET vEqNumber = CAST(vEqlJobCount + vCounter AS VARCHAR(10));
     END IF;

     SET vEqRef = vJobRef || vEqlPrefix || vEqNumber || vEqlSuffix;

     UNTIL EqRefIsUnique(aJobID, vEqRef)

   END REPEAT ;

  ELSE

   SELECT *
 	 INTO #tmp
 	 FROM (SELECT COUNT(DISTINCT eql_no) AS Total
 		     FROM eqlists
 	       WHERE
         ListType = aListType
         AND EqlistClass = aEqlistClass);

   SET vCounter = COALESCE((SELECT SUM(Total)
 			                      FROM #tmp), 0);

   IF aEqlistClass = 0 THEN   -- Rental or Subhire
     SET vEqlistStart = COALESCE((SELECT EqlStart
 		                             	FROM Config1
 		                            	WHERE
                                  link = 1), 0);

     SET vSubhireStart = COALESCE((SELECT SubStart
 		                               FROM Config1
 			                             WHERE
                                   link = 1), 0);
   ELSE  -- Sales or Order
     SET vEqlistStart = COALESCE((SELECT SalesStart
 		                             	FROM Config1
 		                            	WHERE
                                  link = 1), 0);

     SET vSubhireStart = COALESCE((SELECT SalesOrderStart
 		                               FROM Config1
 			                             WHERE
                                   link = 1), 0);

   END IF;

     IF aListType = 0 THEN -- Rental or Sales
 	      IF vEqlistStart + vCounter < 10 THEN
 		       SET vEqNumber = '0' || CAST(vEqlistStart + vCounter AS VARCHAR(10));
     	  ELSE
 		       SET vEqNumber = CAST(vEqlistStart + vCounter AS VARCHAR(10));
 	      END IF ;

 	      SET vEqRef = vEqlPrefix || vEqNumber || vEqlSuffix;
     ELSE  -- Subhire or Sales Order
 	      IF vSubhireStart + vCounter < 10 THEN
 		       SET vEqNumber = '0' || CAST(vSubhireStart + vCounter AS VARCHAR(10));
       	ELSE
 		       SET vEqNumber = CAST(vSubhireStart + vCounter AS VARCHAR(10));
 	       END IF ;

 	      SET vEqRef = vEqlPrefix || vEqNumber || vEqlSuffix;
     END IF ;
  END IF ;

ELSE -- Its a Global Subhire, Job Loan, Global Loan, Virtual Warehouse Build, Global Sales Order or Warehouse / Class Transfer

  IF aEqlistClass = 0 THEN
    IF aListType = 2 THEN
      SET vEqRef = TOSTRINGLEN('GLSH: '   || CAST(aEqlistID AS VARCHAR(10)),30) ;
    ELSEIF aListType = 3 THEN
      SET vEqRef = 'JBTR: ';
    ELSEIF aListType = 4 THEN
      SET vEqRef = TOSTRINGLEN('GLTR: '   || CAST(aEqlistID AS VARCHAR(10)),30) ;
    ELSEIF aListType = 5 THEN
      SET vEqRef = TOSTRINGLEN('VW: '   || CAST(aEqlistID AS VARCHAR(10)),30) ;
    ELSEIF aListType = 6 THEN
      SET vEqRef = TOSTRINGLEN('RST: '   || CAST(aEqlistID AS VARCHAR(10)),30) ; -- Rental Warehouse Transfer
    ELSEIF aListType = 7 THEN
      SET vEqRef = TOSTRINGLEN('RCT: '   || CAST(aEqlistID AS VARCHAR(10)),30) ; -- Rental Class Transfer
    END IF;
  ELSE
    IF aListType = 2 THEN
      SET vEqRef = TOSTRINGLEN('GLSAO: '   || CAST(aEqlistID AS VARCHAR(10)),30) ;
    ELSEIF aListType = 6 THEN
      SET vEqRef = TOSTRINGLEN('SST: '   || CAST(aEqlistID AS VARCHAR(10)),30) ;  -- Sales Warehouse Transfer
    ELSEIF aListType = 7 THEN
      SET vEqRef = TOSTRINGLEN('SCT: '   || CAST(aEqlistID AS VARCHAR(10)),30) ;  -- Sales Class Transfer
    END IF;
  END IF; --aEqlistClass


END IF ; -- aListType IN (0,1)

RETURN vEqRef;

END;

/* GetNewInvoiceNumber */
CREATE FUNCTION GetNewInvoiceNumber
( aDocumentID integer,
  aAccountsDocument smallInt,
  aSiteID integer )
RETURNS VarChar(20)
READS SQL DATA
MODIFIES SQL DATA
BEGIN

-- TAccountsDocument = (adRentalInvoice, adRentalInvoiceCredit, adRentalOrder,  adRentalOrderCredit,  adSalesInvoice, adSalesInvoiceCredit, adSalesOrder, adSalesOrderCredit);
-- TImportMode = (imPurchaseNumbers, imInvoicenumbers);

DECLARE vPrefix VarChar(10);
DECLARE vSuffix VarChar(10);
DECLARE vOffSet integer;
DECLARE vSuppressedMasters integer;
DECLARE vInvRefCounter  integer;
DECLARE vUseExternal boolean;
DECLARE vResult VarChar(20);

-- do external numbers check

SET vUseExternal = (SELECT UseExternalInvoiceRefs FROM Rules WHERE SiteID = aSiteID);

IF vUseExternal THEN

 SET vResult = (SELECT TOP 1 ExternalRef FROM ExternalNumbers WHERE xSite = aSiteID and TNumberType = 1 and xInternal is Null);

 IF (vResult IS NULL) or (vResult = '') THEN
  SIGNAL 'All external invoice numbers have been used.';
 END IF;

END IF;

-- get a new vInvRefCounter value
START TRANSACTION;

 TRY
 INSERT INTO AI_Inv
  (Inv_type, xInvNo )
  VALUES
 (aAccountsDocument,aDocumentID);

 SET vInvRefCounter = (Select LASTAUTOINC from #Dummy);

 COMMIT;

 CATCH TRUE
 ROLLBACK;
 SIGNAL ERROR_MESSAGE;

END;

-- if vUseExternal then we already have the result, else...
IF NOT vUseExternal THEN

 IF  aAccountsDocument in (0,4 ) THEN
  SET vPrefix = (SELECT InvoiceHead FROM Config1 WHERE link = aSiteID);
  SET vSuffix = (SELECT InvoiceTrail FROM Config1 WHERE link = aSiteID);
 END IF;

 IF  aAccountsDocument in (1,5) THEN
  SET vPrefix = (SELECT InvCreditHead FROM Config1 WHERE link = aSiteID);
  SET vSuffix = (SELECT InvCreditTrail FROM Config1 WHERE link = aSiteID);
 END IF;

-- code change 21 Jan 20144: offset to be retrieved from Site 1 ONLY
 SET vOffSet = (SELECT InvoiceStart FROM Config1 WHERE link = 1) ;

 SET vSuppressedMasters = (SELECT count(MasterNo) FROM I_master WHERE SuppressMaster = TRUE );

 SET vResult = Coalesce(vPrefix,'')  || cast(vInvRefCounter + vOffSet - vSuppressedMasters as varchar(10)) ||  Coalesce(vSuffix,'');

ELSE

 UPDATE ExternalNumbers SET xInternal = vInvRefCounter WHERE ExternalRef = vResult;

END IF;

RETURN vResult;

END;

/* GetNewJobRef */
CREATE FUNCTION GetNewJobRef
(aJobID INT,
 aSiteID INT)
RETURNS VARCHAR(20)
READS SQL DATA
BEGIN

DECLARE vCounter INT;
DECLARE vSite INT;


-- code change 21 Jan 20144: offset to be retrieved from Site 1 ONLY
SET vCounter = (
		SELECT jobstart
		FROM Config1
		WHERE link = 1
		) + aJobID - 21;


RETURN (
		SELECT COALESCE(Jobhead,'') + CAST(vCounter AS VARCHAR(10)) + COALESCE(JobTrail,'')
		FROM Config1
		WHERE link = aSiteID
		) ;


END;

/* GetNewOrderNumber */
CREATE FUNCTION GetNewOrderNumber
( aDocumentID integer,
  aAccountsDocument smallInt,
  aSiteID integer )
RETURNS VarChar(20)
READS SQL DATA
MODIFIES SQL DATA
BEGIN

-- TAccountsDocument = (adRentalInvoice, adRentalInvoiceCredit, adRentalOrder,  adRentalOrderCredit,  adSalesInvoice, adSalesInvoiceCredit, adSalesOrder, adSalesOrderCredit);
-- TImportMode = (imPurchaseNumbers, imInvoicenumbers);

DECLARE vPrefix VarChar(10);
DECLARE vSuffix VarChar(10);
DECLARE vOffSet integer;
DECLARE vInvRefCounter  integer;
DECLARE vUseExternal boolean;
DECLARE vResult VarChar(20);

-- do external numbers check

SET vUseExternal = (SELECT UseExternalIPORefs FROM Rules WHERE SiteID = aSiteID);

IF vUseExternal THEN

 SET vResult = (SELECT TOP 1 ExternalRef FROM ExternalNumbers WHERE xSite = aSiteID and TNumberType = 0 and xInternal is Null);

 IF (vResult IS NULL) or (vResult = '') THEN
  SIGNAL 'All external order numbers have been used.';
 END IF;

END IF;

-- get a new vInvRefCounter value
START TRANSACTION;

TRY
INSERT INTO AI_Purc
(Inv_type, xInvNo )
VALUES
(aAccountsDocument,aDocumentID);

SET vInvRefCounter = (Select LASTAUTOINC from #Dummy);

COMMIT;

CATCH TRUE
ROLLBACK;
SIGNAL ERROR_MESSAGE;

END;

-- if vUseExternal then we already have the result, else...
IF NOT vUseExternal THEN

IF  aAccountsDocument in (2,6 ) THEN
  SET vPrefix = (SELECT POHead FROM Config1 WHERE link = aSiteID);
  SET vSuffix = (SELECT POTrail FROM Config1 WHERE link = aSiteID);
END IF;

IF  aAccountsDocument in (3,7) THEN
  SET vPrefix = (SELECT POCreditHead FROM Config1 WHERE link = aSiteID);
  SET vSuffix = (SELECT POCreditTrail FROM Config1 WHERE link = aSiteID);
END IF;

-- code change 21 Jan 20144: offset to be retrieved from Site 1 ONLY
SET vOffSet = (SELECT POStart FROM Config1 WHERE link = 1) ;
SET vResult = Coalesce(vPrefix,'')  || cast(vInvRefCounter + vOffSet  as varchar(10)) ||  Coalesce(vSuffix,'');

ELSE

 UPDATE ExternalNumbers SET xInternal = vInvRefCounter WHERE ExternalRef = vResult;

END IF;

RETURN vResult;

END;

