/* GetRentalCosts */
CREATE FUNCTION "GetRentalCosts"
(aEqlistID INT)
RETURNS TABLE
MODIFIES SQL DATA
BEGIN

 DECLARE vEquipmentCostsRule TINYINT;
 DECLARE vWarehouseID INT;

 SET vWarehouseID = (SELECT MainSite FROM Eqlists WHERE Eql_no = aEqlistID);
 SET vEquipmentCostsRule = (SELECT EquipmentCosts FROM Rules WHERE SiteID = GetEqlistSite(vWarehouseID));

 SELECT *
 INTO #Sort
 FROM Sort
 WHERE
 Eqlno = aEqlistID;

	IF vEquipmentCostsRule > 0 THEN
		SELECT
		COALESCE(SUM((S.Quant - S.SubHiredQty) *  -- ignore subhired Qty
		CASE
		WHEN E.Pricemode = 0 THEN H.PrepCostA
		WHEN E.Pricemode = 1 THEN H.PrepCostB
		WHEN E.Pricemode = 2 THEN H.PrepCostC
		WHEN E.Pricemode = 3 THEN H.PrepCostD
		END),0) AS PrepCostTotal,

		COALESCE(SUM((S.Quant - SubHiredQty) *
		CASE
		WHEN S.XCat > 0 THEN -- only include Days multiplier for non consumables
				CASE
				WHEN vEquipmentCostsRule = 1 THEN CEILING(CAST(E.DateBack AS DOUBLE PRECISION) - CAST(E.DateOut AS DOUBLE PRECISION) )
				ELSE
				E.HireDays
				END
		ELSE 1
		END
		*
		CASE
		WHEN E.Pricemode = 0 THEN H.DailyCostA
		WHEN E.Pricemode = 1 THEN H.DailyCostB
		WHEN E.Pricemode = 2 THEN H.DailyCostC
		WHEN E.Pricemode = 3 THEN H.DailyCostD
		END),0) AS UsageCostTotal,

    COALESCE(SUM(S.CurrentCostPrice),0) AS ExtraCostTotal,
    COALESCE(SUM(S.AnticipatedCostPrice),0) AS SubHireCostTotal

		INTO #InternalCosts

		FROM "#Sort" S
		LEFT OUTER JOIN Hetype H
		ON S."Type" = H."Type"
		INNER JOIN EQLISTS E
		ON S.Eqlno = E.Eql_no
		WHERE
		S.Eqlno = aEqlistID
		AND
		S.Virt = FALSE;

	ELSE

   SELECT
    CAST(0 AS MONEY) AS PrepCostTotal,
    CAST(0 AS MONEY) AS UsageCostTotal,
    COALESCE(SUM(S.CurrentCostPrice),0) AS ExtraCostTotal,
    COALESCE(SUM(S.AnticipatedCostPrice),0) AS SubHireCostTotal
    INTO #InternalCosts
    FROM "#Sort" S
    WHERE
		S.Eqlno = aEqlistID
		AND
		S.Virt = FALSE;

	END IF;

 RETURN
 SELECT * FROM
 #InternalCosts;

END;

