/* GetStandardJobCommissions */
CREATE FUNCTION GetStandardJobCommissions
(aJobID INT)
RETURNS TABLE
MODIFIES SQL DATA -- needs either read-access
BEGIN
 DECLARE vEqlistOwnTotal MONEY;
 DECLARE vEqlistSubTotal MONEY;
 DECLARE vEqlistConTotal MONEY;
 DECLARE vEqlistAdditionalTotal MONEY;
 DECLARE vEqlistRTOwnTotal MONEY;
 DECLARE vEqlistRTSubTotal MONEY;
 DECLARE vCrewOwnTotal MONEY;
 DECLARE vCrewSubTotal MONEY;
 DECLARE vTransportOwnTotal MONEY;
 DECLARE vTransportSubTotal MONEY;
 DECLARE vMiscOwnTotal MONEY;
 DECLARE vMiscSubTotal MONEY;

 DECLARE vEqlistIncomeCommission MONEY;
 DECLARE vCrewIncomeCommission MONEY;
 DECLARE vTransportIncomeCommission MONEY;
 DECLARE vMiscIncomeCommission MONEY;

 DECLARE vEqlistExpenditureCommission MONEY;
 DECLARE vCrewExpenditureCommission MONEY;
 DECLARE vTransportExpenditureCommission MONEY;
 DECLARE vMiscExpenditureCommission MONEY;

 DECLARE vEqlistIncomeCommissionRateForJob FLOAT;
 DECLARE vEqlistIncomeCommissionRateAVG FLOAT;
 DECLARE vCrewIncomeCommissionRate FLOAT;
 DECLARE vTransportIncomeCommissionRate FLOAT;
 DECLARE vMiscIncomeCommissionRate FLOAT;

 DECLARE vEqlistExpenditureCommissionRateForJob FLOAT;
 DECLARE vEqlistExpenditureCommissionRateAVG FLOAT;
 DECLARE vCrewExpenditureCommissionRate FLOAT;
 DECLARE vTransportExpenditureCommissionRate FLOAT;
 DECLARE vMiscExpenditureCommissionRate FLOAT;

 DECLARE vVenueID INT;

 DECLARE vSelectedOnly BOOL;
 DECLARE vNoConsumables BOOL;
 DECLARE vNoAdditionals BOOL;

 -- TJobCommssionType = (jctNone, jctSplit, jctFull);
 DECLARE vCommssionType TINYINT;

 -- TVenueCommissionApplication = (vcaNever, vcaManual, vcaAutomatic, vcaPromptForJob, vcaAdvancedForJob);
 DECLARE vVenueCommission TINYINT;


 SET vVenueID = (SELECT Client
                  FROM Jobs
                  WHERE
                  Jobno = aJobID);

 SET vSelectedOnly = (SELECT CommissionOnSelectedOnly
                      FROM Rules
                      WHERE
                      SiteID = (SELECT PrimarySite FROM Jobs WHERE Jobno = aJobID));

 SET vVenueCommission = (SELECT xVenueCommission
                        FROM Rules
                        WHERE
                        SiteID = (SELECT PrimarySite FROM Jobs WHERE Jobno = aJobID));

 SET vCommssionType = (SELECT JobCommissionType
                      FROM Jobs
                      WHERE
                      Jobno = aJobID);

 SET vNoConsumables = (SELECT SplitCommissionNotOnConsumables
                      FROM Jobs
                      WHERE
                      Jobno = aJobID);

 SET vNoAdditionals = (SELECT CommissionNotOnAdditionals
                      FROM Jobs
                      WHERE
                      Jobno = aJobID);

 SET vEqlistIncomeCommissionRateForJob = COALESCE((SELECT RentalIncomeCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);

 SET vCrewIncomeCommissionRate = COALESCE((SELECT CrewIncomeCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);

 SET vTransportIncomeCommissionRate = COALESCE((SELECT TransportIncomeCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);

 SET vMiscIncomeCommissionRate = COALESCE((SELECT MiscIncomeCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);

--vEqlistExpenditureCommissionRateAVG set later

 SET vEqlistExpenditureCommissionRateForJob = COALESCE((SELECT RentalExpenditureCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);

 SET vCrewExpenditureCommissionRate = COALESCE((SELECT CrewExpenditureCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);

 SET vTransportExpenditureCommissionRate = COALESCE((SELECT TransportExpenditureCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);

 SET vMiscExpenditureCommissionRate = COALESCE((SELECT MiscExpenditureCommission
                              FROM Jobs
                              WHERE
                              Jobno = aJobID), 0);
 -- rental income

 IF vCommssionType > 0 THEN

  DECLARE lEqlno INT;
  DECLARE lIncomeCommissionRate FLOAT;
  DECLARE lExpenditureCommissionRate FLOAT;

  DECLARE cEqlists CURSOR FOR
  SELECT E.Eql_no, E.IncomeCommission, E.ExpenditureCommission, E.AddnCharge
  FROM  Eqlists E
  WHERE
  E.Job_no = aJobID
  AND E.ListType = 0
  AND E.Defcon >=1
  AND (E.SELECTED = TRUE OR E.SELECTED = vSelectedOnly);

  OPEN cEqlists;
  TRY

  SET vEqlistOwnTotal = 0;
  SET vEqlistSubTotal = 0;
  SET vEqlistConTotal = 0;
  SET vEqlistRTOwnTotal = 0;
  SET vEqlistRTSubTotal = 0;
  SET vEqlistIncomeCommission = 0;
  SET vEqlistExpenditureCommission = 0;

  FETCH FIRST FROM cEqlists INTO lEqlno, lIncomeCommissionRate, lExpenditureCommissionRate, vEqlistAdditionalTotal;

  WHILE @@FETCH_STATUS = 0 DO

  -- rental Additionals
     IF  vNoAdditionals THEN
        SET vEqlistAdditionalTotal = 0;
     END IF;

  -- rental indicator
     SET vEqlistOwnTotal = COALESCE((SELECT SUM(S.Price * (S.Quant - S.SubHiredQty) / S.Quant)
                        FROM
                        Sort S
                        WHERE
                        S.Eqlno = lEqlno
                        AND S.Quant > 0),0);

  -- rental consumables
     SET vEqlistConTotal = COALESCE((SELECT SUM(CASE WHEN (S.xCat < 0 AND vNoConsumables)  THEN
                                                  S.Price END)
                        FROM
                        Sort S
                        WHERE
                        S.Eqlno = lEqlno),0);

  -- rental expenditure
     SET vEqlistSubTotal = COALESCE((SELECT SUM(CASE WHEN (S.xCat > 0)  THEN
                                            (S.Price * S.SubHiredQty) / S.Quant END)
                           FROM
                           Sort S
                           WHERE
                           S.Eqlno = lEqlno
                           AND S.Quant > 0),0);

     SET vEqlistRTOwnTotal = vEqlistRTOwnTotal + vEqlistOwnTotal;
     SET vEqlistRTSubTotal = vEqlistRTSubTotal + vEqlistSubTotal;

     IF vCommssionType = 1 THEN --split

        SET vEqlistIncomeCommission = vEqlistIncomeCommission +
                                    ((vEqlistOwnTotal - vEqlistConTotal + vEqlistAdditionalTotal) * CAST(CASE WHEN vVenueCommission < 4 THEN vEqlistIncomeCommissionRateForJob
                                                                 ELSE lIncomeCommissionRate
                                                                 END AS FLOAT) / 100);



        SET vEqlistExpenditureCommission = vEqlistExpenditureCommission +
                                      (vEqlistSubTotal   *  CAST(CASE WHEN vVenueCommission < 4 THEN vEqlistExpenditureCommissionRateForJob
                                                                      ELSE lExpenditureCommissionRate
                                                                      END AS FLOAT) / 100);
     ELSE
        SET vEqlistIncomeCommission = vEqlistIncomeCommission +
                                    ((vEqlistOwnTotal - vEqlistConTotal + vEqlistAdditionalTotal + vEqlistSubTotal ) * CAST(CASE WHEN vVenueCommission < 4 THEN vEqlistIncomeCommissionRateForJob
                                                                 ELSE lIncomeCommissionRate
                                                                 END AS FLOAT) / 100);

     END IF;



 FETCH NEXT FROM cEqlists INTO lEqlno, lIncomeCommissionRate, lExpenditureCommissionRate, vEqlistAdditionalTotal;
 END WHILE;

 CLOSE cEqlists;

 CATCH TRUE
  CLOSE cEqlists;
  SIGNAL ERROR_MESSAGE;
 END;


 ELSE
  SET vEqlistIncomeCommission = 0;
  SET vEqlistExpenditureCommission = 0;
 END IF;

 -- work out commission rate AVG
 SET vEqlistIncomeCommissionRateAVG = 0;
 SET vEqlistExpenditureCommissionRateAVG = 0;

 IF vCommssionType = 1 THEN --split
    IF vEqlistRTOwnTotal  + vEqlistConTotal + vEqlistAdditionalTotal> 0 THEN
       SET vEqlistIncomeCommissionRateAVG = ( vEqlistIncomeCommission / (vEqlistRTOwnTotal + vEqlistConTotal + vEqlistAdditionalTotal)) * 100;
    END IF;

    IF vEqlistRTSubTotal > 0 THEN
       SET vEqlistExpenditureCommissionRateAVG =  (vEqlistExpenditureCommission / vEqlistRTSubTotal) * 100;
    END IF;
 ELSE  -- FULL

    IF vEqlistRTOwnTotal + vEqlistConTotal + vEqlistAdditionalTotal + vEqlistRTSubTotal > 0 THEN
       SET vEqlistIncomeCommissionRateAVG = ( vEqlistIncomeCommission / (vEqlistRTOwnTotal + vEqlistConTotal + vEqlistAdditionalTotal + vEqlistRTSubTotal) ) * 100;
    END IF;

 END IF;

-- finally set the Vars that we will be writing to out output table to the real totals
 SET vEqlistOwnTotal = vEqlistRTOwnTotal;
 SET vEqlistSubTotal = vEqlistRTSubTotal;

-- crew income
 SET vCrewOwnTotal = COALESCE((SELECT SUM(E.Total)
                               FROM Crew E
                               WHERE
                               E.Job_no = aJobID
                               AND E.xStatus >=1
                               AND E.Quantity > 0
                               AND (E.SELECTED = TRUE OR E.SELECTED = vSelectedOnly )),0);


-- crew expenditure
 SET vCrewSubTotal = COALESCE((SELECT SUM(E.TotalPay)
                               FROM Crew E
                               WHERE
                               E.Job_no = aJobID
                               AND E.xStatus >=1
                               AND E.Quantity > 0
                               AND (E.SELECTED = TRUE OR E.SELECTED = vSelectedOnly )),0);

IF vCommssionType > 0 THEN
 IF vCommssionType = 1 THEN
    SET vCrewIncomeCommission = vCrewOwnTotal * CAST(vCrewIncomeCommissionRate AS FLOAT) / 100;
	  SET vCrewExpenditureCommission = vCrewSubTotal * CAST(vCrewExpenditureCommissionRate AS FLOAT) / 100;
 ELSE
    SET vCrewIncomeCommission = (vCrewOwnTotal + vCrewSubTotal ) * CAST(vCrewIncomeCommissionRate AS FLOAT) / 100;
 END IF;
ELSE
 SET vCrewIncomeCommission = 0;
 SET vCrewExpenditureCommission = 0;
END IF;

-- Transport  Own total only gets calculated if there are NO costs associated with it
 SET vTransportOwnTotal = COALESCE((SELECT SUM(E.Charge)
                               FROM Tranplan E
                               WHERE
                               E.Job_number = aJobID
                               AND E.xStatus >=1
                               AND (E.SELECTED = TRUE OR E.SELECTED = vSelectedOnly )),0);

 SET vTransportSubTotal =  COALESCE((SELECT SUM(E.Cost)
                               FROM Tranplan E
                               WHERE
                               E.Job_number = aJobID
                               AND E.xStatus >=1
                               AND (E.SELECTED = TRUE OR E.SELECTED = vSelectedOnly )),0);

 IF  vCommssionType = 0 THEN

     SET vTransportIncomeCommission = 0;
     SET vTransportExpenditureCommission = 0;

 ELSEIF vCommssionType = 1 THEN

        SET vTransportIncomeCommission = (vTransportOwnTotal * vTransportIncomeCommissionRate) / 100;
        SET vTransportExpenditureCommission = (vTransportSubTotal * vTransportExpenditureCommissionRate) / 100;
 ELSE
        SET vTransportIncomeCommission = ((vTransportOwnTotal + vTransportSubTotal) * vTransportIncomeCommissionRate) / 100;
        SET vTransportExpenditureCommission = 0;
 END IF;

-- Misc income
  SET vMiscOwnTotal = COALESCE((SELECT SUM(E.InvoiceOnPrice)
                               FROM Costs E
                               WHERE
                               E.xJob = aJobID
                               AND E.xStatus >=1
                               AND xInternalCostCentre = 0
                               AND (E.SELECTED = TRUE OR E.SELECTED = vSelectedOnly )),0);

   SET vMiscSubTotal = COALESCE((SELECT SUM(CASE WHEN E.ActualPrice = 0 THEN E.AnticipatedPrice ELSE E.ActualPrice END)
                               FROM Costs E
                               WHERE
                               E.xJob = aJobID
                               AND E.xStatus >=1
                               AND xInternalCostCentre = 0
                               AND (E.SELECTED = TRUE OR E.SELECTED = vSelectedOnly )),0);

 IF  vCommssionType = 0 THEN

     SET vMiscIncomeCommission = 0;
     SET vMiscExpenditureCommission = 0;

 ELSEIF vCommssionType = 1 THEN

        SET vMiscIncomeCommission = (vMiscOwnTotal * vMiscIncomeCommissionRate) / 100;
        SET vMiscExpenditureCommission = (vMiscSubTotal * vMiscExpenditureCommissionRate) / 100;
 ELSE
        SET vMiscIncomeCommission = ((vMiscOwnTotal + vMiscSubTotal) * vMiscIncomeCommissionRate) / 100;
        SET vMiscExpenditureCommission = 0;
 END IF;

 DROP TABLE IF EXISTS #Commissions; -- needed if this function has to be called multiple times in a block of calling code.

 CREATE TABLE #Commissions
 (CommissionType TINYINT,
  CommissionIncomeTotal MONEY,
  CommissionRate FLOAT,
  CommissionAmount MONEY);

/*
 TInternalCostCentre = (iccNone = 0, iccPayment = 1, iccEqUsage = 2, iccPrep = 3, iccTransport = 4, iccGlobalPurchaseOrderAllocation = 5, iccCrewSurchage = 6,
                        iccVenueCommission = 7,
                        iicEqCommisson, iicEqSubCommission,iicCrewCommisson, iicCrewSubCommission,iicTransportCommisson, iicTransportSubCommission,iicCostsCommisson, iicCostsSubCommission);

*/
  INSERT INTO #Commissions
  VALUES
  (8, vEqlistOwnTotal, vEqlistIncomeCommissionRateAVG, -vEqlistIncomeCommission), -- CommisionIncomeTotal for Jobs table not worked out here
  (9, vEqlistSubTotal, vEqlistExpenditureCommissionRateAVG, -vEqlistExpenditureCommission), -- CommisionIncomeTotal for Jobs table not worked out here
  (10, vCrewOwnTotal, vCrewIncomeCommissionRate, -vCrewIncomeCommission),
  (11, vCrewSubTotal, vCrewExpenditureCommissionRate, -vCrewExpenditureCommission),
  (12, vTransportOwnTotal, vTransportIncomeCommissionRate, -vTransportIncomeCommission),
  (13, vTransportSubTotal, vTransportExpenditureCommissionRate, -vTransportExpenditureCommission),
  (14, vMiscOwnTotal, vMiscIncomeCommissionRate, -vMiscIncomeCommission),
  (15, vMiscSubTotal, vMiscExpenditureCommissionRate, -vMiscExpenditureCommission);

 RETURN SELECT * FROM #Commissions;

END;

/* GetStatusFunction */
CREATE FUNCTION GetStatusFunction
(aStatusID INT)
RETURNS TINYINT
READS SQL DATA
BEGIN
  RETURN (SELECT "Function"
          FROM Defcon
          WHERE
          Defcon_Idx = aStatusID);

END;

/* GetSupplierPriceScheme */
CREATE FUNCTION GetSupplierPriceScheme
( aSupplierID integer,
aSite smallint,
aCurrency integer
)
RETURNS Integer
READS SQL DATA
BEGIN

 IF aCurrency = 0 THEN
  RETURN COALESCE((SELECT xDefaultPurchasingPriceSchemeA FROM ext_company WHERE CompanyLink = aSupplierID AND Site = aSite),0);
 END IF;

   IF aCurrency = 1 THEN
  RETURN COALESCE((SELECT xDefaultPurchasingPriceSchemeB FROM ext_company WHERE CompanyLink = aSupplierID AND Site = aSite),0);
   END IF;

   IF aCurrency = 2 THEN
  RETURN COALESCE((SELECT xDefaultPurchasingPriceSchemeC FROM ext_company WHERE CompanyLink = aSupplierID AND Site = aSite),0);
   END IF;

   IF aCurrency = 3 THEN
  RETURN COALESCE((SELECT xDefaultPurchasingPriceSchemeD FROM ext_company WHERE CompanyLink = aSupplierID AND Site = aSite),0);
   END IF;

END;

/* GetTotalIncQuote */
CREATE FUNCTION GetTotalIncQuote
( aJobID INT)
RETURNS MONEY
READS SQL DATA
BEGIN
  RETURN
  COALESCE((SELECT SUM(Total) FROM Eqlists WHERE Job_no = aJobID AND SELECTED = True),0) +
  COALESCE((SELECT SUM(Total) FROM Crew WHERE Job_no = aJobID AND SELECTED = True),0) +
  COALESCE((SELECT SUM(Charge) FROM Tranplan WHERE Job_number = aJobID AND SELECTED = True),0) +
  COALESCE((SELECT SUM(InvoiceOnPrice) FROM Costs WHERE xJob = aJobID AND SELECTED = True),0);
END;

/* GetTransportDailyRate */
CREATE FUNCTION GetTransportDailyRate
(aJobID INT,
 aVehicleID INT )
RETURNS MONEY
READS SQL DATA
BEGIN
  DECLARE vCurrency BYTE;
  DECLARE vDaily MONEY;

  SET vCurrency = (SELECT Currency FROM Jobs WHERE Jobno = aJobID);

  SET vDaily = CASE
               WHEN vCurrency = 0 THEN  (SELECT DailyA FROM "veh-type" WHERE vehicle_counter =aVehicleID )
               WHEN vCurrency = 1 THEN  (SELECT DailyB FROM "veh-type" WHERE vehicle_counter =aVehicleID )
               WHEN vCurrency = 2 THEN  (SELECT DailyC FROM "veh-type" WHERE vehicle_counter =aVehicleID )
               WHEN vCurrency = 3 THEN  (SELECT DailyD FROM "veh-type" WHERE vehicle_counter =aVehicleID )
               END;

 RETURN vDaily;

END;

/* GetTransportFunctionNameFromHeaderID */
CREATE FUNCTION GetTransportFunctionNameFromHeaderID
( aTransportHeaderID integer )
RETURNS varChar(50)
READS SQL DATA
BEGIN
  return (
          select Coalesce(F."Description",'') from TranplanHeader H
          inner join TransFunction F
           on F.IDX = H.xTranplanFunction
           WHERE H.IDX =aTransportHeaderID
         );
END;

/* GetTransportTitleFromHeaderID */
CREATE FUNCTION GetTransportTitleFromHeaderID
( aTransportHeaderID integer )
RETURNS varChar(100)
READS SQL DATA
BEGIN
  return (
          select Coalesce(H."Description",'') from TranplanHeader H
           WHERE H.IDX =aTransportHeaderID
         );
END;

/* GetUserID */
CREATE FUNCTION GetUserID
( )
RETURNS integer
READS SQL DATA
BEGIN
DECLARE vID integer;

set vID =COALESCE ((select  UID  from users where cast(ServerLoginID as varchar(38)) = Current_User), -1) ;


return vID;
END;

/* GetUserName */
CREATE FUNCTION GetUserName
( aUserID INT)
RETURNS VARCHAR(100)
READS SQL DATA
BEGIN

 RETURN
  (SELECT
   CASE
    WHEN COALESCE(FirstName,'') <> '' AND COALESCE(LastName,'') <> ''  THEN FirstName || ' '|| LastName
   ELSE
    UserName
   END
   FROM Users
   WHERE
   UID = aUserID);
END;

/* GetWarehouseColumnFromWarehouseID */
CREATE FUNCTION GetWarehouseColumnFromWarehouseID
(pWH_ID integer )
RETURNS byte
READS SQL DATA
BEGIN
 return (select WHlevelColumn from Warehouses where IDX = pWH_ID);
END;

/* GetWarehouseCount */
CREATE FUNCTION GetWarehouseCount
( )
RETURNS Byte
READS SQL DATA
BEGIN
  RETURN (select max(Idx) from Warehouses);
END;

/* GetWarehouseProgressStatus */
CREATE FUNCTION GetWarehouseProgressStatus
(aPrepStatus INT,
 aDipatchStatus INT,
 aReturnStatus INT,
 aCheckInStatus INT,
 aListType TINYINT, --  TWarehouseActivity = (waHire, waJobSubhire, waGlobalSubhire, waJobTransfer, waGlobalTransfer, waVirtualWarehouseBuild);
 aListClass TINYINT,--   TEqlistClass = (emRentalClass, emSalesClass);
 aReturnsInFuture BOOL)
RETURNS INT
DETERMINISTIC
BEGIN

/*
0 - Stage 1 Not Started (All)
1 - Stage 1 Started (All)
2 - Stage 2 Not Started (All)
3 - Stage 2 Started (All)
4 - Stage 2 Completed (All)
5 - Stage 3 Not Started (Rental)
6 - Stage 3 Not Started (Sales)
7 - Stage 3 Started (Rental)
8 - Stage 3 Started (Sales)
9 - Stage 4 Not Started (Rental)
10 - Stage 4 Not Started (Sales)
11 - Stage 4 Started (Rental)
12 - Stage 4 Started (Sales)
13 - Stage 4 Completed (Rental)
14 - Stage 4 Completed (Sales)
*/

DECLARE vStatusTotal INT;

SET vStatusTotal = CAST(POWER(2,COALESCE(aPrepStatus,0) + 0) + 0.5 AS INT) + CAST(POWER(2,COALESCE(aDipatchStatus,0) + 3) + 0.5 AS INT) +
                   CAST(POWER(2,COALESCE(aReturnStatus,0) + 6) + 0.5 AS INT) + CAST(POWER(2,COALESCE(aCheckInStatus,0) + 9) + 0.5 AS INT);

 IF BITAND(vStatusTotal, CAST(POWER(2,0) AS INT)) = CAST(POWER(2,0) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 0;
         ELSEIF aListType IN (1,2) THEN RETURN 0;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 0;
         ELSEIF aListType IN (1,2) THEN RETURN 0;
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,1) AS INT)) = CAST(POWER(2,1) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 1;
         ELSEIF aListType IN (1,2) THEN RETURN 1;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 1;
         ELSEIF aListType IN (1,2) THEN RETURN 1;
         END IF;
      END IF;
  ELSEIF (BITAND(vStatusTotal, CAST(POWER(2,2) AS INT)) = CAST(POWER(2,2) AS INT)) AND  (BITAND(vStatusTotal, CAST(POWER(2,3) AS INT)) = CAST(POWER(2,3) AS INT)) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 2;
         ELSEIF aListType IN (1,2) THEN RETURN 2;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 2;
         ELSEIF aListType IN (1,2) THEN RETURN 2;
         END IF;
      END IF;
/*  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,3) AS INT)) = CAST(POWER(2,3) AS INT)
      THEN RETURN 'Dispatch Pending';    */
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,4) AS INT)) = CAST(POWER(2,4) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 3;
         ELSEIF aListType IN (1,2) THEN RETURN 3;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 3;
         ELSEIF aListType IN (1,2) THEN RETURN 3;
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,5) AS INT)) = CAST(POWER(2,5) AS INT) AND (BITAND(vStatusTotal, CAST(POWER(2,6) AS INT)) = CAST(POWER(2,6) AS INT))  AND aReturnsInFuture THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 4;
         ELSEIF aListType IN (1,2) THEN RETURN 4;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 4;
         ELSEIF aListType IN (1,2) THEN RETURN 4;
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,5) AS INT)) = CAST(POWER(2,5) AS INT) AND (BITAND(vStatusTotal, CAST(POWER(2,6) AS INT)) = CAST(POWER(2,6) AS INT))  AND NOT aReturnsInFuture THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 5;
         ELSEIF aListType IN (1,2) THEN RETURN 5;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 6;
         ELSEIF aListType IN (1,2) THEN RETURN 6;
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,7) AS INT)) = CAST(POWER(2,7) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 7;
         ELSEIF aListType IN (1,2) THEN RETURN 7;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 8;
         ELSEIF aListType IN (1,2) THEN RETURN 8;
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,8) AS INT)) = CAST(POWER(2,8) AS INT) AND BITAND(vStatusTotal, CAST(POWER(2,9) AS INT)) = CAST(POWER(2,9) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 9;
         ELSEIF aListType IN (1,2) THEN RETURN 9;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 10;
         ELSEIF aListType IN (1,2) THEN RETURN 10;
         END IF;
      END IF;
/*  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,9) AS INT)) = CAST(POWER(2,9) AS INT)
      THEN RETURN 'Check In Pending';  */
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,10) AS INT)) = CAST(POWER(2,10) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 11;
         ELSEIF aListType IN (1,2) THEN RETURN 11;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 12;
         ELSEIF aListType IN (1,2) THEN RETURN 12;
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,11) AS INT)) = CAST(POWER(2,11) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 13;
         ELSEIF aListType IN (1,2) THEN RETURN 13;
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 14;
         ELSEIF aListType IN (1,2) THEN RETURN 14;
         END IF;
      END IF;
  ELSE RETURN -1;
 END IF;
END;

/* GetWarehouseProgressText */
CREATE FUNCTION GetWarehouseProgressText
(aPrepStatus INT,
 aDipatchStatus INT,
 aReturnStatus INT,
 aCheckInStatus INT,
 aListType TINYINT, --  TWarehouseActivity = (waHire, waJobSubhire, waGlobalSubhire, waJobTransfer, waGlobalTransfer, waVirtualWarehouseBuild);
 aListClass TINYINT,--   TEqlistClass = (emRentalClass, emSalesClass);
 aReturnsInFuture BOOL)
RETURNS VARCHAR(40)
DETERMINISTIC
BEGIN

/*
0 - Stage 1 Not Started (All)
1 - Stage 1 Started (All)
2 - Stage 2 Not Started (All)
3 - Stage 2 Started (All)
4 - Stage 2 Completed (All)
5 - Stage 3 Not Started (Rental)
6 - Stage 3 Not Started (Sales)
7 - Stage 3 Started (Rental)
8 - Stage 3 Started (Sales)
9 - Stage 4 Not Started (Rental)
10 - Stage 4 Not Started (Sales)
11 - Stage 4 Started (Rental)
12 - Stage 4 Started (Sales)
13 - Stage 4 Completed (Rental)
14 - Stage 4 Completed (Sales)
*/

DECLARE vStatusTotal INT;

SET vStatusTotal = CAST(POWER(2,COALESCE(aPrepStatus,0) + 0) + 0.5 AS INT) + CAST(POWER(2,COALESCE(aDipatchStatus,0) + 3) + 0.5 AS INT) +
                   CAST(POWER(2,COALESCE(aReturnStatus,0) + 6) + 0.5 AS INT) + CAST(POWER(2,COALESCE(aCheckInStatus,0) + 9) + 0.5 AS INT);

 IF BITAND(vStatusTotal, CAST(POWER(2,0) AS INT)) = CAST(POWER(2,0) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Ready for Prepping';
         ELSEIF aListType IN (1,2) THEN RETURN 'Waiting for Arrival';
         ELSEIF aListType IN (3,4) THEN RETURN 'Ready for Loan Dispatch';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Ready for Prepping';
         ELSEIF aListType IN (1,2) THEN RETURN 'Waiting for Arrival';
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,1) AS INT)) = CAST(POWER(2,1) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Prepping in progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Receiving SubHire';
         ELSEIF aListType IN (3,4) THEN RETURN 'Loan Dispatch in progress';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Prepping in progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Receiving Order';
         END IF;
      END IF;
  ELSEIF (BITAND(vStatusTotal, CAST(POWER(2,2) AS INT)) = CAST(POWER(2,2) AS INT)) AND  (BITAND(vStatusTotal, CAST(POWER(2,3) AS INT)) = CAST(POWER(2,3) AS INT)) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Ready for Dispatching';
         ELSEIF aListType IN (1,2) THEN RETURN 'Ready for Verifying';
         ELSEIF aListType IN (3,4) THEN RETURN 'Ready for Loans Receive';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Ready for Dispatching';
         ELSEIF aListType IN (1,2) THEN RETURN 'Ready for Verifying';
         END IF;
      END IF;
/*  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,3) AS INT)) = CAST(POWER(2,3) AS INT)
      THEN RETURN 'Dispatch Pending';    */
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,4) AS INT)) = CAST(POWER(2,4) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Dispatching in progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Verifying in progress';
         ELSEIF aListType IN (3,4) THEN RETURN 'Loans Receive in progress';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Dispatching in Progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Stocking In in progress';
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,5) AS INT)) = CAST(POWER(2,5) AS INT) AND (BITAND(vStatusTotal, CAST(POWER(2,6) AS INT)) = CAST(POWER(2,6) AS INT))  AND aReturnsInFuture THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Dispatch Completed';
         ELSEIF aListType IN (1,2) THEN RETURN 'Ready for Use';
         ELSEIF aListType IN (3,4) THEN RETURN 'Loans Receive Completed';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Dispatch Completed';
         ELSEIF aListType IN (1,2) THEN RETURN 'Stock In Completed';
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,5) AS INT)) = CAST(POWER(2,5) AS INT) AND (BITAND(vStatusTotal, CAST(POWER(2,6) AS INT)) = CAST(POWER(2,6) AS INT))  AND NOT aReturnsInFuture THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Ready for Returning';
         ELSEIF aListType IN (1,2) THEN RETURN 'Ready for Packing';
         ELSEIF aListType IN (3,4) THEN RETURN 'Loans Ready for Returning';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Dispatch Completed';
         ELSEIF aListType IN (1,2) THEN RETURN 'Stock In Completed';
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,7) AS INT)) = CAST(POWER(2,7) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Returning in Progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Packing in Progress';
         ELSEIF aListType IN (3,4) THEN RETURN 'Loans Returning in Progress';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'RMA in progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Rejecting Order, in progress';
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,8) AS INT)) = CAST(POWER(2,8) AS INT) AND BITAND(vStatusTotal, CAST(POWER(2,9) AS INT)) = CAST(POWER(2,9) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Ready for Checking In';
         ELSEIF aListType IN (1,2) THEN RETURN 'Ready for returning to supplier';
         ELSEIF aListType IN (3,4) THEN RETURN 'Ready for Loans Back';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'RMA Completed';
         ELSEIF aListType IN (1,2) THEN RETURN 'Rejectecting Order, Completed';
         END IF;
      END IF;
/*  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,9) AS INT)) = CAST(POWER(2,9) AS INT)
      THEN RETURN 'Check In Pending';  */
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,10) AS INT)) = CAST(POWER(2,10) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Checking in Progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Returning to Supplier';
         ELSEIF aListType IN (3,4) THEN RETURN 'Loans Back in Progress';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Returning to stock in progress';
         ELSEIF aListType IN (1,2) THEN RETURN 'Return To Supplier in progress';
         END IF;
      END IF;
  ELSEIF BITAND(vStatusTotal, CAST(POWER(2,11) AS INT)) = CAST(POWER(2,11) AS INT) THEN
      IF aListClass = 0 THEN
         IF aListType = 0 THEN RETURN 'Checking Finished';
         ELSEIF aListType IN (1,2) THEN RETURN 'Subhire Returned';
         ELSEIF aListType IN (3,4) THEN RETURN 'Loans Back Finished';
         END IF;
      ELSEIF aListClass = 1 THEN
         IF aListType = 0 THEN RETURN 'Return To Stock Completed';
         ELSEIF aListType IN (1,2) THEN RETURN 'Return To Supplier Completed';
         END IF;
      END IF;
  ELSE RETURN '';
 END IF;
END;

/* GetWarehouseStageText */
CREATE FUNCTION GetWarehouseStageText
(aListType TINYINT,
 aListClass TINYINT,
 aStage TINYINT,
 aPastParticple BOOL)
RETURNS VARCHAR(40)
DETERMINISTIC
BEGIN

  IF aListClass = 0 THEN
     IF aListType = 0 THEN
        IF (aStage = 1) THEN IF  (NOT aPastParticple) THEN RETURN 'Prep'; ELSE RETURN 'Prepped'; END IF;
        ELSEIF (aStage = 2) THEN IF  (NOT aPastParticple) THEN RETURN 'Dispatch'; ELSE RETURN 'Dispatched'; END IF;
        ELSEIF (aStage = 3) THEN IF  (NOT aPastParticple) THEN RETURN 'Return'; ELSE RETURN 'Returned'; END IF;
        ELSEIF (aStage = 4) THEN IF  (NOT aPastParticple) THEN RETURN 'Check In'; ELSE RETURN 'Checked In'; END IF;
        END IF;
     ELSEIF  aListType IN (1,2,5) THEN
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Arrival'; ELSE RETURN 'Arrived'; END IF;
        ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Available'; ELSE RETURN 'Available'; END IF;
        ELSEIF (aStage = 3) THEN IF (NOT aPastParticple) THEN RETURN 'Pack'; ELSE RETURN 'Packed'; END IF;
        ELSEIF (aStage = 4) THEN IF (NOT aPastParticple) THEN RETURN 'Return'; ELSE RETURN 'Returned'; END IF;
        END IF;
     ELSEIF  aListType IN (3,4) THEN
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Dispatch'; ELSE RETURN 'Dispatched'; END IF;
        ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Receive'; ELSE RETURN 'Received'; END IF;
        ELSEIF (aStage = 3) THEN IF (NOT aPastParticple) THEN RETURN 'Return'; ELSE RETURN 'Returned'; END IF;
        ELSEIF (aStage = 4) THEN IF (NOT aPastParticple) THEN RETURN 'Back'; ELSE RETURN 'Back'; END IF;
        END IF;
     ELSEIF  aListType IN (6) THEN
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Send'; ELSE RETURN 'Sent'; END IF;
        ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Receive'; ELSE RETURN 'Received'; END IF;
        END IF;
     ELSEIF  aListType IN (7) THEN
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Transfer'; ELSE RETURN 'Transferred'; END IF;
       -- ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Receive'; ELSE RETURN 'Received'; END IF;
        END IF;
     END IF;
   ELSE
     IF aListType = 0 THEN  -- Sales List
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Pull'; ELSE RETURN 'Pulled'; END IF;
        ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Dispatch'; ELSE RETURN 'Dispatched'; END IF;
        ELSEIF (aStage = 3) THEN IF (NOT aPastParticple) THEN RETURN 'Return (Stock In)'; ELSE RETURN 'Returned (Stocked In)'; END IF;
        ELSEIF (aStage = 4) THEN IF (NOT aPastParticple) THEN RETURN 'On Shelf'; ELSE RETURN 'On Shelf'; END IF;
        END IF;
     ELSEIF  aListType IN (1,2) THEN -- Sales Order Lists
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Goods In'; ELSE RETURN 'Goods In'; END IF;
        ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Stock In'; ELSE RETURN 'Stocked In'; END IF;
        ELSEIF (aStage = 3) THEN IF (NOT aPastParticple) THEN RETURN 'Reject (Stock Out)'; ELSE RETURN 'Rejected (Stocked Out)'; END IF;
        ELSEIF (aStage = 4) THEN IF (NOT aPastParticple) THEN RETURN 'Return'; ELSE RETURN 'Returned'; END IF;
        END IF;
     ELSEIF  aListType IN (6) THEN
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Send'; ELSE RETURN 'Sent'; END IF;
        ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Receive'; ELSE RETURN 'Received'; END IF;
        END IF;
     ELSEIF  aListType IN (7) THEN
        IF (aStage = 1) THEN IF (NOT aPastParticple) THEN RETURN 'Transfer'; ELSE RETURN 'Transferred'; END IF;
       -- ELSEIF (aStage = 2) THEN IF (NOT aPastParticple) THEN RETURN 'Receive'; ELSE RETURN 'Received'; END IF;
        END IF;
     END IF;
  END IF;
END;

/* HowManyCompositesCanBeMadeFromWarehouseStage */
CREATE FUNCTION HowManyCompositesCanBeMadeFromWarehouseStage
(aLineRef INT,
 aWarehouseOp TINYINT) -- TWarehouseOp = (woNone, woCarnet, woPrepLocal, woPrepLoan, woPrepSubHire, woDispatch, woReturn, woCheckIn);
RETURNS INT
READS SQL DATA
BEGIN
     DECLARE vResult INT DEFAULT 2147483647;
     DECLARE vMasterTypeID INT;
     DECLARE vComponentTypeID INT;
     DECLARE vComponentQty INT;
     DECLARE vOpsTypeID INT;
     DECLARE vOpsQty INT;
     DECLARE vTempQty INT;


     SET vMasterTypeID = (SELECT Type FROM Sort WHERE LineRef =  aLineRef);

     DECLARE cComponentQtys CURSOR FOR SELECT ComponentType, Quantity FROM Composit WHERE MasterType = vMasterTypeID;
     OPEN cComponentQtys;

     TRY
        DECLARE cOpsLines CURSOR FOR SELECT Type, CASE
                                                  WHEN aWarehouseOp = 1 THEN CarnetQty
                                                  WHEN aWarehouseOp IN (2,3,4) THEN PreppedQty
                                                  WHEN aWarehouseOp = 5 THEN "Out"
                                                  WHEN aWarehouseOp = 6 THEN Back
                                                  WHEN aWarehouseOp = 7 THEN CheckedInQty
                                                  END
                                                  FROM Sort WHERE LineCode = aLineRef AND LineRef <> aLineRef;
        OPEN cOpsLines;
        TRY

        FETCH FIRST FROM cOpsLines INTO vOpsTypeID, vOpsQty ;
        WHILE @@FETCH_STATUS = 0 DO

              FETCH FIRST FROM cComponentQtys INTO vComponentTypeID, vComponentQty ;
              WHILE @@FETCH_STATUS = 0 DO

                    IF vOpsTypeID = vComponentTypeID THEN
                       SET vTempQty = vOpsQty / vComponentQty;

                       IF vTempQty < vResult THEN
                          SET vResult =  vTempQty;
                       END IF;

                    END IF;

                    FETCH NEXT FROM cComponentQtys INTO vComponentTypeID, vComponentQty ;
              END WHILE;

              FETCH NEXT FROM cOpsLines INTO vOpsTypeID, vOpsQty ;
        END WHILE;

        CLOSE cOpsLines;

        CATCH TRUE
              CLOSE cOpsLines;
              SIGNAL ERROR_MESSAGE;
        END;

     CLOSE cComponentQtys;

     CATCH TRUE
           CLOSE cComponentQtys;
           SIGNAL ERROR_MESSAGE;
     END;

     RETURN vResult;

END;

