/* NumberToHex */
CREATE FUNCTION NumberToHex
( number INTEGER )
RETURNS VarChar(20)

BEGIN
    DECLARE hexString VARCHAR(255) DEFAULT '';
    DECLARE remainder INT;

    IF number = 0 THEN
        RETURN '#00';
    END IF;

    WHILE number > 0 DO
        SET remainder = MOD(number, 16);
        SET hexString = GetHexChar(remainder) + hexString;
        SET number = number / 16;
    END WHILE;

    IF CHAR_LENGTH(hexstring) = 1 THEN SET hexstring = '0' + hexstring;
    END IF;
    SET hexstring = '#' + hexstring;

    RETURN hexString;
END;

