CREATE FUNCTION RecordExists (
	TableName VARCHAR(50),
	FieldName VARCHAR(50),
	RecordID INT
	)
RETURNS BOOLEAN READS SQL DATA

BEGIN
	DECLARE query VARCHAR(500);

	SET query = 'SELECT 1 INTO #tmp FROM ' + TableName + ' WHERE ' + FieldName + ' = ' + CAST(RecordID AS VARCHAR(10));

	EXECUTE IMMEDIATE query;

	RETURN EXISTS (
