/* StocklevelsForCompany */
CREATE FUNCTION "StocklevelsForCompany"
( )
RETURNS table
READS SQL DATA
BEGIN
  declare vQuery varchar(1000);
  declare vFieldList varchar (1000);
  declare vStoreCount integer;

  set vStoreCount = 1;
  set vFieldList = '';

  while vStoreCount < 64 do
  if vStoreCount < 63 THEN
  set vFieldList = vFieldList + 'LOC' +  cast(vStoreCount as varchar(10)) + '+' ;
  Else
  set vFieldList = vFieldList + 'LOC' +  cast(vStoreCount as varchar(10)) ;
  End IF;
  set vStoreCount = vStoreCount + 1;
  End While;

  set vQuery = 'select TypeIDX, Sum(' +vFieldList + ') as StockLevel into #tmp from Whlevel  group  by TypeIDX';

  EXECUTE IMMEDIATE vQuery ;

  return select * from #tmp order by TypeIDX;
END;

/* StocklevelsForSite */
CREATE FUNCTION StocklevelsForSite
( aSite integer)
RETURNS table
READS SQL DATA
BEGIN
  declare vQuery varchar(1000);
  declare vFieldList varchar (1000);
  declare vStoreCount integer;

  set vStoreCount = 1;
  set vFieldList = '';

  while vStoreCount < 64 do
  if vStoreCount < 63 THEN
  set vFieldList = vFieldList + 'LOC' +  cast(vStoreCount as varchar(10)) + '+' ;
  Else
  set vFieldList = vFieldList + 'LOC' +  cast(vStoreCount as varchar(10)) ;
  End IF;
  set vStoreCount = vStoreCount + 1;
  End While;

  set vQuery = 'select xSite, TypeIDX, ' +vFieldList + ' as StockLevel into #tmp from Whlevel where xSite = '  + cast(aSite as varchar(10)) ;

  EXECUTE IMMEDIATE vQuery ;

  return select * from #tmp order by TypeIDX;
END;

/* StockTakeLateReturnedBarcodes */
CREATE FUNCTION StockTakeLateReturnedBarcodes
(aStockTakeID INT )
RETURNS TABLE
READS SQL DATA

BEGIN
SELECT DISTINCT O.xItemRef
INTO #Late
FROM OpScans O

WHERE
xEqLineRef IN (SELECT LineRef
            FROM vLateReturns)
AND OpsType < 6
AND
NOT EXISTS (SELECT COUNT(*)
            FROM StockTakeDetails S
            WHERE
            S.xItemID = O.xItemRef
            AND
            S.xStockTake =  aStockTakeID
            HAVING COUNT( * ) > 0);

RETURN
SELECT I.Barcode, H."Description", E.Eql_Name, J.Job_Ref, J."Name" AS Customer, S.SiteName AS Owner, W.WarehouseName as HomeLocation
FROM #Late O
INNER JOIN Item I
ON O.xItemRef = I.ItemRef
INNER JOIN Hetype H
ON I."Type" = H."Type"
INNER JOIN Eqlists E
ON I.CurrentJob = E.Eql_no
INNER JOIN Jobs J
ON E.Job_no = J.Jobno
INNER JOIN Sites S
ON I.Int1 = S.Idx
INNER JOIN Warehouses W
ON I.Homelocation = W.Idx
ORDER BY I.Barcode;

END;

/* StockTakeNotSeenBarcodes */
CREATE FUNCTION StockTakeNotSeenBarcodes
(aStockTakeID INT )
RETURNS TABLE
READS SQL DATA

BEGIN
DECLARE vDate TIMESTAMP;

SET vDate = (SELECT StartDate
             FROM StockTakes
             WHERE
             IDX = aStockTakeID);

--TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bscDisposed);
SELECT I.Barcode, I.Type, I.CurrentJob, I.Int1, I.Homelocation
INTO #NotSeen
FROM Item I

WHERE
CommissionStatus IN (0,1,5)  --TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bcsDisposed, bcsLoggedForRepair);
AND
NOT EXISTS (SELECT COUNT(*)
            FROM Opscans O
            WHERE
            O.xItemRef = I.ItemRef
            AND
            O.ScanDate > vDate
            HAVING COUNT( * ) > 0)
AND
NOT EXISTS (SELECT COUNT(*)
            FROM StockTakeDetails S
            WHERE
            S.xItemID = I.ItemRef
            AND
            S.xStockTake =  aStockTakeID
            HAVING COUNT( * ) > 0);

RETURN
SELECT I.Barcode, I.Type, I.CurrentJob, H."Description", E.Eql_Name, J.Job_Ref, J."Name" AS Customer, S.SiteName AS Owner, W.WarehouseName as HomeLocation
FROM  #NotSeen I
INNER JOIN Hetype H
ON I."Type" = H."Type"
INNER JOIN Eqlists E
ON I.CurrentJob = E.Eql_no
INNER JOIN Jobs J
ON E.Job_no = J.Jobno
INNER JOIN Sites S
ON I.Int1 = S.Idx
INNER JOIN Warehouses W
ON I.Homelocation = W.Idx
ORDER BY I.Barcode;

END;

/* SYS_REPARSEALL_IMPLEMENTATION */
CREATE FUNCTION SYS_REPARSEALL_IMPLEMENTATION()
RETURNS TABLE
MODIFIES SQL DATA
BEGIN
  CREATE TABLE #ROUTINES (
    TYPE      NVARCHAR(9),
    NAME      NVARCHAR(255),
    SOURCE    NCLOB,
    SUCCESS   BOOLEAN,
    ERROR_MSG NCLOB,
    PRIMARY KEY (TYPE, NAME)
  );

  INSERT INTO #ROUTINES (TYPE, NAME, SOURCE)
  (
    SELECT
      'PROCEDURE' AS TYPE,
      PROCEDURE_NAME AS NAME,
      PROCEDURE_SOURCE AS SOURCE
    FROM #PROCEDURES
  );

  INSERT INTO #ROUTINES (TYPE, NAME, SOURCE)
  (
    SELECT
      'FUNCTION' AS TYPE,
      FUNCTION_NAME AS NAME,
      FUNCTION_SOURCE AS SOURCE
    FROM #FUNCTIONS
  );

  INSERT INTO #ROUTINES (TYPE, NAME, SOURCE)
  (
    SELECT
      'TRIGGER' AS TYPE,
      TRIGGER_NAME AS NAME,
      TRIGGER_SOURCE AS SOURCE
    FROM #TRIGGERS
  );

  DECLARE lTYPE NVARCHAR(9);
  DECLARE lNAME NVARCHAR(255);
  DECLARE lSOURCE NCLOB;
  DECLARE lSOURCEAlter NCLOB;
  DECLARE lSUCCESS BOOLEAN;
  DECLARE lERROR_MSG NCLOB;
  DECLARE cRoutines CURSOR FOR SELECT TYPE, NAME, SOURCE FROM #ROUTINES ORDER BY TYPE, NAME;

  OPEN cRoutines;
  TRY

  FETCH FIRST FROM cRoutines INTO lTYPE, lNAME, lSOURCE;
  WHILE @@FETCH_STATUS = 0 DO

    SET lSOURCEAlter = 'CREATE OR ALTER' || SUBSTRING(lSOURCE FROM 7);

    SET lSUCCESS=NULL;
    SET lERROR_MSG=NULL;
    TRY
      EXECUTE IMMEDIATE lSOURCEAlter;
      SET lSUCCESS=TRUE;
    CATCH TRUE
      SET lSUCCESS=FALSE;
      SET lERROR_MSG=ERROR_MESSAGE;
    END;

    UPDATE #ROUTINES SET
      SUCCESS = lSUCCESS,
      ERROR_MSG = lERROR_MSG
    WHERE
          TYPE = lTYPE
      AND NAME = lNAME;

    FETCH NEXT FROM cRoutines INTO lTYPE, lNAME, lSOURCE;
  END WHILE;

  CLOSE cRoutines;

  CATCH TRUE
  CLOSE cRoutines;
  SIGNAL ERROR_MESSAGE;
  END;

  RETURN SELECT * FROM #ROUTINES;
END;

