/* TimeStampString */
CREATE FUNCTION TimeStampString
(aMode TINYINT
/* 0 = return date string only
   1 = return time string only
   2 = return date time string */)
RETURNS VARCHAR(20)
BEGIN
     IF aMode = 0 THEN
        RETURN CAST(F_FORMATDATE(Current_Date) AS VARCHAR(20));
     ELSEIF aMode = 1 THEN
        RETURN CAST(ToString(Current_Time) AS VARCHAR(20));
     ELSE
        RETURN CAST(F_FORMATDATE(Current_Date) AS VARCHAR(10)) + ' @ '  + CAST(ToString(Current_Time) AS VARCHAR(5));
     END IF;
END;

/* TriggersActive */
CREATE FUNCTION TriggersActive()
RETURNS BOOLEAN
MODIFIES SQL DATA
BEGIN

DECLARE vTriggersActive BOOLEAN;
SET  vTriggersActive = FALSE;

START TRANSACTION;

TRY

UPDATE hiretrack_version
 SET TriggerCheck = COALESCE(TriggerCheck,0) + 1;

COMMIT;

CATCH POSITION('Triggers are active' IN ERROR_MESSAGE ) <> 0

SET  vTriggersActive = TRUE;

END;

RETURN vTriggersActive;

END;

/* TriggersActive_v4 */
CREATE FUNCTION TriggersActive_v4()
RETURNS BOOLEAN
MODIFIES SQL DATA
BEGIN

DECLARE vTriggersActive BOOLEAN;
SET  vTriggersActive = FALSE;

START TRANSACTION;

TRY

 UPDATE hiretrack_version
  SET TriggerCheck = COALESCE(TriggerCheck,0) + 1;

COMMIT;

CATCH POSITION('Triggers are active' IN ERROR_MESSAGE ) <> 0

 ROLLBACK;
 SET  vTriggersActive = TRUE;

END;

RETURN vTriggersActive;

END;

/* TypeIsOnJobs */
CREATE FUNCTION TypeIsOnJobs
( aTypeID INT,
  aIsActive BOOL)
RETURNS BOOL
READS SQL DATA
BEGIN

IF aIsActive IS NULL THEN   --  been out and back
 RETURN (SELECT COUNT(*) > 0
         FROM "Sort"
         WHERE
         "Type" = aTypeID
         AND NotBack = FALSE
         AND PreppedQty > 0);

ELSEIF aIsActive THEN        -- lists on warehouse ops
 RETURN (SELECT COUNT(*) > 0
         FROM "Sort"
         WHERE
         "Type" = aTypeID
         AND NotBack = TRUE);
ELSE
 RETURN (SELECT COUNT(*) > 0 -- lists awaiting warehouse ops
         FROM "Sort"
         WHERE
         "Type" = aTypeID
         AND NotBack = FALSE
         AND PreppedQty = 0);
END IF;

END;

/* UserHasFeatureAccess */
CREATE FUNCTION UserHasFeatureAccess
(aUserID INT,
 aFeatureEnum VARCHAR(50) )
RETURNS TINYINT
READS SQL DATA
BEGIN

-- see   TSecurityLevel  = (slFeatureUnassigned, slAllowFeature, slReadData, slEditData, slCreateData);
IF (SELECT SystemAdmin FROM Users WHERE UID = aUserID) THEN
  RETURN 4;
ELSE

  SELECT TOP 1 C.SecurityLevel
  INTO #Tmp
  FROM Features F
  INNER JOIN FeatureCollectionsLkp C
  ON F.UID = C.xFeatureID
  INNER JOIN UserFeatures U
  ON C.xFeatureCollection = U.xFeatureCollection
  WHERE
  F.FeatureEnum = aFeatureEnum
  AND U.xUser = aUserID
  ORDER BY
  SecurityLevel DESC;

  RETURN COALESCE((SELECT SecurityLevel FROM #Tmp),0);
END IF;

END;

