/* CloneJobContacts */
CREATE PROCEDURE CloneJobContacts (
		aSourceJobID INT,
                aDestJobID INT
		)
MODIFIES SQL DATA
BEGIN

INSERT INTO Contacts (
	Company,
	Person,
	TelephoneNumber,
	"Position",
	Email,
	xLink,
	RecordType,
	MainContact,
        MobileNumber,
        xRecordStatus
	)
SELECT	Company,
	Person,
	TelephoneNumber,
	"Position",
	Email,
        aDestJobID,
	RecordType,
	MainContact,
        MobileNumber,
        xRecordStatus
FROM Contacts
WHERE xLink = aSourceJobID
      AND RecordType = 'ctJobs';


END ;

/* CloneJobCosts */
CREATE PROCEDURE CloneJobCosts (
		aSourceJobID INT,
    aDestJobID INT )
MODIFIES SQL DATA
BEGIN

 DECLARE vCostID INT;

 DECLARE cJobCosts CURSOR FOR
   SELECT IDX
   FROM Costs
   WHERE
   xJob = aSourceJobID
   AND xInternalCostCentre = 0
   ORDER BY
   IDX;

 OPEN cJobCosts;
 TRY
 FETCH NEXT FROM cJobCosts INTO vCostID;

 WHILE @@FETCH_STATUS = 0 DO

       CloneCost(vCostID,aDestJobID);

       FETCH NEXT FROM cJobCosts INTO vCostID;

 END WHILE;

 CLOSE cJobCosts;

 CATCH TRUE
 CLOSE cJobCosts;
 SIGNAL ERROR_MESSAGE;
 END;

END;

/* CloneJobDiary */
CREATE PROCEDURE CloneJobDiary (
		aSourceJobID INT,
    aDestJobID INT,
    aDaysAdd INT )
MODIFIES SQL DATA
BEGIN

 DECLARE vDiaryID INT;

 DECLARE cJobDiary CURSOR FOR
   SELECT IDX
   FROM Diary
   WHERE
   xEventOwnerID = aSourceJobID
   ORDER BY
   IDX;

 OPEN cJobDiary;
 TRY
 FETCH NEXT FROM cJobDiary INTO vDiaryID;

 WHILE @@FETCH_STATUS = 0 DO

       CloneDiary(vDiaryID, aDestJobID, aDaysAdd);

       FETCH NEXT FROM cJobDiary INTO vDiaryID;

 END WHILE;

 CLOSE cJobDiary;

 CATCH TRUE
 CLOSE cJobDiary;
 SIGNAL ERROR_MESSAGE;
 END;

END;

