CREATE PROCEDURE CloneJobNarratives (
		aSourceJobID INT,
    aDestJobID INT )
MODIFIES SQL DATA
BEGIN

 INSERT INTO JobNarratives
 (xJob, Narrative, xJobNarrativeAreas, Active)
 SELECT
 aDestJobID, Narrative, xJobNarrativeAreas, Active
 FROM JobNarratives
 WHERE
 xJob = aSourceJobID;

END;

/* CopyEqlistLines */
CREATE PROCEDURE CopyEqlistLines
( aDestEqlistID INT,
  aSourceLineIDs TEXT,
  aDestSectionID INT,
  aClassTransferType TINYINT -- TClassTransferType = (cttToNone, cttToSalesExRental, cttToRental, ccToSalesNew);
  )
MODIFIES SQL DATA
BEGIN

 DECLARE vDynamicSQL TEXT;
 DECLARE vOldLookupField INT;
 DECLARE vNewLookupField INT;
 DECLARE vSectionSortOrder INT;
 DECLARE vMaxLineSortOrder INT;
 DECLARE vTextField VARCHAR(255);
 DECLARE vWhereClause TEXT;
 DECLARE vDestEqlistPriceLocked BOOL;
 DECLARE vQuant VARCHAR(120);
 DECLARE vChargeQuant VARCHAR(120);
 DECLARE vRecType VARCHAR(120);
 SET vWhereClause = 'WHERE LineRef IN (' +  aSourceLineIDs + ') AND Virt = FALSE AND RecType <> 17'; --etCompositePrepModified = 17

 IF aClassTransferType = 1 THEN -- do not clone consumables as they will have been sold!
    SET vWhereClause = vWhereClause + ' AND xCat > 0';
 END IF;

 IF aClassTransferType = 3 THEN -- if rental list has reminders then set these 1) as normal and 2) make sure that the ChargeQty = Quant if they have been set to no charge
    SET vQuant = 'Quant,';
    SET vChargeQuant = 'ChargeQuantity,';
    SET vRecType = 'CASE WHEN RecType IN (4,5,8,9,10,15,16,17) THEN 10 WHEN RecType IN (2,3,6,7,14) THEN 1  else RecType END AS RecType,';
 ELSE
    SET vQuant = 'CASE WHEN RecType IN (16,17) THEN ChargeQuantity ELSE Quant END AS Quant,';
    SET vChargeQuant = 'ChargeQuantity,';
    SET vRecType = 'CASE WHEN RecType IN (16,17) THEN 10 else RecType END AS RecType,';
 END IF;

 --Get Sort rows
 SET vDynamicSQL =
 'SELECT
 "Type",' +
  vQuant +
  vChargeQuant +
	'Xcat,' +
	CAST(aDestEqlistID AS VARCHAR(10)) + ' AS Eqlno,
	Virt,
	D1,
	D2,
	Alloc,
	Defcon,
	Subhire,
	ListType,
	Daily,
	DailyMultiplier,
	PreDiscount,
	Discount,
	Price,
	0 InvoicedTotal,
	False AS Invoiced,
	Notes,
	Slink1,
	Slink2,
	sectionID,
	xFreeText,
	SortOrder,'+
  vRecType +
  'CASE WHEN RecType IN (7,9,13) THEN xGUID ELSE NEWGUID END AS xGUID,
	0 AS LoansInQty,
	0 AS SubHiredQty,
	0 AS CarnetQty,
	0 AS PreppedQty,
	0 AS "Out",
	0 AS Back,
	0 AS CheckedInQty,
	UnitWeight,
	UnitValue,
	LineRef AS oldLineRef,
	FALSE NotBack,
  CurrentCostPrice,
  AnticipatedCostPrice,
	0 AS xLateEqlno,
        xTransferInWarehouse,
	CAST (NULL AS INT) AS xTransferToLine
      INTO #Sort
      FROM "SORT" '
      + vWhereClause;

 EXECUTE IMMEDIATE  vDynamicSQL;

 SET vMaxLineSortOrder = (SELECT MAX(SortOrder) FROM #Sort);

 UPDATE #Sort SET
 SortOrder = SortOrder + vMaxLineSortOrder;

 -- sort out sync'd Priced Alias GUIDs
 DECLARE vOldGUID, vNewGUID GUID;

 DECLARE cGUIDs CURSOR FOR
 SELECT xGUID
 FROM #Sort
 WHERE
 Rectype = 13;

 OPEN cGUIDs;
 TRY
 FETCH FIRST FROM cGUIDs INTO vOldGUID;

 WHILE @@FETCH_STATUS = 0 DO
       SET vNewGUID = NEWGUID;

       UPDATE #Sort SET
       xGUID = vNewGUID
       WHERE
       xGUID = vOldGUID;

FETCH NEXT  FROM cGUIDs INTO vOldGUID;
END WHILE;

CLOSE cGUIDs;

CATCH TRUE
  CLOSE cGUIDs;
  SIGNAL ERROR_MESSAGE;
END;

-- Ensure that eqlist lines are in sync with eqlist header
SELECT E.* INTO #Eqlists
FROM Eqlists E
WHERE E.Eql_no = aDestEqlistID;

SET vDestEqlistPriceLocked = (SELECT Int2 > 0 FROM #Eqlists);

UPDATE "#Sort" S SET
S.Defcon = (SELECT Defcon FROM #Eqlists),
S.Subhire = (SELECT Subhire FROM #Eqlists),
S.ListType = (SELECT ListType FROM #Eqlists),
S.Slink1 = (SELECT MainSite FROM #Eqlists),
S.Slink2 = (SELECT Int1 FROM #Eqlists),
S.D1 = (SELECT CASE
        WHEN PrepAvail THEN PrepDate
        ELSE DateOut
        END
        FROM #Eqlists),
S.D2 = (SELECT CASE
        WHEN CheckInAvail THEN CheckInDate
        ELSE DateBack
        END
        FROM #Eqlists),
-- price locking
S.Discount = CASE WHEN vDestEqlistPriceLocked THEN 100 ELSE S.Discount END,
S.Price = CASE WHEN vDestEqlistPriceLocked THEN 0 ELSE S.Price END,
S.xTransferInWarehouse = (SELECT xTransferInWarehouse FROM #Eqlists);

 --Get FreeText
 SET vDynamicSQL = 'SELECT * INTO #FreeText FROM FreeText  WHERE Idx IN (SELECT xFreeText FROM "SORT" ' + vWhereClause + ');';
 EXECUTE IMMEDIATE  vDynamicSQL;

 IF aDestSectionID IS NULL THEN
   --Get Section headers for source list and replicate
  SET vDynamicSQL = 'SELECT * INTO #EqSections FROM EqSections  WHERE Idx IN (SELECT DISTINCT SectionID FROM "SORT" ' + vWhereClause + ');';
  EXECUTE IMMEDIATE  vDynamicSQL;

  -- new Section headers
  DECLARE cEqSections CURSOR FOR SELECT IDX, SectionText, SortOrder FROM #EqSections;
  OPEN cEqSections;
  TRY
  FETCH NEXT FROM cEqSections INTO vOldLookupField, vTextField, vSectionSortOrder ;
  WHILE @@FETCH_STATUS = 0 DO

  INSERT INTO EqSections
  (SectionText,xEqlno, SortOrder)
  VALUES
  (vTextField,aDestEqlistID,vSectionSortOrder);

  SET vNewLookupField = LASTAUTOINC;

  UPDATE "#Sort" SET
  sectionID = vNewLookupField
  WHERE sectionID = vOldLookupField;

  FETCH NEXT FROM cEqSections INTO vOldLookupField, vTextField, vSectionSortOrder;

  END WHILE;

  CLOSE cEqSections;

  CATCH TRUE
  CLOSE cEqSections;
  SIGNAL ERROR_MESSAGE;
END;

 ELSE
 -- we are writing to a specific existing section
  UPDATE "#Sort" SET
  sectionID = aDestSectionID;
 END IF;

 -- new FreeText lines
 DECLARE cFreeText CURSOR FOR SELECT * FROM #FreeText;
 OPEN cFreeText;

 TRY
 FETCH NEXT FROM cFreeText INTO vOldLookupField, vTextField ;
 WHILE @@FETCH_STATUS = 0 DO

 INSERT INTO FreeText
  (fText)
 VALUES
  (vTextField);

 SET vNewLookupField = LASTAUTOINC;

  UPDATE "#Sort" SET
  xFreetext = vNewLookupField
  WHERE xFreetext = vOldLookupField;

  FETCH NEXT FROM cFreeText INTO vOldLookupField, vTextField;

 END WHILE;
 CLOSE cFreeText;

 CATCH TRUE
  CLOSE cFreeText;
  SIGNAL ERROR_MESSAGE;
END;

 -- if a copying to a different equipment class then update the Type field. The list will need to be re-priced in the client
 IF aClassTransferType <> 0 THEN   --TClassTransferType = (cttToNone, cttToSalesExRental, cttToRental, ccToSalesNew);
    UPDATE #Sort S SET
    S.TYPE =     (SELECT CASE
                         WHEN aClassTransferType = 1 THEN ToExRentalSales
                         WHEN aClassTransferType = 2 THEN COALESCE(ToRental, ToConsumable)
                         ELSE
                         ToNewSales
                         END
                  FROM Hetype H
                  WHERE
                  H.Type = S.Type);

    -- sync the category for the new type
    UPDATE #Sort S SET
    S.xCat = (SELECT H.Category
             FROM Hetype H
             WHERE
             H.Type = S.Type),
    S.Discount = 0,
    S.Notes = '';

    -- if this has resulted in some null S.Type records due to there being no linked type for the aClassTransferType then delete them
    DELETE FROM #Sort
    WHERE
    Type IS NULL
    AND RecType > 0;

 END IF;

 -- Finally create actual new lines
 INSERT INTO "Sort" (
	"Type",
	Quant,
  ChargeQuantity,
	Xcat,
	Eqlno,
	Virt,
	D1,
	D2,
	Alloc,
	Defcon,
	Subhire,
	ListType,
	Daily,
	DailyMultiplier,
	PreDiscount,
	Discount,
	Price,
	InvoicedTotal,
	Invoiced,
	Notes,
	Slink1,
	Slink2,
	sectionID,
	xFreeText,
	SortOrder,
	RecType,
	xGUID,
	LoansInQty,
	SubHiredQty,
	CarnetQty,
	PreppedQty,
	"Out",
	Back,
	CheckedInQty,
	UnitWeight,
	UnitValue,
	oldLineRef,
	NotBack,
  CurrentCostPrice,
  AnticipatedCostPrice,
	xLateEqlno,
	xTransferInWarehouse,
	xTransferToLine
	)
 SELECT *
 FROM "#Sort";

 --Clean up empty sections after the INSERT
 DELETE FROM EqSections
 WHERE
 xEqlno = aDestEqlistID
 AND SectionText = 'Default Section Header'
 AND Idx NOT IN (SELECT sectionID FROM Sort WHERE Eqlno = aDestEqlistID);

END;

/* CreateCrewJobFinanceRecord */
CREATE PROCEDURE CreateCrewJobFinanceRecord
(aJobno INT,
 aIsIncome BOOL,
 aCostCentreID INT,
 aStatus INT,
 aLastQuotedDate TIMESTAMP,
 aQuotedPrice MONEY,
 aActualPrice MONEY,
 aRef VARCHAR(50),
 aTitle VARCHAR(255),
 aSubCostCentre TINYINT)
 MODIFIES SQL DATA -- or write access
BEGIN

IF aIsIncome THEN
 INSERT into JobFinances
 (xJob,    IsIncome, xCostCentreID, xGeneralCostCentre, xStatus,  LastQuotedDate, QuotedPrice, ActualPrice, Reference, Title, SubCostCentre)
 VALUES
 (aJobno, aIsIncome, aCostCentreID,          1,      aStatus, aLastQuotedDate, COALESCE(aQuotedPrice,0), aActualPrice, aRef, aTitle, aSubCostCentre);
ELSE
 INSERT into JobFinances
 (xJob,    IsIncome, xCostCentreID, xGeneralCostCentre, xStatus,  LastQuotedDate, QuotedPrice, Reference, Title, SubCostCentre)
 VALUES
 (aJobno, aIsIncome, aCostCentreID,          1,      aStatus, aLastQuotedDate, COALESCE(aQuotedPrice,0), aRef, aTitle, aSubCostCentre);
END IF;
END;

/* CreateMarkUpForEqlist */
CREATE PROCEDURE CreateMarkUpForEqlist
(  aEqlistID INT, aMarkupID INT)
 MODIFIES SQL DATA -- or write access
BEGIN

IF NOT aMarkupID IS NULL THEN
     INSERT INTO EqlistMarkups
     (xEqlno,xMarkupID,xMarkUpKind,rate)
     SELECT
     aEqlistID, aMarkupID, MarkupKind, Rate
     FROM
     vMarkups
     WHERE
     MarkupID = aMarkupID;
 ELSE
     INSERT INTO EqlistMarkups
     (xEqlno,xMarkupID,xMarkUpKind,rate)
     SELECT
     aEqlistID, aMarkupID, MarkupKind, Rate
     FROM
     vMarkups
     WHERE
     Active = TRUE;
 END IF;
END;

/* CreatePrepPackInstanceFromTemplate */
CREATE PROCEDURE CreatePrepPackInstanceFromTemplate
( aTemplateTypeID INT, aMasterItem INT)
MODIFIES SQL DATA
BEGIN

 -- clear the PrePackInstance
 CALL DeletePrepPackInstance(aMasterItem);

 DECLARE vQty INT;
 DECLARE vLinkedType INT;

 DECLARE cPrePack CURSOR FOR
 SELECT R.xLinkedType, R.Quantity
 FROM PrePackTemplates R
 WHERE
 R.xTemplateType = aTemplateTypeID
 ORDER BY
 R.SortOrder;

 OPEN cPrePack;
 TRY
 FETCH FIRST FROM cPrePack INTO vLinkedType, vQty;
 -- fill the PrePackInstance
 WHILE @@FETCH_STATUS = 0 DO
       REPEAT
             INSERT INTO PrePackInstances
             (xMasterItem, xLinkedType, Required)
             VALUES
             (aMasterItem,vLinkedType, TRUE);

             SET vQty = vQty - 1;

       UNTIL vQty = 0
       END REPEAT;

 FETCH NEXT FROM cPrePack INTO vLinkedType, vQty;
 END WHILE;

 CLOSE cPrePack;

 CATCH TRUE
  CLOSE cPrePack;
  SIGNAL ERROR_MESSAGE;
 END;

END;

/* DeletePrepPackInstance */
CREATE PROCEDURE DeletePrepPackInstance
( aMasterItem INT)
MODIFIES SQL DATA
BEGIN

  DELETE FROM PrePackInstances
  WHERE
  xMasterItem = aMasterItem;

END;

/* DoOverDueDairy */
CREATE PROCEDURE DoOverDueDairy(
 aOwnerID INTEGER,
 aEventType INTEGER)
MODIFIES SQL DATA
BEGIN
-- TEventStatus = (esNotDone, esInitiated, esOverdue, esCompleted);
IF (aOwnerID IS NULL) OR (aEventType IS NULL) THEN
 UPDATE Diary SET
 Status = 2
 WHERE
 Status IS NOT NULL
 AND Status < 2
 AND DueDate < CURRENT_TIMESTAMP;
ELSE
 UPDATE Diary SET
 Status = 2
 WHERE
 Status IS NOT NULL
 AND Status < 2
 AND DueDate < CURRENT_TIMESTAMP
 AND xEventOwnerID = aOwnerID
 AND EventType = aEventType;
END IF;
END;

/* DoTags */
CREATE PROCEDURE DoTags
(
    IN aTableName SHORTSTRING(50),
    aRecord INTEGER
)
-- READS SQL DATA -- needs either read-access
MODIFIES SQL DATA -- or write access
BEGIN
    -- ============================================================================
    -- Reference: InheritTags procedure signature
    -- CREATE PROCEDURE InheritTags
    -- (IN aDonorType INTEGER,
    --     aDonerRecords STRING,
    --     aRecipientType INTEGER,
    --     aRecipientRecord INTEGER)
    --
    -- TTagType = (TTCustom=0, TTJob=1, TTCompany=2, TTPerson=3, TTEquipmentType,
    --             TTEquipmentItem, TTProject, TTCRM, TTEquipmentList, TTPurchaseOrder)
    -- Can be extended - DO NOT INSERT new values
    -- ============================================================================

    -- TTagType Constants
    DECLARE TTCustom INTEGER DEFAULT 0;
    DECLARE TTJob INTEGER DEFAULT 1;
    DECLARE TTCompany INTEGER DEFAULT 2;
    DECLARE TTPerson INTEGER DEFAULT 3;
    DECLARE TTEquipmentType INTEGER DEFAULT 4;
    DECLARE TTEquipmentItem INTEGER DEFAULT 5;
    DECLARE TTProject INTEGER DEFAULT 6;
    DECLARE TTCRM INTEGER DEFAULT 7;
    DECLARE TTEquipmentList INTEGER DEFAULT 8;
    DECLARE TTPurchaseOrder INTEGER DEFAULT 9;

    -- Working Variables
    DECLARE DonorRecord SHORTSTRING(10);        -- Single value
    DECLARE ListDonorRecords SHORTSTRING(100);  -- Comma-separated LIST
    DECLARE vTableName SHORTSTRING(50);
    DECLARE Intermediate INTEGER;

    -- ============================================================================
    -- Main Logic
    -- ============================================================================
    SET vTableName = LOWER(aTableName);

    -- ----------------------------------------------------------------------------
    -- JOBS: Inherit from Client
    -- ----------------------------------------------------------------------------
    IF vTableName = 'jobs' THEN
        SET DonorRecord = (
            SELECT CAST(Client AS VARCHAR(10))
            FROM Jobs
            WHERE JobNo = aRecord
        );
        CALL InheritTags(TTCompany, DonorRecord, TTJob, aRecord);

    -- ----------------------------------------------------------------------------
    -- COMPANY: Just doing Default Tags
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'company' THEN
        CALL InheritTags(TTCompany, '', TTCompany, aRecord);

    -- ----------------------------------------------------------------------------
    -- NAME2 (Person): Just doing Default Tags
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'name2' THEN
        CALL InheritTags(TTPerson, '', TTPerson, aRecord);

    -- ----------------------------------------------------------------------------
    -- PORDER (Purchase Order): Just doing Default Tags
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'porder' THEN
        CALL InheritTags(TTPurchaseOrder, '', TTPurchaseOrder, aRecord);

    -- ----------------------------------------------------------------------------
    -- EQLISTS (Equipment Lists): Deal with Venue, Client, and Job
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'eqlists' THEN
        -- Get Venue and Client
        SET ListDonorRecords = (
            SELECT LIST(DISTINCT Donor)
            FROM (
                SELECT CAST(Client_no AS VARCHAR(10)) AS Donor
                FROM eqlists
                WHERE eql_no = aRecord

                UNION

                SELECT CAST(Venue_no AS VARCHAR(10)) AS Donor
                FROM eqlists
                WHERE eql_no = aRecord
            )
        );
        CALL InheritTags(TTCompany, ListDonorRecords, TTEquipmentList, aRecord);

        -- Get Job
        SET DonorRecord = (
            SELECT CAST(job_no AS VARCHAR(10))
            FROM eqlists
            WHERE eql_no = aRecord
        );
        CALL InheritTags(TTJob, DonorRecord, TTEquipmentList, aRecord);

    -- ----------------------------------------------------------------------------
    -- PROJECT: Deal with Venue
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'project' THEN
        SET DonorRecord = (
            SELECT CAST(proj_xVenue AS VARCHAR(10))
            FROM Project
            WHERE Idx = aRecord
        );
        CALL InheritTags(TTCompany, DonorRecord, TTProject, aRecord);

    -- ----------------------------------------------------------------------------
    -- CRMLEADS: Deal with Company
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'crmleads' THEN
        SET DonorRecord = (
            SELECT CAST(xCompany AS VARCHAR(10))
            FROM crmleads
            WHERE Idx = aRecord
        );
        CALL InheritTags(TTCompany, DonorRecord, TTCRM, aRecord);

    -- ----------------------------------------------------------------------------
    -- HETYPE (Equipment Type): Deal with Supplier and Manufacturer
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'hetype' THEN
        SET ListDonorRecords = (
            SELECT LIST(DISTINCT Donor)
            FROM (
                SELECT CAST(Pattest AS VARCHAR(10)) AS Donor
                FROM hetype
                WHERE "type" = aRecord

                UNION

                SELECT CAST(xmanufacturer AS VARCHAR(10)) AS Donor
                FROM hetype
                WHERE "type" = aRecord
            )
        );
        CALL InheritTags(TTCompany, ListDonorRecords, TTEquipmentType, aRecord);

    -- ----------------------------------------------------------------------------
    -- CONTACTS: Deal with Company -> Person relationship
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'contacts' THEN
        SET DonorRecord = (
            SELECT CAST(company AS VARCHAR(10))
            FROM contacts
            WHERE contactscounter = aRecord
        );
        SET Intermediate = (
            SELECT person
            FROM contacts
            WHERE contactscounter = aRecord
        );
        CALL InheritTags(TTCompany, DonorRecord, TTPerson, Intermediate);

    -- ----------------------------------------------------------------------------
    -- SORT (Equipment List Lines): Deal with Equipment Types
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'sort' THEN
        SET DonorRecord = (
            SELECT CAST("type" AS VARCHAR(10))
            FROM "sort"
            WHERE lineref = aRecord
        );
        SET Intermediate = (
            SELECT eqlno
            FROM "sort"
            WHERE lineref = aRecord
        );
        CALL InheritTags(TTEquipmentType, DonorRecord, TTEquipmentList, Intermediate);

    -- ----------------------------------------------------------------------------
    -- ITEM: Deal with Equipment Type and Purchase Order
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'item' THEN
        -- Inherit from Equipment Type
        SET DonorRecord = (
            SELECT CAST("type" AS VARCHAR(10))
            FROM item
            WHERE itemref = aRecord
        );
        CALL InheritTags(TTEquipmentType, DonorRecord, TTEquipmentItem, aRecord);

        -- Inherit from Purchase Order (if exists)
        DECLARE MyKey INTEGER;

        SET MyKey = COALESCE(
            (
                SELECT A.xWarehouseOpLine
                FROM "Item"
                INNER JOIN Audit A ON CostCentre = A.auditkey
                WHERE itemref = aRecord
            ),
            0
        );

        IF (MyKey > 0) THEN
            SET ListDonorRecords = (
                SELECT LIST(DISTINCT CAST(INVNO AS VARCHAR(10))) AS PONumber
                FROM OperationsDetail
                INNER JOIN POData P ON xeqlistline = sortlink
                WHERE RowType = 5
                  AND OperationsDetail.idx = MyKey
            );
        ELSE
            SET ListDonorRecords = (
                SELECT '0' AS PONumber
                FROM #DUMMY
            );
        END IF;

        -- Only call if we found actual PO numbers
        IF ListDonorRecords <> '0' THEN
            CALL InheritTags(TTPurchaseOrder, ListDonorRecords, TTEquipmentItem, aRecord);
        END IF;

    -- ----------------------------------------------------------------------------
    -- PROJJOB (Project-Job Link): Deal with Project -> Job relationship
    -- ----------------------------------------------------------------------------
    ELSEIF vTableName = 'projjob' THEN
        SET DonorRecord = (
            SELECT CAST("xproject" AS VARCHAR(10))
            FROM projjob
            WHERE Idx = aRecord
        );
        SET Intermediate = (
            SELECT "xjob"
            FROM projjob
            WHERE Idx = aRecord
        );
        CALL InheritTags(TTProject, DonorRecord, TTJob, Intermediate);

    END IF;
END;

/* GenerateTableFieldListing */
CREATE PROCEDURE GenerateTableFieldListing
( aTableName varchar(30))
READS SQL DATA
BEGIN

// for development use only

DECLARE vQuery CLOB ;
DECLARE vFieldName VARCHAR(50);
DECLARE vLineEnd VARCHAR(3);

SET vLineEnd = CHR(13) || CHR(10);

SET vQuery = '';


DECLARE cTypes CURSOR FOR SELECT Field_Name FROM #fields WHERE UPPER(table_name) = UPPER(aTableName);

OPEN cTypes;
TRY
FETCH FIRST FROM cTypes INTO vFieldName;

 WHILE @@FETCH_STATUS = 0 DO

Set vQuery = vQuery + vFieldName || vLineEnd ;

  FETCH NEXT FROM cTypes INTO vFieldName;

END WHILE;

CLOSE cTypes;

CATCH TRUE
  CLOSE cTypes;
  SIGNAL ERROR_MESSAGE;
END;


 SELECT vQuery
 INTO #tmp
 FROM #Dummy;
END;

/* GenerateUpdateSQL */
CREATE PROCEDURE GenerateUpdateSQL
( aTableName varchar(30))
READS SQL DATA
BEGIN

// for development use only

DECLARE vQuery CLOB ;
DECLARE vFieldName VARCHAR(50);
DECLARE vLineEnd VARCHAR(3);

SET vLineEnd = chr(13) || chr(10);

SET vQuery = 'UPDATE ' || aTableName || ' SET' || vLineEnd ;


DECLARE cTypes CURSOR FOR Select Field_Name FROM #fields WHERE UPPER(table_name) = UPPER(aTableName)  AND Field_Index > 0;

OPEN cTypes;
TRY
FETCH FIRST FROM cTypes INTO vFieldName;

 WHILE @@FETCH_STATUS = 0 DO

SET vQuery = vQuery + vFieldName || ' = :' || vFieldName  || ',' || vLineEnd ;

  FETCH NEXT FROM cTypes INTO vFieldName;

END WHILE;

CLOSE cTypes;

CATCH TRUE
  CLOSE cTypes;
  SIGNAL ERROR_MESSAGE;
END;


SET vQuery = vQuery + 'WHERE .....';


SELECT vQuery
INTO #tmp
FROM #Dummy;

END;

/* InheritTags */
CREATE PROCEDURE InheritTags
(
    IN aDonorType INTEGER,
    aDonerRecords NULLSTRING,  -- One value or a comma-separated list
    aRecipientType INTEGER,
    aRecipientRecord INTEGER
)
-- READS SQL DATA -- needs either read-access
MODIFIES SQL DATA -- or write access
BEGIN
    -- Variable Declarations
    DECLARE vCode NULLSTRING(1000);
    DECLARE TTCustom INTEGER DEFAULT 0;

    -- ============================================================================
    -- SECTION 1: Apply Default Tags
    -- ============================================================================
    IF NOT aDonorType IS NULL
       AND NOT aRecipientType IS NULL
       AND NOT aRecipientRecord IS NULL THEN

        -- Insert default tags for the recipient type
        INSERT INTO SmartTags (
            Tag,
            xCurrentCategory,
            xCreatedCategory,
            TagOwnerType,
            xRef,
            SortOrder,
            xParentTag
        )
        SELECT DISTINCT
            Tag,
            xCreatedCategory,  -- Categories deliberately swapped
            xCurrentCategory,
            aRecipientType,
            aRecipientRecord,
            SortOrder,
            S.Idx
        FROM SmartTags S
        INNER JOIN SmartTagCategory C ON xCurrentCategory = C.Idx
        WHERE xCurrentCategory <> xCreatedCategory
          AND c.TagType = aRecipientType
          AND TagOwnerType = 0
          AND NOT EXISTS (
              SELECT Idx
              FROM SmartTags T
              WHERE S.Tag = T.Tag
                AND xRef = aRecipientRecord
                AND TagOwnerType = aRecipientType
          );
    END IF;

    -- ============================================================================
    -- SECTION 2: Inherit Tags from Donor(s)
    -- ============================================================================
    IF NOT aDonorType IS NULL
       AND NOT (aDonerRecords = '')
       AND NOT aRecipientType IS NULL
       AND NOT aRecipientRecord IS NULL THEN

        -- --------------------------------------------------------------------
        -- Step 1: Delete ALL relevant tags (we'll put them back next)
        -- --------------------------------------------------------------------
        DELETE FROM SmartTags
        WHERE Idx IN (
            SELECT S.Idx
            FROM SmartTags S
            INNER JOIN SmartTagCategory C ON xCurrentCategory = C.Idx
            WHERE xCurrentCategory <> xCreatedCategory
              AND c.TagType = aDonorType
              AND TagOwnerType = aRecipientType
              AND xRef = aRecipientRecord
        );

        -- --------------------------------------------------------------------
        -- Step 2: Insert inherited tags from donor(s)
        -- Note: This supports passing multiple records via CSV list
        --       (e.g., when there are two donors like venue & client on eq lists)
        -- --------------------------------------------------------------------
        INSERT INTO SmartTags (
            Tag,
            xCurrentCategory,
            xCreatedCategory,
            TagOwnerType,
            xRef,
            SortOrder,
            xParentTag
        )
        SELECT DISTINCT
            Tag,
            xCreatedCategory,  -- Categories deliberately swapped
            xCurrentCategory,
            aRecipientType,
            aRecipientRecord,
            SortOrder,
            S.Idx
        FROM SmartTags S
        INNER JOIN SmartTagCategory C ON xCurrentCategory = C.Idx
        WHERE xCurrentCategory <> xCreatedCategory
          AND c.TagType = aRecipientType
          AND TagOwnerType = aDonorType
          AND xRef IN (
              SELECT IntValues
              FROM TABLE(IntegerTableFromCSV(aDonerRecords)) AS CSV
          )
          AND NOT EXISTS (
              SELECT Idx
              FROM SmartTags T
              WHERE S.Tag = T.Tag
                AND xRef = aRecipientRecord
                AND TagOwnerType = aRecipientType
          );  -- Stop tag duplication
    END IF;
END;

/* LogUserJobs */
CREATE PROCEDURE LogUserJobs
( aUserID integer, aMyWorkID integer, aMyWork integer)
MODIFIES SQL DATA
BEGIN

  UPDATE UserJobs SET AccessDate =  current_timestamp
  WHERE xUser = aUserID AND xMyWorkID = aMyWorkID and xMyWork = aMyWork;

  IF ROWSAFFECTED = 0 THEN

    INSERT INTO UserJobs
    (xUser, xMyWorkID, xMyWork)
    VALUES
    (aUserID, aMyWorkID, aMyWork);

  END IF;
END;

/* MoveCrewActivitiesForArea */
CREATE PROCEDURE MoveCrewActivitiesForArea
( aAreaID INT,
 aDays INT, -- negative to move back, positive to move forward
 aFromDate DATE -- if passed as CAST(NULL AS Date) then all activities moved; if not null used to limit what is moving
 )
MODIFIES SQL DATA
BEGIN
  IF aDays > 0 THEN
		DECLARE aAreaIDCursor CURSOR FOR
		SELECT Idx, ActivityDate
		FROM  CrewActivities
		WHERE
		xArea = aAreaID
    AND (aFromDate IS NULL OR ActivityDate >= aFromDate)
		ORDER BY
		ActivityDate DESC; -- note this
  ELSE
		DECLARE aAreaIDCursor CURSOR FOR
		SELECT Idx, ActivityDate
		FROM  CrewActivities
		WHERE
		xArea = aAreaID
    AND (aFromDate IS NULL OR ActivityDate <= aFromDate)
		ORDER BY
		ActivityDate ASC; -- note this
  END IF;

	DECLARE vIDX INT;
	DECLARE vDate DATE;

	OPEN aAreaIDCursor;
  TRY

		FETCH FIRST FROM aAreaIDCursor INTO vIDX, vDate;

		WHILE @@FETCH_STATUS = 0 DO
		 UPDATE CrewActivities SET ActivityDate = CAST(CAST(vDate AS INT) + aDays AS DATE) WHERE Idx = vIDX ;

		 FETCH NEXT FROM aAreaIDCursor INTO vIDX, vDate;
		END WHILE;

		CLOSE aAreaIDCursor;
  CATCH TRUE
    CLOSE aAreaIDCursor;
    SIGNAL ERROR_MESSAGE;
  END;

END;

/* MoveCrewActivitiesForJob */
CREATE PROCEDURE MoveCrewActivitiesForJob
( aJobID INT,
 aDays INT,  -- negative to move back, positive to move forward
 aFromDate DATE -- if passed as CAST(NULL AS Date) then all activities moved; if not null used to limit what is moving
 )
MODIFIES SQL DATA
BEGIN

	DECLARE aAreaCursor CURSOR FOR
	SELECT Idx
	FROM  Crew_header
	WHERE
	xJob = aJobID;

	DECLARE vIDX INT;

	OPEN aAreaCursor;
  TRY

		FETCH FIRST FROM aAreaCursor INTO vIDX;

		WHILE @@FETCH_STATUS = 0 DO
          CALL MoveCrewActivitiesForArea(vIDX, aDays, aFromDate);

		 FETCH NEXT FROM aAreaCursor INTO vIDX;
		END WHILE;

		CLOSE aAreaCursor;
  CATCH TRUE
    CLOSE aAreaCursor;
    SIGNAL ERROR_MESSAGE;
  END;

END;

/* ReplaceStr */
CREATE PROCEDURE ReplaceStr
(aTableName VARCHAR(50),
 aFieldName VARCHAR(50),
 aOldStr VARCHAR(255),
 aNewStr VARCHAR(255))
 MODIFIES SQL DATA
BEGIN
DECLARE vQuery TEXT;
DECLARE vLine VARCHAR(2);

SET vLine = CHR(13) || CHR(10);

SET vQuery = 'UPDATE ' || aTableName || ' SET ' || vLine;
SET vQuery = vQuery || aFieldName || ' = SUBSTRING(' || aFieldName ||' FROM 1 FOR POSITION(''' || aOldStr || ''' IN ' || aFieldName || ')-1)'|| ' || ' || '''' || aNewStr || '''' ||'||' || vLine;
SET vQuery = vQuery || 'SUBSTRING(' || aFieldName || ' FROM (POSITION(''' || aOldStr || ''' IN ' || aFieldName || ') + ' || 'CHAR_LENGTH(' || '''' || aOldStr || '''' || ')))' || vLine;
SET vQuery = vQuery || 'WHERE POSITION(''' ||aOldStr || ''' IN ' || aFieldName || ') > 0';

--signal vQuery;
EXECUTE IMMEDIATE vQuery;

END;

/* SaveCrewShiftOrderedDetails */
CREATE PROCEDURE SaveCrewShiftOrderedDetails
(aShiftID INT,
 aPayAmount MONEY,
 aPayPDS MONEY,
 aPayTravel MONEY,
 aOvertimeTot MONEY)
MODIFIES SQL DATA
BEGIN

 SELECT A.ActivityDate, S.xActivity, S.xPosition, S.Shift1Start, S.Shift1End, S.Shift2Start, S.Shift2End
 INTO #CrewShift
 FROM CrewShifts S
 INNER JOIN CrewActivities A
 ON S.xActivity = A.idx
 WHERE
 S.IDX = aShiftID;

 DECLARE vJSON TEXT;
 SET vJSON =
 '{
  "ActivityISODate":"'+ TOSTRING((SELECT ActivityDate FROM #CrewShift)) +'",
  "ActivityID":'+ TOSTRING((SELECT xActivity FROM #CrewShift)) +',
  "PositionID":'+ TOSTRING((SELECT xPosition FROM #CrewShift)) +',
  "Amounts":
  {
    "OrderedPay":'+ TOSTRING(COALESCE(aPayAmount,0)) +',
    "OrderedPDS":'+ TOSTRING(COALESCE(aPayPDS,0)) +',
    "OrderedOvertime":'+ TOSTRING(COALESCE(aPayTravel,0)) +',
    "OrderedTravel":'+ TOSTRING(COALESCE(aOvertimeTot,0)) +'
  },
  "ShiftTimes":
  {
    "FEnd1":"'+ TOSTRING((SELECT Shift1End FROM #CrewShift)) +'",
    "FEnd2":"'+ TOSTRING((SELECT Shift2End FROM #CrewShift)) +'",
    "FStart1":"'+ TOSTRING((SELECT Shift1Start FROM #CrewShift)) +'",
    "FStart2":"'+ TOSTRING((SELECT Shift2Start FROM #CrewShift)) +'"
  },
 }';

 UPDATE CrewShifts SET OrderDetails = vJSON WHERE IDX = aShiftID;

END;

/* SET_SESSION_VARIABLE */
CREATE PROCEDURE SET_SESSION_VARIABLE(VAR_NAME VARCHAR(40),VAR_VALUE VARCHAR(40))
MODIFIES SQL DATA
BEGIN
	TRY

	UPDATE ##SESSION_VARIABLES SET
	VARIABLE_VALUE = VAR_VALUE
	WHERE
	VARIABLE_NAME = VAR_NAME;

	IF ROWSAFFECTED = 0 THEN
		INSERT INTO
    ##SESSION_VARIABLES
    VALUES
    (VAR_NAME,VAR_VALUE);
	END IF;

	CATCH POSITION('Unable to open table' IN ERROR_MESSAGE) > 0

	      CREATE TABLE ##SESSION_VARIABLES
	      (VARIABLE_NAME ShortString(40),VARIABLE_VALUE ShortString(40));

	      CREATE INDEX Index_VARNAME ON ##SESSION_VARIABLES(VARIABLE_NAME);

	      CALL SET_SESSION_VARIABLE(VAR_NAME,VAR_VALUE);

	END;
END;

/* SetCompositeValueFromComponents */
CREATE PROCEDURE SetCompositeValueFromComponents
(aCompositeMasterID INT, aFieldType TINYINT)
 MODIFIES SQL DATA -- write access
BEGIN
-- TFieldType = (ftWeight = 0, ftReplacement = 1);

IF aFieldType = 0 THEN -- update Weight

UPDATE Hetype SET
 Weight =
 (SELECT SUM(C.Quantity * H2.Weight)
 FROM composit C
 INNER JOIN hetype H2
 ON C.ComponentType = H2.type
 WHERE
 C.MasterType = aCompositeMasterID)
 WHERE
 Type = aCompositeMasterID;

ELSEIF aFieldType = 1 THEN -- update Replacement Value

UPDATE Hetype SET
 Replacement =
 (SELECT SUM(C.Quantity * H2.Replacement)
 FROM composit C
 INNER JOIN hetype H2
 ON C.ComponentType = H2.type
 WHERE
 C.MasterType = aCompositeMasterID),
 Replacement2 =
 (SELECT SUM(C.Quantity * H2.Replacement2)
 FROM composit C
 INNER JOIN hetype H2
 ON C.ComponentType = H2.type
 WHERE
 C.MasterType = aCompositeMasterID),
 Replacement3 =
 (SELECT SUM(C.Quantity * H2.Replacement3)
 FROM composit C
 INNER JOIN hetype H2
 ON C.ComponentType = H2.type
 WHERE
 C.MasterType = aCompositeMasterID),
 Replacement4 =
 (SELECT SUM(C.Quantity * H2.Replacement4)
 FROM composit C
 INNER JOIN hetype H2
 ON C.ComponentType = H2.type
 WHERE
 C.MasterType = aCompositeMasterID)

WHERE
 Type = aCompositeMasterID;

END IF;

END;

/* SetEqlistPrepStatuses */
CREATE PROCEDURE SetEqlistPrepStatuses
(aEqlistID INT)
MODIFIES SQL DATA
BEGIN

DECLARE vRestrictedPrepBayStatuses BOOLEAN;

SET vRestrictedPrepBayStatuses = (SELECT RestrictedPrepBayStatuses
                                  FROM Rules
                                  WHERE
                                  SiteID = 1);

IF NOT vRestrictedPrepBayStatuses THEN
  SELECT CASE
		WHEN SUM(S.PreppedQty) = 0
			THEN 0
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) = 0
			THEN 2
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) > 0
			THEN 1
		END AS PrepStatus,
	CASE
		WHEN SUM(S."Out") = 0
			THEN 0
		WHEN SUM(S.Quant) - SUM(S."Out") = 0
			THEN 2
		WHEN SUM(S.Quant) - SUM(S."Out") > 0
			THEN 1
		END AS DispatchStatus
INTO #tmp
FROM "sort" s
WHERE S.Eqlno = aEqlistID;

ELSE

SELECT CASE
		WHEN SUM(S.PreppedQty) = 0
			THEN 0
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) = 0
			THEN 2
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) > 0
			THEN 1
		END AS PrepStatus,
	CASE
		WHEN SUM(S."Out") = 0
			THEN 0
		WHEN SUM(S.PreppedQty) - SUM(S."Out") = 0
			THEN 2
		WHEN SUM(S.PreppedQty) - SUM(S."Out") > 0
			THEN 1
		END AS DispatchStatus
INTO #tmp
FROM "sort" s
WHERE S.Eqlno = aEqlistID;

END IF;


UPDATE Eqlists SET
PrepStatus = COALESCE((SELECT T.PrepStatus
             FROM #tmp T),0),
DelStatus = COALESCE((SELECT T.DispatchStatus
            FROM #tmp T),0)
WHERE
Eql_no = aEqlistID
AND
(PrepStatus <> COALESCE((SELECT T.PrepStatus
             FROM #tmp T),0)
OR
DelStatus <> COALESCE((SELECT T.DispatchStatus
            FROM #tmp T),0));
END;

/* SetEqlistPrepStatusesFromPrepBayID */
CREATE PROCEDURE SetEqlistPrepStatusesFromPrepBayID
(aPrepBayID INT)
MODIFIES SQL DATA
BEGIN

DECLARE vRestrictedPrepBayStatuses BOOLEAN;

SET vRestrictedPrepBayStatuses = (SELECT RestrictedPrepBayStatuses
                                  FROM Rules
                                  WHERE
                                  SiteID = 1);

IF NOT vRestrictedPrepBayStatuses THEN
  SELECT
  E.Eql_no,
  CASE
		WHEN SUM(S.PreppedQty) = 0 THEN 0
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) = 0	THEN 2
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) > 0 THEN 1
		END AS PrepStatus,
	CASE
		WHEN SUM(S."Out") = 0	THEN 0
		WHEN SUM(S.Quant) - SUM(S."Out") = 0 THEN 2
		WHEN SUM(S.Quant) - SUM(S."Out") > 0 THEN 1
		END AS DispatchStatus
    INTO #tmp
    FROM "sort" s
    INNER JOIN eqlists E
	  ON E.Eql_no = S.Eqlno
    INNER JOIN PrepBays P
	  ON P.idx = E.xPrepBay
   WHERE
   P.idx = aPrepBayID
   GROUP BY
   E.Eql_no;

ELSE

   SELECT
   E.Eql_no,
   CASE
		WHEN SUM(S.PreppedQty) = 0 THEN 0
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) = 0 THEN 2
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) > 0	THEN 1
		END AS PrepStatus,
	CASE
		WHEN SUM(S."Out") = 0 THEN 0
		WHEN SUM(S.PreppedQty) - SUM(S."Out") = 0	THEN 2
		WHEN SUM(S.PreppedQty) - SUM(S."Out") > 0 THEN 1
		END AS DispatchStatus
    INTO #tmp
    FROM "sort" s
    INNER JOIN eqlists E
	  ON E.Eql_no = S.Eqlno
    INNER JOIN PrepBays P
    ON P.idx = E.xPrepBay
    WHERE
    P.idx = aPrepBayID
    GROUP BY
    E.Eql_no;

END IF;


UPDATE Eqlists E SET
E.PrepStatus = COALESCE((SELECT T.PrepStatus FROM #tmp T WHERE T.Eql_no = E.Eql_no ),0),
E.DelStatus = COALESCE((SELECT T.DispatchStatus  FROM #tmp T WHERE T.Eql_no = E.Eql_no),0)
WHERE
E.Eql_no IN (SELECT Eql_no FROM #Tmp);

END;

/* SetEqlistWeightsAndValues */
CREATE PROCEDURE SetEqlistWeightsAndValues
(aEqlistID INT,
 aReset BOOL )
-- READS SQL DATA -- needs either read-access
 MODIFIES SQL DATA -- or write access
BEGIN
  DECLARE vCurrency TINYINT;

  SET vCurrency = (SELECT PriceMode FROM Eqlists WHERE Eql_no = aEqlistID);

	SELECT H.Weight,
		H."Type",
	       CASE
	         WHEN vCurrency = 0 THEN H.Replacement
	         WHEN vCurrency = 1 THEN H.Replacement2
	         WHEN vCurrency = 2 THEN H.Replacement3
	         WHEN vCurrency = 3 THEN H.Replacement4
	       END AS ReplacementValue
	INTO #Tmp
	FROM HeType H
	WHERE
  H."Type" IN (SELECT S."Type"
              FROM "Sort" S
			        WHERE
              S.eqlno = aEqlistID
				      AND S.Virt = FALSE
				      AND S.Rectype > 0);

	UPDATE "Sort" S SET
	S.UnitWeight = CASE WHEN S.UnitWeight = 0 OR aReset THEN (SELECT COALESCE(T.Weight,0)
				                                                   FROM #Tmp T
				                                                   WHERE
	                                                         T."Type" = S."Type" )
                 ELSE S.UnitWeight
                 END,
	S.UnitValue = CASE WHEN S.UnitValue = 0 OR aReset THEN (SELECT COALESCE(T.ReplacementValue,0)
                                                         FROM #Tmp T
                                                         WHERE
                                                         T."Type" = S."Type" )
                 ELSE S.UnitValue
                 END
	WHERE
	S.eqlno = aEqlistID
  AND S.RecType > 0
  AND S.Virt = FALSE;

END;

/* SetPrepBayStatuses */
CREATE PROCEDURE SetPrepBayStatuses
(aPrepBay INT)
MODIFIES SQL DATA
BEGIN

DECLARE vRestrictedPrepBayStatuses BOOLEAN;

SET vRestrictedPrepBayStatuses = (SELECT RestrictedPrepBayStatuses
                                  FROM Rules
                                  WHERE
                                  SiteID = 1);

IF NOT vRestrictedPrepBayStatuses THEN
  SELECT CASE
		WHEN SUM(S.PreppedQty) = 0
			THEN 0
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) = 0
			THEN 2
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) > 0
			THEN 1
		END AS PrepStatus,
	CASE
		WHEN SUM(S."Out") = 0
			THEN 0
		WHEN SUM(S.Quant) - SUM(S."Out") = 0
			THEN 2
		WHEN SUM(S.Quant) - SUM(S."Out") > 0
			THEN 1
		END AS DispatchStatus
INTO #tmp
FROM "sort" s
INNER JOIN eqlists E
	ON E.Eql_no = S.Eqlno
INNER JOIN PrepBays P
	ON P.idx = E.xPrepBay
WHERE P.idx = aPrepBay;

ELSE

SELECT CASE
		WHEN SUM(S.PreppedQty) = 0
			THEN 0
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) = 0
			THEN 2
		WHEN SUM(S.Quant) - SUM(S.PreppedQty) > 0
			THEN 1
		END AS PrepStatus,
	CASE
		WHEN SUM(S."Out") = 0
			THEN 0
		WHEN SUM(S.PreppedQty) - SUM(S."Out") = 0
			THEN 2
		WHEN SUM(S.PreppedQty) - SUM(S."Out") > 0
			THEN 1
		END AS DispatchStatus
INTO #tmp
FROM "sort" s
INNER JOIN eqlists E
	ON E.Eql_no = S.Eqlno
INNER JOIN PrepBays P
	ON P.idx = E.xPrepBay
WHERE P.idx = aPrepBay;

END IF;


UPDATE PrepBays
SET PrepStatus =COALESCE((
                SELECT T.PrepStatus
		FROM #tmp T
		),0),
	DelStatus = COALESCE((
		SELECT T.DispatchStatus
		FROM #tmp T
		),0)
WHERE idx = aPrepBay;


END;

/* SetRepairActive */
CREATE PROCEDURE SetRepairActive
(aRepairLineRef INT, aItemID INT )
-- READS SQL DATA -- needs either read-access
 MODIFIES SQL DATA -- or write access
BEGIN


   IF aItemID IS NOT NULL THEN --   TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bscDisposed, bscLoggedForRepair);
      UPDATE "Item" SET CommissionStatus = 2 WHERE ItemRef = aItemID;
   END IF;

   UPDATE ServData SET Notes = (SELECT S.Notes from Sort S WHERE LineRef = aRepairLineRef) WHERE xRepairLineRef = aRepairLineRef;

   UPDATE "SORT" SET Defcon = 4, PreppedQty = 1, "Out" = 1 , Notes = '' WHERE LineRef = aRepairLineRef;

END;

/* SetReturnsBayStatuses */
CREATE PROCEDURE SetReturnsBayStatuses
(aEqlistID INT)
MODIFIES SQL DATA
BEGIN

DECLARE vEqlistClass TINYINT;
SET vEqlistClass = (SELECT EqlistClass FROM Eqlists WHERE Eql_no = aEqlistID);
-- no for Sales/Sales Order lists the default for null sum values is still NULL, but 2 (completed) for Rental lists that have consumables only.

  SELECT
    COALESCE(CASE
	  	         WHEN SUM(S.Back) = 0 THEN 0
	             WHEN (SUM(S."Out") > 0) AND (SUM(S."Out") - SUM(S.Back)) = 0 THEN 2
		           WHEN SUM(S."Out") - SUM(S.Back) > 0 THEN 1
	             END,CASE WHEN vEqlistClass = 0 THEN 2 ELSE NULL END) AS ReturnedStatus,
  	COALESCE(CASE
	           	 WHEN SUM(S.CheckedInQty) = 0 THEN 0
	  	         WHEN (SUM(S.Back) > 0) AND (SUM(S.Back) - SUM(S.CheckedInQty) = 0) THEN 2
	  	         WHEN SUM(S.Back) - SUM(S.CheckedInQty) > 0	THEN 1
	           END,CASE WHEN vEqlistClass = 0 THEN 2 ELSE NULL END) AS CheckedInStatus
  INTO #Results
  FROM "Sort" s
  WHERE
  S.Eqlno = aEqlistID
  AND S.xCat > 0;

  UPDATE Eqlists SET
  ReturnedStatus = (SELECT T.ReturnedStatus FROM #Results T),
  CheckedInStatus = (SELECT T.CheckedInStatus FROM #Results T)
  WHERE
  Eql_no = aEqlistID;

END;

/* SyncCompositeDefinition */
CREATE PROCEDURE SyncCompositeDefinition
(aTypeID INT )
MODIFIES SQL DATA
BEGIN

DECLARE vLineRef INT;

DROP TABLE IF EXISTS #SortComposites;
DROP TABLE IF EXISTS #RealComposites;
DROP TABLE IF EXISTS #LineCodes;
DROP TABLE IF EXISTS #PreppedCheck;

CREATE TABLE #SortComposites(
  MasterType INT,
  ComponentType INT,
  Qty INT,
  CONSTRAINT pk_test PRIMARY KEY (MasterType,ComponentType));

CREATE TABLE #RealComposites(
  MasterType INT,
  ComponentType INT,
  Qty INT,
  CONSTRAINT pk_test PRIMARY KEY (MasterType,ComponentType));

CREATE TABLE #LineCodes(
 LineCode INT,
 CONSTRAINT pk_LineCode PRIMARY KEY (LineCode));

CREATE TABLE #PreppedCheck(
 LineCode INT,
 TotalPrepped INT,
 TotalCheckedIn INT,
 CONSTRAINT pk_LineCode PRIMARY KEY (LineCode));

DECLARE aSortCursor CURSOR FOR
SELECT S.LineRef
FROM "Sort" S
WHERE
S."Type" = aTypeID
AND PreppedQty = 0 AND CarnetQty = 0
AND D2 > CURRENT_TIMESTAMP
AND RecType <> 17; --etCompositePrepModified

OPEN aSortCursor;
TRY
FETCH FIRST FROM aSortCursor
INTO vLineRef;

WHILE @@FETCH_STATUS = 0 DO

  DELETE FROM #SortComposites;
  DELETE FROM #RealComposites;

  INSERT INTO #SortComposites
  SELECT aTypeID,  S1."Type", S1.Quant
  FROM "Sort" S1
  WHERE
  S1.LineCode = vLineRef
  AND S1.LineRef <> vLineRef
  ORDER BY S1."Type";


  INSERT INTO #RealComposites
  SELECT aTypeID, ComponentType, Quantity
  FROM Composit
  WHERE
  Mastertype = aTypeID
  ORDER BY ComponentType;

  TRY
  ASSERT TABLE #SortComposites = TABLE #RealComposites;

  CATCH TRUE

  INSERT INTO #LineCodes
  (LineCode)
  VALUES
  (vLineRef);

  END;

FETCH NEXT FROM aSortCursor
INTO vLineRef;

END WHILE;

CLOSE aSortCursor;

CATCH TRUE
  CLOSE aSortCursor;
  SIGNAL ERROR_MESSAGE;
END;


INSERT INTO #PreppedCheck
SELECT LineCode, SUM(PreppedQty), SUM(CarnetQty)
FROM "Sort"
WHERE
Linecode IN (SELECT Linecode FROM #LineCodes)
GROUP BY
LineCode
HAVING
SUM(PreppedQty) = 0 AND SUM(CarnetQty) = 0;


SELECT *
INTO #Sort
FROM Sort S
INNER JOIN #PreppedCheck P
ON S.LineRef = P.LineCode
WHERE
S.LineRef IN (SELECT Linecode FROM #LineCodes)
AND Invoiced = False;


DELETE FROM "sort"
WHERE
LineCode IN (SELECT LineRef FROM #Sort)
AND Virt = TRUE;

/*
  TEqlistRecordType = (
    etFreeText = 0,
    etNormal = 1,
    etNormalReminder = 2, etNormalReminderNoCharge = 3, etCompositeReminder = 4, etCompositeReminderNoCharge = 5,
    etNormalAliasPart = 6, etNormalPricedAliasPart = 7, etCompositeAliasPart = 8, etCompositPricedAliasPart = 9,
    etComposite = 10, etCompositeComponent = 11,
    etAlias = 12, etPricedAlias = 13, etNormalAliasPartNoCharge = 14, etCompositeAliasPartNoCharge = 15, etCompositePrepSplit = 16, etCompositePrepModified = 17);
 */

INSERT INTO "sort"
  (Linecode,Quant,"Type", XCat, virt, eqlno, D1, D2, Defcon, LoansInQty, sectionID, rectype, subhire, xGUID, slink1,  xTransferInWarehouse, listType)
  SELECT
    s.LineRef,
    s.Quant * C.Quantity,
    C.ComponentType,
    s.XCat,
    True,
    s.eqlno,
    s.D1,
    s.D2,
    s.defcon,
    s.LoansInQty * C.Quantity,
    s.sectionID,
    11,
    s.subhire,
    s.XGUID,
    s.slink1,
    s.xTransferInWarehouse,
    s.ListType
  FROM #Sort S
  INNER JOIN Composit C
  ON C.MasterType = S."type"
  ORDER BY C.SortID;

  -- fix up the xTransferToLine values for loaned composite components
  SELECT  LineCode
  INTO #ProblemLoanedCompositeLinecodes
  FROM #Sort;

  SELECT S.xTransferToLine AS DonorLineRef, P.Linecode AS LoanLineCode
  INTO #MasterBorrowingLineRef
  FROM #ProblemLoanedCompositeLinecodes P
  INNER JOIN Sort S
  ON P.LineCode = S.LineRef;

  SELECT S.LineRef AS DonorLineRef , S.LineCode AS DonorLineCode, S.Type AS DonorType, S.Eqlno AS DonorListID, M.LoanLineCode
  INTO #DonorRecords
  FROM #MasterBorrowingLineRef M
  INNER JOIN Sort S
  ON M.DonorLineRef = S.Linecode
  ORDER BY
  S.LineRef;

  SELECT D.*, S.Lineref AS LoanLineRef, S.LineCode as LoanLineCode, S.Type AS LoanType, S.Eqlno AS LoanListID, S.xTransferToLine
  INTO #JoinedUpData
  FROM  #DonorRecords D
  INNER JOIN Sort S
  ON D.LoanLineCode = S.LineCode AND D.DonorType = S.Type
  ORDER By
  S.LineCode, S.LineRef;

  UPDATE Sort S SET
  S.xTransferToLine = (SELECT J.DonorLineRef FROM #JoinedUpData J WHERE J.LoanLineRef = S.LineRef)
  WHERE
  S.LineRef IN (SELECT LoanLineRef FROM #JoinedUpData);

  -- fix up legacy misalignments of Rectypes
  UPDATE "Sort" SET
  RecType = CASE
            WHEN RecType = 1 THEN 10
            WHEN RecType = 2 THEN 4
            WHEN RecType = 3 THEN 5
            WHEN RecType = 6 THEN 8
            WHEN RecType = 7 THEN 9
            WHEN RecType = 14 THEN 15
            END
  WHERE
  LineRef IN (SELECT Linecode FROM #LineCodes)
  AND
  RecType IN (1,2,3,6,7,14);


END;

/* SyncCrewPositionOffers */
CREATE PROCEDURE SyncCrewPositionOffers
(aSourcePosition INT, aDestPosition INT)
 MODIFIES SQL DATA -- or write access
BEGIN

     DELETE FROM CrewPositionOffers
     WHERE
     xPosition = aDestPosition
     AND xPerson IN (SELECT xPerson FROM CrewPositionOffers WHERE xPosition = aSourcePosition);

     INSERT INTO CrewPositionOffers
     (xPosition, xPerson, CorrespondenceType, CorrespondenceDate, OfferStatusDate, OfferStatus)
     SELECT aDestPosition, xPerson, CorrespondenceType, CorrespondenceDate, OfferStatusDate, OfferStatus
     FROM CrewPositionOffers
     WHERE
     xPosition = aSourcePosition;

     DECLARE vSourceStatus TINYINT;
     SET vSourceStatus = (SELECT Status FROM CrewPositions WHERE IDX = aSourcePosition);

     UPDATE CrewPositions SET
     xPerson = (SELECT xPerson FROM CrewPositions WHERE IDX = aSourcePosition),
     Status  = CASE WHEN Status < vSourceStatus THEN vSourceStatus ELSE Status END
     WHERE
     Idx = aDestPosition;

END;

/* SyncCrewPositionOrderStatus */
CREATE PROCEDURE SyncCrewPositionOrderStatus
( aPositionID INT )
 MODIFIES SQL DATA -- or write access
BEGIN
   -- TShiftOrderStatus = (sosNone, sosPartial, sosFullfilled, sosOver, sosMisaligned);
   -- TShiftStatus = (ssUnprocessed, ssInProgress, ssPencilled, ssBooked);
   -- TPositionOrderStatus = (posNotRequired, posOutstandingNone, posOutstandingSome, posFullfilled);
   -- TShiftBookingState = (sbsIncQuote, sbsExcQuote, sbsCancelled, sbsBlackout);
   SELECT
   COALESCE(SUM(CASE WHEN S.Status < 3 /*AND S.OrderStatus  = 0}*/ THEN 1 ELSE 0 END),0) AS ShiftsNotBookedCount,
   COALESCE(SUM(CASE WHEN S.Status = 3 AND S.OrderStatus  = 0 THEN 1 ELSE 0 END),0) AS ShiftsNotOrderedCount,
   COALESCE(SUM(CASE WHEN S.Status = 3 AND S.OrderStatus  IN (1,3,4) THEN 1 ELSE 0 END),0) AS ShiftsPartiallyOrderedCount,
   COALESCE(SUM(CASE WHEN S.Status = 3 AND S.OrderStatus  = 2 THEN 1 ELSE 0 END),0) AS ShiftsCompletelyOrderedCount,
   COUNT(*) AS TotalShiftCount
   INTO #ShiftsSummary
   FROM CrewShifts S
   WHERE
   S.xPosition = aPositionID
   AND S.ShiftType = 1;

   UPDATE CrewPositions P SET
   OrderStatus = CASE WHEN P.xPerson IS NULL THEN 0 ELSE
                           (SELECT CASE
                           WHEN( S.ShiftsNotBookedCount  = S.TotalShiftCount) THEN 0 -- nothing needs ordered yet
                           WHEN S.ShiftsNotOrderedCount = S.TotalShiftCount - S.ShiftsNotBookedCount  THEN 1 -- nothing ordered yet but should be
                           WHEN S.ShiftsPartiallyOrderedCount > 0 THEN 2 -- either not enough ordering, too much ordering or misaligned ordering
                           ELSE
                           3 -- every ordered correctly
                           END
                           FROM #ShiftsSummary S)
                  END
   WHERE
   IDX = aPositionID;
END;

/* SyncCrewShiftOrderStatus */
CREATE PROCEDURE SyncCrewShiftOrderStatus
(aShiftID INT,
 aSyncAfterOrdering BOOL)
MODIFIES SQL DATA -- or write access
BEGIN

-- TShiftOrderStatus = (sosNone, sosPartial, sosFullfilled, sosOver, sosMisaligned)
DECLARE vUpdateShiftOrderStatus BOOL;
SET vUpdateShiftOrderStatus = aSyncAfterOrdering OR (SELECT OrderStatus <> 4 FROM CrewShifts WHERE IDX = aShiftID);

IF vUpdateShiftOrderStatus THEN

   SELECT
   SUM(CASE WHEN SubCostCentre = 1 THEN LineTotal ELSE 0 END) AS LabourTot,
   SUM(CASE WHEN SubCostCentre = 2 THEN LineTotal ELSE 0 END) AS PDsTot,
   SUM(CASE WHEN SubCostCentre = 3 THEN LineTotal ELSE 0 END) AS TravelTot,
   SUM(CASE WHEN SubCostCentre = 4 THEN LineTotal ELSE 0 END) AS OvertimeTot,
   COUNT(*) AS TotalOrderRecords,
   SUM(ABS(LineTotal)) AS AbsTotal,
   SUM(LineTotal) AS NetTotal,
   SortLink AS MasterRecord
   INTO #OrderTotals
   FROM POData
   WHERE
   SortLink = aShiftID
   AND xGeneralCostCentre = 1
   AND SubCostCentre IN (1,2,3,4)
   GROUP BY
   SortLink;

   SELECT
   O.MasterRecord, O.TotalOrderRecords, O.AbsTotal, O.NetTotal, S.xPosition,
   (S.PayAmount) + (S.PayPDsAmount) + (S.PayTravelAmount) + (S.PayOvertimeAmount)  AS TotalCost,
   (o.LabourTot) + (o.PDsTot) + (o.TravelTot) + (o.OvertimeTot)  AS TotalOrdered
   INTO #SummaryData
   FROM
   #OrderTotals O
   INNER JOIN CrewShifts S
   ON O.MasterRecord = S.Idx;

   -- Sync CrewShift.OrderStatus
   UPDATE CrewShifts S SET
   OrderStatus = COALESCE((SELECT CASE
                         WHEN (D.TotalOrderRecords = 0) OR (D.AbsTotal > 0 AND D.TotalOrdered = 0) THEN 0 -- no orders yet
                         WHEN (D.TotalCost > 0) AND (D.TotalCost - D.TotalOrdered > 0)   THEN 1 -- partially ordered
                         WHEN ((D.TotalCost > 0) AND (D.TotalCost - D.TotalOrdered = 0))OR
                              ((D.AbsTotal = 0) AND  (D.TotalOrderRecords > 0) ) THEN 2 -- fully ordered
                         WHEN (D.TotalOrdered > 0) AND (D.TotalCost - D.TotalOrdered < 0) THEN 3 -- over ordered
                         END
                  FROM #SummaryData D
                  WHERE
                  D.MasterRecord = S.Idx),0)
   WHERE
   IDX = aShiftID;

   -- if we are call this SP from trPODataAFTER then we need to update the JSON data in CrewShifts
   IF aSyncAfterOrdering THEN
      CALL SaveCrewShiftOrderedDetails(aShiftID,
                                       (SELECT LabourTot FROM #OrderTotals WHERE MasterRecord = aShiftID),
                                       (SELECT PDsTot FROM #OrderTotals WHERE MasterRecord = aShiftID),
                                       (SELECT TravelTot FROM #OrderTotals WHERE MasterRecord = aShiftID),
                                       (SELECT OvertimeTot FROM #OrderTotals WHERE MasterRecord = aShiftID));

   END IF;
END IF;

   -- Sync CrewPositions.OrderStatus

   -- TPositionOrderStatus = (posNotRequired, posOutstandingNone, posOutstandingSome, posFullfilled);
   -- TShiftStatus = (ssUnprocessed, ssInProgress, ssPencilled, ssBooked);
   DECLARE vCrewPositionID INT;

   SET vCrewPositionID = (SELECT xPosition FROM CrewShifts WHERE IDX = aShiftID);

   CALL SyncCrewPositionOrderStatus(vCrewPositionID);
END;

/* SyncGlobalDispatchCompletedDate */
CREATE PROCEDURE SyncGlobalDispatchCompletedDate
( aJobID INT)
MODIFIES SQL DATA -- or write access
BEGIN

DECLARE vCompletedDelStatus TINYINT;
SET vCompletedDelStatus = 2;

SELECT xGlobalDispatch, xJob
INTO #GlobalDispatches
FROM GlobalDispatchJobs
WHERE
xJob = aJobID;


SELECT  G.xGlobalDispatch
INTO #Completed
FROM PrepBays P
INNER JOIN
#GlobalDispatches G
ON G.xJob = P.xJob
WHERE
P.xJob = aJobID
GROUP BY
G.xGlobalDispatch
HAVING
SUM(P.DelStatus)/ vCompletedDelStatus = COUNT(*);

UPDATE GlobalDispatch G SET
G.CompletedDate = CASE
                    WHEN EXISTS (SELECT *
                                 FROM #Completed
                                 WHERE
                                 xGlobalDispatch = G.IDX) THEN
                                 CASE
                                   WHEN G.CompletedDate IS NULL THEN CURRENT_TIMESTAMP
                                 ELSE  G.CompletedDate
                                 END
                    ELSE NULL
                    END
WHERE
G.IDX IN (SELECT xGlobalDispatch
          FROM #GlobalDispatches) ;

END;

/* SyncPat_Item */
CREATE PROCEDURE SyncPat_Item (aBarcodeID INT)
MODIFIES SQL DATA
BEGIN

    IF aBarcodeID IS NOT NULL  THEN
        INSERT INTO Pat_Item
        (Itemref,	ENextDate,	RNextDate)
        VALUES
        (aBarcodeID,	TIMESTAMP '1980-01-01 00:00:00',	TIMESTAMP '1980-01-01 00:00:00');
    ELSE
        SELECT I.ItemRef
        INTO #tmp
        FROM Item I
        LEFT JOIN Pat_Item P
        	ON I.ItemRef = P.ItemRef
        WHERE
        I.BarcodeType <> 1
        AND P.ItemRef IS NULL;

        INSERT INTO Pat_Item
        (Itemref,	ENextDate,	RNextDate)
        SELECT
        ItemRef,	TIMESTAMP '1980-01-01 00:00:00',	TIMESTAMP '1980-01-01 00:00:00'
        FROM #tmp;

    END IF;

END;

/* SyncPat_Type */
CREATE PROCEDURE SyncPat_Type (aTypeID INT)
MODIFIES SQL DATA
BEGIN

    IF aTypeID IS NOT NULL  THEN
        INSERT INTO Pat_Type
        (Typeref)
        VALUES
        (aTypeID);
    ELSE
        SELECT H.Type
        INTO #tmp
        FROM Hetype H
        LEFT JOIN Pat_Type P
        	ON H.Type = P.Typeref
        WHERE
        H.EquipmentType = 1
        AND P.Typeref IS NULL;

        INSERT INTO Pat_Type
        (Typeref)
        SELECT
        Type
        FROM #tmp;

    END IF;

END;

/* SyncRBDictionay */
CREATE PROCEDURE SyncRBDictionay
( aTableName VARCHAR(50))
 MODIFIES SQL DATA -- or write access
BEGIN

 DELETE FROM rbTable
 WHERE
 UPPER(TableName) = UPPER(aTableName);

 INSERT INTO rbTable
 (TableName, TableAlias)
 VALUES
 (aTableName, aTableName);

 DELETE FROM rbField
 WHERE
 UPPER(TableName) = UPPER(aTableName);

 INSERT INTO rbField
 (TableName,
 FieldName,
 FieldAlias,
 DataType,
 Selectable,
 Searchable,
 Sortable,
 AutoSearch,
 Mandatory)
 SELECT
  aTableName,
  Field_Name,
  aTableName ||'.'||Field_Name,
  CASE
   WHEN Field_Type_SQL IN ('AUTOINC','BYTE','DWORD','INTEGER','SHORTINT','SMALLINT','WORD') THEN 'dtInteger'
   WHEN Field_Type_SQL IN ('BIGINT') THEN 'dtLargeInt'
   WHEN Field_Type_SQL IN ('BOOLEAN') THEN 'dtBoolean'
   WHEN Field_Type_SQL IN ('DATE') THEN 'dtDate'
   WHEN Field_Type_SQL IN ('TIME') THEN 'dtTime'
   WHEN Field_Type_SQL IN ('TIMESTAMP') THEN 'dtDateTime'
   WHEN Field_Type_SQL IN ('MONEY') THEN 'dtCurrency'
   WHEN Field_Type_SQL IN ('IMAGE') THEN 'dtGraphic'
   WHEN Field_Type_SQL IN ('GUID') THEN 'dtGUID'
   WHEN Field_Type_SQL IN ('SHORTSTRING','CHARACTER VARYING') THEN 'dtString'
   WHEN Field_Type_SQL IN ('CHARACTER LARGE OBJECT') THEN 'dtMemo'
   WHEN Field_Type_SQL IN ('BINARY LARGE OBJECT') THEN 'dtBLOB'
   WHEN Field_Type_SQL IN ('FLOAT') THEN 'dtSingle'
   WHEN Field_Type_SQL IN ('DOUBLE PRECISION','DECIMAL') THEN 'dtDouble'
   WHEN Field_Type_SQL IN ('EXTENDED') THEN 'dtExtended'
  END,
  'T',
  'T',
  'T',
  'F',
  'F'
  FROM
  #Fields
  WHERE
  UPPER(Table_Name) = UPPER(aTableName);

END ;

/* SyncRules */
CREATE PROCEDURE SyncRules
( aInserting  BOOL,
  aSite  INT )
 MODIFIES SQL DATA -- or write access
BEGIN
IF (aSite = 1 AND NOT aInserting) or (aSite > 1 AND aInserting) THEN

DECLARE vQuery TEXT;
DECLARE vFieldName VARCHAR(50);
DECLARE vLineEnd VARCHAR(3);

-- vQuery MUST be initialized
SET vQuery = '';

SET vLineEnd = ';' || CHR(13) || CHR(10);

DECLARE cRules CURSOR FOR
  SELECT Field_Name
  FROM #fields
  WHERE
  UPPER(table_name) = 'RULES'
  AND Field_Index > 0
  AND Field_Name NOT LIKE '%TAX%' IGNORE CASE ;

OPEN cRules;

TRY
FETCH FIRST FROM cRules INTO vFieldName;

 WHILE @@FETCH_STATUS = 0 DO

   IF UPDATING THEN
    SET vQuery = vQuery + 'UPDATE Rules T Set T.' || vFieldName || ' = (SELECT ' || vFieldName ||
    ' FROM Rules WHERE SiteID = 1) WHERE T.SiteID > 1 AND (T.' || vFieldName || ' IS NULL OR T.' || vFieldName ||
    ' = (SELECT ' || vFieldName || ' FROM Rules WHERE SiteID = 1)' ')' || vLineEnd ;
   ELSE
    SET vQuery = vQuery + 'UPDATE Rules T Set T.' || vFieldName || ' = (SELECT ' || vFieldName ||
    ' FROM Rules WHERE SiteID = 1) WHERE T.SiteID > 1 ' || vLineEnd ;
   END IF;

  FETCH NEXT FROM cRules INTO vFieldName;

  END WHILE;

CLOSE cRules;
CATCH TRUE
CLOSE cRules;
SIGNAL ERROR_MESSAGE;
END;

EXECUTE IMMEDIATE vQuery;

END IF;
END;

/* SyncStockLevelForType */
CREATE PROCEDURE SyncStockLevelForType
(aTypeID INT,
 aWarehouseID INT)
MODIFIES SQL DATA -- or write access
BEGIN

DECLARE vWarehouseID INT;
DECLARE vQuery TEXT;
DECLARE vWarehouseColumn VARCHAR(20);
DECLARE vWarehouseQty  INT;
DECLARE vSite INT;

IF aWarehouseID IS NULL THEN

 DECLARE crWarehouse CURSOR FOR
 SELECT IDX, xSite
 FROM Warehouses
 WHERE
 Virtual IS FALSE ;

ELSE

 DECLARE crWarehouse CURSOR FOR
 SELECT IDX, xSite
 FROM Warehouses
 WHERE
 IDX = aWarehouseID  ;

END IF;

OPEN crWarehouse;
TRY

	FETCH FIRST FROM crWarehouse INTO vWarehouseID,vSite;

	WHILE @@FETCH_STATUS = 0 DO

	  SET vWarehouseColumn = 'Loc' + Cast(GetWarehouseColumnFromWarehouseID(vWarehouseID) AS VARCHAR(10));

	  SET vWarehouseQty = (SELECT COALESCE(SUM(Quantity),0)
	                       FROM WhAudit
	                       WHERE
	                       xType = aTypeID
	                       AND xWarehouse = vWarehouseID) ;

	  SET vQuery = 'UPDATE Whlevel set ' + vWarehouseColumn + ' = ' + cast(vWarehouseQty as varchar(10))
	            +  ' WHERE xSite = ' + cast(vSite as varchar(10)) + ' and TypeIDX = ' + cast(aTypeID as varchar(10));

	  EXECUTE IMMEDIATE vQuery;

	  FETCH NEXT FROM crWarehouse INTO vWarehouseID,vSite;
	END WHILE;

	CLOSE crWarehouse;

CATCH TRUE
CLOSE crWarehouse;
SIGNAL ERROR_MESSAGE;
END;

END;

/* TotalizeCrewAccommodationPay */
CREATE PROCEDURE TotalizeCrewAccommodationPay
( aJobID INT )
-- READS SQL DATA -- needs either read-access
 MODIFIES SQL DATA -- or write access
BEGIN
     SELECT COUNT(*) AS RequestCount, A.Idx
     INTO #ShiftsSummary
     FROM CrewAccommodation A
     INNER JOIN CrewAccommodationLkp L
     ON A.Idx = l.xCrewAccommodation
     WHERE
     A.xJob = aJobID
     GROUP BY
     A.Idx;

     SELECT A.idx , P.xCrewRequest, A.Charge / R.RequestCount AS Charge, A.Charge AS RawCharge , R.RequestCount
     INTO #Summary
     FROM CrewAccommodation A
     INNER JOIN #ShiftsSummary R
     ON A.Idx = R.Idx
     INNER JOIN CrewAccommodationLkp L
     ON A.Idx = l.xCrewAccommodation
     INNER JOIN CrewShifts S
     ON L.xCrewShift = S.IDX
     INNER JOIN CrewPositions P
     ON S.xPosition = P.IDX;


     SELECT xCrewRequest, SUM(Charge) AS Charge
     INTO #ChargeSummary
     FROM #Summary
     GROUP BY
     xCrewRequest;

     UPDATE Crew C SET
     C.AccommodationPay = COALESCE((SELECT S.Charge  FROM  #ChargeSummary S WHERE S.xCrewRequest = C.Idx),0)
     WHERE
     C.Job_no = aJobID;

END;

/* TotalizeShiftsForRolesOnJob */
CREATE PROCEDURE TotalizeShiftsForRolesOnJob
( aJobID INT,
  aRoleIDs TEXT )
MODIFIES SQL DATA -- or write access
BEGIN
 DECLARE vDynamicSQL TEXT;

 IF COALESCE(aRoleIDs, '') = '' THEN
    SET vDynamicSQL = 'SELECT * INTO #Crew FROM Crew WHERE Job_No = ' || ToString(aJobID);
 ELSE
    SET vDynamicSQL = 'SELECT * INTO #Crew FROM Crew WHERE Idx IN (' || aRoleIDs || ')';
 END IF;

 EXECUTE IMMEDIATE  vDynamicSQL;

 SELECT
 P.xCrewRequest,
 --TAccommodationStatus = (asNotRequired, asClientProvides, asWeProvide);
 SUM(CASE WHEN S.BookingState = 0 THEN CASE WHEN S.AccommodationStatus = 2 THEN S.AccommodationCharge ELSE 0 END ELSE 0 END) AS AccommodationChargeQuote,
 SUM(CASE WHEN S.AccommodationStatus = 2 THEN S.AccommodationCharge ELSE 0 END) AS AccommodationChargeALL,
 SUM(CASE WHEN S.BookingState = 0 THEN S.ChargeAmount ELSE 0 END) AS ChargeAmountQuote, SUM(S.ChargeAmount) AS ChargeAmountAll,
 SUM(CASE WHEN S.BookingState = 0 THEN S.ChargePDsAmount ELSE 0 END) AS ChargePDsAmountQuote, SUM(S.ChargePDsAmount) AS ChargePDsAmountALL,
 SUM(CASE WHEN S.BookingState = 0 THEN S.ChargeTravelAmount ELSE 0 END) AS ChargeTravelAmountQuote, SUM(S.ChargeTravelAmount) AS ChargeTravelAmountAll,
 SUM(CASE WHEN S.BookingState = 0 THEN S.ChargeOvertimeAmount ELSE 0 END) AS ChargeOvertimeAmountQuote, SUM(S.ChargeOvertimeAmount) AS ChargeOvertimeAmountAll,
 SUM(S.PayAmount) AS LabourPay, SUM(S.PayPDsAmount) AS PayPDsAmount, SUM(S.PayTravelAmount) AS PayTravelAmount, SUM(S.PayOvertimeAmount) AS PayOvertimeAmount,
 COUNT(DISTINCT P.xPerson) AS Allocated,
 COUNT(CASE WHEN S.BookingState = 0 THEN 1 ELSE NULL END) AS QuotedOnly
 INTO #Summary
 FROM #Crew C
 INNER JOIN CrewPositions P
 ON P.xCrewRequest = C.Idx
 INNER JOIN CrewShifts S
 ON P.Idx = S.xPosition
 WHERE
 S.BookingState <2 -- TShiftBookingState = (sbsIncQuote, sbsExcQuote, sbsCancelled, sbsBlackout);
 AND P.Cancelled = FALSE
 GROUP BY
 P.xCrewRequest;

 UPDATE CREW C SET
 -- charges
  C.LabourCharge =  COALESCE((SELECT ChargeAmountQuote FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.PDCharge =  COALESCE((SELECT ChargePDsAmountQuote FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.TravelCharge =  COALESCE((SELECT ChargeTravelAmountQuote FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.OvertimeCharge =  COALESCE((SELECT ChargeOvertimeAmountQuote FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.AccommodationCharge = COALESCE((SELECT AccommodationChargeQuote FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.LabourChargeForBilling =  COALESCE((SELECT ChargeAmountAll FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.PDChargeForBilling =  COALESCE((SELECT ChargePDsAmountAll FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.TravelChargeForBilling =  COALESCE((SELECT ChargeTravelAmountAll FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.OvertimeChargeForBilling =  COALESCE((SELECT ChargeOvertimeAmountAll FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.AccommodationChargeForBilling = COALESCE((SELECT AccommodationChargeAll FROM #Summary WHERE xCrewRequest = C.IDX),0),
 --costs
  C.LabourPay = COALESCE((SELECT LabourPay FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.PDPay =  COALESCE((SELECT PayPDsAmount FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.TravelPay =  COALESCE((SELECT PayTravelAmount FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.OvertimePay =  COALESCE((SELECT PayOvertimeAmount FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.Allocated =  COALESCE((SELECT Allocated FROM #Summary WHERE xCrewRequest = C.IDX),0),
  C.Selected = (SELECT QuotedOnly > 0 FROM #Summary WHERE xCrewRequest = C.IDX)
  WHERE
  C.Idx IN (SELECT IDX FROM #Crew);

 END;

/* UpdateCrewJobFinanceRecord */
CREATE PROCEDURE UpdateCrewJobFinanceRecord
(aCostCentreID INT,
 aIsIncome BOOL,
 aStatus INT,
 aLastQuotedDate TIMESTAMP,
 aQuotedPrice MONEY,
 aActualPrice MONEY,
 aRef VARCHAR(50),
 aTitle VARCHAR(255),
 aSubCostCentre TINYINT)
 MODIFIES SQL DATA -- or write access
BEGIN

 UPDATE JobFinances SET
 xStatus = aStatus,
 LastQuotedDate =
 CASE
     WHEN aLastQuotedDate IS NOT NULL THEN
     aLastQuotedDate
     ELSE
     LastQuotedDate
 END,
 QuotedPrice =
  CASE
      WHEN aQuotedPrice IS NULL THEN QuotedPrice ELSE aQuotedPrice END,
 ActualPrice =
  CASE
     WHEN aIsIncome THEN
     aActualPrice
     ELSE
     ActualPrice
  END,
 Reference = CASE WHEN aRef IS NULL THEN Reference ELSE aRef END,
 Title =  CASE WHEN aTitle IS NULL THEN Title ELSE aTitle END
 WHERE
 xCostCentreID = aCostCentreID
 AND IsIncome = aIsIncome
 AND xGeneralCostCentre = 1
 AND SubCostCentre = aSubCostCentre;

END;

/* WriteInternalCostsToMiscTable */
CREATE PROCEDURE WriteInternalCostsToMiscTable
( aEqlistID INT,
  aUsageCostTotal MONEY,
  aPrepCostTotal MONEY,
  aExtraCostTotal MONEY,
  aSubHireCostTotal MONEY,
  aCostOfSalesTotal MONEY )
-- READS SQL DATA -- needs either read-access
 MODIFIES SQL DATA -- or write access
BEGIN

/*
  TInternalCostCentre = (iccNone = 0, iccPayment = 1, iccEqUsage = 2, iccPrep = 3, iccTransport = 4, iccGlobalPurchaseOrderAllocation = 5, iccCustomSurchage = 6,
    iccVenueCommission = 7,
    iccEqCommisson, iccEqSubCommission, iccCrewCommisson, iccCrewSubCommission, iccTransportCommisson, iccTransportSubCommission, iccCostsCommisson, iccCostsSubCommission,
    iccCostOfSale, iccExtraRentalCosts, iccAnticipatedSubhireCosts=18);

*/
	-- get a handle on the eqlist record
	SELECT *
	INTO #Eqlists
	FROM Eqlists
	WHERE
	Eql_no = aEqlistID;

       -- Usage Costs
    IF aUsageCostTotal > 0 THEN
      IF NOT EXISTS (SELECT COUNT(*)
                     FROM Costs WHERE
                     xJob = (SELECT Job_no FROM #Eqlists)
                     AND xCostCentreID = aEqlistID
                     AND xInternalCostCentre = 2 HAVING COUNT(*) > 0) THEN

            INSERT INTO Costs
            (xJob,     xCostCentreID, xInternalCostCentre, IsIncome, xStatus, Title, xPaymentType, OurRef,     AnticipatedPrice, Selected)
             VALUES
             ((SELECT Job_no FROM #Eqlists), aEqlistID,      2 ,                  FALSE, (SELECT Defcon FROM #Eqlists), (SELECT Eql_Title  FROM #Eqlists),   4,      (SELECT Eql_Name FROM #Eqlists), aUsageCostTotal, FALSE );
      ELSE
            UPDATE Costs SET
            AnticipatedPrice = aUsageCostTotal,
            XStatus = (SELECT Defcon FROM #Eqlists)
            WHERE
            xJob = (SELECT Job_no FROM #Eqlists)
            AND xCostCentreID = aEqlistID
            AND xInternalCostCentre = 2;
      END IF;
    ELSE
        DELETE FROM Costs
        WHERE
        xJob = (SELECT Job_no FROM #Eqlists)
        AND xCostCentreID = aEqlistID
        AND xInternalCostCentre = 3;
    END IF;

     -- Prep Costs
    IF  aPrepCostTotal > 0 THEN
      IF NOT EXISTS (SELECT COUNT(*)
                     FROM Costs WHERE
                     xJob = (SELECT Job_no FROM #Eqlists)
                     AND xCostCentreID = aEqlistID
                     AND xInternalCostCentre = 3 HAVING COUNT(*) > 0) THEN
            INSERT INTO Costs
            (xJob,     xCostCentreID, xInternalCostCentre, IsIncome, xStatus, Title,  xPaymentType,OurRef, AnticipatedPrice, Selected)
             VALUES
            ((SELECT Job_no FROM #Eqlists), aEqlistID,      3,  FALSE, (SELECT Defcon FROM #Eqlists), (SELECT Eql_Title  FROM #Eqlists), 4,(SELECT Eql_Name FROM #Eqlists), aPrepCostTotal, FALSE );
      ELSE
            UPDATE Costs SET
            AnticipatedPrice = aPrepCostTotal,
            XStatus = (SELECT Defcon FROM #Eqlists)
            WHERE
            xJob = (SELECT Job_no FROM #Eqlists)
            AND xCostCentreID = aEqlistID
            AND xInternalCostCentre = 3;

      END IF;
    ELSE
        DELETE FROM Costs
        WHERE
        xJob = (SELECT Job_no FROM #Eqlists)
        AND xCostCentreID = aEqlistID
        AND xInternalCostCentre = 3;
    END IF;

     -- Extra Costs
    IF  aExtraCostTotal > 0 THEN
        IF NOT EXISTS (SELECT COUNT(*)
                     FROM Costs WHERE
                     xJob = (SELECT Job_no FROM #Eqlists)
                     AND xCostCentreID = aEqlistID
                     AND xInternalCostCentre = 17 HAVING COUNT(*) > 0) THEN
            INSERT INTO Costs
            (xJob,     xCostCentreID, xInternalCostCentre, IsIncome, xStatus, Title,  xPaymentType,OurRef, AnticipatedPrice, Selected)
             VALUES
            ((SELECT Job_no FROM #Eqlists), aEqlistID,      17,  FALSE, (SELECT Defcon FROM #Eqlists), (SELECT Eql_Title  FROM #Eqlists), 4,(SELECT Eql_Name FROM #Eqlists), aExtraCostTotal, FALSE );
        ELSE
            UPDATE Costs SET
            AnticipatedPrice = aExtraCostTotal,
            XStatus = (SELECT Defcon FROM #Eqlists)
            WHERE
            xJob = (SELECT Job_no FROM #Eqlists)
            AND xCostCentreID = aEqlistID
            AND xInternalCostCentre = 17;

        END IF;
    ELSE
        DELETE FROM Costs
        WHERE
        xJob = (SELECT Job_no FROM #Eqlists)
        AND xCostCentreID = aEqlistID
        AND xInternalCostCentre = 17;
    END IF;

     -- Subhire Costs
    IF  aSubHireCostTotal > 0 THEN
        IF NOT EXISTS (SELECT COUNT(*)
                     FROM Costs WHERE
                     xJob = (SELECT Job_no FROM #Eqlists)
                     AND xCostCentreID = aEqlistID
                     AND xInternalCostCentre = 18 HAVING COUNT(*) > 0) THEN
            INSERT INTO Costs
            (xJob,     xCostCentreID, xInternalCostCentre, IsIncome, xStatus, Title,  xPaymentType,OurRef, AnticipatedPrice, Selected)
             VALUES
            ((SELECT Job_no FROM #Eqlists), aEqlistID,      18,  FALSE, (SELECT Defcon FROM #Eqlists), (SELECT Eql_Title  FROM #Eqlists), 4,(SELECT Eql_Name FROM #Eqlists), aSubHireCostTotal, FALSE );
        ELSE
            UPDATE Costs SET
            AnticipatedPrice = aSubHireCostTotal,
            XStatus = (SELECT Defcon FROM #Eqlists)
            WHERE
            xJob = (SELECT Job_no FROM #Eqlists)
            AND xCostCentreID = aEqlistID
            AND xInternalCostCentre = 18;

        END IF;
    ELSE
        DELETE FROM Costs
        WHERE
        xJob = (SELECT Job_no FROM #Eqlists)
        AND xCostCentreID = aEqlistID
        AND xInternalCostCentre = 18;
    END IF;


    IF  aCostOfSalesTotal > 0 THEN
      IF NOT EXISTS (SELECT COUNT(*)
                     FROM Costs WHERE
                     xJob = (SELECT Job_no FROM #Eqlists)
                     AND xCostCentreID = aEqlistID
                     AND xInternalCostCentre = 16 HAVING COUNT(*) > 0) THEN
            INSERT INTO Costs
            (xJob,     xCostCentreID, xInternalCostCentre, IsIncome, xStatus, Title,  xPaymentType,OurRef, AnticipatedPrice, Selected)
             VALUES
             ((SELECT Job_no FROM #Eqlists), aEqlistID,      16,                   FALSE, (SELECT Defcon FROM #Eqlists), (SELECT Eql_Title  FROM #Eqlists),   4,     (SELECT Eql_Name FROM #Eqlists), aCostOfSalesTotal, FALSE );
      ELSE
            UPDATE Costs SET
            AnticipatedPrice = aCostOfSalesTotal,
            XStatus = (SELECT Defcon FROM #Eqlists)
            WHERE
            xJob = (SELECT Job_no FROM #Eqlists)
            AND xCostCentreID = aEqlistID
            AND xInternalCostCentre = 16;

      END IF;
    END IF;
END;

