/* trAccountsIntegrationBEFORE */
CREATE TRIGGER trAccountsIntegrationBEFORE
BEFORE UPDATE OF IntegrationCombinination ON AccountsIntegration
REFERENCING OLD AS o NEW AS n
BEGIN

 IF (SELECT COUNT(*) > 0
    FROM AccountsIntegration
    WHERE
    IDX <> n.IDX
    AND IntegrationCombinination <> 0
    AND n.IntegrationCombinination <> 0
    AND (BITOR(IntegrationCombinination, n.IntegrationCombinination) = n.IntegrationCombinination OR
        BITOR(IntegrationCombinination, n.IntegrationCombinination) = IntegrationCombinination))  THEN
        SIGNAL 'Different "integration types" cannot include the same integration actions, e.g. Sage Export Invoices and Zapier Export Invoices. Change the "integration types" for your other Accounts Package and try again.';
 END IF;

END;

