/* trAddressLog_Company */
CREATE TRIGGER trAddressLog_Company
AFTER INSERT, DELETE, UPDATE ON Company
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  DECLARE cCompanyName BOOLEAN;

  SET cCompanyName = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trAddressLog_Company' AND KEY = 'cCompanyName' AND U."USER" = 'GLOBAL'), false) FROM #dummy);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

-- TAddressLogGroup(alCompany, alPerson, alContacts....)
-- TAddressLogMeaning = (almCreated, almCompanyNameChanged...)

  SET vLogGroup = 0;

  IF INSERTING THEN

    SET vNarrative = TRIM(TOSTRINGLEN(n.CompanyName,255));

    INSERT INTO AddressLogs
    (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser,ChangeMeaning)
    VALUES
    (vNarrative ,'Company',0,n.CompanyCounter,vLogGroup,vUserID,0);

  ELSEIF UPDATING THEN

      -- CompanyName change
  IF cCompanyName THEN
    IF NOT EQUIVALENT(n.CompanyName, o.CompanyName) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.CompanyName + ': COMPANY NAME',255));

     SET vChangeInfo = 'Old Company Name = ' + o.CompanyName;
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Company Name = ' + n.CompanyName;

     INSERT INTO AddressLogs
     (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (vNarrative,'Company',1,n.CompanyCounter,vLogGroup,vUserID, vChangeInfo,1);

    END IF;
  END IF;

  ELSEIF DELETING THEN

     SET vNarrative = TRIM(TOSTRINGLEN(o.CompanyName,255));

     INSERT INTO AddressLogs
     (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (vNarrative ,'Company',2,o.CompanyCounter,vLogGroup,vUserID);

  END IF;
END;

