/* trAuditAFTER */
CREATE TRIGGER trAuditAFTER
AFTER INSERT, DELETE, UPDATE OF "Type", Quantity, Site, "Date", UnitPrice ON Audit
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vSiteOwnsQty INT;

IF INSERTING
	OR UPDATING THEN
       --UPDATE WHLevel
	SET vSiteOwnsQty = COALESCE((	SELECT sum(Quantity)
                     FROM Audit
			               WHERE
                      "type" = n."Type"
				              AND Site = n.Site),0);

  UPDATE Whlevel SET
  SiteOwns = vSiteOwnsQty ,
  LastStockManageOperation = n.StockManageOperation
  WHERE
   xSite =n.Site
   and TypeIDX = n."Type" ;

  --UPDATE DisposedQty

  IF (n.xStockIn > 0) THEN  -- its a stock out line that is either new or having its Qty a
     UPDATE Audit A SET
     A.DisposedQty = GetMinINT(A.Quantity, COALESCE((SELECT -SUM(A2.Quantity )	FROM Audit A2 WHERE A2.xStockIn = n.xStockIn),0))
	   WHERE
     A.AuditKey = n.xStockIn;
  END IF ;

  IF UPDATING THEN -- Items sync
     IF (NOT EQUIVALENT(o."Date",n."Date")) OR (NOT EQUIVALENT(o.UnitPrice,n.UnitPrice)) THEN

            UPDATE Item I SET
            I.PurchDate = n."Date",
            I.PurchPrice = n.UnitPrice
            WHERE
            I.CostCentre = n.AuditKey;

     END IF;
  END IF;

ELSEIF DELETING THEN

 --UPDATE WHLevel
	SET vSiteOwnsQty = COALESCE((	SELECT sum(Quantity)
                     FROM Audit
			               WHERE
                      "type" = o."Type"
				              AND Site = o.Site),0);

  UPDATE Whlevel SET
  SiteOwns = vSiteOwnsQty ,
  LastStockManageOperation = o.StockManageOperation
  WHERE
  xSite = o.Site
  and TypeIDX = o."Type" ;

 --UPDATE DisposedQty
 IF (o.xStockIn > 0) THEN
     UPDATE Audit A SET
     A.DisposedQty = GetMinINT(A.Quantity, COALESCE((SELECT -SUM(A2.Quantity )	FROM Audit A2 WHERE A2.xStockIn = o.xStockIn),0))
	   WHERE
     A.AuditKey = o.xStockIn;
 END IF ;

END IF ;


END;

/* trAuditBefore */
CREATE TRIGGER "trAuditBefore"
BEFORE  INSERT ON Audit
REFERENCING OLD AS o NEW AS n
BEGIN

 -- user
 DECLARE vUserID integer;

 SET vUserID = GetUserID();

 IF vUserID > -1 THEN
   SET n.xUser = vUserID;
 END IF;


 -- always make sure that Reference has something in it that can identify the transaction.
 IF COALESCE(n.Reference,'') = '' THEN
   SET n.Reference = F_FORMATDATE(n."Date") || ', Qty: ' || CAST(n.Quantity AS VARCHAR(10));
 END IF;

 -- residual value for a stock in
 IF n.StockManageOperation = 1 THEN
  SET n.ResidualValue = CASE
      WHEN n.Currency = 0 THEN (SELECT H.ResidualValueA
                                FROM Hetype H
                                WHERE
                                H."Type" = n."Type")
      WHEN n.Currency = 1 THEN (SELECT H.ResidualValueB
                                FROM Hetype H
                                WHERE
                                H."Type" = n."Type")
      WHEN n.Currency = 2 THEN (SELECT H.ResidualValueC
                                FROM Hetype H
                                WHERE
                                H."Type" = n."Type")
      WHEN n.Currency = 3 THEN (SELECT H.ResidualValueC
                                FROM Hetype H
                                WHERE
                                H."Type" = n."Type")
      END;
  END IF;

END;

