/* trCategoryBEFORE */
CREATE TRIGGER trCategoryBEFORE
BEFORE  INSERT, DELETE, UPDATE ON  Category
REFERENCING OLD AS o NEW AS n
BEGIN

IF INSERTING THEN

   IF n.Sales = TRUE THEN

      SET n.Category = (SELECT COALESCE(MIN(Category),0) -1 FROM Category);

      IF n."Description" = '' THEN
       SET n."Description" = 'NEW CONSUMABLE CATEGORY';
      END IF;

    ELSE
    SET n.Category = (SELECT COALESCE(max(Category),0) +1 FROM Category);

     IF n."Description" = '' THEN
       SET n."Description" = 'NEW CATEGORY';
     END IF;

  END IF; // if sales

  IF n.MasterCat IS NULL THEN
    SET n.MasterCat = (SELECT TOP 1 McatID  FROM MasterCat WHERE System = True);
  END IF;

  SET n.SortOrder =  (n. MasterCat * 1000) + n.Category;

  ELSEIF DELETING THEN

  IF o.N  THEN
    SIGNAL 'This is a system Category - deletion not permitted';
  END IF;

//  ELSEIF UPDATING THEN

//  IF n.SortOrder <> o.SortOrder THEN
  //SET n.SortOrder =  (n. MasterCat * 1000) + n.SortOrder;
  //END IF;

  END IF;

END;

