/* trCompanyAfter */
CREATE TRIGGER "trCompanyAfter"
AFTER INSERT, UPDATE ON "Company"
REFERENCING OLD AS o NEW AS n
BEGIN
Declare FOUND Boolean;
SET FOUND = FALSE;
IF EXISTS
(
   SELECT TOP 1 IDX FROM "EmailAddressWareHouse"
   WHERE
    XLink=N.CompanyCounter
    and  SourceTable='Company'
    and SourceField ='CompanyCounter'
)
   THEN
   SET FOUND = TRUE;
END IF;

IF NOT FOUND THEN
 IF COALESCE(n.EmailAddress,'') <> '' AND COALESCE(n.CompanyName,'') <> '' THEN
 Insert into "EmailAddressWareHouse"
 (FullName, Email, XLink, SourceTable, SourceField)
 VALUES
 (N.CompanyName, N.EmailAddress, N.CompanyCounter, 'Company', 'CompanyCounter');
 END IF;
END IF;

IF FOUND THEN

  IF COALESCE(o.EmailAddress,'') <> ''  AND N.EmailAddress = '' THEN
    DELETE FROM EmailAddressWareHouse
    WHERE
    XLink=N.CompanyCounter
    and  SourceTable='Company'
    and SourceField ='CompanyCounter';
  END IF;

Update "EmailAddressWareHouse"
  set FullName =  N.CompanyName, Email= N.EmailAddress
  where
   XLink=N.CompanyCounter
  and  SourceTable='Company'
  and SourceField ='CompanyCounter';
END IF;

END;

