/* trCompanyBEFORE */
CREATE TRIGGER "trCompanyBEFORE"
BEFORE INSERT, DELETE , UPDATE OF AccRef, CompanyName ON "Company"
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vAccDuplicateName VARCHAR(50);
DECLARE vUserID INT;

SET vUserID = GetUserID();

 IF INSERTING OR UPDATING THEN

  SET n.CompanyName = TRIM(n.CompanyName);

  IF INSERTING THEN
    SET n.xAccountStatus = (SELECT COALESCE(xDefaultAccountStatus,1)
                          FROM Rules
                          WHERE
                          SITEID = 1);
  END IF;

  IF NOT EQUIVALENT(n.AccRef,o.AccRef) THEN
   IF (NOT n.AccRef IS NULL) AND (NOT n.AccRef = '') THEN
    IF (SELECT COUNT(*) FROM Company
        WHERE
        AccRef = n.AccRef) > 0 THEN

     SET vAccDuplicateName = (SELECT TOP 1 CompanyName FROM Company
                              WHERE
                              AccRef = n.AccRef);

     SIGNAL 'Account Ref ' || n.AccRef || ' is already used for company ' || vAccDuplicateName;
    END IF;
   END IF;
  END IF;

  IF vUserID > -1 THEN
     SET n.xModifiedBy = vUserID;
  END IF;

  SET n.ModifiedDate = CURRENT_TIMESTAMP;


 ELSEIF DELETING THEN

   IF EXISTS(SELECT COUNT(*) FROM POrder
           WHERE
           Client = o.CompanyCounter
           AND Company = TRUE
           HAVING COUNT(*) > 0) THEN

   SIGNAL 'Its is not possible to delete this Address Book entry: there is other data that is linked to it.';

   END IF;

 END IF;

END;

