/* trCompositeAFTER */
CREATE TRIGGER trCompositeAFTER
AFTER  INSERT , DELETE , UPDATE  ON Composit
REFERENCING OLD AS o NEW AS n
BEGIN

 DECLARE vMasterType INT;
 DECLARE vMasterTypeIsStillComposite BOOLEAN;
 DECLARE vComponentType INT;

 IF DELETING THEN
  SET vMasterType = o.MasterType;
  SET vComponentType = o.ComponentType;

  -- clear linked component barcodes
  DELETE FROM Subcode
  WHERE
  MasterType = vMasterType
  AND
  SubType = vComponentType;

 ELSE
  SET vMasterType = n.MasterType;
  SET vComponentType = n.ComponentType;
 END IF;

 SET vMasterTypeIsStillComposite = (COALESCE((SELECT H.EquipmentType = 1
                                    FROM
                                    Hetype H
                                    WHERE
                                    H."Type" = vMasterType),FALSE));

 -- roadcase stuff
 IF vMasterTypeIsStillComposite THEN

  UPDATE Hetype H
  SET H.RoadCase = CASE
                           WHEN (EXISTS(SELECT COUNT(*)
                           FROM Hetype H2
                           WHERE
                           "Type" IN (SELECT C.ComponentType
                                      FROM
                                      Composit C
                                      WHERE
                                      C.MasterType = vMasterType)
                           AND (H2.RoadCase = TRUE OR H2.Category = 1)
                           HAVING COUNT(*) > 0))
                           THEN NULL
    ELSE
    FALSE
    END
  WHERE
   H."Type" = vMasterType;

 END IF;

-- sync eqlist lines
IF (EQUIVALENT(o.Ratio2, n.Ratio2)) THEN
 IF CompositeBookingsNeedChanging(vMasterType) THEN
   CALL SyncCompositeDefinition(vMasterType);
 END IF;
END IF;

END;

/* trCompositeBefore */
CREATE TRIGGER trCompositeBefore
BEFORE INSERT, DELETE, UPDATE OF Mastertype, Componenttype, Quantity, Ratio2 ON Composit
REFERENCING OLD AS o NEW AS n
BEGIN

 DECLARE vMasterType INT;
 DECLARE vCompositeNoChangeReason TINYINT;
 DECLARE vCompositeIssueStr VARCHAR(20);

 IF DELETING THEN
   SET vMasterType = o.MasterType;
 ELSE
   SET vMasterType = n.MasterType;
 END IF;

 IF INSERTING OR DELETING OR (UPDATING AND EQUIVALENT(n.Ratio2, o.Ratio2)) THEN

   SET vCompositeNoChangeReason = CompositeCanChange(vMasterType);
   SET vCompositeIssueStr = 'Composite Issue #' || CAST(vCompositeNoChangeReason AS VARCHAR(10));
   -- if the structure of the vCompositeIssueStr string is changed then make sure that the client code constant for it is also modified

   IF vCompositeNoChangeReason = 1 THEN
     SIGNAL vCompositeIssueStr + 'This composite is currently out on one or more jobs. It cannot be modified until every example has been Checked In.';
   ELSEIF vCompositeNoChangeReason = 2 THEN
     SIGNAL vCompositeIssueStr + 'This composite is linked to one or more future Subhires. It cannot be modified these allocations are cleared';
   ELSEIF vCompositeNoChangeReason = 3 THEN
     SIGNAL vCompositeIssueStr + 'This composite is currently out on one or more jobs and is also linked to one or more future Subhires. It cannot be modified until every example has been Checked In and all Subhire allocations are cleared.';
   END IF;
 END IF;


 IF (UPDATING AND NOT EQUIVALENT(n.Quantity, o.Quantity)) THEN
    IF n.Quantity <  COALESCE((SELECT TOP 1 COUNT(DISTINCT SubItem) / COUNT(DISTINCT MasterItem) AS SubItemsPerMasterItem
                     FROM Subcode
                     WHERE
                     MasterType = n.MasterType
                     AND SubType = n.Componenttype
                     GROUP BY
                     MasterItem
                     ORDER BY
                     SubItemsPerMasterItem DESC), 0) THEN
     SIGNAL 'Quantity for Component types cannot be less than the maximum number of component barcodes already allocated to a master composite barcode';
    END IF;
 END IF;

 IF INSERTING THEN
    SET n.SortID = n.IDX;
 END IF;

 IF INSERTING OR UPDATING THEN

    IF n.Quantity < 1 THEN
      SET n.Quanity = 1;
    END IF;

  IF n.ComponentType < 1 THEN
    SIGNAL 'You must assign a unique component type to a composit before updating.';
  END IF;

  IF n.MasterType = n.ComponentType THEN
    SIGNAL 'You cannot assign a composite to itself.';
  END IF;

 END IF;

END;

