/* trContactsAFTER */
CREATE TRIGGER "trContactsAFTER"
AFTER INSERT, DELETE, UPDATE ON "Contacts"
REFERENCING OLD AS o NEW AS n
BEGIN

IF DELETING THEN

  DELETE FROM EmailAddressWareHouse
  WHERE
  SourceTable='Contacts'
  AND xLink = o.ContactsCounter;

ELSE
Declare MyFullname VarChar(50);
Declare FOUND Boolean;
SET FOUND = FALSE;
IF EXISTS
(
   SELECT TOP 1 IDX FROM "EmailAddressWareHouse"
   WHERE
  XLink=N.ContactsCounter
  and  SourceTable='Contacts'
  and SourceField ='ContactsCounter'
)
   THEN
   SET FOUND = TRUE;
END IF;

Set MyFullName = Coalesce((SELECT FULLNAME from Name2 WHERE NameCounter = N.Person), '');

IF NOT FOUND THEN
 IF COALESCE(n.Email,'') <> '' AND COALESCE(MyFullName,'') <> '' THEN
   Insert into "EmailAddressWareHouse"
   (FullName, Email, XLink, SourceTable, SourceField)
   VALUES
  (MyFullName, N.Email, N.ContactsCounter, 'Contacts', 'ContactsCounter');
 END IF;
END IF;


  IF COALESCE(o.Email,'') <> ''  AND N.Email = '' THEN
    DELETE FROM EmailAddressWareHouse
    WHERE
    XLink=N.ContactsCounter
    and  SourceTable='Contacts'
    and SourceField ='ContactsCounter';
  END IF;


  Update "EmailAddressWareHouse"
  set FullName =  MyFullname, Email= N.Email
  where
  XLink=N.ContactsCounter
  and  SourceTable='Contacts'
  and SourceField ='ContactsCounter';

END IF;


END;

