/* trCostDetailsAFTER */
CREATE TRIGGER trCostDetailsAFTER
AFTER INSERT, DELETE, UPDATE of NetTotal ON CostsDetail
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vxCost integer;

IF NOT DELETING THEN
    SET vxCost = n.xCost;
ELSE
    SET vxCost = o.xCost;
END IF;

UPDATE Costs C
SET C.AnticipatedPrice = (
		SELECT SUM(NetTotal)
		FROM CostsDetail
		WHERE xCost = vxCost
		),
	C.ActualPrice = CASE
		WHEN (SELECT P.PaymentMode FROM PaymentTypes P WHERE P.Idx = C.xPaymentType) <> 2
			THEN (
					SELECT COALESCE(SUM(NetTotal), 0)
					FROM CostsDetail
					WHERE xCost = vxCost
					)
		ELSE C.ActualPrice
		END
WHERE C.IDX = vxCost
	AND C.IsList;

END;

/* trCostDetailsBEFORE */
CREATE TRIGGER trCostDetailsBEFORE
BEFORE INSERT, UPDATE ON CostsDetail
REFERENCING OLD AS o NEW AS n
BEGIN

  IF n.Discount > 100 THEN
    SET n.Discount = 100;
  END IF;

  IF n.Discount < 0 THEN
    SET n.Discount = 0;
  END IF;

  IF n.ReceivedToDate > n.Quantity THEN
    SET n.ReceivedToDate = n.Quantity ;
  END IF;

  SET n.GrossTotal = n.Quantity * n.UnitPrice;
  SET n.NetTotal =  RoundToTwoDP( n.GrossTotal * ( 1 - (n.Discount /100)));

END;

/* trCostsBefore */
CREATE TRIGGER trCostsBefore
BEFORE INSERT, DELETE, UPDATE ON Costs
REFERENCING OLD AS o NEW AS n
BEGIN


  DECLARE vUserID INT;
  SET vUserID = GetUserID();

  IF INSERTING THEN

     IF vUserID > -1 then
        SET n.xCreatedBy = vUserID;
     END IF;

  ELSEIF UPDATING THEN

    IF vUserID > -1 then
       SET n.xModifiedBy = vUserID;
    END IF;

    SET n.ModifiedDate = Current_Timestamp;

    IF n.InvoiceOnPrice IS NULL THEN
       SET n.InvoiceOnPrice = 0;
    END IF;

    -- check if its invoiced
    IF n.InvoiceOnPrice < 0 THEN
       IF n.InvoiceOnPrice >  n.InvoicedTotal THEN
          SIGNAL 'This line has already been negatively invoiced for more than the new line price.';
       END IF;
    ELSE
       IF n.InvoiceOnPrice <  n.InvoicedTotal THEN
          SIGNAL 'This line has already been invoiced for more than the new line price.';
       END IF;
    END IF;

  ELSEIF DELETING THEN

      -- block deleting if invoiced
      IF o.Invoiced THEN
        SIGNAL 'This line has already been invoiced and cannot be deleted.';
      END IF;

      -- block deleting if PO raised
      IF o.Ordered THEN
        SIGNAL 'This line has already been ordered against and cannot be deleted.';
      END IF;

   END IF;
END;

/* trCostsTotalsAFTER */
CREATE TRIGGER "trCostsTotalsAFTER"
AFTER INSERT, DELETE, UPDATE ON Costs
REFERENCING OLD AS o NEW AS n
BEGIN

 -- TGeneralCostCentre = (gccEquipment =0, gccCrew =1, gccTransport = 2, gccMisc = 3);
 -- TInternalCostCentre = (iccNone = 0, iccPayment = 1, iccEqUsage = 2, iccPrep = 3, iccTransport = 4, iccGlobalPurchaseOrderAllocation = 5);

 DECLARE vLastQuotedDate Timestamp;
 DECLARE vInternalCostCentre BYTE;

 -- QuoteDate
 IF NOT EQUIVALENT(o.QuoteCount, n.QuoteCount) THEN
   SET vLastQuotedDate = Current_TimeStamp;
 ELSE
   SET vLastQuotedDate = NULL;
 END IF;


 IF NOT DELETING THEN
   SET vInternalCostCentre = n.xInternalCostCentre;
 ELSE
   SET vInternalCostCentre = o.xInternalCostCentre;
 END IF;

  IF INSERTING THEN

  IF n.IsIncome THEN
    INSERT INTO JobFinances
    (xJob,  IsIncome, xCostCentreID, xGeneralCostCentre, xInternalCostCentre, LastQuotedDate, xStatus,   QuotedPrice,        ActualPrice,      Reference,   Title)
    VALUES
    (n.xJob, TRUE,    n.IDX,         3,                vInternalCostCentre, vLastQuotedDate, n.xStatus, n.LastQuotedTotal,  n.InvoiceOnPrice,  n.OurRef,   n.Title);
  END IF;

  IF n.IsExpenditure THEN
    IF vInternalCostCentre = 1 THEN -- its a payment
      UPDATE  JobFinances
      SET ActualPrice = n.ActualPrice
      WHERE
      xCostCentreID =  n.xCostCentreID  AND xGeneralCostCentre = n.xGeneralCostCentre;
    ELSE

      INSERT INTO JobFinances
      (xJob,   IsIncome, xCostCentreID, xGeneralCostCentre, xInternalCostCentre, xStatus,  QuotedPrice,         Reference, Title)
      VALUES
      (n.xJob, FALSE,     n.IDX,        3,                vInternalCostCentre,  n.xStatus, n.AnticipatedPrice,  n.OurRef, n.Title);

    END IF;
  END IF;


  ELSEIF UPDATING THEN

   IF o.IsList and not n.IsList  THEN
     DELETE FROM CostsDetail
     WHERE xCost =  o.IDX;
   END IF;

   IF o.IsIncome AND NOT n.IsIncome THEN
     DELETE FROM JobFinances
     WHERE xCostCentreID = o.IDX
     AND xGeneralCostCentre = 3
     AND IsIncome = TRUE;
   END IF;

   IF o.IsExpenditure AND NOT n.IsExpenditure THEN
     DELETE FROM JobFinances
     WHERE
     xCostCentreID = o.IDX
     AND xGeneralCostCentre = 3
     AND IsIncome = FALSE;
   END IF;


   IF n.IsIncome THEN
     -- create record in JobFinances table if necessary
    IF not o.IsIncome THEN

    INSERT INTO JobFinances
    (xJob,  IsIncome, xCostCentreID, xGeneralCostCentre,xInternalCostCentre, LastQuotedDate, xStatus,   QuotedPrice,        ActualPrice,   Reference,   Title)
    VALUES
    (n.xJob, True,    n.IDX,         3,                vInternalCostCentre, vLastQuotedDate, n.xStatus, n.LastQuotedTotal,  n.InvoiceOnPrice, n.OurRef,   n.Title);

    ELSE

    UPDATE JobFinances SET
    LastQuotedDate =
    CASE
    WHEN vLastQuotedDate IS NOT NULL THEN vLastQuotedDate
    ELSE
    LastQuotedDate
    END,
    xStatus = n.xStatus,
    QuotedPrice = n.LastQuotedTotal,
    ActualPrice = n.InvoiceOnPrice,
    Reference = n.OurRef,
    Title = n.Title
    WHERE
    xCostCentreID = n.IDX and IsIncome = True and xGeneralCostCentre = 3;
    END IF;

   END IF; --n.IsIncome

   IF n.IsExpenditure THEN
    IF NOT o.IsExpenditure THEN

      IF vInternalCostCentre = 1 THEN -- its a payment
      UPDATE  JobFinances
      SET ActualPrice = n.ActualPrice
      WHERE
      xCostCentreID =  n.xCostCentreID  AND xGeneralCostCentre = n.xGeneralCostCentre;
      ELSE
        INSERT INTO JobFinances
        (xJob,   IsIncome, xCostCentreID, xGeneralCostCentre, xInternalCostCentre, xStatus,  QuotedPrice,                        Reference, Title)
         VALUES
        (n.xJob, FALSE,     n.IDX,        3,  vInternalCostCentre, n.xStatus, n.AnticipatedPrice,                 n.OurRef,  n.Title);

      END IF;

    ELSE
     UPDATE JobFinances SET
     xStatus = n.xStatus,
     QuotedPrice = CASE
     WHEN vInternalCostCentre <>  1 THEN n.AnticipatedPrice
     ELSE QuotedPrice
     END,
     ActualPrice = CASE
     WHEN vInternalCostCentre = 1 THEN n.ActualPrice
     ELSE ActualPrice
     END,
     Reference = n.OurRef,
     Title = n.Title
     WHERE
     xCostCentreID = n.IDX and IsIncome = False and xGeneralCostCentre = 3;
    END IF;

   END IF;

   IF o.QuoteCount <> n.QuoteCount then
      UPDATE Jobs SET LastQuotedMiscCosts = (SELECT SUM(LastQuotedTotal) FROM Costs where xJob = n.xJob and Selected = True) WHERE Jobno = n.xJob ;
   END IF;

   IF o.Invoiced <> n.Invoiced then
      UPDATE CostsDetail SET Invoiced = n.Invoiced WHERE xCost = n.IDX ;
   END IF;

  ELSEIF DELETING THEN
    IF vInternalCostCentre = 1 THEN --its a payment

      UPDATE JobFinances SET
      ActualPrice = ActualPrice - o.ActualPrice
      WHERE
      xCostCentreID = o.xCostCentreID and IsIncome = False and xGeneralCostCentre = o.xGeneralCostCentre;

    ELSE

      DELETE FROM JobFinances
      WHERE xCostCentreID = o.IDX
      AND xGeneralCostCentre = 3;

    END IF;

      -- reset any Service records
    IF o.xInternalCostCentre IN (19,20) THEN -- see htTypesU.pas TInternalCostCentre
       UPDATE ServData SET
       RepairAction = NULL
       WHERE
       Recordno = o.xCostCentreID;
    END IF;

    DELETE FROM CostsDetail
    WHERE
    xCost =  o.IDX;

    UPDATE Jobs SET
    LastQuotedMiscCosts = (SELECT SUM(LastQuotedTotal) FROM Costs where xJob = o.xJob and Selected = True)
    WHERE
    Jobno = o.xJob ;

  END IF;
END;

