/* trCrewAccommodationAFTER */
CREATE TRIGGER trCrewAccommodationAFTER
AFTER INSERT, DELETE, UPDATE OF Charge ON CrewAccommodation
REFERENCING OLD AS o NEW AS n
BEGIN
    DECLARE vJobID INT;
    SET vJobID = COALESCE(n.xJob, o.xJob);

     IF INSERTING THEN
        INSERT INTO JobFinances
        (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus,  QuotedPrice, Reference, Title, SubCostCentre)
        VALUES
        (n.xJob, FALSE, n.Idx,             1,               3,        n.Charge,    'Accommodation' , (SELECT CompanyName FROM Company WHERE CompanyCounter = n.xCompany), 5);
     ELSEIF UPDATING THEN
            IF (SELECT COUNT(*) = 0 FROM JobFinances WHERE xJob = n.xJob AND xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 5) THEN

               INSERT INTO JobFinances
               (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus,  QuotedPrice, Reference, Title, SubCostCentre)
               VALUES
               (n.xJob, FALSE, n.Idx,             1,               3,        n.Charge,    'Accommodation' , (SELECT CompanyName FROM Company WHERE CompanyCounter = n.xCompany), 5);

            ELSEIF n.Charge > 0 THEN

              UPDATE JobFinances SET
              QuotedPrice = n.Charge
              WHERE
              xJob = n.xJob
              AND xCostCentreID = n.Idx
              AND xGeneralCostCentre = 1
              AND SubCostCentre = 5 ;

            ELSE

              DELETE FROM JobFinances
              WHERE
              xJob = n.xJob
              AND xCostCentreID = n.Idx
              AND xGeneralCostCentre = 1
              AND SubCostCentre = 5 ;

            END IF;
     ELSE

         DELETE FROM JobFinances
         WHERE
         xJob = o.xJob
         AND xCostCentreID = o.Idx
         AND xGeneralCostCentre = 1
         AND SubCostCentre = 5 ;

     END IF;

     CALL TotalizeCrewAccommodationPay(vJobID);

END;

/* trCrewAccommodationBEFORE */
CREATE TRIGGER trCrewAccommodationBEFORE
BEFORE DELETE, UPDATE ON CrewAccommodation
REFERENCING OLD AS o NEW AS n
BEGIN

	IF DELETING THEN
	  IF O.OrderStatus > 0 THEN
	        SIGNAL 'One or more Accommodation Purchase Orders have been raised for this Shift';
	  END IF;
	ELSE
    --  OrderStatus change
	  IF NOT EQUIVALENT(o.OrderStatus, n.OrderStatus) AND (n.OrderStatus = 2) THEN -- if raising an order clear flag
	     SET n.Flag = 0;

       IF n.FlagNarrative IS NULL THEN
          SET n.FlagNarrative = COALESCE(n.FlagNarrative, TimeStampString(2) + ' - ' +  'Flag cleared after PO raised') ;
       ELSE
          SET n.FlagNarrative = n.FlagNarrative + CHR(13)+ CHR(10)+ TimeStampString(2) + ' - ' +  'Flag cleared after PO raised' ;
       END IF;
	  END IF;

    -- Flag change
    IF NOT EQUIVALENT(o.Flag, n.Flag) AND (n.Flag > 0) THEN
       SET n.Charge = 0;

       IF n.FlagNarrative IS NULL THEN
          SET n.FlagNarrative = COALESCE(n.FlagNarrative, TimeStampString(2) + ' - ' +  'Charge of ' + TOSTRING(o.Charge) + ' set to zero due to flag change') ;
       ELSE
          SET n.FlagNarrative = n.FlagNarrative + CHR(13)+ CHR(10)+ TimeStampString(2) + ' - ' +  'Charge of ' + TOSTRING(o.Charge) + ' set to zero due to flag change' ;
       END IF;

       SET n.OrderStatus = CalcCrewAccomodationOrderStatus(n.IDX, n.Charge);
    END IF;

	END IF;

END;

