/* trCrewBEFORE */
CREATE TRIGGER trCrewBEFORE
BEFORE  INSERT, DELETE,  UPDATE ON Crew
REFERENCING OLD AS o NEW AS n
WHEN (INSERTING OR DELETING OR EQUIVALENT(o.Rectype, n.Rectype))
BEGIN

    IF n.Back < n."Out" THEN
      SIGNAL 'Date Back can not be before the Date Out';
    END IF;

    DECLARE vUserID INT;
    SET vUserID = GetUserID();

    DECLARE vNewCrewing BOOL;
    SET vNewCrewing = (SELECT COALESCE(NewCrewing,True) FROM Jobs WHERE Jobno = COALESCE(n.Job_No, o.Job_no));


  IF INSERTING THEN

     IF vUserID > -1 THEN
       SET n.createdby =vUserID;
     END IF;

     IF (n.xCrewTask IS NULL) AND (NOT vNewCrewing) THEN
        SET n.xStatus  = (SELECT xStatus FROM Crew_Header WHERE IDX = n.Header);
     END IF;

  ELSEIF UPDATING THEN

     IF vUserID > -1 THEN
       SET n.modifiedby = vUserID;
     END IF;

    SET  n.ModifiedDate  = CURRENT_TIMESTAMP;

    IF vNewCrewing AND n.Rectype IN (2,3) THEN  --TCrewRecordType = (crtOld, crtUpgrading, crtUpgraded, crtNew);
       SET n.Total = n.LabourChargeForBilling + n.PDChargeForBilling +  n.TravelChargeForBilling + n.OvertimeChargeForBilling + n.AccommodationChargeForBilling;
       SET n.QuotationChargeTotal = n.LabourCharge + n.PDCharge +  n.TravelCharge + n.OvertimeCharge + n.AccommodationCharge;
       SET n.TotalPay = n.LabourPay + n.PDPay +  n.TravelPay + n.OvertimePay;
    END IF;

    --check if its invoiced
    IF n.Total < 0 THEN
       IF n.Total >  n.InvoicedTotal THEN
          SIGNAL 'This line has already been negatively invoiced for more than the new line price.';
       END IF;
    ELSE
        IF n.Total <  n.InvoicedTotal THEN
           SIGNAL 'This line has already been invoiced for more than the new line price.';
        END IF;
    END IF;

    IF (NOT EQUIVALENT(N.Quantity,n.Quantity)) AND  (n.Quantity < n.Allocated) THEN
      SIGNAL 'Quantity booked cannot be reduced below Allocated Quantity.';
    END IF;

    IF (vNewCrewing) AND (NOT EQUIVALENT(n.xStatus , o.xstatus)) THEN
       SET n.xStatus  = CASE
                        WHEN n.xStatus < 0 THEN 0
                        WHEN n.xStatus > 3 THEN 3
                        ELSE n.xStatus
                        END;
    END IF;

    IF (NOT EQUIVALENT(n.xStatus , o.xstatus)) AND (n.Allocated > 0) AND (GetStatusFunction(n.xstatus) = 0) AND (NOT vNewCrewing) THEN
      SIGNAL 'Cannot demote to this status while crew allocated';
    END IF;

   ELSEIF DELETING THEN
    -- block deleting if invoiced
      IF (o.InvoicedTotal > 0) OR (o.Invoiced) THEN
        SIGNAL 'This line has already been invoiced and cannot be deleted.';
      END IF;


    IF n.Allocated > 0 THEN
      SIGNAL 'Allocated Crew Requirements can not be deleted. Unallocate all people first.';
    END IF;

  END IF;
END;

/* trCrewEqlNewAFTER */
CREATE TRIGGER trCrewEqlNewAFTER
AFTER INSERT, DELETE ON CrewEqlNew
REFERENCING OLD AS o NEW AS n
BEGIN
 DECLARE vCrewID INTEGER;

 IF DELETING THEN
   SET vCrewID = O.CrewRef;
   ELSE
   SET vCrewID = N.CrewRef;
 END IF;

  UPDATE CREW C SET C.EqlistsAllocated =
   (SELECT COUNT(*) FROM CrewEqlNew E
    WHERE E.CrewRef = vCrewID)
  WHERE C.IDX = vCrewID;
END;

/* trCrewHeaderAFTER */
CREATE TRIGGER trCrewHeaderAFTER
AFTER UPDATE of Title ON Crew_header
REFERENCING OLD AS o NEW AS n
BEGIN

   SELECT C.IDX, GetCrewTitleFromCrewHeaderID(C.Header) || ' - ' || GetCrewTypeTextFromID(C.Type) AS NewText
   INTO #Updates
   FROM Crew C
   WHERE
   C.Job_no = n.xJob;

   UPDATE JobFinances J SET
   J.Title = (SELECT U.NewText FROM #Updates U WHERE U.IDX = J.xCostCentreID)
   WHERE
   J.xJob = n.xJob
   AND xGeneralCostCentre = 1;
END;

/* trCrewHeaderBefore */
CREATE TRIGGER "trCrewHeaderBefore"
BEFORE  INSERT, UPDATE ON Crew_Header
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;

   SET vUserID = GetUserID();

  IF INSERTING THEN

     IF vUserID > -1 then
       SET n.createdby = vUserID;
     END IF;

      -- ScheduleStart has changed is >  ScheduleEnd
     IF  n.ScheduleStart > n.ScheduleEnd THEN
      SET n.ScheduleEnd = n.ScheduleStart + INTERVAL '1' DAY;
     END IF;

      -- PriceStart has changed is >  PriceEnd
      IF  n.PriceStart > n.PriceEnd THEN
       SET n.PriceEnd = n.PriceStart + INTERVAL '1' DAY;
      END IF;

     SET n.xStatus = GetJobStatus(n.xJob);

  ELSEIF UPDATING THEN

     IF vUserID > -1 then
       SET n.modifiedby = vUserID;
     END IF;

     SET n.ModifiedDate = CURRENT_TIMESTAMP;

       -- ScheduleStart has changed
     IF NOT EQUIVALENT(n.ScheduleStart, o.ScheduleStart)  AND  n.ScheduleStart > n.ScheduleEnd THEN
      SET n.ScheduleEnd = CAST(CAST(n.ScheduleEnd AS DOUBLE PRECISION) + (CAST(n.ScheduleStart AS DOUBLE PRECISION) - CAST(o.ScheduleStart AS DOUBLE PRECISION)) AS TIMESTAMP);
     END IF;

     -- ScheduleEnd has changed
     IF NOT EQUIVALENT(n.ScheduleEnd, o.ScheduleEnd)   AND  n.ScheduleStart > n.ScheduleEnd THEN
      SET n.ScheduleStart = CAST(CAST(n.ScheduleStart AS DOUBLE PRECISION) + (CAST(n.ScheduleEnd AS DOUBLE PRECISION) - CAST(o.ScheduleEnd AS DOUBLE PRECISION)) AS TIMESTAMP);
     END IF;

      -- PriceStart has changed
     IF NOT EQUIVALENT(n.PriceStart , o.PriceStart) AND (n.PriceStart > n.PriceEnd) THEN
       SET n.PriceEnd = CAST(CAST(n.PriceEnd AS DOUBLE PRECISION) + (CAST(n.PriceStart AS DOUBLE PRECISION) - CAST(o.PriceStart AS DOUBLE PRECISION)) AS TIMESTAMP);
     END IF;

      -- PriceEnd has changed
     IF NOT EQUIVALENT(n.PriceEnd , o.PriceEnd) AND (n.PriceStart > n.PriceEnd) THEN
       SET n.PriceStart = CAST(CAST(n.PriceStart AS DOUBLE PRECISION) + (CAST(n.PriceEnd AS DOUBLE PRECISION) - CAST(o.PriceEnd AS DOUBLE PRECISION)) AS TIMESTAMP);
     END IF;

    IF NOT EQUIVALENT(n.ScheduleEnd , o.ScheduleEnd) OR NOT EQUIVALENT(n.ScheduleStart , o.ScheduleStart) THEN
      UPDATE Crew SET
        "Out" = n.ScheduleStart,
        "Back" = n.ScheduleEnd
      WHERE  Header = n.IDX ;
     END IF;

     -- status has changed
     IF NOT EQUIVALENT(n.xStatus , o.xStatus) THEN
      UPDATE Crew SET xStatus = n.xStatus
      WHERE  Header = n.IDX ;
     END IF;

     -- Finances table
     SELECT
     C.IDX
     INTO #Crew
     FROM Crew C
     WHERE
     C.header = n.IDX ;

     UPDATE JobFinances SET
     Title = n.Title
     WHERE
     xCostCentreID IN (SELECT IDX FROM #Crew)
     AND xGeneralCostCentre = 1;

  END IF;

 END;

/* trCrewJobAFTER */
CREATE TRIGGER trCrewJobAFTER
AFTER INSERT,  DELETE , UPDATE  ON CrewJobs
REFERENCING OLD AS o NEW AS n
BEGIN

	DECLARE vNewCrewing BOOL;
	DECLARE vCrewTask BOOL;

	SET vNewCrewing = COALESCE((SELECT COALESCE(J.NewCrewing,True) FROM Crew C INNER JOIN Jobs J ON C.Job_no = J.Jobno WHERE C.Idx = COALESCE(n.JobRef, o.JobRef)), FALSE);
	SET vCrewTask = (SELECT C.Job_no IS NULL FROM Crew C WHERE C.Idx = COALESCE(n.JobRef, o.JobRef));

	IF NOT vNewCrewing THEN -- we are allocating crew people to legacy crew requests

	    IF UPDATING AND (n.Ordered = TRUE) AND (n.Pay < n.Purchased) THEN
			SIGNAL 'Pay value cannot be lower than Purchased value!';
		END IF;

		IF DELETING AND (o.Ordered = TRUE) THEN
			SIGNAL 'Cannot delete crew assignment when there is a Purchased Order for it!';
		END IF;

		UPDATE Crew C SET
	    C.Allocated = COALESCE((SELECT COUNT(J.Counter) FROM CrewJobs J WHERE J.JobRef = COALESCE(n.JobRef, o.JobRef)),0),
	    C.TotalPay = COALESCE((SELECT SUM(J.Pay) FROM CrewJobs J WHERE J.JobRef = COALESCE(n.JobRef, o.JobRef)),0)
	    WHERE
	    C.IDX = COALESCE(n.JobRef, o.JobRef);

	   --JobFinances
		UPDATE JobFinances SET
		ActualPrice = COALESCE((SELECT SUM(Purchased)
	                          FROM
	                          CrewJobs
	                          WHERE
	                          JobRef = COALESCE(n.JobRef, o.JobRef)),0)
		WHERE
		xCostCentreID = COALESCE(n.JobRef, o.JobRef)
		AND xGeneralCostCentre = 1
		AND IsIncome = FALSE;

	ELSEIF vCrewTask THEN-- we are creating Crew Tasks

		DECLARE vQty DWORD;
		SET vQty = COALESCE((SELECT COUNT(J.Counter) FROM CrewJobs J WHERE J.JobRef = COALESCE(n.JobRef, o.JobRef)),0);

		UPDATE Crew C SET
		C.Quantity = vQty,
		C.Allocated = vQty
		WHERE
		C.IDX = COALESCE(n.JobRef, o.JobRef);

	END IF;

END;

