/* trCrewPositionOffersBEFORE */
CREATE TRIGGER trCrewPositionOffersBEFORE
BEFORE  INSERT, UPDATE ON CrewPositionOffers
REFERENCING OLD AS o NEW AS n
BEGIN
  -- NX user
  DECLARE vUserID INT;
  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

  SET n.LastModifiedBy = vUserID;

  --OfferStatus. See TCrewOfferStatus = (cosShortlisted, cosContacted, cosUnavailable, cosPossiblyAvailablity, cosAvailable, cosRejected, cosPencilled, cosBooked, cosCancelled);
  IF NOT EQUIVALENT(n.OfferStatus, o.OfferStatus) THEN

     -- if the NX client has somehow allowed a double booking, reject with a signal
     IF n.OfferStatus = 7 THEN
        IF (SELECT COUNT(*) > 0 FROM CrewPositionOffers WHERE xPosition = n.xPosition AND OfferStatus = 7) THEN
           SIGNAL 'Crew already booked for this position. Cancel them before proceding to book this person';
        END IF;
     END IF;

     -- if OfferStatus has changed then Crew person must have replied to update us on "something"
     UPDATE Name2 SET LastCrewingContactReplyDate = CURRENT_TIMESTAMP
     WHERE
     NameCounter = n.xPerson;

     IF n.OfferStatus = 7 THEN --  setting as cosBooked
        UPDATE Name2 SET LastCrewingBookedDate = CURRENT_TIMESTAMP
        WHERE
        NameCounter = n.xPerson;
     END IF;

     IF o.OfferStatus = 7 THEN --  unsetting as cosBooked, so get the last offer date for this person that is not this record
        UPDATE Name2 SET LastCrewingBookedDate = (SELECT MAX(OfferStatusDate) FROM CrewPositionOffers
                                                 WHERE
                                                 xPerson = n.xPerson
                                                 AND OfferStatus = 7
                                                 AND IDX <> n.IDX)
        WHERE
        NameCounter = n.xPerson;
     END IF;
  END IF;

  --CorrespondenceType
  IF NOT EQUIVALENT(n.CorrespondenceType, o.CorrespondenceType) THEN
     UPDATE Name2 SET LastCrewingContactDate = CURRENT_TIMESTAMP WHERE NameCounter = n.xPerson;
  END IF;

END;

/* trCrewShiftsAFTER */
CREATE TRIGGER trCrewShiftsAFTER
AFTER UPDATE OF  BookingState, xPosition, xActivity, AccommodationCharge, AccommodationStatus, AccommodationDays
ON CrewShifts
REFERENCING OLD AS o NEW AS n
BEGIN

 --TShiftBookingState = (sbsIncQuote, sbsExcQuote, sbsCancelled, sbsBlackout);
 IF UPDATING AND (NOT EQUIVALENT(o.BookingState,n.BookingState)) AND (n.BookingState = 2) AND (o.AccommodationStatus <> 0) THEN  -- when cancelling, AccommodationStatus gets set to 0
    DECLARE vCrewAccommodationLkpIDX INT;
    DECLARE vNarrativeString TEXT;

    SET vNarrativeString = TimeStampString(2) + ' - Shift for ' + F_FORMATDATE((SELECT ActivityDate FROM CrewActivities WHERE IDX = n.xActivity)) + ' set to Cancelled';

    IF (SELECT COUNT(*) > 0 FROM CrewAccommodationLkp WHERE xCrewShift = n.Idx) THEN
       UPDATE CrewAccommodation SET
       Flag = 3, --TAccommodationFlag = (afNone, afShiftDateChange, afShiftRoomChange, afShiftCancelled, afPositionChange, afDateAndPositionChange);
       FlagNarrative = CASE
                              WHEN FlagNarrative IS NULL THEN vNarrativeString
                              ELSE
                              FlagNarrative + CHR(13)+ CHR(10)+ vNarrativeString
                          END
       WHERE
       IDX IN (SELECT xCrewAccommodation FROM CrewAccommodationLkp WHERE xCrewShift = n.Idx);

       DELETE FROM CrewAccommodationLkp C
       WHERE
       C.xCrewShift = n.IDX;
    END IF;

 END IF;

 IF UPDATING AND (NOT EQUIVALENT(o.AccommodationDays,n.AccommodationDays)) AND (n.AccommodationDays < o.AccommodationDays) THEN

    IF (BITAND(o.AccommodationDays, 1 ) = 1) AND (BITAND(n.AccommodationDays, 1 ) <> 1) THEN -- DayBefore being removed
       DELETE FROM CrewAccommodationLkp WHERE xCrewShift = n.Idx AND AccommodationDay = 0;
    END IF;

    IF (BITAND(o.AccommodationDays, 2 ) = 2) AND (BITAND(n.AccommodationDays, 2 ) <> 2) THEN -- ShiftDay being removed
       DELETE FROM CrewAccommodationLkp WHERE xCrewShift = n.Idx AND AccommodationDay = 1;
    END IF;

    IF (BITAND(o.AccommodationDays, 4 ) = 4) AND (BITAND(n.AccommodationDays, 2 ) <> 4) THEN -- DayAfter being removed
       DELETE FROM CrewAccommodationLkp WHERE xCrewShift = n.Idx AND AccommodationDay = 2;
    END IF;

 END IF;

 IF UPDATING AND ((NOT EQUIVALENT(o.xActivity,n.xActivity))OR (NOT EQUIVALENT(o.xPosition,n.xPosition))) AND (n.AccommodationStatus <> 0) THEN
    DECLARE vOldDate DATE;
    DECLARE vNewDate DATE;
    DECLARE vNarrativeString TEXT;
    DECLARE vDayString VARCHAR(20);
    DECLARE vCrewAccommodationIDX INT;
    DECLARE vCrewAccommodationLkpIDX INT;
    DECLARE vCrewAccommodationCompany INT;
    DECLARE vCrewAccommodationJob INT;
    DECLARE vCrewAccommodationPerson VARCHAR(50);
    DECLARE vCrewAccommodationCharge MONEY;
    DECLARE vAccommodationDay TINYINT;
    DECLARE vFlag TINYINT;

    --TAccommodationFlag = (afNone, afShiftDateChange, afShiftRoomChange, afShiftCancelled, afPositionChange, afDateAndPositionChange);
    SET vFlag = CASE
        WHEN (NOT EQUIVALENT(o.xActivity,n.xActivity)) AND ( EQUIVALENT(o.xPosition,n.xPosition)) THEN 1
        WHEN (EQUIVALENT(o.xActivity,n.xActivity)) AND (NOT EQUIVALENT(o.xPosition,n.xPosition)) THEN 4
        WHEN (NOT EQUIVALENT(o.xActivity,n.xActivity)) AND (NOT EQUIVALENT(o.xPosition,n.xPosition)) THEN 5
        END;

    DECLARE cAccomm CURSOR FOR
    SELECT A.IDX, A.xCompany, A.xJob, A.Charge, c.AccommodationDay,  c.IDX AS CrewAccommodationLkpIDX, COALESCE(N2.Fullname,'Person Unassigned')
    FROM CrewAccommodationLkp C
    INNER JOIN CrewAccommodation A
    ON C.xCrewAccommodation = A.Idx
    INNER JOIN CrewShifts S
    ON C.xCrewShift = S.IDX
    INNER JOIN CrewPositions P
    ON S.xPosition = P.IDX
    LEFT OUTER JOIN Name2 N2
    ON P.xPerson = N2.NameCounter
    WHERE
    C.xCrewShift = n.Idx
    ORDER BY
    c.AccommodationDay ASC;

    OPEN cAccomm;
    TRY

    FETCH FIRST FROM cAccomm INTO vCrewAccommodationIDX, vCrewAccommodationCompany, vCrewAccommodationJob, vCrewAccommodationCharge, vAccommodationDay, vCrewAccommodationLkpIDX, vCrewAccommodationPerson;

    WHILE @@FETCH_STATUS = 0 DO

	  --SET vShiftChargeAmount = vCrewAccommodationCharge / vCrewAccommodationShiftCount;

      SET vNewDate = (SELECT ActivityDate FROM CrewActivities WHERE IDX = n.xActivity);
      SET vOldDate = (SELECT ActivityDate FROM CrewActivities WHERE IDX = o.xActivity);
      SET vDayString = 'Night OF Shift';

      IF vAccommodationDay = 0 THEN
         SET vNewDate = vNewDate - INTERVAL '1' DAY;
         SET vOldDate = vOldDate - INTERVAL '1' DAY;
         SET vDayString = 'Night BEFORE Shift';
      ELSEIF vAccommodationDay = 2 THEN
         SET vNewDate = vNewDate + INTERVAL '1' DAY;
         SET vOldDate = vOldDate + INTERVAL '1' DAY;
         SET vDayString = 'Night AFTER Shift';
      END IF;

      SET vNarrativeString = TimeStampString(2) + ' - ' +  vCrewAccommodationPerson + ' date changed from ' + F_FORMATDATE(vOldDate) + ' to ' +  F_FORMATDATE(vNewDate) + ' (' + vDayString + ')';

       IF (SELECT COUNT(*) = 0 FROM CrewAccommodation C  -- any record found in CrewAccommodation for the shift's job, hotel and date? If not we need to create a CrewAccommodation record & update CrewAccommodationLkp
          WHERE
          C.xJob = vCrewAccommodationJob
          AND C.BookingDate = vNewDate
          AND C.xCompany = vCrewAccommodationCompany) THEN

          INSERT INTO CrewAccommodation
          (xJob, BookingDate, xCompany, Flag, FlagNarrative)
          VALUES
          (vCrewAccommodationJob, vNewDate, vCrewAccommodationCompany, 1, vNarrativeString);

          UPDATE CrewAccommodationLkp SET -- link in the Shift
          xCrewAccommodation  = LASTAUTOINC
          WHERE
          Idx = vCrewAccommodationLkpIDX;



          -- the original CrewAccommodation record and set it's flag -TAccommodationFlag = (afNone, afShiftDateChange, afShiftRoomChange)
          UPDATE CrewAccommodation C SET
          Flag = vFlag,
          FlagNarrative = CASE
                              WHEN FlagNarrative IS NULL THEN vNarrativeString
                              ELSE
                              FlagNarrative + CHR(13)+ CHR(10)+ vNarrativeString
                          END
          WHERE
          C.IDX = vCrewAccommodationIDX;

       ELSE
          -- we a CrewAccommodation record that matches the shift's job, hotel and date so just update the Shift's link to it, and adjust the charges accordingly
          DECLARE vFoundCrewAccommodationIDX INT;

          SET vFoundCrewAccommodationIDX = (SELECT IDX FROM CrewAccommodation C
                                            WHERE
                                            C.xJob = vCrewAccommodationJob
                                            AND C.BookingDate = vNewDate
                                            AND C.xCompany = vCrewAccommodationCompany);

          UPDATE CrewAccommodationLkp SET
          xCrewAccommodation =  vFoundCrewAccommodationIDX
          WHERE
          Idx = vCrewAccommodationLkpIDX;

          -- the original CrewAccommodation record needs it's flag set -TAccommodationFlag = (afNone, afShiftDateChange, afShiftRoomChange)
          UPDATE CrewAccommodation C SET
          Flag = vFlag,
          FlagNarrative = CASE
                              WHEN FlagNarrative IS NULL THEN vNarrativeString
                              ELSE
                              FlagNarrative + CHR(13)+ CHR(10)+ vNarrativeString
                          END
          WHERE
          C.IDX = vCrewAccommodationIDX;

          -- the Found CrewAccommodation record needs it's flag set -TAccommodationFlag = (afNone, afShiftDateChange, afShiftRoomChange)
          UPDATE CrewAccommodation C SET
          Flag = vFlag,
          FlagNarrative = CASE
                              WHEN FlagNarrative IS NULL THEN vNarrativeString
                              ELSE
                              FlagNarrative + CHR(13)+ CHR(10)+ vNarrativeString
                          END
          WHERE
          C.IDX = vFoundCrewAccommodationIDX;

       END IF;

      FETCH NEXT FROM cAccomm INTO vCrewAccommodationIDX, vCrewAccommodationCompany, vCrewAccommodationJob, vCrewAccommodationCharge, vAccommodationDay, vCrewAccommodationLkpIDX, vCrewAccommodationPerson;
    END WHILE;
    CLOSE cAccomm;

	CATCH TRUE
	CLOSE cAccomm;
	SIGNAL ERROR_MESSAGE;
	END;

    -- clean up CrewAccommodation records that no longer have links to CrewAccommodationLkp
    DELETE FROM CrewAccommodation
    WHERE
    xJob = vCrewAccommodationJob
    AND IDX NOT IN (SELECT xCrewAccommodation FROM CrewAccommodationLkp)
    AND OrderStatus = 0;

 END IF;


END;

/* trCrewShiftsBEFORE */
CREATE TRIGGER trCrewShiftsBEFORE
BEFORE DELETE, UPDATE OF xPosition, xActivity ON CrewShifts
REFERENCING OLD AS o NEW AS n
BEGIN
  IF DELETING AND O.OrderStatus > 0 THEN
        SIGNAL 'One or more purchase orders have been raised for this Shift';
  END IF;

  --TShiftOrderStatus = (sosNone, sosPartial, sosFullfilled, sosOver, sosMisaligned);
  IF UPDATING AND n.OrderStatus IN (1,2,3) THEN  -- if changing position or activity and ordering done we must set the orderstatus to sosMisaligned so that user knows to address this
     SET n.OrderStatus = 4; -- note: it's down the the client to correct this should the user move the shift back to it's original position or activity
  END IF;
END;

/* trCrewTasksBEFORE */
CREATE TRIGGER  trCrewTasksBEFORE
BEFORE DELETE ON CrewTasks
REFERENCING OLD AS o NEW AS n
BEGIN
  IF n.TaskType = 1 THEN
     SIGNAL 'This Crew Task is a system entry and cannot be deleted';
  END IF;

END;

/* trCrewTotalsAFTER */
CREATE TRIGGER trCrewTotalsAFTER
AFTER INSERT, DELETE, UPDATE of "Type", LastQuotedTotal, Total, TotalPay, QuoteCount, xStatus,
LabourChargeForBilling, PDChargeForBilling, TravelChargeForBilling, OvertimeChargeForBilling, AccommodationChargeForBilling,
LabourPay, PDPay, TravelPay, OvertimePay, AccommodationPay
ON Crew
REFERENCING OLD AS o NEW AS n
WHEN (DELETING OR (n.RecType <> 1 AND COALESCE(o.RecType,0) <> 1)) -- TCrewRecordType = (crtOld, crtUpgrading, crtUpgraded, crtNew);
BEGIN

 --TGeneralCostCentre  = (gccEquipment = 0, gccCrew = 1, gccTransport = 2, gccMisc = 3);
 DECLARE vNonFinancialChange BOOL;
 DECLARE vLastQuotedDate Timestamp;
 DECLARE vNewCrewing BOOL;

 DECLARE vOldTotalChargeNeeded BOOL;
 DECLARE vLabourChargeNeeded BOOL;
 DECLARE vPDChargeNeeded BOOL;
 DECLARE vTravelChargeNeeded BOOL;
 DECLARE vOvertimeChargeNeeded BOOL;
 DECLARE vAccommodationChargeNeeded BOOL;

 DECLARE vOldTotalPayNeeded BOOL;
 DECLARE vLabourPayNeeded BOOL;
 DECLARE vPDPayNeeded BOOL;
 DECLARE vTravelPayNeeded BOOL;
 DECLARE vOvertimePayNeeded BOOL;

 DECLARE vLastQuotedTotal MONEY;

 SET vNewCrewing = (SELECT COALESCE(NewCrewing,True) FROM Jobs WHERE Jobno = COALESCE(n.Job_No, o.Job_no));
 SET vNonFinancialChange = (UPDATING) AND ((NOT EQUIVALENT(o.xStatus,n.xStatus)) OR (NOT EQUIVALENT(o."Type",n."Type")));

 -- QuoteDate
 IF NOT EQUIVALENT(o.QuoteCount , n.QuoteCount) THEN
   SET vLastQuotedDate = Current_TimeStamp;
 ELSE
   SET vLastQuotedDate = NULL;
 END IF;

 SET vLastQuotedTotal = NULL;

 IF (NOT vNewCrewing) AND (NOT EQUIVALENT(o.LastQuotedTotal , n.LastQuotedTotal) ) THEN
    SET vLastQuotedTotal = n.LastQuotedTotal;
 END IF;


 IF (INSERTING OR UPDATING) AND n.Job_no IS NOT NULL THEN
   -- INCOME

    SET vOldTotalChargeNeeded = (NOT vNewCrewing) AND  ((NOT EQUIVALENT(o.Total, n.Total)) OR (vLastQuotedTotal IS NOT NULL) OR (vNonFinancialChange));
    SET vLabourChargeNeeded =  (vNewCrewing) AND ((NOT EQUIVALENT(o.LabourChargeForBilling, n.LabourChargeForBilling)) OR (vNonFinancialChange));
    SET vPDChargeNeeded = (vNewCrewing) AND  ((NOT EQUIVALENT(o.PDChargeForBilling, n.PDChargeForBilling)) OR (vNonFinancialChange));
    SET vTravelChargeNeeded = (vNewCrewing) AND ((NOT EQUIVALENT(o.TravelChargeForBilling, n.TravelChargeForBilling)) OR (vNonFinancialChange));
    SET vOvertimeChargeNeeded = (vNewCrewing) AND ((NOT EQUIVALENT(o.OvertimeChargeForBilling, n.OvertimeCharge)) OR (vNonFinancialChange));
    SET vAccommodationChargeNeeded = (vNewCrewing) AND ((NOT EQUIVALENT(o.AccommodationChargeForBilling, n.AccommodationChargeForBilling)) OR (vNonFinancialChange));

    IF (vOldTotalChargeNeeded) THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 0 AND IsIncome = TRUE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, TRUE,  n.IDX, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.Total, GetCrewFunctionNameFromCrewHeaderID(n.Header), GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 0);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, TRUE, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.Total, GetCrewFunctionNameFromCrewHeaderID(n.Header), GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),0);
       END IF;
    END IF;
    IF (vLabourChargeNeeded)THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 1 AND IsIncome = TRUE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, TRUE,  n.IDX, n.xStatus, vLastQuotedDate, COALESCE(n.LastQuotedTotal,0), n.LabourChargeForBilling, 'Labour Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 1);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, TRUE, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.LabourChargeForBilling, 'Labour Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),1);
       END IF;
    END IF;
     IF (vPDChargeNeeded) THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 2 AND IsIncome = TRUE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, TRUE,  n.IDX, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.PDChargeForBilling, 'PD Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 2);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, TRUE, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.PDChargeForBilling, 'PD Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),2);
       END IF;
    END IF;
    IF (vTravelChargeNeeded) THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 3 AND IsIncome = TRUE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, TRUE,  n.IDX, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.TravelChargeForBilling, 'Travel Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 3);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, TRUE, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.TravelChargeForBilling, 'Travel Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),3);
       END IF;
    END IF;
    IF (vOvertimeChargeNeeded) THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 4 AND IsIncome = TRUE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, TRUE,  n.IDX, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.OvertimeChargeForBilling, 'Overtime Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 4);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, TRUE, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.OvertimeChargeForBilling, 'Overtime Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),4);
       END IF;
    END IF;
    IF (vAccommodationChargeNeeded) THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 5 AND IsIncome = TRUE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, TRUE,  n.IDX, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.AccommodationChargeForBilling, 'Accommodation Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 5);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, TRUE, n.xStatus, vLastQuotedDate, vLastQuotedTotal, n.AccommodationChargeForBilling, 'Accommodation Charges', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),5);
       END IF;
    END IF;

    -- EXPENDITURE
    SET vOldTotalPayNeeded = (NOT vNewCrewing) AND (NOT EQUIVALENT(o.TotalPay, n.TotalPay)) AND (n.TotalPay = 0);
    SET vLabourPayNeeded =  (vNewCrewing) AND (NOT EQUIVALENT(o.LabourPay, n.LabourPay)) AND (n.LabourPay = 0);
    SET vPDPayNeeded = (vNewCrewing) AND (NOT EQUIVALENT(o.PDPay, n.PDPay)) AND (n.PDPay = 0);
    SET vTravelPayNeeded = (vNewCrewing) AND (NOT EQUIVALENT(o.TravelPay, n.TravelPay)) AND (n.TravelPay = 0);
    SET vOvertimePayNeeded = (vNewCrewing) AND (NOT EQUIVALENT(o.OvertimePay, n.OvertimePay)) AND (n.OvertimePay = 0);
//    SET vAccommodationPayNeeded = ((vNewCrewing) AND (NOT EQUIVALENT(o.AccommodationPay, n.AccommodationPay)));

    IF  vOldTotalPayNeeded  THEN  -- setting CrewPay back to zero so remove expenditure
      DELETE FROM JobFinances WHERE xCostCentreID = n.IDX  AND xGeneralCostCentre = 1 AND SubCostCentre = 0 AND IsIncome = FALSE;
    END IF;
    IF vLabourPayNeeded THEN  -- setting CrewPay back to zero so remove expenditure
      DELETE FROM JobFinances WHERE xCostCentreID = n.IDX  AND xGeneralCostCentre = 1 AND SubCostCentre = 1 AND IsIncome = FALSE;
    END IF;
    IF vPDPayNeeded THEN  -- setting CrewPay back to zero so remove expenditure
      DELETE FROM JobFinances WHERE xCostCentreID = n.IDX  AND xGeneralCostCentre = 1 AND SubCostCentre = 2 AND IsIncome = FALSE;
    END IF;
    IF vTravelPayNeeded THEN  -- setting CrewPay back to zero so remove expenditure
      DELETE FROM JobFinances WHERE xCostCentreID = n.IDX  AND xGeneralCostCentre = 1 AND SubCostCentre = 3 AND IsIncome = FALSE;
    END IF;
    IF vOvertimePayNeeded THEN  -- setting CrewPay back to zero so remove expenditure
      DELETE FROM JobFinances WHERE xCostCentreID = n.IDX  AND xGeneralCostCentre = 1 AND SubCostCentre = 4 AND IsIncome = FALSE;
    END IF;

    SET vOldTotalPayNeeded = (NOT vNewCrewing)  AND (n.TotalPay > 0) AND ((NOT EQUIVALENT(o.TotalPay, n.TotalPay)) OR (vNonFinancialChange));
    SET vLabourPayNeeded =  (vNewCrewing)  AND (n.LabourPay > 0) AND ((NOT EQUIVALENT(o.LabourPay, n.LabourPay)) OR (vNonFinancialChange));
    SET vPDPayNeeded = (vNewCrewing)  AND (n.PDPay > 0) AND ((NOT EQUIVALENT(o.PDPay, n.PDPay)) OR (vNonFinancialChange));
    SET vTravelPayNeeded = (vNewCrewing)  AND (n.TravelPay > 0) AND ((NOT EQUIVALENT(o.TravelPay, n.TravelPay)) OR (vNonFinancialChange));
    SET vOvertimePayNeeded = (vNewCrewing)  AND (n.OvertimePay > 0) AND ((NOT EQUIVALENT(o.OvertimePay, n.OvertimePay)) OR (vNonFinancialChange));

      -- note how we write Pay amounts to the JobFinances.QuotedPrice field, not ActualPrice, which is used for Order amounts
     IF vOldTotalPayNeeded THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 0 AND IsIncome = FALSE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, FALSE,  n.IDX, n.xStatus, vLastQuotedDate, n.TotalPay, CAST(NULL AS MONEY), GetCrewFunctionNameFromCrewHeaderID(n.Header), GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 0);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, FALSE, n.xStatus, vLastQuotedDate, n.TotalPay, CAST(NULL AS MONEY), GetCrewFunctionNameFromCrewHeaderID(n.Header), GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),0);
       END IF;
    END IF;
    IF vLabourPayNeeded THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 1 AND IsIncome = FALSE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, FALSE,  n.IDX, n.xStatus, vLastQuotedDate, n.LabourPay, CAST(NULL AS MONEY), 'Labour Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 1);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, FALSE, n.xStatus, vLastQuotedDate, n.LabourPay, CAST(NULL AS MONEY), 'Labour Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),1);
       END IF;
    END IF;
     IF vPDPayNeeded THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 2 AND IsIncome = FALSE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, FALSE,  n.IDX, n.xStatus, vLastQuotedDate, n.PDPay, CAST(NULL AS MONEY), 'PD Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 2);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, FALSE, n.xStatus, vLastQuotedDate, n.PDPay, CAST(NULL AS MONEY), 'PD Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),2);
       END IF;
    END IF;
    IF vTravelPayNeeded THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 3 AND IsIncome = FALSE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, FALSE,  n.IDX, n.xStatus, vLastQuotedDate, n.TravelPay, CAST(NULL AS MONEY), 'Travel Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 3);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, FALSE, n.xStatus, vLastQuotedDate, n.TravelPay, CAST(NULL AS MONEY), 'Travel Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),3);
       END IF;
    END IF;
    IF vOvertimePayNeeded THEN
       IF COALESCE((SELECT COUNT(*) FROM  JobFinances WHERE xGeneralCostCentre = 1 AND xCostCentreID = n.IDX AND SubCostCentre = 4 AND IsIncome = FALSE),0) = 0 THEN
          CALL CreateCrewJobFinanceRecord (n.Job_no, FALSE,  n.IDX, n.xStatus, vLastQuotedDate, n.OvertimePay, CAST(NULL AS MONEY), 'Overtime Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type), 4);
       ELSE
           CALL UpdateCrewJobFinanceRecord(n.IDX, FALSE, n.xStatus, vLastQuotedDate, n.OvertimePay, CAST(NULL AS MONEY), 'Overtime Pay', GetCrewTitleFromCrewHeaderID(n.Header) || ' - ' || GetCrewTypeTextFromID(n.Type),4);
       END IF;
    END IF;

    -- Jobs update
    IF o.QuoteCount <> n.QuoteCount then
       UPDATE Jobs SET LastQuotedCrew = (SELECT SUM(LastQuotedTotal) FROM Crew WHERE Job_no = n.Job_no  and Selected = TRUE) WHERE Jobno = n.Job_no ;
    END IF;

 ELSEIF DELETING  AND (o.Job_no IS NOT NULL) THEN
    DELETE FROM JobFinances
    WHERE
    xCostCentreID = o.IDX
    AND xGeneralCostCentre = 1;

    UPDATE Jobs SET LastQuotedCrew = (SELECT SUM(LastQuotedTotal)
    FROM Crew
    WHERE
    Job_no = o.Job_no
    AND Selected = TRUE)
    WHERE
    Jobno = o.Job_no ;
 END IF;

END;

