/* trCRMLeadsBEFORE */
CREATE TRIGGER trCRMLeadsBEFORE
BEFORE INSERT, UPDATE ON crmLeads
REFERENCING OLD AS o NEW AS n
BEGIN
-- TMyWork = (mwJobs, mwProjects , mwCRM) ;

DECLARE vUserID integer;
DECLARE vUserJobFound boolean;


SET vUserID = GetUserID();


  IF INSERTING THEN

    IF vUserID > -1 THEN
     INSERT INTO UserJobs
     (xUser, xMyWorkID, xMyWork)
     VALUES
     (vUserID, n.Idx, 2);

     SET n.createdby = vUserID;
    END IF;


  ELSEIF UPDATING THEN
// user jobs
   IF vUserID > -1 THEN
     SET  vUserJobFound =  (SELECT count(idx)  > 0 from UserJobs WHERE  xMyWorkID = o.IDX AND xUser = vUserID AND xMyWork = 2);

    IF vUserJobFound THEN
     UPDATE  UserJobs SET AccessDate = current_Timestamp WHERE xMyWorkID = o.idx AND xUser = vUserID AND xMyWork = 2;
    ELSE
     INSERT into UserJobs
    (xUser, xMyWorkID, xMyWork)
     VALUES
    (vUserID, o.IDX, 2);
    END IF;
   END IF;

   SET n.ModifiedDate = Current_Timestamp;

   // users again
     IF vUserID > -1 THEN
        SET n.ModifiedBy = vUserID;
     END IF;
  END IF;
END;

