/* trDefconBEFORE */
CREATE TRIGGER trDefconBEFORE
BEFORE INSERT, DELETE, UPDATE OF "Function" ON Defcon
REFERENCING OLD AS o NEW AS n
BEGIN
-- Function field is  TAvailabilityStatus = (asQuote = 1, asProvisional = 2, asConfirmed = 3);
  IF INSERTING THEN

    IF n."Function" IN (0,1,2) THEN
     SET n.DefCon_IDX = COALESCE((SELECT MIN(Defcon_idx) FROM Defcon),0) - 1 ;
    ELSE
     SET n.DefCon_IDX = COALESCE((SELECT MAX(Defcon_idx) FROM Defcon),0) + 1 ;
    END IF;

  ELSEIF UPDATING THEN
    IF o."Function" < 3 AND n."Function" >=3 THEN
      SIGNAL 'Cannot promote this function';
    END IF;

    IF o."Function" >= 3 AND n."Function" <3 THEN
      SIGNAL 'Cannot demote this function';
    END IF;

  ELSEIF DELETING THEN

    IF o.System THEN
      SIGNAL 'System Statuses cannot be deleted';
    END IF;

  END IF;
END;

