/* trDiaryBEFORE */
CREATE TRIGGER trDiaryBEFORE
BEFORE INSERT, DELETE, UPDATE ON Diary
REFERENCING OLD AS o NEW AS n
BEGIN

 DECLARE vUserID INT;
 DECLARE vCompletedStatus INT;

 SET vUserID = GetUserID();

 -- TEventStatus = (esNotDone, esInitiated, esOverdue, esCompleted);
 SET vCompletedStatus = 3;

  IF INSERTING THEN

     IF vUserID > -1 then
       SET n.xCreatedBy =vUserID;
     END IF;

     IF n.Status = vCompletedStatus AND o.Status < vCompletedStatus THEN
      SET n.xCompletedBy = vUserID;
      SET n.CompletedDate = Current_TimeStamp;
     END IF;

  ELSEIF UPDATING THEN

     IF vUserID > -1 then
      SET n.xModifiedby = vUserID;
     END IF;

     SET n.ModifiedDate = Current_Timestamp;

     IF n.Status = vCompletedStatus AND o.Status < vCompletedStatus THEN
      SET n.xCompletedBy = vUserID;
      SET n.CompletedDate = Current_TimeStamp;
     END IF;

     IF n.Status < vCompletedStatus AND o.Status = vCompletedStatus THEN
      SET n.xCompletedBy = NULL;
      SET n.CompletedDate = NULL;
     END IF;

  ELSEIF DELETING THEN
     IF o.Status = vCompletedStatus THEN
       SIGNAL 'Cannot delete Completed diary events';
     END IF;
  END IF;
END;

