/* trEmail_IncomingMatchesAFTER */
CREATE TRIGGER "trEmail_IncomingMatchesAFTER"
AFTER INSERT, UPDATE, DELETE ON Email_IncomingMatches

REFERENCING OLD AS o NEW AS n
BEGIN

-- Now Build Narrative as its too slow to build this on the fly using joins etc
DECLARE Narrative VARCHAR(255);
DECLARE FullNarrative TEXT;
DECLARE vEMail Integer;
IF INSERTING OR UPDATING THEN
SET vEmail = n.xemail;
ELSE
SET vEmail = o.xemail;
END IF;
DECLARE MatchCursor CURSOR FOR Select MatchNarrative from Email_IncomingMatches where xemail = vEmail;
SET FullNarrative = '';
OPEN MatchCursor;
TRY

FETCH FIRST FROM MatchCursor INTO Narrative;
WHILE @@FETCH_STATUS = 0 DO
  IF FullNarrative = '' then
  SET FullNarrative =  Narrative;
  ELSE
  SET FullNarrative = FullNarrative || chr(13) || chr(10) || Narrative;
  END IF;
  FETCH NEXT FROM MatchCursor INTO Narrative;
END WHILE;
CLOSE MatchCursor;

CATCH TRUE
  CLOSE MatchCursor;
  SIGNAL ERROR_MESSAGE;
END;

UPDATE Email_Incoming SET MatchNarrative = FullNarrative WHERE IDX = vEmail;

END;

/* trEmail_IncomingRecipientsAFTER */
CREATE TRIGGER "trEmail_IncomingRecipientsAFTER"
AFTER INSERT, UPDATE ON Email_IncomingRecipients
REFERENCING OLD AS o NEW AS n
WHEN ((n.rescan = FALSE) AND (n.DelayedRescan = FALSE))
BEGIN
Declare vEmail VarChar(255);
Declare vJobPeriod VarChar(3);
Declare vEMailDate TimeStamp;
Declare vInReplyTo VarChar(999);
Declare vMatches Integer;
Declare vIgnoreUserEmail Boolean;
Declare vIgnoreUserCC Boolean;
Declare vIgnoreUserReplyTo Boolean;

Set vJobPeriod = 7;
Set vEmail = (SELECT lower(Email) from EmailRecipients WHERE Idx = n.xRecipient);
Set vEmailDate = (SELECT SentDateTime from Email_Incoming WHERE Idx = n.xemail);
Set vInReplyTo = (SELECT lower(InReplyTo) from Email_Incoming WHERE Idx = n.xemail);
Set vMatches = (Select IMAP_Rules from Rules WHERE SiteID = 1);

SET vIgnoreUserEmail = Exists(SELECT Email from users where email = vEmail);
SET vIgnoreUserReplyTo = Exists(SELECT ReplyToEmailAddress from users where ReplyToEmailAddress = vEmail);
SET vIgnoreUserCC = Exists(SELECT ccEmailAddress from users where ccEmailAddress = vEmail);


--   TEmailSource = (esGeneral, esJobRecord, esCRMRecord, esNoteBookRecord, esCompanyAddressRecord, esPersonAddressRecord, esProjectRecord);
--   TContactType = (ctNone, ctAddress, ctJobs, ctLead);

--Firstly try and match an Outgoing Email  // 1
IF BITAND(vMatches, 1) = 1 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail,  B.EmailSourceType, EmailSourceIDX, 'mtOutGoingEMail', '[Email] ' + B.Subject
FROM EmailSentLog A
INNER JOIN
EmailSentMessages B
ON
A.XEmailID = B.Idx
WHERE  lower(A.MessageID) = vInReplyTo AND NOT A.MessageID IS NULL AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches E
 where E.xemail=n.xemail AND E.recordtype=B.EmailSourceType  AND xrecord = B.EmailSourceIDX);
END IF;

-- IF Email isn't one of ours or if we're NOT Ignoring ours

IF
NOT((BITAND(vMatches, 2) = 2) AND vIgnoreUserEmail)
AND
NOT((BITAND(vMatches, 4) = 4) AND vIgnoreUserCC)
AND
NOT((BITAND(vMatches, 8) = 8) AND vIgnoreUserReplyTo)
THEN

--Match Person Email Address   //16
IF BITAND(vMatches, 16) = 16 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esPersonAddressRecord', NameCounter, 'mtAddressBook', '[Person] ' + A.Fullname
FROM Name2 A
WHERE  lower(A.email) = vEmail AND NOT A.Email IS NULL AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esPersonAddressRecord' AND xrecord = A.NameCounter);
END IF;


-- // 32
IF BITAND(vMatches, 32) = 32 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esPersonAddressRecord', Person, 'mtCompanyContact', '[Company Contact] ' + B.Fullname
FROM Contacts A
INNER JOIN Name2 B
ON A.Person = B.NameCounter
WHERE lower(A.email) = vEmail AND NOT A.Email IS NULL AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esPersonAddressRecord' AND xrecord = A.Person);
END IF;

 --Match Company Email Address // 64
IF BITAND(vMatches, 64) = 64 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esCompanyAddressRecord', CompanyCounter, 'mtAddressBook', '[Company] ' + A.CompanyName
FROM Company A
WHERE lower(A.emailAddress) = vEmail AND NOT A.emailAddress IS NULL
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esCompanyAddressRecord' AND xrecord = A.CompanyCounter);
END IF;

-- // 128
IF BITAND(vMatches, 128) = 128 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esCompanyAddressRecord', Company, 'mtAssociatedCompany', '[Associated Company] ' + B.CompanyName
FROM Contacts A
INNER JOIN Company B
ON A.Company = B.CompanyCounter
WHERE lower(A.email) = vEmail AND NOT A.email IS NULL AND RecordType= 'ctAddress'
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esCompanyAddressRecord' AND xrecord = A.Company);
END IF;

 --Job Based Contact // 256
IF BITAND(vMatches, 256) = 256 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esJobRecord', JobNo, 'mtJobContact' ,'[Job Contact] ' + B.Job_Title
FROM Contacts A
INNER JOIN Jobs B
ON A.xlink = B.JobNo
WHERE lower(A.email) = vEmail AND NOT A.email IS NULL AND RecordType= 'ctJobs' AND
-- email date is after 7 days before the created date
(vEmailDate > B.CreatedDate - INTERVAL '7'  DAY) AND
-- email date is before 7 days after due back date
 (vEmailDate < B."Due Back" + INTERVAL '7'  DAY)
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esJobRecord' AND xrecord = B.JobNo);
END IF;

--job based client // 512
IF BITAND(vMatches, 512) = 512 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esJobRecord', Jobno, 'mtJobsClient','[Job Client] ' + A.Job_Title
FROM Jobs A
INNER JOIN Company B
ON A.Client = B.CompanyCounter
WHERE lower(B.emailAddress) = vEmail AND NOT B.emailAddress IS NULL AND
-- email date is after 7 days before the created date
(vEmailDate > A.CreatedDate - INTERVAL '7'  DAY) AND
-- email date is before 7 days after due back date
 (vEmailDate < A."Due Back" + INTERVAL '7'  DAY)
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esJobRecord' AND xrecord = A.JobNo);
END IF;


--job based venue // 1024
IF BITAND(vMatches, 1024) = 1024 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esJobRecord', Jobno, 'mtJobsVenue','[Job Venue] ' + A.Job_Title
FROM Jobs A
INNER JOIN Eqlists E
ON E.Job_no = A.Jobno
INNER JOIN Company B
ON E.Venue_no = B.CompanyCounter
WHERE lower(B.emailAddress) = vEmail AND NOT B.emailAddress IS NULL AND
-- email date is after 7 days before the created date
(vEmailDate > A.CreatedDate - INTERVAL '7'  DAY) AND
-- email date is before 7 days after due back date
 (vEmailDate < A."Due Back" + INTERVAL '7'  DAY)
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esJobRecord' AND xrecord = A.JobNo);
END IF;

--job based crew //2048
IF BITAND(vMatches, 2048) = 2048 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esJobRecord', Jobno, 'mtJobsCrew','[Job Crew] ' + A.Job_Title
FROM Jobs A
INNER JOIN Crew C
ON C.Job_no = A.Jobno
INNER JOIN CrewJobs J
ON J.JobRef = C.Idx
INNER JOIN Name2 B
ON J.CrewRef = B.NameCounter
WHERE lower(B.email) = vEmail AND NOT B.email IS NULL AND
-- email date is after 7 days before the created date
(vEmailDate > A.CreatedDate - INTERVAL '7'  DAY) AND
-- email date is before 7 days after due back date
 (vEmailDate < A."Due Back" + INTERVAL '7'  DAY)
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esJobRecord' AND xrecord = A.JobNo);
END IF;

--CRM Company
--CRMLead = xCompany // 4096
IF BITAND(vMatches, 4096) = 4096 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esCRMRecord', Idx, 'mtLeadProspect', '[Lead] ' + A."Description"
FROM CRMLeads A
INNER JOIN Company B
ON A.xCompany = B.CompanyCounter
WHERE lower(B.emailAddress) = vEmail AND NOT B.emailAddress IS NULL AND
-- email date is after 7 days before the created date
(vEmailDate > A.CreationDate - INTERVAL '7'  DAY) AND
-- email date is before 7 days after due back date
 (vEmailDate < Cast(A.TargetDate + INTERVAL '7'  DAY as TimeStamp))
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esCRMRecord' AND xrecord = A.Idx);
END IF;

--CRM Contacts //8192
IF BITAND(vMatches, 8192) = 8192 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esCRMRecord', Idx, 'mtLeadContact', '[Lead Contact] ' + B."Description"
FROM Contacts A
INNER JOIN CRMLeads B
ON A.xlink = B.xCompany
WHERE lower(A.email) = vEmail AND NOT A.email IS NULL AND RecordType= 'ctLeads' AND
-- email date is after 7 days before the created date
(vEmailDate > B.CreationDate - INTERVAL '7'  DAY) AND
-- email date is before 7 days after due back date
 (vEmailDate < Cast(B.TargetDate + INTERVAL '7'  DAY as TimeStamp))
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esCRMRecord' AND xrecord = B.Idx);
END IF;

--Project
--proj_xvenue //16384
IF BITAND(vMatches, 16384) = 16384 THEN
INSERT INTO Email_IncomingMatches (xemail, recordtype, xrecord, MatchType, MatchNarrative)
SELECT DISTINCT n.xemail, 'esProjectRecord', Idx, 'mtProjectVenue','[Project Venue] ' + A.Proj_Name
FROM Project A
INNER JOIN Company B
ON A.proj_xvenue = B.CompanyCounter
WHERE lower(B.emailAddress) = vEmail AND NOT B.emailAddress IS NULL AND
-- email date is after 7 days before the created date
(vEmailDate > A.Created - INTERVAL '7'  DAY) AND
-- email date is before 7 days after due back date
 (vEmailDate < Cast(A.Proj_End + INTERVAL '7'  DAY as TimeStamp))
AND
 NOT EXISTS
 (Select idx from Email_IncomingMatches
 where xemail=n.xemail AND recordtype= 'esProjectRecord' AND xrecord = A.Idx);
END IF;

END IF; -- -- IF Email isn't one of ours or if we're NOT Ignoring ours
END;

