/* trEmailAddressWarehouseAfter */
CREATE TRIGGER "trEmailAddressWarehouseAfter"
AFTER INSERT,  UPDATE ON "EmailAddressWarehouse"
REFERENCING OLD AS o NEW AS n
-- 'Any Email address change in other tables will update the EmailAddressWarehouse which will set the DelayeRescan flag so the Email service can re_match incoming emails'

WHEN (NOT EQUIVALENT(o.Email , n.Email))
BEGIN
Declare vEmail VarChar(255);
Set VEmail = n.Email; --without the variable the query uses the wrong index
UPDATE Email_IncomingRecipients I
SET   DelayedRescan = True
  WHERE
  I.Xrecipient IN
  (SELECT Idx FROM EMailRecipients E WHERE E.Email = VEmail);
END;

