/* trEqlistAFTER */
CREATE TRIGGER "trEqlistAFTER"
AFTER UPDATE of DateOut, DateBack, PrepDate, CheckInDate, PrepAvail, CheckinAvail, xPrepBay, Eql_Name, Defcon ON Eqlists
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vStartDate TIMESTAMP;
  DECLARE vEndDate TIMESTAMP;
  DECLARE vDateStartDiff DOUBLE PRECISION;
  DECLARE vDateEndDiff DOUBLE PRECISION;
  DECLARE vFlippingAvailStartDate BOOL;
  DECLARE vFlippingAvailEndDate BOOL;
  DECLARE vEqlID INT;

  SET vFlippingAvailStartDate = NOT EQUIVALENT(o.PrepAvail, N.PrepAvail);
  SET vFlippingAvailEndDate = NOT EQUIVALENT(o.CheckInAvail, N.CheckInAvail);


  -- loans
    IF (NOT EQUIVALENT(N.defcon , O.Defcon)) AND (n.ListType = 0) THEN

     SET vEqlID = n.eql_no;

     UPDATE Eqlists SET
     defcon = n.defcon
     WHERE
     eql_no IN (SELECT E.eql_no
                 FROM Eqlists E
                 WHERE
                 E.xTransferToList = vEqlID
                 AND E.Defcon < 4);
    END IF;


  IF N.PrepAvail THEN
   SET vStartDate = N.PrepDate;

   IF vFlippingAvailStartDate THEN
    SET vDateStartDiff = CAST(o.DateOut AS DOUBLE PRECISION) - CAST(n.PrepDate AS DOUBLE PRECISION);
   ELSE
    SET vDateStartDiff = CAST(o.PrepDate AS DOUBLE PRECISION) - CAST(n.PrepDate AS DOUBLE PRECISION);
   END IF;

  ELSE
   SET vStartDate = N.DateOut;

   IF vFlippingAvailStartDate THEN
    SET vDateStartDiff = CAST(o.PrepDate AS DOUBLE PRECISION) - CAST(n.DateOut AS DOUBLE PRECISION);
   ELSE
    SET vDateStartDiff = CAST(o.DateOut AS DOUBLE PRECISION) - CAST(n.DateOut AS DOUBLE PRECISION);
   END IF;

  END IF; --IF N.PrepAvail THEN

  IF N.CheckInAvail THEN
   SET vEndDate = N.CheckInDate;

   IF vFlippingAvailEndDate THEN
    SET vDateEndDiff = CAST(n.CheckInDate AS DOUBLE PRECISION) - CAST(o.DateBack AS DOUBLE PRECISION);
   ELSE
    SET vDateEndDiff = CAST(n.CheckInDate AS DOUBLE PRECISION) - CAST(o.CheckInDate AS DOUBLE PRECISION);
   END IF;

  ELSE
   SET vEndDate = N.DateBack;

   IF vFlippingAvailEndDate THEN
     SET vDateEndDiff = CAST(o.DateBack AS DOUBLE PRECISION) - CAST(n.CheckInDate AS DOUBLE PRECISION);
   ELSE
     SET vDateEndDiff = CAST(n.DateBack AS DOUBLE PRECISION) - CAST(o.DateBack AS DOUBLE PRECISION);
   END IF;

  END IF; --IF N.CheckInAvail THEN

 -- sync eqlist line dates
  UPDATE "sort" S  SET
     S.D1 = vStartDate,
     S.D2 = vEndDate
  WHERE
     S.eqlno = o.Eql_no
  AND S.Virt = FALSE;

  -- deal with linked loan lists.
  IF N.ListType = 0 THEN --TWarehouseActivity
   UPDATE Eqlists E SET
     E.PrepDate = CAST(CAST(E.PrepDate AS DOUBLE PRECISION) - vDateStartDiff AS TIMESTAMP),
     E.DateOut = CAST(CAST(E.DateOut AS DOUBLE PRECISION) - vDateStartDiff AS TIMESTAMP),
     E.DateBack = CAST(CAST(E.DateBack AS DOUBLE PRECISION) + vDateEndDiff AS TIMESTAMP),
     E.CheckInDate = CAST(CAST(E.CheckInDate AS DOUBLE PRECISION) + vDateEndDiff AS TIMESTAMP)
   WHERE
   E.xTransferToList = N.Eql_no;
  END IF;

 -- PrepBays
   IF NOT EQUIVALENT(o.xPrepBay,n.xPrepBay) AND (n.xPrepBay IS NULL) THEN
      CALL SetPrepBayStatuses(o.xPrepBay);
   END IF;

 -- job loans. If changing eq ref of borrowing list then update the ref of the donor list so Planner makes sense
  IF (NOT EQUIVALENT(o.Eql_Name,n.Eql_Name)) AND (n.ListType = 0) THEN

    UPDATE Eqlists E SET
    E.Eql_Name = GetJobLoanEqRef(n.Eql_no)
    WHERE
    E.xTransferToList = n.Eql_no;

  END IF;

END;

/* trEqlistIncQuote */
CREATE TRIGGER trEqlistIncQuote
AFTER UPDATE OF SELECTED ON Eqlists
REFERENCING OLD AS o NEW AS n
BEGIN

 DECLARE cUpdateCrew BOOL;
 DECLARE cUpdateTransport BOOL;

 SET cUpdateCrew = COALESCE((SELECT CAST(VALUE AS Boolean) FROM USERSETTINGS U WHERE Section = 'trEqlistIncQuote' AND KEY = 'cUpdateCrew' AND U."USER" = 'GLOBAL'), TRUE) ;
 SET cUpdateTransport = COALESCE((SELECT CAST(VALUE AS Boolean) FROM USERSETTINGS U WHERE Section = 'trEqlistIncQuote' AND KEY = 'cUpdateTransport' AND U."USER" = 'GLOBAL'), TRUE);
 -- sync crew
 IF cUpdateCrew THEN

    SELECT ce.CrewRef
    INTO #CrewUpdates
    FROM CrewEqlNew ce
    WHERE
    ce.Eqlno = n.Eql_no;

    UPDATE
    Crew c
    SET
    c.Selected = n.Selected
    WHERE
    c.IDX IN (SELECT CrewRef FROM #CrewUpdates);

 END IF;
 -- sync transport
 IF cUpdateTransport THEN

    SELECT te.TransportRef
    INTO #TransportUpdates
    FROM TransEqlNew te
    WHERE
    te.Eqlno = n.Eql_no;

    UPDATE
    Tranplan t
    SET
    t.SELECTED = n.Selected
    WHERE
    t.TransportCounter IN (SELECT TransportRef FROM #TransportUpdates);

 END IF;

END;

/* trEqlistMarkUps */
CREATE TRIGGER trEqlistMarkUps
BEFORE DELETE, UPDATE ON EqlistMarkUps
REFERENCING OLD AS o NEW AS n
BEGIN
  IF UPDATING THEN
    --check if its invoiced
    IF n.Amount < 0 THEN
       IF n.Amount >  n.InvoicedTotal THEN
          SIGNAL 'This line has already been negatively invoiced for more than the new line price.';
       END IF;
    ELSE
        IF n.Amount <  n.InvoicedTotal THEN
           SIGNAL 'This line has already been invoiced for more than the new line price.';
        END IF;
    END IF;

  ELSEIF DELETING THEN
    -- block deleting if invoiced
      IF o.InvoicedTotal > 0 THEN
        SIGNAL 'This markup line has already been invoiced and cannot be deleted.';
      END IF;
  END IF;
END;

/* trEqlistsAFTERDelete */
CREATE TRIGGER "trEqlistsAFTERDelete"
AFTER DELETE  ON Eqlists
REFERENCING OLD AS o NEW AS n
BEGIN

   -- Note how there is no RI onEqlist for clearing down sort because the trSortBEFORE trigger manages the clearing of VIRT lines
   DELETE FROM "sort" S WHERE S.eqlno = o.eql_no and S.Virt = FALSE;

END;

/* trEqlistsAFTERtag */
CREATE TRIGGER trEqlistsAFTERtag
AFTER INSERT, DELETE, UPDATE OF venue_no, client_no, job_no ON eqlists
REFERENCING OLD AS o NEW AS n
BEGIN
IF DELETING THEN
  CALL DoTags('Eqlists', o.Eql_no);
ELSE
  CALL DoTags('Eqlists', n.Eql_no);
END IF;
END;

/* trEqlistsBefore */
CREATE TRIGGER "trEqlistsBefore"
BEFORE INSERT, DELETE, UPDATE  ON Eqlists
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;
  DECLARE vMinMinutes INT;

  SET vUserID = GetUserID();

  IF NOT DELETING THEN

    -- deal with Client_name;
    IF NOT EQUIVALENT(n.Client_no, o.Client_no) THEN
      SET n.Client_Name = (SELECT c.CompanyName
                           FROM Company c
                           WHERE
                           c.CompanyCounter = n.Client_no);
    END IF;

    -- deal with Venue
   IF NOT EQUIVALENT(n.Venue_no, o.Venue_no) THEN

     DECLARE vDelAddExists boolean;

     -- store single record in memory table for efficiency
     SELECT * INTO #tmp
     FROM Company
     WHERE CompanyCounter = n.Venue_no;

     SET n.Venue_name =(SELECT CompanyName FROM #tmp);
     SET n.Venue_Telephone = (SELECT MainTelephone FROM #tmp);
     SET n.Venue_Facsimile = (SELECT MainFax FROM #tmp);

     IF n.ListType IN (1,2) THEN -- subhires
      SET n.Discount = GetClientDiscount(n.Venue_no, TRUE, n.EqlistClass);
     END IF;

     -- is there a Delivery address assigned
     SET vDelAddExists = (SELECT DelAdd1<> '' FROM #tmp);

     IF vDelAddExists THEN
      SET n.Venue_addr1 = (SELECT DelAdd1 FROM #tmp);
      SET n.Venue_addr2 = (SELECT DelAdd2 FROM #tmp);
      SET n.Venue_addr3 = (SELECT DelAdd3 FROM #tmp);
      SET n.Venue_town = (SELECT DelTown FROM #tmp);
      SET n.Venue_postcode = (SELECT DelPostCode FROM #tmp);
      SET n.Venue_County = (SELECT DelCounty FROM #tmp);
      SET n.Venue_Country = (SELECT DelCountry FROM #tmp);
     ELSE
      SET n.Venue_addr1 = (SELECT Address1 FROM #tmp);
      SET n.Venue_addr2 = (SELECT Address2 FROM #tmp);
      SET n.Venue_addr3 = (SELECT Address3 FROM #tmp);
      SET n.Venue_town = (SELECT Town FROM #tmp);
      SET n.Venue_postcode = (SELECT PostCode FROM #tmp);
      SET n.Venue_County = (SELECT County FROM #tmp);
      SET n.Venue_Country = (SELECT Country FROM #tmp);
     END IF;
   END IF; --VENUE

   -- For LOANS we need to result the Leaves (PrepDate) and Back (CheckInDate) if the warehouses are changed

   IF (N.ListType IN (3, 4)) AND (n.xTransferInWarehouse < 1) THEN
    SIGNAL 'Invalid destination warehouse specified for a loan';
   END IF;

   IF (N.ListType IN (3, 4)) AND ((NOT EQUIVALENT(n.MainSite,o.MainSite)) OR
      (NOT EQUIVALENT(n.xTransferInWarehouse,o.xTransferInWarehouse))) THEN

    SET vMinMinutes = (SELECT Hours * 60
                       FROM
                       WarehouseTransitTimes
                       WHERE
                       WarehouseFrom =  n.MainSite
                       AND WarehouseTo = n.xTransferInWarehouse);

    IF vMinMinutes = 0 THEN
      SET vMinMinutes = 10; -- min time for availability to make a difference
    END IF;

    SET n.PrepDate = CAST(CAST(n.DateOut AS DOUBLE PRECISION) - CAST(vMinMinutes / 1440 AS DOUBLE PRECISION) AS DATETIME);
    SET n.CheckInDate = CAST(CAST(n.DateBack AS DOUBLE PRECISION) + CAST(vMinMinutes / 1440 AS DOUBLE PRECISION) AS DATETIME);

   END IF; -- Loan


  END IF;  -- NOT DELETING

  IF INSERTING THEN

    IF vUserID > -1 then
     SET n.createdby = vUserID;
    END IF;

    -- auto set Print Order field
    IF n.ListType = 0 THEN
       SET n.SortOrder = COALESCE((SELECT MAX(SortOrder) FROM Eqlists WHERE Job_no = n.Job_no AND n.ListType = 0 ),0) + 1;
    END IF;

  ELSEIF UPDATING THEN

   IF vUserID > -1 then
     SET n.modIFiedby = vUserID;
   END IF;

   SET n.ModDate  = CURRENT_TIMESTAMP;

   -- check dispatches for warehouse change
   IF (NOT EQUIVALENT(n.MainSite , o.MainSite)) AND (EqlistIsPrepped(n.Eql_no)) THEN
     SIGNAL 'Cannot change booking warehouse once a list has a ' || GetWarehouseStageText(n.ListType,n.EqlistClass,1, FALSE) || ' Note assigned. Remove the Note in order to make this change.';
   END IF;

   IF NOT EQUIVALENT(n.Defcon , o.DefCon) THEN

     -- check dispatches for status change
     IF (n.Defcon < o.DefCon ) AND (EqlistIsPrepped(n.Eql_no)) AND (N.Defcon < 4) THEN
      SIGNAL 'Cannot demote status of ' || n.Eql_Name || ' below Active once a list has a ' || GetWarehouseStageText(n.ListType,n.EqlistClass,1, FALSE) || ' Note assigned. Remove the Note in order to make this change.';
     END IF;

     -- if subhire and allocations assigned then block demotion
     IF (n.ListType IN (1,2)) AND (n.EqlistClass = 0) THEN
       IF (n.Defcon < 3) AND
          (SELECT COUNT(*)
           FROM SubData
           WHERE
           SubListno = N.Eql_NO) > 0 THEN

         SIGNAL 'Cannot demote status of a Subhire once line allocations have been made';
       END IF;
     END IF;

     -- Status Sync with Lines  Job status
     UPDATE "Sort" S SET
     S.Defcon = n.Defcon
     WHERE
     S.eqlno = n.Eql_no
     AND S.Virt = FALSE ;

     IF (GetStatusFunction(n.Defcon) > GetStatusFunction(GetJobStatus(n.job_no)))
     OR ((GetStatusFunction(n.Defcon) = GetStatusFunction(GetJobStatus(n.job_no))) AND (n.Defcon > GetJobStatus(n.job_no)))  THEN
        UPDATE Jobs J SET
        J.status = n.Defcon
        WHERE
        J.Jobno = n.job_no;
     END IF;

     IF N.defcon < 3 THEN
      SET n.xPrepBay = NULL;
     END IF;

   END IF;

   -- changine warehouse
   IF NOT EQUIVALENT(n.MainSite , o.MainSite) THEN
   -- remove loans
     DELETE FROM "SORT"
     WHERE Eqlno =
        (SELECT eql_no
         FROM eqlists
         WHERE
         xTransferToList = n.eql_no)
         AND  Virt = FALSE;

     UPDATE "Sort" S SET
      S.LoansInQty = 0,
      Slink1 =n.MainSite
      WHERE
      Eqlno = n.eql_no;
   END IF;

   -- changing borrowing list in Global Loans
   IF NOT EQUIVALENT(n.xTransferInWarehouse , o.xTransferInWarehouse) THEN
    UPDATE "Sort" S SET
     xTransferInWarehouse = n.xTransferInWarehouse
    WHERE
     eqlno = n.eql_no;
   END IF;

-- Deleting
  ELSEIF DELETING THEN

   IF EqlistIsPrepped(o.Eql_no) THEN
     IF o.ListType <> 3 THEN
       SIGNAL 'You cannot delete a list once a ' || GetWarehouseStageText(o.ListType,o.EqlistClass,1, FALSE) || ' Note has been assigned. Remove the Note in order to make this change.';
     ELSE
       SIGNAL 'Clearing Assigned Loans: you cannot delete list ' + o.Eql_Name + ' once a ' || GetWarehouseStageText(o.ListType,o.EqlistClass,1, FALSE) || ' Note has been assigned. Remove the Note in order to make this change.';
     END IF;
   END IF;

   IF o.ListType = 0 THEN

     -- remove any internal costs from Costs.nx1

     /* TInternalCostCentre = (iccNone = 0, iccPayment = 1, iccEqUsage = 2, iccPrep = 3, iccTransport = 4, iccGlobalPurchaseOrderAllocation = 5, iccCustomSurchage = 6,
    iccVenueCommission = 7,
    iccEqCommisson, iccEqSubCommission, iccCrewCommisson, iccCrewSubCommission, iccTransportCommisson, iccTransportSubCommission, iccCostsCommisson, iccCostsSubCommission,
    iccCostOfSale, iccExtraRentalCosts, iccAnticipatedSubhireCosts=18);*/

    DELETE FROM Costs
    WHERE
    xJob = o.Job_no
    AND xCostCentreID = o.Eql_no
    AND xInternalCostCentre IN (2,3,16,17,18);


     IF o.ExtensionType IN (2,3) THEN --an extension list
      -- clean up subdata.
        UPDATE SubData D SET
        D.EqlLine = (SELECT S.xTransferToLine FROM Sort S WHERE S.LineRef = D.EqlLine)
        WHERE
        D.EqlLine IN (SELECT LineRef FROM Sort WHERE Eqlno = o.Eql_no);

     END IF;

     IF o.ExtensionType = 0 THEN -- not an extension list
        DELETE FROM Eqlists
        WHERE
        xTransferToList = O.Eql_no;
     ELSE
        UPDATE Eqlists SET
         xTransferToList = NULL
        WHERE
         xTransferToList = O.Eql_no;
     END IF;
   END IF;

  END IF;

END;

/* trEqlistTotalsAFTER */
CREATE TRIGGER trEqlistTotalsAFTER
AFTER  INSERT, DELETE, UPDATE OF LastQuotedTotal, Total, Defcon, Eql_name, Eql_Title ON Eqlists
REFERENCING OLD AS o NEW AS n
BEGIN

/*
 TGeneralCostCentre = (gccEquipment =0, gccCrew =1, gccTransport = 2, gccMisc = 3);

  TInternalCostCentre = (iccNone = 0, iccPayment = 1, iccEqUsage = 2, iccPrep = 3, iccTransport = 4, iccGlobalPurchaseOrderAllocation = 5, iccCustomSurchage = 6,
    iccVenueCommission = 7,
    iccEqCommisson, iccEqSubCommission, iccCrewCommisson, iccCrewSubCommission, iccTransportCommisson, iccTransportSubCommission, iccCostsCommisson, iccCostsSubCommission,
    iccCostOfSale, iccExtraRentalCosts, iccAnticipatedSubhireCosts=18);
*/

 DECLARE vIsIncome Boolean;
 DECLARE vEqlID Integer;
 DECLARE vLastQuotedDate Timestamp;
 DECLARE vListType BYTE;
 DECLARE vEqlistClass BYTE;
 DECLARE vCostOfSaleText VARCHAR(50);

 -- QuoteDate
 IF NOT EQUIVALENT(o.QuoteCount , n.QuoteCount) THEN
   SET vLastQuotedDate = Current_TimeStamp;
 ELSE
   SET vLastQuotedDate = NULL;
 END IF;

 -- initalize VARS depending on Deleting status
 IF DELETING THEN
  SET vEqlID = o.Eql_No;
  SET vIsIncome =  o.ListType IN (0);
  SET vEqlistClass = o.EqlistClass;
  SET vListType = o.ListType;
 ELSE
  SET vEqlID = n.Eql_No;
  SET vIsIncome = n.ListType IN (0);
  SET vEqlistClass = n.EqlistClass;
  SET vListType = n.ListType;
 END IF;

 IF vEqlistClass = 1 THEN
   SET vCostOfSaleText = 'Sales Costs';
 ELSE
   SET vCostOfSaleText = 'Prep, Usage or Anticipated Costs';
 END IF;

-- clean up old Sales Orders that have generated costs on a job.
/* IF  (vEqlistClass = 1 AND vListType IN (1)) THEN
             DELETE FROM JobFinances
             WHERE
             xCostCentreID = o.Eql_no
             AND IsIncome = FALSE
             AND xGeneralCostCentre = 0;
 END IF;
*/

 IF vListType IN (0,1) THEN -- Job Rentals, Job Subhires, Job Sales Lists Job Sales Orders only
-- main bit of code
  IF INSERTING THEN

    -- Job Finances
   IF vIsIncome THEN

    INSERT INTO JobFinances
    (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus, LastQuotedDate, QuotedPrice, ActualPrice, Reference, Title)
    VALUES
    (n.Job_no, vIsIncome, n.Eql_no, 0 , n.defcon,vLastQuotedDate, n.LastQuotedTotal, n.Total, n.Eql_name, n.Eql_Title);


   ELSE  -- EXPENDITURE

    IF (vEqlistClass = 1 AND vListType IN (1)) THEN -- Sales Order, so this is just a "placeholder" record that can get an ActualPrice when a PO is raise. No Quoted Price so as not to double add costs to predicted job totals etc
       INSERT INTO JobFinances
       (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus, LastQuotedDate, QuotedPrice,  Reference, Title)
       VALUES
       (n.Job_no, vIsIncome, n.Eql_no, 0 , n.defcon,vLastQuotedDate, 0,  n.Eql_name, n.Eql_Title);
    ELSE
       INSERT INTO JobFinances
       (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus, LastQuotedDate, QuotedPrice,  Reference, Title)
       VALUES
       (n.Job_no, vIsIncome, n.Eql_no, 0 , n.defcon,vLastQuotedDate, n.Total,  n.Eql_name, n.Eql_Title);

    END IF;

   END IF;

  ELSEIF UPDATING THEN

     IF vIsIncome THEN -- INCOME and Costs (not expenditure)

         UPDATE JobFinances SET
         xStatus = n.defcon,
         LastQuotedDate =
         CASE
         WHEN vLastQuotedDate IS NOT NULL THEN vLastQuotedDate
         ELSE
         LastQuotedDate
         END,
         QuotedPrice = n.LastQuotedTotal,
         ActualPrice = n.Total,
         Reference = n.Eql_name,
         Title = n.Eql_Title
         WHERE
         xCostCentreID = n.Eql_no and IsIncome = vIsIncome and xGeneralCostCentre = 0;

         --costs
         IF n.Costs > 0 THEN

           IF  NOT (SELECT COUNT(*) > 0
                    FROM JobFinances
                    WHERE
                    xCostCentreID = n.Eql_no
                    AND IsIncome = FALSE
                    AND xGeneralCostCentre = 0
                    AND xInternalCostCentre = 16) THEN

               INSERT INTO JobFinances
               (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xInternalCostCentre, xStatus, LastQuotedDate, QuotedPrice,  Reference, Title)
               VALUES
               (n.Job_no, FALSE, n.Eql_no    , 0                 , 16                  , n.defcon,vLastQuotedDate, n.Costs,  n.Eql_name, vCostOfSaleText);

            ELSE

                UPDATE JobFinances SET
                xStatus = n.defcon,
                LastQuotedDate =
                CASE
                WHEN vLastQuotedDate IS NOT NULL THEN vLastQuotedDate
                ELSE
                LastQuotedDate
                END,
                QuotedPrice = n.Costs,
                Reference = n.Eql_name,
                Title = vCostOfSaleText
                WHERE
                xCostCentreID = n.Eql_no
                AND IsIncome = FALSE
                AND xGeneralCostCentre = 0
                AND xInternalCostCentre = 16;

           END IF;

         END IF;

         IF n.Costs = 0 AND o.Costs > 0 THEN
             DELETE FROM JobFinances
             WHERE
             xCostCentreID = o.Eql_no
             AND IsIncome = FALSE
             AND xGeneralCostCentre = 0
             AND xInternalCostCentre = 16;
         END IF;

    ELSE   -- EXPENDITURE
           UPDATE JobFinances SET
           xStatus = n.defcon,
           LastQuotedDate =
           CASE
           WHEN vLastQuotedDate IS NOT NULL THEN vLastQuotedDate
           ELSE
           LastQuotedDate
           END,
           QuotedPrice = CASE WHEN vEqlistClass =  1 AND vListType = 1 THEN 0 ELSE n.Total END,
           Reference = n.Eql_name,
           Title = n.Eql_Title
           WHERE
           xCostCentreID = n.Eql_no and IsIncome = vIsIncome and xGeneralCostCentre = 0;
    END IF;


   IF vIsIncome THEN
    IF o.QuoteCount <> n.QuoteCount then
      UPDATE Jobs SET
      LastQuotedEquipment = (SELECT SUM(LastQuotedTotal)
                             FROM Eqlists
                             WHERE
                             Job_no = n.Job_no
                             AND Selected = TRUE)
      WHERE
      Jobno = n.Job_no ;
     END IF;
    END IF;

  ELSEIF DELETING THEN

    DELETE FROM JobFinances
    WHERE xCostCentreID = o.Eql_no
    AND xGeneralCostCentre = 0;

    DELETE FROM Costs
    WHERE
    xJob = o.Job_no
    AND xCostCentreID = o.Eql_no
    AND  xInternalCostCentre IN (2,3,16);

   IF vIsIncome THEN
      UPDATE Jobs SET
      LastQuotedEquipment = (SELECT SUM(LastQuotedTotal)
                             FROM Eqlists
                             WHERE
                             Job_no = o.Job_no
                             AND Selected = True)
      WHERE Jobno = o.Job_no ;
    END IF;
  END IF;

END IF;
END;

