/* trHetypeAFTER */
CREATE TRIGGER trHetypeAFTER
AFTER INSERT, DELETE, UPDATE OF EquipmentType, RoadCase, PrePack, Category ON Hetype
REFERENCING OLD AS o NEW AS n
BEGIN

 DECLARE vSiteCount BYTE;
 DECLARE vCounter BYTE;

 -- TEquipmentType = (etSimple, etCompositeKit, etAliasKit, etPricedAliasKit, etMarkup);
IF INSERTING AND n.EquipmentType IN (0,1) THEN

   SET vSiteCount = GetSiteCount();
   SET vCounter = 1;

   WHILE vCounter <= vSiteCount DO

   INSERT INTO Whlevel
   (TypeIDX, xSite)
   VALUES
   (n."Type", vCounter);

   SET vCounter = vCounter + 1;

   END WHILE;

 ELSEIF UPDATING THEN

  -- changing from composite to something else
  IF (o.EquipmentType = 1 AND n.EquipmentType <> 1) THEN

   DELETE FROM composit
   WHERE
   MasterType = o."Type";

   DELETE FROM Subcode
   WHERE
   MasterType = o."Type";

   SELECT LineRef
   INTO #Tmp
   FROM "Sort"
   WHERE
   "Type" = o."Type";


   DELETE FROM "Sort" s
   WHERE
    S.LineCode IN
    (SELECT LineRef
     FROM
     #Tmp)
    AND s.Virt = TRUE;

  END IF;

  -- changing from alias to something else
  IF (o.EquipmentType IN (2,3) AND  n.EquipmentType NOT IN (2,3)) THEN
    DELETE FROM related
    WHERE
    masterType = o."Type";

  END IF;

  -- changing from Simple Alias to Priced Alias
  IF o.EquipmentType = 2 AND  n.EquipmentType = 3 THEN
     UPDATE Related SET
     Charge = FALSE
     WHERE
     MasterType = n.Type;

  END IF;

  -- changing from Priced Alias to Simple Alias
  IF o.EquipmentType = 3 AND  n.EquipmentType = 2 THEN
     UPDATE Related SET
     Charge = TRUE
     WHERE
     MasterType = n.Type;

  END IF;

  --changing to Core Stock Type so add a record to Whlevel
  IF (o.EquipmentType > 1 and n.EquipmentType IN (0,1)) THEN

   SET vSiteCount = GetSiteCount();
   SET vCounter = 1;

   WHILE vCounter <= vSiteCount do

   IF (SELECT COUNT(*) = 0 FROM  Whlevel WHERE TypeIDX = n.Type AND xSite = vCounter) THEN

      INSERT INTO Whlevel
      (TypeIDX, xSite)
      VALUES
      (n."Type", vCounter);

   END IF;

   SET vCounter = vCounter + 1;

   END WHILE;
  END IF;

  --changing FROM Core Stock Type so delete Whlevel records
  IF (o.EquipmentType IN (0,1) AND n.EquipmentType > 1) THEN

   DELETE FROM Whlevel
   WHERE
   TypeIDX = n.Type;

  END IF;

  -- if changing Roadcase status and a Normal type write to composite table (unused Ratio2 field) to force trCompositeBefore to fire so that composite masters become Virtual Roadcases
  IF ((o.RoadCase <> n.RoadCase) OR (NOT EQUIVALENT(n.Category, o.Category) AND (n.Category = 1 OR o.Category = 1)))
       AND (n.EquipmentType < 1) THEN

    UPDATE Composit C SET
    C.Ratio2 = COALESCE(C.Ratio2,0) + 1
    WHERE
    C.ComponentType = n."Type";

  END IF;

   -- PrePacks
   IF NOT EQUIVALENT(n.PrePack, o.PrePack) AND (NOT n.PrePack) THEN

      DECLARE vType INT;
      SET vType = n.Type;

      DELETE FROM PrePackInstances
      WHERE
      xMasterItem IN (SELECT ItemRef FROM Item WHERE Type = vType);

   END IF;

  ELSEIF DELETING THEN

         UPDATE Hetype SET
         ToRental = NULL
         WHERE
         ToRental IS NOT NULL
         AND ToRental = o.Type;

         UPDATE Hetype SET
         ToConsumable = NULL
         WHERE
         ToConsumable IS NOT NULL
         AND ToConsumable = o.Type;

         UPDATE Hetype SET
         ToNewSales = NULL
         WHERE
         ToNewSales IS NOT NULL
         AND ToNewSales = o.Type;

         UPDATE Hetype SET
         ToExRentalSales = NULL
         WHERE
         ToExRentalSales IS NOT NULL
         AND ToExRentalSales = o.Type;

 END IF;

END;

/* trHeTypeAFTERtag */
CREATE TRIGGER trHeTypeAFTERtag
AFTER INSERT, DELETE, UPDATE OF pattest, xmanufacturer ON hetype
REFERENCING OLD AS o NEW AS n
BEGIN
IF DELETING THEN
  CALL DoTags('hetype', o."type");
ELSE
  CALL DoTags('hetype', n."type");
END IF;
END;

/* trHetypeBEFORE */
CREATE TRIGGER  "trHetypeBEFORE"
BEFORE INSERT, UPDATE  ON Hetype
REFERENCING OLD AS o NEW AS n
BEGIN

IF INSERTING THEN

   SET n.SortOrder = n."Type";

   IF n.DefNominal IS NULL THEN
     SET n.DefNominal = (
		SELECT DefaultRentalNominal
		FROM Rules
		WHERE siteID = 1
		);
   END IF;


ELSEIF UPDATING THEN

  IF (NOT EQUIVALENT(n.Category, o.Category)) AND (ExcecutingUnderHireTrack = False) THEN -- sort.xCat
    UPDATE "Sort" S SET
     S.XCat = n.Category
    WHERE
     S."Type" = o."Type"
    AND S.D1 > CURRENT_TIMESTAMP
    AND S.xCat = o.Category
    AND S.virt = FALSE
    AND S.NotBack = FALSE;
  END IF;

  --PrePackMode
  IF NOT EQUIVALENT(n.roadcase, o.roadcase) AND (n.roadcase = FALSE) THEN
    SET n.PrePack = FALSE;
  END IF;

  --PrePackMode
  IF NOT EQUIVALENT(n.PrePack, o.PrePack) AND (n.PrePack = TRUE AND n.roadcase = FALSE) THEN
    SIGNAL 'Pre-Pack can only be assigned to Roadcases';
  END IF;


  IF NOT EQUIVALENT(n.EquipmentType, o.EquipmentType) THEN -- cf. TEquipmentType do legacy values

    IF n.EquipmentType = 0 THEN
      SET n.virt = False;
      SET n."Alias" = False;
      SET n.UserT3 = 0;
    END IF;

    IF n.EquipmentType IN (1,2,3) THEN  -- cannot change Core Stock to anything else if there is an audit trail for it.
      IF (SELECT COUNT(*)
          FROM Audit A
          WHERE A.Type = n.Type) > 0 THEN

      SIGNAL 'Cannot change "Core Stock" ('|| n.Description||') to a different Eq Type if there is an audit trail (stock IN/OUT) for it.';

      END IF;

    END IF;

    IF n.EquipmentType = 1 THEN -- composite

      IF (o.EquipmentType = 0) AND (SELECT COUNT(*) > 0 FROM Composit WHERE ComponentType =  n.Type) THEN
         SIGNAL 'This Type is already part of one or more Composites so cannot be changed itself to a Composite';
      END IF;

      SET n.virt = True;
      SET n."Alias" = False;
      SET n.UserT3 = 0;
    END IF;

    IF n.EquipmentType = 2 THEN -- Alias
      SET n.virt = False;
      SET n."Alias" = True;
      SET n.UserT3 = 0;
    END IF;

    IF n.EquipmentType = 3 THEN -- Priced Alias
      SET n.virt = False;
      SET n."Alias" = True;
      SET n.UserT3 = 1;
    END IF;

    IF n.EquipmentType > 3 THEN -- Markup
      SET n.virt = False;
      SET n."Alias" = True;
    END IF;

  END IF;


  -- Barcodes AND TypeCodes
  IF NOT EQUIVALENT(n.shortcode , o.shortcode) AND  (COALESCE( n.shortcode,'') <> '')  THEN

   DECLARE vTypeCodeCount INT;
   DECLARE vBarcodeCount INT;

   SET vTypeCodeCount = (
		SELECT count(shortcode)
		FROM hetype
		WHERE upper(shortcode) = upper(n.shortcode)
		);


    IF vTypeCodeCount > 0 THEN
     SIGNAL 'This TypeCode is already in use. Please cancel or enter a different code';
    ELSE
     SET vBarcodeCount = (
		SELECT count(barcode) AS dup
		FROM item
		WHERE upper(barcode) = upper(n.shortcode)
		);

     IF vBarcodeCount > 0 THEN
       SIGNAL  'This TypeCode is in use as a Barcode. Please cancel or enter a different code';
     END IF;

    END IF; --vTypeCodeCount
  END IF; --shortcode

   -- discount

   IF  NOT EQUIVALENT(n.MaxDiscount, o.MaxDiscount) THEN

     IF n.MaxDiscount > 100 THEN
      SET n.MaxDiscount = 100;
     END IF;

     IF n.MaxDiscount < 0 THEN
      SET n.MaxDiscount = 0;
     END IF;

   END IF;

  -- replacment updates

  DECLARE vAutoCalcReplaceValues BOOLEAN;

  SET vAutoCalcReplaceValues = (
		SELECT AutoCalcReplaceValues
		FROM Rules
		WHERE siteID = 1
		);


  IF vAutoCalcReplaceValues THEN

   IF NOT EQUIVALENT(n.Replacement, o.Replacement) THEN
    IF  EQUIVALENT(n.Replacement2, o.Replacement2) THEN
     SET n.Replacement2 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 2),n.Replacement2 );
    END IF;
    IF  EQUIVALENT(n.Replacement3, o.Replacement3) THEN
     SET n.Replacement3 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 3),n.Replacement3 );
    END IF;
    IF  EQUIVALENT(n.Replacement4, o.Replacement4) THEN
     SET n.Replacement4 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 4),n.Replacement4 );
    END IF;
   END IF;

   IF NOT EQUIVALENT(n.Replacement2 , o.Replacement2) THEN
    IF  EQUIVALENT(n.Replacement2, o.Replacement2) THEN
     SET n.Replacement = COALESCE(n.Replacement2 / (SELECT ExchangeRate FROM currency WHERE Scheme = 2),n.Replacement);
    END IF;
    IF  EQUIVALENT(n.Replacement3, o.Replacement3) THEN
     SET n.Replacement3 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 3),n.Replacement3 );
    END IF;
    IF  EQUIVALENT(n.Replacement4, o.Replacement4) THEN
     SET n.Replacement4 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 4),n.Replacement4 );
    END IF;
   END IF;

   IF NOT EQUIVALENT(n.Replacement3 , o.Replacement3) THEN
    IF  EQUIVALENT(n.Replacement2, o.Replacement2) THEN
     SET n.Replacement = COALESCE(n.Replacement3 / (SELECT ExchangeRate FROM currency WHERE Scheme = 2),n.Replacement );
    END IF;
    IF  EQUIVALENT(n.Replacement3, o.Replacement3) THEN
     SET n.Replacement2 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 3),n.Replacement2 );
    END IF;
    IF  EQUIVALENT(n.Replacement4, o.Replacement4) THEN
     SET n.Replacement4 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 4),n.Replacement4 );
    END IF;
   END IF;

   IF NOT EQUIVALENT(n.Replacement4 , o.Replacement4) THEN
    IF  EQUIVALENT(n.Replacement2, o.Replacement2) THEN
     SET n.Replacement = COALESCE(n.Replacement4 / (SELECT ExchangeRate FROM currency WHERE Scheme = 2),n.Replacement );
    END IF;
    IF  EQUIVALENT(n.Replacement3, o.Replacement3) THEN
     SET n.Replacement2 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 3),n.Replacement2 );
    END IF;
    IF  EQUIVALENT(n.Replacement4, o.Replacement4) THEN
     SET n.Replacement3 = COALESCE(n.Replacement * (SELECT ExchangeRate FROM currency WHERE Scheme = 4),n.Replacement3 );
    END IF;
   END IF;

  END IF; --vAutoCalcReplaceValues

END IF;
END;

/* trHetypeCompositeSync */
CREATE TRIGGER trHetypeCompositeSync
AFTER UPDATE OF Weight, Replacement, Replacement2, Replacement3, Replacement4 ON Hetype
REFERENCING OLD AS o NEW AS n
WHEN (n.EquipmentType = 0) -- only fire for Normal types
BEGIN

DECLARE cCompositeIDs CURSOR FOR
 SELECT MasterType
 FROM Composit
 WHERE
 ComponentType = n.Type;

DECLARE vCompositeID INT;

OPEN cCompositeIDs;
 FETCH FIRST FROM cCompositeIDs INTO vCompositeID;

WHILE @@FETCH_STATUS = 0 DO

-- Weights
 IF NOT EQUIVALENT(o.Weight, n.Weight) THEN
 CALL SetCompositeValueFromComponents(vCompositeID,0);
 END IF;

-- Replacements
 IF (NOT EQUIVALENT(o.Replacement, n.Replacement)) OR (NOT EQUIVALENT(o.Replacement2, n.Replacement2)) OR (NOT EQUIVALENT(o.Replacement3, n.Replacement3)) OR (NOT EQUIVALENT(o.Replacement4, n.Replacement4)) THEN
 CALL SetCompositeValueFromComponents(vCompositeID,1);
 END IF;

FETCH NEXT FROM cCompositeIDs INTO vCompositeID;

END WHILE;

CLOSE cCompositeIDs;


END;

/* trHetypeWEIGHT */
CREATE TRIGGER trHetypeWEIGHT
AFTER UPDATE OF Weight ON Hetype
REFERENCING OLD AS o NEW AS n
BEGIN
  IF ExcecutingUnderHireTrack = False THEN
		UPDATE "sort" S SET
		S.UnitWeight = n.Weight
		WHERE
		S.D2 > CURRENT_TIMESTAMP - INTERVAL '7' DAY
		AND S."type" = n."type"
		AND s.rectype <> 11;

		SELECT DISTINCT Eqlno
		INTO #EqlistIDs
		FROM
		"Sort" S
		WHERE
		S.D2 > CURRENT_TIMESTAMP - INTERVAL '7' DAY
		AND S."type" = n."type"
		AND s.rectype <> 11;

		UPDATE Eqlists E SET
		E.TotalWeight = COALESCE((SELECT SUM(S.Quant * S.UnitWeight)
		                          FROM "Sort" S
		                          WHERE
		                          S.Eqlno = E.Eql_no), 0)
		                          WHERE
		                          E.Eql_no IN (SELECT Eqlno
		                          FROM #EqlistIDs);
  END IF;

END;

