/* trInventoryLog_Item */
CREATE TRIGGER trInventoryLog_Item
AFTER UPDATE OF CommissionStatus ON "item"
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  DECLARE cRepairStatus BOOLEAN;

  SET cRepairStatus = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trInventoryLog_Repair' AND KEY = 'cRepairStatus' AND U."USER" = 'GLOBAL'), false) FROM #dummy);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

-- TInventoryLogGroup(ilType, ilItem, ilCategory, ilMasterCategory, ilRepair....)
--  TInventoryLogMeaning = (lmCreated, ilmRepairStatus, ilmRepairCompletedDate

  SET vLogGroup = 4;

IF UPDATING THEN

  -- Commission status change
  IF cRepairStatus THEN
    IF NOT EQUIVALENT(n.CommissionStatus, o.CommissionStatus) AND ((n.CommissionStatus =2) OR (o.CommissionStatus=2)) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Barcode + ': COMMISSION STATUS',255));

     SET vChangeInfo = 'Old Commission Status = ' + cast(o.CommissionStatus as Varchar(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Commission Status = ' + cast(n.CommissionStatus as Varchar(10));

     INSERT INTO InventoryLogs
     (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (vNarrative,'item',1,n.itemRef,vLogGroup,vUserID, vChangeInfo,1);

    END IF;
  END IF;
 END IF;

END;

/* trInventoryLog_ServData */
CREATE TRIGGER trInventoryLog_ServData
AFTER INSERT, DELETE, UPDATE ON ServData
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  DECLARE cRepairStatus BOOLEAN;
  DECLARE cRepairDates BOOLEAN;

  SET cRepairStatus = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trInventoryLog_Repair' AND KEY = 'cRepairStatus' AND U."USER" = 'GLOBAL'), false) FROM #dummy);
  SET cRepairDates = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trInventoryLog_Repair' AND KEY = 'cRepairDates' AND U."USER" = 'GLOBAL'), false) FROM #dummy);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

-- TInventoryLogGroup(ilType, ilItem, ilCategory, ilMasterCategory, ilRepair....)
--  TInventoryLogMeaning = (lmCreated, ilmRepairStatus, ilmRepairCompletedDate

  SET vLogGroup = 4;

  IF INSERTING THEN
    IF cRepairStatus THEN
      SET vNarrative = TRIM(TOSTRINGLEN(Cast(n.RecordNo as Varchar(10)),255));
     SET vChangeInfo = 'LineRef = ' + cast(Coalesce(n.xRepairLineRef, 'null') as Varchar(10));

      INSERT INTO InventoryLogs
          (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser,ChangeInfo,ChangeMeaning)
      VALUES
       (vNarrative ,'servdata',0,n.RecordNo,vLogGroup,vUserID,vChangeInfo, 0);
    END IF;
  ELSEIF UPDATING THEN

  -- Commission status change
  IF cRepairStatus THEN
    IF NOT EQUIVALENT(n.RepairAction, o.RepairAction) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(Cast(n.RecordNo as Varchar(10)) + ': REPAIR ACTION',255));

     SET vChangeInfo = 'Old Repair Action = ' + cast(Coalesce(o.RepairAction, 'null') as Varchar(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Repair Action = ' + cast(Coalesce(n.RepairAction, 'null') as Varchar(10));

     INSERT INTO InventoryLogs
     (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (vNarrative,'servdata',1,n.RecordNo,vLogGroup,vUserID, vChangeInfo,1);

    END IF;
  END IF;

  -- Completed Dates change
   IF cRepairDates THEN
     IF NOT EQUIVALENT(n.CompletedDate, o.CompletedDate) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(Cast(n.RecordNo as Varchar(10)) +  ': COMPLETED DATE',255));

     SET vChangeInfo = 'Old Completed Date = ' + cast(Coalesce(o.CompletedDate, 'null') as Varchar(30));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Completed Date = ' + cast(Coalesce(n.CompletedDate, 'null') as Varchar(30));

     INSERT INTO InventoryLogs
     (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (vNarrative,'servdata',1,n.RecordNo,vLogGroup,vUserID, vChangeInfo,2);

     END IF;
    END IF;
   ELSEIF DELETING THEN
     IF cRepairStatus THEN
     SET vNarrative = TRIM(TOSTRINGLEN(Cast(o.RecordNo as Varchar(10)),255));

     INSERT INTO InventoryLogs
     (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     ( vNarrative ,'servdata',2,o.RecordNo,vLogGroup,vUserID);
     END IF;
 END IF;

END;

/* trInventoryLog_Sort */
CREATE TRIGGER trInventoryLog_Sort
AFTER INSERT, DELETE, UPDATE ON "sort"
REFERENCING OLD AS o NEW AS n
WHEN (((EQUIVALENT(o.Flagged,n.Flagged) AND EQUIVALENT(o.SortOrder,n.SortOrder))))
BEGIN
 IF (o.eqlno = 0) or (n.eqlno = 0) THEN
  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  DECLARE cRepairStatus BOOLEAN;

  SET cRepairStatus = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trInventoryLog_Repair' AND KEY = 'cRepairStatus' AND U."USER" = 'GLOBAL'), false) FROM #dummy);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

-- TInventoryLogGroup(ilType, ilItem, ilCategory, ilMasterCategory, ilRepair....)
--  TInventoryLogMeaning = (lmCreated, ilmRepairStatus, ilmRepairCompletedDate

  SET vLogGroup = 4;

  IF INSERTING THEN
    IF cRepairStatus THEN
      SET vNarrative = TRIM(TOSTRINGLEN(n.lineref,255));

      INSERT INTO InventoryLogs
       (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser,ChangeMeaning)
      VALUES
       (vNarrative ,'sort',0,n.LineRef,vLogGroup,vUserID,0);
    END IF;

  ELSEIF UPDATING THEN

  -- Tracking Repairs change
  IF cRepairStatus THEN
    IF NOT EQUIVALENT(n.xRepairStatus, o.xRepairStatus) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(Cast(n.LineRef as Varchar(10)) + ': REPAIR STATUS',255));

     SET vChangeInfo = 'Old Repair Status = ' + cast(o.xRepairStatus as Varchar(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Repair Status = ' + cast(n.xRepairStatus as Varchar(10));

     INSERT INTO InventoryLogs
     (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (vNarrative,'sort',1,n.LineRef,vLogGroup,vUserID, vChangeInfo,1);

    END IF;
  END IF;

  ELSEIF DELETING THEN
     IF cRepairStatus THEN
       SET vNarrative = TRIM(TOSTRINGLEN(o.LineRef,255));

       INSERT INTO InventoryLogs
        (ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
       VALUES
       (vNarrative ,'sort',2,o.LineRef,vLogGroup,vUserID);
     END IF;

  END IF;
 END IF;
END;

/* trInvoiceBEFORE */
CREATE TRIGGER trInvoiceBEFORE
BEFORE INSERT, UPDATE OF  Client, Terms, Inv_Date , xShipTo ON invoice
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;
  DECLARE vDelAddExists BOOL;
  DECLARE vInvAddExists BOOL;
  DECLARE vDays  INT;

-- Users stuff
  SET vUserID = GetUserID();

  IF INSERTING THEN
    IF vUserID > -1 then
     SET n.xCreatedBy = vUserID;
    END IF;

  ELSEIF UPDATING THEN
     -- actually handled in client now as  UPDATE OF is now limited in the fields it monitors
    IF vUserID > -1 then
     SET n.xModIFiedBy =vUserID;
    END IF;

    SET n.ModifiedDate = CURRENT_TIMESTAMP;
  END IF;


-- Main edits, which applies to Inserts and Updates
  IF NOT EQUIVALENT(n.Client , o.Client) THEN
     -- store single record in memory table for efficiency
     IF n.company THEN
      SELECT * INTO #tmp FROM Company WHERE CompanyCounter = n.Client ;

      SET n."Name" =(SELECT CompanyName FROM #tmp);
      SET n.Telephone = (SELECT MainTelephone FROM #tmp);
      SET n.Facsimile = (SELECT MainFax FROM #tmp);
      SET n.Terms = (SELECT PaymentTerms FROM #tmp);
      SET vInvAddExists = (SELECT InvAdd1<> '' FROM #tmp);

     ELSE
      SELECT * into #tmp FROM Name2 WHERE NameCounter = n.Client;
      SET n."Name" =(SELECT FullName FROM #tmp);
      SET n.Telephone = (SELECT Telephone FROM #tmp);
      SET n.Facsimile = (SELECT Facsimile FROM #tmp);
      SET vInvAddExists = False;
     END IF;

     IF vInvAddExists AND n.company = TRUE THEN
      SET n.Address1 = (SELECT InvAdd1 FROM #tmp);
      SET n.Address2 = (SELECT InvAdd2 FROM #tmp);
      SET n.Address3 = (SELECT InvAdd3 FROM #tmp);
      SET n.Town = (SELECT Invtown FROM #tmp);
      SET n.Postcode = (SELECT InvPostcode FROM #tmp);
      SET n.County = (SELECT InvCounty FROM #tmp);
      SET n.Country = (SELECT InvCountry FROM #tmp);
     ELSE
      SET n.Address1 = (SELECT Address1 FROM #tmp);
      SET n.Address2 = (SELECT Address2 FROM #tmp);
      SET n.Address3 = (SELECT Address3 FROM #tmp);
      SET n.Town = (SELECT Town FROM #tmp);
      SET n.Postcode = (SELECT PostCode FROM #tmp);
      SET n.County = (SELECT County FROM #tmp);
      SET n.Country = (SELECT Country FROM #tmp);
    END IF;

 END IF;-- client

 -- terms
 IF NOT EQUIVALENT(n.Terms,o.Terms) OR (NOT EQUIVALENT(n.Inv_Date,o.Inv_date)) THEN
   SET vDays = (SELECT COALESCE(T.Days,0) FROM Terms T WHERE T.Terms_idx = n.Terms);
   SET n.Due = CAST(CAST(n.Inv_Date AS DOUBLE PRECISION) + vDays AS DATE);
 END IF;

  -- deal with ShipTo change
 IF NOT EQUIVALENT(n.xShipTo , o.xShipTo) THEN
     -- store single record in memory table for efficiency
     SELECT * INTO #tmp
     FROM Company
     WHERE CompanyCounter = n.xShipTo ;

     SET n.T1 =(SELECT CompanyName FROM #tmp);
     SET vDelAddExists = (SELECT DelAdd1<> '' FROM #tmp);

     IF vDelAddExists THEN
      SET n.T2 = (SELECT DelAdd1 FROM #tmp);
      SET n.T3 = (SELECT DelAdd2 FROM #tmp);
      SET n.T4 = (SELECT DelAdd3 FROM #tmp);
      SET n.T5 = (SELECT Deltown FROM #tmp);
      SET n.T6 = (SELECT DelCounty FROM #tmp);
      SET n.T7 = (SELECT DelPostCode FROM #tmp);
      SET n.T8 = (SELECT DelCountry FROM #tmp);
     ELSE
      SET n.T2 = (SELECT Address1 FROM #tmp);
      SET n.T3 = (SELECT Address2 FROM #tmp);
      SET n.T4 = (SELECT Address3 FROM #tmp);
      SET n.T5 = (SELECT Town FROM #tmp);
      SET n.T6 = (SELECT County FROM #tmp);
      SET n.T7 = (SELECT PostCode FROM #tmp);
      SET n.T8 = (SELECT Country FROM #tmp);
     END IF;

 END IF;-- ShipTo


END;

/* trInvoiceTotalsAFTER */
CREATE TRIGGER "trInvoiceTotalsAFTER"
AFTER  DELETE, UPDATE OF ModifiedDate, TotalEx ON  Invoice
REFERENCING OLD AS o NEW AS n
BEGIN
/*
 TRowType =
   (rtEqlistCostCentreHeader, rtEqlistHeader, rtEqlistSectionHeader, rtEqlistMCatHeader, rtEqlistCatHeader, rtEqlistData, rtEqlistMarkupHeader, rtEqlistMarkupData,
    rtCrewCostCentreHeader, rtCrewHeader, rtCrewData,
    rtTransportCostCentreHeader, rtTransportHeader, rtTransportData,
    rtMiscCostCentreHeader, rtMiscHeader, rtMiscData,
    rtSummaryHeader); */

DECLARE vInvID INT;
DECLARE vJobID INT;
DECLARE vNewCrewing BOOL;

SET vInvID = COALESCE(n.Invoice_Count, o.Invoice_Count);
SET vJobID = COALESCE(n.Job, o.Job);

SET  vNewCrewing = (SELECT COALESCE(NewCrewing,TRUE) FROM Jobs WHERE Jobno = vJobID);

SELECT  D.Sort_Link, D.xGeneralCostCentre, D.SubCostCentre, D.LineTotal, D.RowType
INTO #TmpInvSummary
FROM Invoice I
INNER JOIN InvData D
ON I.Invoice_Count = D.InvNo
WHERE
I.Job = vJobID
AND RowType IN (5,7,10,13,16);


SELECT
CASE
 WHEN T.RowType = 5 THEN S.Eqlno
 WHEN T.RowType = 7 THEN E.xEqlno
ELSE
 T.Sort_Link
END
AS Sort_Link ,
T.xGeneralCostCentre,
T.SubCostCentre,
T.LineTotal,
T.RowType
INTO #InvSummary
FROM #TmpInvSummary T
LEFT OUTER JOIN Sort S
ON T.Sort_Link = S.LineRef AND T.Rowtype = 5
LEFT OUTER JOIN EqlistMarkUps E
ON T.Sort_Link = E.IDX AND T.Rowtype = 7;

DROP TABLE IF EXISTS #tmp;

 CREATE TABLE #tmp
 ( IDX integer,
  xGeneralCostCentre  TINYINT,
  SubCostCentre  TINYINT,
  Total  MONEY,
  PRIMARY KEY (idx, xGeneralCostCentre, SubCostCentre));

  INSERT INTO #tmp
   (IDX, xGeneralCostCentre, SubCostCentre, Total )
  SELECT
   COALESCE(Sort_Link,0), xGeneralCostCentre,  SubCostCentre, Sum(LineTotal)
  FROM #InvSummary
  GROUP BY
  xGeneralCostCentre, Sort_Link, SubCostCentre;

  UPDATE JobFinances J
  SET J.InvoicedPrice =
  COALESCE((SELECT T.Total FROM #Tmp T
            WHERE
            T.IDX = J.xCostCentreID
            AND T.xGeneralCostCentre = J.xGeneralCostCentre
            AND T.SubCostCentre = J.SubCostCentre),0)
  WHERE
  J.IsIncome = True
  AND J.xJob = vJobID;

  -- TAccountsDocument = (adRentalInvoice, adRentalInvoiceCredit, adRentalOrder, adRentalOrderCredit, adSalesInvoice, adSalesInvoiceCredit, adSalesOrder, adSalesOrderCredit);
  IF n.DocType = 1 THEN-- credit note

     SELECT
     COALESCE(SUM(TotalEx),0) as TotalEx,
     COALESCE(SUM(TotalInc),0) as TotalInc
     INTO #InvTotals
     FROM Invoice
     WHERE xInvoice = n.xInvoice;

     UPDATE Invoice SET
     CreditedTotalEx = (SELECT TOP 1 TotalEx from #InvTotals),
     CreditedTotalInc = (SELECT TOP 1 TotalInc from #InvTotals)
     WHERE
     Invoice_Count = n.xInvoice;

  END IF; -- Credit note stuff

END;

/* trItem_LOG */
CREATE TRIGGER  trItem_LOG
AFTER INSERT, DELETE, UPDATE ON Item
REFERENCING OLD AS o NEW AS n

BEGIN

DECLARE vIDX INTEGER;

DECLARE vSuspendTriggers BOOL;
SET vSuspendTriggers = (SELECT OPTION('TriggerSuspend') = 'True' FROM #DUMMY);

IF (NOT vSuspendTriggers) THEN

  IF INSERTING THEN
   INSERT INTO Lookups_LOG
    (TableName, MasterID, ActionID)
   VALUES
   ('Item', n."ItemRef", 0);

  ELSEIF UPDATING AND
  (
   EQUIVALENT(o.CurrentJob,n.CurrentJob)
   AND EQUIVALENT(o.Lcurrent,n.Lcurrent)
   AND EQUIVALENT(o.LastOperation,n.LastOperation)
   AND EQUIVALENT(o.LastOpType,n.LastOpType)
   AND EQUIVALENT(o.LastWarehouseBay,n.LastWarehouseBay)
   AND EQUIVALENT(o.OnLoan,n.OnLoan)
   AND EQUIVALENT(o.OnLoan,n.OnLoan)
   AND EQUIVALENT(o.xTransferredToItem,n.xTransferredToItem)
   AND (EQUIVALENT(o.LastService,n.LastService) OR NOT EQUIVALENT(o.HomeLocation,n.HomeLocation) )
   AND EQUIVALENT(o.LastOpScan,n.LastOpScan)
  )
  THEN

   SET vIDX = LookupsLog_RecordExists('Item', o."ItemRef", 1) ;

   IF vIDX > -1 THEN
     UPDATE Lookups_LOG
      SET EditDate = CURRENT_TIMESTAMP
     WHERE IDX = vIDX;
   ELSE
     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('Item',n."ItemRef", 1);
   END IF;  -- vIDX

  ELSEIF DELETING THEN

     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('Item',o."ItemRef", 2);

  END IF; -- DELETING
END IF;
END;

/* trItemAfter */
CREATE TRIGGER  trItemAfter
AFTER INSERT, DELETE, UPDATE OF Type, CostCentre, HoursUsed, CommissionStatus, LastOpType ON Item

REFERENCING OLD AS o NEW AS n
BEGIN

IF INSERTING AND n.BarcodeType <> 1 THEN
   CALL SyncPat_Item(n.ItemRef);
END IF;


DECLARE vSuspendTriggers BOOL;
SET vSuspendTriggers = (SELECT OPTION('TriggerSuspend') = 'True' FROM #DUMMY);

IF (NOT vSuspendTriggers) THEN

	IF INSERTING and n.CostCentre IS NOT NULL THEN

	 UPDATE Audit
	 SET LinkedBarcodesQty = (SELECT COUNT(*)
							             FROM Item
							             WHERE
	                         CostCentre = n.CostCentre
							             AND HoursUsed IS NULL)
	 WHERE
	 AuditKey = n.CostCentre;

	 UPDATE Audit
	 SET LinkedBarcodesQty = (SELECT COUNT(*)
							             FROM Item
							             WHERE
	                         HoursUsed = n.HoursUsed
							             AND HoursUsed IS NOT NULL)
	 WHERE
	 AuditKey = n.HoursUsed;


	ELSEIF UPDATING OR DELETING THEN

   --TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bscDisposed);
   IF (NOT EQUIVALENT(n.CommissionStatus, o.CommissionStatus)) AND (o.NoIndependentScans) AND (n.CommissionStatus IN (1,3,4)) THEN
     -- component barocde from composite barcode if its no longer in commission
      DELETE FROM Subcode WHERE SubItem = o.ItemRef;
   END IF;

	  -- subcode sync
	 IF (UPDATING) AND (NOT EQUIVALENT(n.LastOpType, o.LastOpType)) AND (o.LastOpType > 4) THEN
	    -- the SETTING of  bcsReturned and bcsUnreturned are done in the client as user has to be prompted. But undoing actions or progressing thereafter needs an automatic sync
      --  TBarcodeComponentState = (bcsReadyToGo, bcsReturned, bcsUnreturned, bcsDetached);
	    -- if its a Master Barcode
	    IF (n.BarcodeType = 1)  THEN
	     IF (SELECT Virt FROM Hetype WHERE Type = n.Type) THEN  -- second if reduces overhead

	        IF (n.LastOpType IN (2,3,4)) AND (n.LastWarehouseBay = 1) THEN  -- Prepping then sync any components that are bcsReturned to bcsReadyToGo.
	           UPDATE SubCode S SET
	           S.BarcodeComponentState = 3  -- bcsDetached
	           WHERE
	           S.MasterItem = n.ItemRef
	           AND S.BarcodeComponentState IN (1,2)
	           AND EXISTS (SELECT COUNT(*) FROM Item WHERE ItemRef = S.SubItem AND LastOpType > 5 HAVING COUNT(*) > 0)  ;
	        END IF;

	        IF (n.LastOpType IN (6)) AND (n.LastWarehouseBay = 2) THEN  -- Returning then sync any components that are bcsReturned to bcsReadyToGo.
	           UPDATE SubCode S SET
	           S.BarcodeComponentState = 0
	           WHERE
	           S.MasterItem = n.ItemRef
	           AND S.BarcodeComponentState IN (1,2)
	           AND EXISTS (SELECT COUNT(*) FROM Item WHERE ItemRef = S.SubItem AND LastOpType = 6 HAVING COUNT(*) > 0)  ;
	        END IF;

	         IF (n.LastOpType IN (7)) AND (n.LastWarehouseBay = 2) THEN  -- Checking In then sync any components that are bcsReturned to bcsReadyToGo.
	           UPDATE SubCode S SET
	           S.BarcodeComponentState = 0
	           WHERE
	           S.MasterItem = n.ItemRef
	           AND S.BarcodeComponentState IN (1,2)
	           AND EXISTS (SELECT COUNT(*) FROM Item WHERE ItemRef = S.SubItem AND LastOpType = 7 HAVING COUNT(*) > 0)  ;
	        END IF;

	        IF (n.LastOpType IN (5)) AND (o.LastWarehouseBay = 2) THEN  -- Unreturning maSTER set every then sync any components that are bcsReturned, bcsUnreturned to bcsReadyToGo.
	           UPDATE SubCode SET
	           BarcodeComponentState = 0
	           WHERE
	           MasterItem = n.ItemRef
	           AND BarcodeComponentState IN (1,2);
	        END IF;
	     END IF;
	    END IF; --IF (n.BarcodeType = 1)  THEN

	 END IF; --IF (UPDATING) AND (NOT EQUIVALENT(n.LastOpType, o.LastOpType)) AND (o.LastOpType > 4) THEN


	 IF (NOT EQUIVALENT(n.HoursUsed, o.HoursUsed)) OR (NOT EQUIVALENT(n.CostCentre, o.CostCentre))THEN

	   UPDATE Audit
	   SET LinkedBarcodesQty = (SELECT COUNT(*)
		                         FROM Item
		                         WHERE
	                           CostCentre = o.CostCentre
	                           AND HoursUsed IS NULL )
	   WHERE AuditKey = o.CostCentre;

	   UPDATE Audit
	   SET LinkedBarcodesQty = (SELECT COUNT(*)
		                         FROM Item
	                           WHERE
	                            CostCentre = n.CostCentre
	                            AND HoursUsed IS NULL)
	   WHERE AuditKey = n.CostCentre;

	   UPDATE Audit
	   SET LinkedBarcodesQty = (SELECT COUNT(*)
							             FROM Item
							             WHERE
	                         HoursUsed = o.HoursUsed
							             AND HoursUsed IS NOT NULL)
	   WHERE
	   AuditKey = o.HoursUsed;


	   UPDATE Audit
	   SET LinkedBarcodesQty = (SELECT COUNT(*)
							             FROM Item
							             WHERE
	                         HoursUsed = n.HoursUsed
							             AND HoursUsed IS NOT NULL)
	   WHERE
	   AuditKey = n.HoursUsed;

	 END IF;

	 IF NOT EQUIVALENT(o.Type, n.Type) THEN
	    UPDATE StockTakeDetails SET
	    xTypeID = n.Type
	    WHERE
	    xTypeID = o.Type;
	 END IF;

	END IF;  --INSERTING, UPDATING...

END IF;  --vSuspendTriggers

END;

/* trItemAFTERtag */
CREATE TRIGGER trItemAFTERtag
AFTER INSERT, DELETE, UPDATE OF "type", CostCentre ON item
REFERENCING OLD AS o NEW AS n
BEGIN
IF DELETING THEN
  CALL DoTags('item', o.itemref);
ELSE
  CALL DoTags('item', n.itemref);
END IF;
END;

/* trItemBefore */
CREATE TRIGGER trItemBefore
BEFORE INSERT, UPDATE of Barcode, "Type", LastOpType, LastWarehouseBay, HoursUsed, CostCentre, CommissionStatus, xStockIN ON Item

REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vSuspendTriggers BOOL;
SET vSuspendTriggers = (SELECT OPTION('TriggerSuspend') = 'True' FROM #DUMMY);

IF (NOT vSuspendTriggers) THEN

  IF INSERTING THEN
     SET n.xLocation = (
              SELECT TOP 1 T.xLocation
              FROM TypeLocations T
              WHERE
              T.xType = n.Type
              AND
              T.xWarehouse = n.HomeLocation);
  END IF;

  IF INSERTING OR (UPDATING AND (NOT EQUIVALENT(n.Barcode , o.Barcode))) THEN

  DECLARE vTypeCodeCount INT;
  DECLARE vBarcodeCount INT;

  SET vTypeCodeCount = (
		SELECT COUNT(shortcode)
		FROM hetype
		WHERE UPPER(shortcode) = UPPER(n.Barcode)
		);


  IF vTypeCodeCount > 0 THEN
    SIGNAL 'Barcode ' + n.Barcode + ' is already in use as a TypeCode. Please cancel or enter a different code';
  ELSE

    SET vBarcodeCount = (
		SELECT COUNT(barcode) AS dup
		FROM item
		WHERE UPPER(barcode) = UPPER(n.Barcode)
		);


    IF vBarcodeCount > 0 THEN
      SIGNAL 'Barcode ' + n.Barcode + '  is already in use. Please cancel or enter a different code';
    END IF;

   END IF;  -- vTypeCodeCount

    IF n.PurchDate IS NULL THEN
     SET n.PurchDate = (SELECT A."Date"
                           FROM Audit A
                           WHERE
                           A.AuditKey = n.CostCentre);
    END IF;

    IF n.PurchPrice IS NULL THEN
     SET n.PurchPrice = (SELECT A.UnitPrice
                            FROM Audit A
                            WHERE
                            A.AuditKey = n.CostCentre);
    END IF;

    IF n.Currency IS NULL THEN
     SET n.Currency = (SELECT A.Currency
                            FROM Audit A
                            WHERE
                            A.AuditKey = n.CostCentre);
    END IF;


  END IF;

  IF UPDATING THEN

  -- make sure type is always assigned
  IF n.Type IS NULL THEN
   SIGNAL 'Equipment Type for Barcode has been cleared. Please correct as this field cannot be null.';
  END IF;

  --   TWarehouseActivity = (waHire, waJobSubhire, waGlobalSubhire, waJobLoan, waGlobalLoan, waVirtualWarehouseBuild, waStockTransfer, waClassTransfer);
   --   TWarehouseBay = (wbNone, wbPrep, wbReturn, wbLoansDispatch, wbLoansReceive, wbLoansReturn, wbLoansBack, wbSubhiresSupply, wbSubhiresReturn, wbWarehouseTransfer, wbClassTransfer);
/*  IF O.LastWarehouseBay = 5 AND n.LastWarehouseBay = 2 AND n.LastOpType = 6 THEN
     -- a LOAN KEEP must being undone so the trOpScans trigger will get the reset of  LastOpType wrong as a checkin scan would never have happened so..
     SET n.LastOpType = 7 ;
  END IF;
*/

  -- maintain xLoanExchange, which is emphemeral and only set at the time of a keep in a Swap. It should be cleared when a barcode is scanned on it's next task.
  IF (NOT EQUIVALENT(o.LastOpType, n.LastOpType)) AND ( o.xLoanExchange IS NOT NULL AND n.xLoanExchange IS NOT NULL) THEN
     SET n.xLoanExchange =  NULL;
  END IF;

  -- OnLoan flag
  IF (o.LastWarehouseBay IN (3,5,6)) OR (n.LastWarehouseBay IN (3,5,6)) OR (NOT EQUIVALENT(n.xLoanExchange , o.xLoanExchange)) THEN

     DECLARE vLoanOutID INT;
     DECLARE vLoanBackID INT;

     SET vLoanOutID = COALESCE((SELECT TOP 1 IDX FROM Opscans WHERE xItemRef = n.ItemRef AND WarehouseBay = 3 ORDER BY IDX DESC), 0);
     SET vLoanBackID = COALESCE((SELECT TOP 1 IDX FROM Opscans WHERE xItemRef = n.ItemRef AND ((WarehouseBay = 5 AND KeepLoanType = 0) OR WarehouseBay = 6) ORDER BY IDX DESC), 0);

     SET n.OnLoan = vLoanOutID > vLoanBackID;

  END IF;


  IF NOT EQUIVALENT(n.CostCentre , o.CostCentre) THEN
     IF o.PurchDate IS NULL THEN
        SET n.PurchDate = (SELECT A."Date"
                           FROM Audit A
                           WHERE
                           A.AuditKey = n.CostCentre);
     END IF;

     IF o.PurchPrice IS NULL THEN
        SET n.PurchPrice = (SELECT A.UnitPrice
                            FROM Audit A
                            WHERE
                            A.AuditKey = n.CostCentre);
     END IF;

     IF o.Currency IS NULL THEN
        SET n.Currency = (SELECT A.Currency
                            FROM Audit A
                            WHERE
                            A.AuditKey = n.CostCentre);
     END IF;
   END IF;

   IF COALESCE(n.HoursUsed,0) < 1 THEN
    SET n.HoursUsed = NULL;
   END IF;

   -- If barcode has been exchanged but is not starting a new rental or loan cycle then clear it's  xLoanExchange field. This is only needed for the duration of a loan in case the exchange needs to be reversed
   IF (n.LastOpType < 6 )  AND (n.xLoanExchange IS NOT NULL) THEN
     SET n.xLoanExchange = NULL;
   END IF;

/*  removed because of mantis 5109. Now see trItemAfter
   -- CommissionStatus of items
   IF (NOT EQUIVALENT(N.CommissionStatus, o.CommissionStatus)) AND n.CommissionStatus  IN (1,3,4) THEN --TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bscDisposed);
      UPDATE Subcode SET BarcodeComponentState = 3 WHERE SubItem = n.ItemRef; --TBarcodeComponentState = (bcsReadyToGo, bcsReturned, bcsUnreturned, bscDetached)
   END IF;
*/
   --TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bscDisposed);
   IF (NOT EQUIVALENT(n.CommissionStatus, o.CommissionStatus)) AND (o.NoIndependentScans) AND (n.CommissionStatus IN (1,3,4)) THEN
     -- component barocde from composite barcode if its no longer in commission
      SET n.NoIndependentScans = FALSE;
  --    DELETE FROM Subcode WHERE SubItem = o.ItemRef;
   END IF;
   -- recommissioning items
   IF (NOT EQUIVALENT(N.CommissionStatus, o.CommissionStatus)) AND (o.CommissionStatus IN (1,3,4))  THEN

     IF n.CommissionStatus = 0 THEN -- only if setting to In Commission
        UPDATE WhAudit SET
        Quantity = Quantity + 1
        WHERE
        Idx  = o.xStockOut;
     END IF;

     IF o.CommissionStatus = 4 THEN -- must be bringing back into ownership
        UPDATE Audit SET
        Quantity = Quantity + 1
        WHERE
        AuditKey = n.HoursUsed
        AND n.HoursUsed IS NOT NULL;
     END IF;

     DELETE FROM WHAudit
     WHERE
     Quantity = 0
     AND Idx  = o.xStockOut;

     DELETE FROM Audit
     WHERE
     Quantity = 0
     AND AuditKey = n.HoursUsed
     AND n.HoursUsed IS NOT NULL;

     IF o.CommissionStatus = 4 THEN
        SET n.HoursUsed = NULL;
     END IF;

     IF n.CommissionStatus = 0 THEN -- only if setting to In Commission and only set here, after the above has run
        SET n.xStockOut = NULL;
     END IF;

   END IF;

  END IF; -- updating

END IF;

END;

/* trItemsBatch_LOG */
CREATE TRIGGER  trItemsBatch_LOG
AFTER INSERT, DELETE, UPDATE ON ItemsBatch
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vIDX INTEGER;

  IF INSERTING THEN
   INSERT INTO Lookups_LOG
    (TableName, MasterID, ActionID)
   VALUES
   ('ItemsBatch', n.IDX, 0);

  ELSEIF UPDATING THEN

   SET vIDX = LookupsLog_RecordExists('ItemsBatch', o.IDX, 1) ;

   IF vIDX > -1 THEN
     UPDATE Lookups_LOG
      SET EditDate = CURRENT_TIMESTAMP
     WHERE IDX = vIDX;
   ELSE
     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('ItemsBatch',n.IDX, 1);
   END IF;  -- vIDX

  ELSEIF DELETING THEN

     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('ItemsBatch',o.IDX, 2);

  END IF; -- DELETING
END;

/* trJobFinancesAFTER */
CREATE TRIGGER trJobFinancesAFTER
AFTER INSERT, DELETE, UPDATE of xStatus, QuotedPrice, ActualPrice, InvoicedPrice ON JobFinances
REFERENCING OLD AS o NEW AS n
BEGIN

/* Main purpose of this code is to update most of the costing summary fields in Jobs.nx1. 8 of these fields however are maintained elsewhere:

  -- in jobs.nx1 BEFORE trigger:
   PredictedQuoteStatusProfit
   PredictedProvisionalStatusProfit
   PredictedConfirmedPlusStatusProfit
   AccountingProfit

   -- in the Eqlist, Crew, Transport and Misc table triggers
   LastQuotedEquipment
   LastQuotedCrew
   LastQuotedTransport
   LastQuotedMisc

    TGeneralCostCentre = (gccEquipment =0, gccCrew =1, gccTransport = 2, gccMisc = 3);

  TInternalCostCentre = (iccNone = 0, iccPayment = 1, iccEqUsage = 2, iccPrep = 3, iccTransport = 4, iccGlobalPurchaseOrderAllocation = 5, iccCustomSurchage = 6,
    iccVenueCommission = 7,
    iccEqCommisson, iccEqSubCommission, iccCrewCommisson, iccCrewSubCommission, iccTransportCommisson, iccTransportSubCommission, iccCostsCommisson, iccCostsSubCommission,
    iccCostOfSale, iccExtraRentalCosts, iccAnticipatedSubhireCosts=18);

     */

 DECLARE vJobID INT;
 SET vJobID = COALESCE(o.xJob, n.xJob);

 SELECT
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 0 THEN QuotedPrice ELSE 0 END) AS AllQuotedEquipment,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 1 THEN QuotedPrice ELSE 0 END) AS AllQuotedCrew,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 2 THEN QuotedPrice ELSE 0 END) AS AllQuotedTransport,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 3 THEN QuotedPrice ELSE 0 END) AS AllQuotedMisc,

 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 0 AND xStatus = 1 THEN ActualPrice ELSE 0 END) AS PredictedEquipmentQuoteIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 0 AND xStatus = 2 THEN ActualPrice ELSE 0 END) AS PredictedEquipmentProvisionalIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 0 AND xStatus >=3 THEN ActualPrice ELSE 0 END) AS PredictedEquipmentConfirmedPlusIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 1 AND xStatus = 1 THEN ActualPrice ELSE 0 END) AS PredictedCrewQuoteIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 1 AND xStatus = 2 THEN ActualPrice ELSE 0 END) AS PredictedCrewProvisionalIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 1 AND xStatus >=3 THEN ActualPrice ELSE 0 END) AS PredictedCrewConfirmedPlusIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 2 AND xStatus = 1 THEN ActualPrice ELSE 0 END) AS PredictedTransportQuoteIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 2 AND xStatus = 2 THEN ActualPrice ELSE 0 END) AS PredictedTransportProvisionalIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 2 AND xStatus >=3 THEN ActualPrice ELSE 0 END) AS PredictedTransportConfirmedPlusIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 3 AND xStatus = 1 AND xInternalCostCentre IN (0,7,19,20) THEN ActualPrice ELSE 0 END) AS PredictedMiscQuoteIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 3 AND xStatus = 2 AND xInternalCostCentre IN (0,7,19,20) THEN ActualPrice ELSE 0 END) AS PredictedMiscProvisionalIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 3 AND xStatus >=3 AND xInternalCostCentre IN (0,7,19,20) THEN ActualPrice ELSE 0 END) AS PredictedMiscConfirmedPlusIncome,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 0 THEN InvoicedPrice ELSE 0 END) AS InvoicedEqlist,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 1 THEN InvoicedPrice ELSE 0 END) AS InvoicedCrew,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 2 THEN InvoicedPrice ELSE 0 END) AS InvoicedTransport,
 SUM(CASE WHEN IsIncome and xGeneralCostCentre = 3 AND xInternalCostCentre IN (0,7,19,20) THEN InvoicedPrice ELSE 0 END) AS InvoicedMisc,

 SUM(CASE WHEN NOT IsIncome and
  ((xGeneralCostCentre = 0) OR (xGeneralCostCentre = 3 AND xInternalCostCentre IN (16,17,18))) -- Rental Prep and Usage or Anticipated Costs Rules.RentalCostsAsMisc is FALSE
                                                                                   AND xStatus = 1 THEN QuotedPrice ELSE 0 END) AS AnticpatedEquipmentQuoteCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 0 AND xStatus = 2 THEN QuotedPrice ELSE 0 END) AS AnticpatedEquipmentProvisionalCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 0 AND xStatus >=3 THEN QuotedPrice ELSE 0 END) AS AnticpatedEquipmentConfirmedPlusCosts,

 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 0 AND xInternalCostCentre = 16 AND xStatus = 1 THEN QuotedPrice ELSE 0 END) AS AnticpatedSalesQuoteCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 0 AND xInternalCostCentre = 16 AND xStatus = 2 THEN QuotedPrice ELSE 0 END) AS AnticpatedSalesProvisionalCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 0 AND xInternalCostCentre = 16 AND xStatus >=3 THEN QuotedPrice ELSE 0 END) AS AnticpatedSalesConfirmedPlusCosts,

 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 1 AND xStatus = 1 THEN QuotedPrice ELSE 0 END) AS AnticpatedCrewQuoteCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 1 AND xStatus = 2 THEN QuotedPrice ELSE 0 END) AS AnticpatedCrewProvisionalCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 1 AND xStatus >=3 THEN QuotedPrice ELSE 0 END) AS AnticpatedCrewConfirmedPlusCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 2 AND xStatus = 1 THEN QuotedPrice ELSE 0 END) AS AnticpatedTransportQuoteCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 2 AND xStatus = 2 THEN QuotedPrice ELSE 0 END) AS AnticpatedTransportProvisionalCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 2 AND xStatus >=3 THEN QuotedPrice ELSE 0 END) AS AnticpatedTransportConfirmedPlusCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 3 AND xStatus = 1 THEN QuotedPrice ELSE 0 END) AS AnticpatedMiscQuoteCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 3 AND xStatus = 2 THEN QuotedPrice ELSE 0 END) AS AnticpatedMiscProvisionalCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 3 AND xStatus >=3 THEN QuotedPrice ELSE 0 END) AS AnticpatedMiscConfirmedPlusCosts,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 0 THEN ActualPrice ELSE 0 END) AS OrderedEqlist,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 1 THEN ActualPrice ELSE 0 END) AS OrderedCrew,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 2 THEN ActualPrice ELSE 0 END) AS OrderedTransport,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 3 THEN ActualPrice ELSE 0 END) AS OrderedMisc,

 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 0 THEN InvoicedPrice ELSE 0 END) AS InvoicesReceivedEqlist,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 1 THEN InvoicedPrice ELSE 0 END) AS InvoicesReceivedCrew,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 2 THEN InvoicedPrice ELSE 0 END) AS InvoicesReceivedTransport,
 SUM(CASE WHEN NOT IsIncome and xGeneralCostCentre = 3 THEN InvoicedPrice ELSE 0 END) AS InvoicesReceivedMisc
 INTO #JobFinances
 FROM JobFinances
 WHERE
 xJob =  vJobID;

  UPDATE Jobs J SET
 AllQuotedEquipment = (SELECT COALESCE(AllQuotedEquipment,0) FROM #JobFinances),
 AllQuotedCrew = (SELECT COALESCE(AllQuotedCrew,0) FROM #JobFinances),
 AllQuotedTransport = (SELECT COALESCE(AllQuotedTransport,0) FROM #JobFinances),
 AllQuotedMisc = (SELECT COALESCE(AllQuotedMisc,0) FROM #JobFinances),

 PredictedEquipmentQuoteIncome = (SELECT COALESCE(PredictedEquipmentQuoteIncome,0) FROM #JobFinances),
