 AnticpatedTransportProvisionalCosts = (SELECT COALESCE(AnticpatedTransportProvisionalCosts,0) FROM #JobFinances),
 AnticpatedTransportConfirmedPlusCosts = (SELECT COALESCE(AnticpatedTransportConfirmedPlusCosts,0) FROM #JobFinances),

