/* trJobFinancesBEFORE */
CREATE TRIGGER trJobFinancesBEFORE
BEFORE DELETE ON JobFinances
REFERENCING OLD AS o NEW AS n
BEGIN
 IF o.InvoicedPrice > 0 THEN
    IF o.IsIncome THEN
       SIGNAL 'One or more invoices have been raised against this Job Finances record so it cannot be deleted' ;
    ELSE
       SIGNAL 'One or more purchase orders have been raised against this Job Finances record so it cannot be deleted' ;
    END IF;
 END IF;
END;

/* trJobLog_Costs */
CREATE TRIGGER trJobLog_Costs
AFTER INSERT, DELETE, UPDATE ON Costs
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;
-- TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrew, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing);
  SET vLogGroup = 5;

  IF INSERTING THEN

    SET vNarrative = TRIM(TOSTRINGLEN(n.Title,255));

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
    VALUES
    (n.XJob, vNarrative ,'Costs',0,n.Idx,vLogGroup,vUserID);

  ELSEIF UPDATING THEN
    -- status change
    IF n.xStatus <> o.xStatus THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Title + ': STATUS',255));

     SET vChangeInfo = 'Old Status = ' + GetJobStatusTextFromID(o.xStatus);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Status = ' + GetJobStatusTextFromID(n.xStatus);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.XJob, vNarrative,'Costs',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;


  ELSEIF DELETING THEN

     SET vNarrative = TRIM(TOSTRINGLEN(o.Title,255));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (o.XJob, vNarrative ,'Costs',2,o.Idx,vLogGroup,vUserID);

  END IF;
END;

/* trJobLog_Crew */
CREATE TRIGGER trJobLog_Crew
AFTER INSERT, DELETE, UPDATE ON Crew
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;
  DECLARE vLogGroup INT;
  DECLARE vJobID INT;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo TEXT;


  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

/*
    TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrewHeaderArea, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing,
    jlgCrewRequest, jlgCrewPosition, jlgCrewActivity, jlgCrewShift)
*/
  SET vLogGroup = 10;

  SET vJobID = COALESCE(n.Job_no, o.Job_no);

-- TTableAction = (taInsert, taUpdate, taDelete)

  IF INSERTING THEN

    SET vNarrative =  TRIM(TOSTRINGLEN('New Crew Request For: ' + (SELECT Title FROM Crew_Header WHERE IDX = n.Header),255));

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
    VALUES
    (vJobID, vNarrative ,'Crew',0,n.Idx,vLogGroup,vUserID);

  ELSEIF UPDATING THEN
    -- Crew Type Change
    IF NOT EQUIVALENT(n.Type , o.Type) THEN

     SET vNarrative = TRIM(TOSTRINGLEN('CREW TYPE CHANGE',255));

     SET vChangeInfo = 'Old Type = ' + COALESCE(GetCrewTypeTextFromID(o.Type),'Unassigned');
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Type = ' + GetCrewTypeTextFromID(n.Type);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (vJobID, vNarrative,'Crew',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- status change
    IF NOT EQUIVALENT(n.xStatus , o.xStatus) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(GetCrewTypeTextFromID(n.Type) + ': STATUS',255));

     SET vChangeInfo = 'Old Status = ' + GetJobStatusTextFromID(o.xStatus);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Status = ' + GetJobStatusTextFromID(n.xStatus);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (vJobID, vNarrative,'Crew',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- Date change
    IF NOT EQUIVALENT(n."Out" , o."Out") THEN

     IF o.Job_No IS NULL THEN
        SET vNarrative = 'CREW TASK OUTDATE';
     ELSE
        SET vNarrative = 'CREW OUTDATE';
    END IF;

     SET vChangeInfo = 'Old Date = ' + ToString(o."Out");
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Date = ' + ToString(n."Out");

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (vJobID, vNarrative,'Crew',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    IF NOT EQUIVALENT(n.Back , o.Back) THEN

     IF o.Job_No IS NULL THEN
        SET vNarrative = 'CREW TASK BACKDATE';
     ELSE
        SET vNarrative = 'CREW BACKDATE';
    END IF;

     SET vChangeInfo = 'Old Date = ' + ToString(o.Back);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Date = ' + ToString(n.Back);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (vJobID, vNarrative,'Crew',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

  ELSEIF DELETING THEN

     SET vNarrative =  TRIM(TOSTRINGLEN('Delete Crew Request For: ' + (SELECT Title FROM Crew_Header WHERE IDX = o.Header),255));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (vJobID, vNarrative ,'Crew',2,o.Idx,vLogGroup,vUserID);

  END IF;
END;

/* trJobLog_CrewActivities */
CREATE TRIGGER trJobLog_CrewActivities
AFTER INSERT, DELETE, UPDATE ON CrewActivities
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;
  DECLARE vLogGroup INT;
  DECLARE vJobID INT;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo TEXT;

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

/*
    TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrewHeaderArea, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing,
    jlgCrewRequest, jlgCrewPosition, jlgCrewActivity, jlgCrewShift)
*/
  SET vLogGroup = 12;

  SET vJobID = (SELECT xJob FROM Crew_Header WHERE IDX = COALESCE(n.xArea,o.xArea));

-- TTableAction = (taInsert, taUpdate, taDelete)

  IF INSERTING THEN

    SET vNarrative = 'New Crew Activity: ' + TRIM(TOSTRINGLEN(n.DESCRIPTION,255));

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
    VALUES
    (vJobID, vNarrative ,'CrewActivities',0,n.Idx,vLogGroup,vUserID, F_FORMATDATE(n.ActivityDate));

  ELSEIF UPDATING THEN
    -- Crew Type Change
    IF NOT EQUIVALENT(n.ActivityType , o.ActivityType) THEN

     SET vNarrative = TRIM(TOSTRINGLEN('ACTIVITY TYPE CHANGE',255));

     SET vChangeInfo = 'Old Activity Type = ' + CASE WHEN o.ActivityType = 0 THEN 'On Site' ELSE 'In Warehouse' END;
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Activity Type = ' + CASE WHEN n.ActivityType = 0 THEN 'On Site' ELSE 'In Warehouse' END;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (vJobID, vNarrative,'CrewActivities',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- status change
    IF NOT EQUIVALENT(n.ActivityDate , o.ActivityDate) THEN

     SET vNarrative = TRIM(TOSTRINGLEN('ACTIVITY DATE CHANGE',255));

     SET vChangeInfo = 'Old Date = ' + F_FORMATDATE(o.ActivityDate);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Date = ' + F_FORMATDATE(n.ActivityDate);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (vJobID, vNarrative,'CrewActivities',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

  ELSEIF DELETING THEN

     SET vNarrative = 'Crew Activity: ' + TRIM(TOSTRINGLEN(o.DESCRIPTION,255));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (vJobID, vNarrative ,'CrewActivities',2,o.Idx,vLogGroup,vUserID,F_FORMATDATE(o.ActivityDate));

  END IF;
END;

/* trJobLog_CrewHeader */
CREATE TRIGGER trJobLog_CrewHeader
AFTER INSERT, DELETE, UPDATE ON Crew_Header
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo TEXT;
  DECLARE vNewCrewing BOOL;

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

/*
    TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrewHeaderArea, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing,
    jlgCrewRequest, jlgCrewPosition, jlgCrewActivity, jlgCrewShift)
*/

  SET vLogGroup = 3;

-- TTableAction = (taInsert, taUpdate, taDelete)

  SET vNewCrewing = (SELECT NewCrewing FROM Jobs WHERE Jobno = COALESCE(o.xJob, n.xJob));

  IF INSERTING THEN

    IF vNewCrewing THEN
       SET vNarrative = 'New Crew Area: ' + TRIM(TOSTRINGLEN(n.Title,255));
    ELSE
       SET vNarrative = 'New Crew Header: ' +TRIM(TOSTRINGLEN(n.Title,255));
    END IF;

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
    VALUES
    (n.XJob, vNarrative ,'Crew_Header',0,n.Idx,vLogGroup,vUserID);

  ELSEIF UPDATING THEN
    -- Title Change
    IF n.Title <> o.Title THEN

     SET vNarrative = TRIM(TOSTRINGLEN('TITLE CHANGE',255));

     SET vChangeInfo = 'Old Title = ' + o.Title;
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Title = ' + n.Title;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.XJob, vNarrative,'Crew_Header',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- status change
    IF n.xStatus <> o.xStatus THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Title + ': STATUS',255));

     SET vChangeInfo = 'Old Status = ' + GetJobStatusTextFromID(o.xStatus);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Status = ' + GetJobStatusTextFromID(n.xStatus);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.XJob, vNarrative,'Crew_Header',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- Schedule Dates change
    IF (n.ScheduleStart <> o.ScheduleStart) or (n.ScheduleEnd <> o.ScheduleEnd) THEN

     SET vNarrative =  TRIM(TOSTRINGLEN(n.Title + ': SCHEDULE DATES',255));

     SET vChangeInfo = 'Old Schedule Start = ' + TOSTRINGLEN(o.ScheduleStart,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Schedule Start = ' + TOSTRINGLEN(n.ScheduleStart,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'Old Schedule End = ' + TOSTRINGLEN(o.ScheduleEnd,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'New Schedule End  = ' + TOSTRINGLEN(n.ScheduleEnd,16);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.XJob, vNarrative,'Crew_Header',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- Pricing Dates change
    IF (n.PriceStart <> o.PriceStart) or (n.PriceEnd <> o.PriceEnd) THEN

     SET vNarrative =  TRIM(TOSTRINGLEN(n.Title + ': PRICING DATES',255));

     SET vChangeInfo = 'Old Price Start = ' + TOSTRINGLEN(o.PriceStart,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Price Start = ' + TOSTRINGLEN(n.PriceStart,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'Old Price End = ' + TOSTRINGLEN(o.PriceEnd,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'New Price End  = ' + TOSTRINGLEN(n.PriceEnd,16);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.XJob, vNarrative,'Crew_Header',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

  ELSEIF DELETING THEN

     SET vNarrative = TRIM(TOSTRINGLEN(o.Title,255));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (o.XJob, vNarrative ,'Crew_Header',2,o.Idx,vLogGroup,vUserID);

  END IF;
END;

/* trJobLog_CrewShifts */
CREATE TRIGGER trJobLog_CrewShifts
AFTER INSERT, DELETE, UPDATE ON CrewShifts
REFERENCING OLD AS o NEW AS n
BEGIN

-- the vLogShifts assignment is used to turn detemine whetherthe main code in this trigger runs. If the HireTrack NX customer wants this logging (it adds overhead)
-- then the support team can create an entry in USERSETTINGS.nx1 to ensure that vLogShifts is set to TRUE.

  DECLARE vLogShifts  BOOL;
  SET vLogShifts  = (SELECT COALESCE((SELECT CAST(VALUE AS Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'trJobLog_CrewShifts' AND U."USER" = 'GLOBAL'), FALSE) FROM #dummy);

  IF vLogShifts  THEN

	  DECLARE vUserID INT;
	  DECLARE vLogGroup INT;
	  DECLARE vJobID INT;
	  DECLARE vNarrative VARCHAR(255);
	  DECLARE vChangeInfo TEXT;
	  SET vUserID = GetUserID();

	  IF vUserID = -1 THEN
	   SET vUserID = CAST(NULL AS INTEGER);
	  END IF;

	/*
	    TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrewHeaderArea, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing,
	    jlgCrewRequest, jlgCrewPosition, jlgCrewActivity, jlgCrewShift)
	*/
	  SET vLogGroup = 13;

	     SELECT H.xJob, H.Title, F_FORMATDATE(A.ActivityDate) AS ActivityDate, A.Description AS ActivityDesc , P.Description AS PositionDesc
	     INTO #NewData
	     FROM CrewActivities A
	     INNER JOIN Crew_Header H
	     ON A.xArea = H.Idx
	     INNER JOIN Crew C
	     ON H.IDX = C.Header
	     INNER JOIN CrewPositions P
	     ON C.Idx = P.xCrewRequest
	     WHERE
	     A.IDX = COALESCE(n.xActivity)
	     AND P.IDX = COALESCE(n.xPosition);

	     SELECT H.xJob, H.Title, F_FORMATDATE(A.ActivityDate) AS ActivityDate, A.Description AS ActivityDesc , P.Description AS PositionDesc
	     INTO #OldData
	     FROM CrewActivities A
	     INNER JOIN Crew_Header H
	     ON A.xArea = H.Idx
	     INNER JOIN Crew C
	     ON H.IDX = C.Header
	     INNER JOIN CrewPositions P
	     ON C.Idx = P.xCrewRequest
	     WHERE
	     A.IDX = COALESCE(o.xActivity)
	     AND P.IDX = COALESCE(o.xPosition);


	  IF INSERTING OR UPDATING THEN
	     SET vJobID = (SELECT xJob FROM #NewData);
	  ELSE
	     SET vJobID = (SELECT xJob FROM #OldData);
	  END IF;

	-- TTableAction = (taInsert, taUpdate, taDelete)

	  IF INSERTING THEN

	    SET vNarrative = 'New Crew Shift for: ' + TRIM(TOSTRINGLEN((SELECT PositionDesc + '(' + ActivityDate +')' FROM #NewData),255)) ;

	    INSERT INTO JobLogs
	    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
	    VALUES
	    (vJobID, vNarrative ,'CrewShifts',0,n.Idx,vLogGroup,vUserID);

	  ELSEIF UPDATING THEN
	    -- Activity change
	    IF NOT EQUIVALENT(n.xActivity , o.xActivity) THEN

	     SET vNarrative = TRIM(TOSTRINGLEN('ACTIVITY / DATE CHANGE',255));

	     SET vChangeInfo = 'Old Activity = ' + (SELECT PositionDesc + '(' + ActivityDate +')' FROM #OldData);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
	     SET vChangeInfo = vChangeInfo + 'New Activity ' + (SELECT PositionDesc + '(' + ActivityDate +')' FROM #NewData);

	     INSERT INTO JobLogs
	     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
	     VALUES
	     (vJobID, vNarrative,'CrewShifts',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

	    END IF;

	    -- Position change
	    IF NOT EQUIVALENT(n.xPosition , o.xPosition) THEN

	     SET vNarrative = TRIM(TOSTRINGLEN('POSITION CHANGE',255));

	     SET vChangeInfo = 'Old Position = ' + (SELECT PositionDesc + '(' + ActivityDate +')' FROM #OldData);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
	     SET vChangeInfo = vChangeInfo + 'New Position = ' + (SELECT PositionDesc + '(' + ActivityDate +')' FROM #NewData);

	     INSERT INTO JobLogs
	     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
	     VALUES
	     (vJobID, vNarrative,'CrewShifts',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

	    END IF;

	    -- BookingState change
	    IF (NOT EQUIVALENT(n.BookingState , o.BookingState)) THEN

	     SET vNarrative = TRIM(TOSTRINGLEN('BOOKING STATE CHANGE',255));

	     SET vChangeInfo = 'Old Booking State = ' + CASE
	                                                WHEN o.BookingState = 0 THEN 'Include In Quotes'
	                                                WHEN o.BookingState = 1 THEN 'Exclude From Quotes'
	                                                WHEN o.BookingState = 2 THEN 'Cancelled'
	                                                WHEN o.BookingState = 3 THEN 'Blackout'
	                                                END;
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
	     SET vChangeInfo = vChangeInfo + 'New Booking State = ' +
	                                                CASE
	                                                WHEN N.BookingState = 0 THEN 'Include In Quotes'
	                                                WHEN n.BookingState = 1 THEN 'Exclude From Quotes'
	                                                WHEN n.BookingState = 2 THEN 'Cancelled'
	                                                WHEN n.BookingState = 3 THEN 'Blackout'
	                                                END;
	     INSERT INTO JobLogs
	     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
	     VALUES
	     (vJobID, vNarrative,'CrewShifts',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

	    END IF;

	    -- Status change
	    IF (NOT EQUIVALENT(n.Status , o.Status)) THEN

	     SET vNarrative = TRIM(TOSTRINGLEN('STATUS CHANGE',255));

	     SET vChangeInfo = 'Old Status = ' + CASE
	                                                WHEN o.Status = 0 THEN 'UnProcessed'
	                                                WHEN o.Status = 1 THEN 'In Progress'
	                                                WHEN o.Status = 2 THEN 'Pencilled'
	                                                WHEN o.Status = 3 THEN 'Booked'
	                                                WHEN o.Status = 4 THEN 'Ordered'
	                                                END;
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
	     SET vChangeInfo = vChangeInfo + 'New Status = ' +
	                                                CASE
	                                                WHEN n.Status = 0 THEN 'UnProcessed'
	                                                WHEN n.Status = 1 THEN 'In Progress'
	                                                WHEN n.Status = 2 THEN 'Pencilled'
	                                                WHEN n.Status = 3 THEN 'Booked'
	                                                WHEN n.Status = 4 THEN 'Ordered'
	                                                END;
	     INSERT INTO JobLogs
	     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
	     VALUES
	     (vJobID, vNarrative,'CrewShifts',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

	    END IF;

	    IF (NOT EQUIVALENT(n.Shift1Start , o.Shift1Start)) OR
	       (NOT EQUIVALENT(n.Shift1End , o.Shift1End)) OR
	       (NOT EQUIVALENT(n.Shift2Start , o.Shift2Start)) OR
	       (NOT EQUIVALENT(n.Shift2End , o.Shift2End)) THEN

	     SET vNarrative = TRIM(TOSTRINGLEN('SHIFT TIMES CHANGE',255));

	     SET vChangeInfo = 'Old Shift Times = ';
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 1 Start: ' + TOSTRING(o.Shift1Start);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 1 End: ' + TOSTRING(o.Shift1End);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 2 Start: ' + TOSTRING(o.Shift2Start);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 2 End: ' + TOSTRING(o.Shift2End);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
	     SET vChangeInfo = vChangeInfo + 'New Shift Times = ';
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 1 Start: ' + TOSTRING(n.Shift1Start);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 1 End: ' + TOSTRING(n.Shift1End);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 2 Start: ' + TOSTRING(n.Shift2Start);
	     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10) + CHR(9);
	     SET vChangeInfo = vChangeInfo + 'Shift 2 End: ' + TOSTRING(n.Shift2End);

	     INSERT INTO JobLogs
	     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
	     VALUES
	     (vJobID, vNarrative,'CrewShifts',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

	    END IF;

	  ELSEIF DELETING THEN

	     SET vNarrative = 'Delete Crew Shift for: ' + TRIM(TOSTRINGLEN((SELECT PositionDesc + '(' + ActivityDate +')' FROM #OldData),255)) ;

	     INSERT INTO JobLogs
	     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
	     VALUES
	     (vJobID, vNarrative ,'CrewShifts',2,o.Idx,vLogGroup,vUserID);

	  END IF;

  END IF;
END;

/* trJobLog_Diary */
CREATE TRIGGER trJobLog_Diary
AFTER INSERT, DELETE, UPDATE ON Diary
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;
-- TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrew, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing);
  SET vLogGroup = 6;
  -- TEventType = (etJob, etProject, etCRM);
  IF INSERTING AND n.EventType = 0 THEN

    SET vNarrative = TRIM(TOSTRINGLEN(n."Description",255));

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
    VALUES
    (n.xEventOwnerID, vNarrative ,'Diary',0,n.Idx,vLogGroup,vUserID);

  ELSEIF UPDATING AND n.EventType = 0 THEN
    -- status change
    IF n.Status <> o.Status THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n."Description" + ': STATUS',255));

     SET vChangeInfo = 'Old Status = ' + GetDiaryStatusTextFromID(o.Status);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Status = ' + GetDiaryStatusTextFromID(n.Status);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.xEventOwnerID, vNarrative,'Diary',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- priority change
    IF n.priority <> o.priority THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n."Description" + ': PRIORITY',255));

     SET vChangeInfo = 'Old Status = ' + GetDiaryPriorityTextFromID(o.priority);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Status = ' + GetDiaryPriorityTextFromID(n.priority);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.xEventOwnerID, vNarrative,'Diary',1,n.Idx,vLogGroup,vUserID, vChangeInfo );

    END IF;

  ELSEIF DELETING AND o.EventType = 0 THEN

     SET vNarrative = TRIM(TOSTRINGLEN(o."Description",255));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (o.xEventOwnerID, vNarrative ,'Diary',2,o.Idx,vLogGroup,vUserID);

  END IF;
END;

/* trJobLog_Eqlists */
CREATE TRIGGER trJobLog_Eqlists
AFTER INSERT, DELETE, UPDATE OF Defcon, DateOut, DateBack, Total ON Eqlists
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

  IF INSERTING OR UPDATING THEN
   IF n.ListType = 0 THEN
    SET vLogGroup = 1;
   ELSEIF n.ListType = 1 THEN
    SET vLogGroup = 2;
   END IF;
  ELSE
   IF o.ListType = 0 THEN
    SET vLogGroup = 1;
   ELSEIF o.ListType = 1 THEN
    SET vLogGroup = 2;
   END IF;
  END IF;


-- TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrew, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing);
-- TJobLogMeaning = (jlmCreated, jlmJobRefChange, jlmJobTitleChange, jlmJobStatushange, jlmJobDatesChange, jlmQuoteValueChange) ;
-- TStatusMonitor = (smInitialStatus, smOldStatus, smCurrentStatus);

IF vLogGroup IS NOT NULL THEN

  IF INSERTING THEN

    SET vNarrative = TRIM(TOSTRINGLEN(n.Eql_Name,255));

    IF FunctionExists('StatusMonitorEqlists') THEN
      INSERT INTO JobLogs
      (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser,ChangeMeaning,xStatusMonitor)
      VALUES
      (n.Job_no, vNarrative ,'Eqlists',0,n.Eql_no,vLogGroup,vUserID,0,0);
    ELSE
      INSERT INTO JobLogs
      (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
      VALUES
      (n.Job_no, vNarrative ,'Eqlists',0,n.Eql_no,vLogGroup,vUserID);
    END IF;

  ELSEIF UPDATING THEN
    -- status change
    IF n.Defcon <> o.Defcon THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Eql_Name + ': STATUS',255));

     SET vChangeInfo = 'Old Status = ' + GetJobStatusTextFromID(o.Defcon);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Status = ' + GetJobStatusTextFromID(n.Defcon);

     IF FunctionExists('StatusMonitorEqlists') THEN

       UPDATE JobLogs SET
       xStatusMonitor = 1
       WHERE
       xJob = n.Job_no
       AND
       xStatusMonitor IS NOT NULL
       AND
       ChangedRecordID = n.Eql_no ;

       INSERT INTO JobLogs
       (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo,ChangeMeaning, xStatusMonitor)
       VALUES
       (n.Job_no, vNarrative,'Eqlists',1,n.Eql_no,vLogGroup,vUserID, vChangeInfo,3, 2 );
     ELSE
       INSERT INTO JobLogs
       (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
       VALUES
       (n.Job_no, vNarrative,'Eqlists',1,n.Eql_no,vLogGroup,vUserID, vChangeInfo );

     END IF;

    END IF;

    -- Dates change
    IF (n.DateOut <> o.DateOut) or (n.DateBack <> o.DateBack) THEN

     SET vNarrative =  TRIM(TOSTRINGLEN(n.Eql_Name + ': DATES',255));

     SET vChangeInfo = 'Old Date Out = ' + TOSTRINGLEN(o.DateOut,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Date Out = ' + TOSTRINGLEN(n.DateOut,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'Old Date Back = ' + TOSTRINGLEN(o.DateBack,16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'New Date Back = ' + TOSTRINGLEN(n.DateBack,16);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.Job_no, vNarrative,'Eqlists',1,n.Eql_no,vLogGroup,vUserID, vChangeInfo );

    END IF;

    -- Price Change
    IF n.Total <> o.Total THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Eql_Name + ': PRICE',255));
     SET vChangeInfo = 'Old Price = ' + TOSTRING(o.Total);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Price = ' + TOSTRING(n.Total);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.Job_no, vNarrative,'Eqlists',1,n.Eql_no,vLogGroup,vUserID, vChangeInfo );

    END IF;

  ELSEIF DELETING THEN

     SET vNarrative = TRIM(TOSTRINGLEN(o.Eql_Name,255));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (o.Job_no, vNarrative,'Eqlists',2,o.Eql_no,vLogGroup,vUserID);

  END IF;

END IF;

END;

/* trJobLog_Invoice */
CREATE TRIGGER trJobLog_Invoice
AFTER INSERT, DELETE, UPDATE ON Invoice
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;
-- TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrew, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing);
  SET vLogGroup = 8;

-- TAccountsDocument = (adRentalInvoice, adRentalInvoiceCredit, adRentalOrder, adRentalOrderCredit, adSalesInvoice, adSalesInvoiceCredit, adSalesOrder, adSalesOrderCredit);
    IF n.DocType = 0 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Invoice: ' +n.Inv_no,255));
    ELSEIF n.DocType = 1 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Credit Note: ' +n.Inv_no,255));
    ELSEIF n.DocType = 2 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order: ' +n.Inv_no,255));
    ELSEIF n.DocType = 3 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order Cancellation: ' +n.Inv_no,255));
    END IF;

  IF INSERTING THEN

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
    VALUES
    (n.Job, vNarrative ,'Invoice',0,n.Invoice_Count,vLogGroup,vUserID);

  ELSEIF UPDATING THEN

    -- New Invoice # being assigned
    IF n.Inv_no <> o.Inv_no OR o.Inv_no IS NULL THEN

     UPDATE JobLogs
     SET ChangeNarrative = vNarrative
     WHERE
     ChangedRecordID = n.Invoice_Count
     AND ChangedTableName =  'Invoice'
     AND ChangeAction = 0;

    END IF;

    -- Credited status
    IF n.CreditedTotalEx <> o.CreditedTotalEx THEN

     SET vLogGroup = 8;
     SET vNarrative = TRIM(TOSTRINGLEN(n.Inv_no + ': CREDITED AMOUNT',255));
     SET vChangeInfo = 'Old Credited Amount = ' + TOSTRING(o.CreditedTotalEx);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Credited Amount = ' + TOSTRING(n.CreditedTotalEx);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.Job, vNarrative,'Invoice',1,n.Invoice_Count,vLogGroup,vUserID, vChangeInfo );

    END IF;

  ELSEIF DELETING THEN

    IF o.DocType = 0 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Invoice: ' +o.Inv_no,255));
    ELSEIF o.DocType = 1 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Credit Note: ' +o.Inv_no,255));
    ELSEIF o.DocType = 2 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order: ' +o.Inv_no,255));
    ELSEIF o.DocType = 3 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order Cancellation: ' +o.Inv_no,255));
    END IF;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (o.Job, vNarrative ,'Invoice',2,o.Invoice_Count,vLogGroup,vUserID);

  END IF;
END;

/* trJobLog_Jobs */
CREATE TRIGGER trJobLog_Jobs
AFTER INSERT, DELETE, UPDATE ON Jobs
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);


 // What do we want to log ?

  DECLARE cStatus BOOLEAN;
  DECLARE cJobRef BOOLEAN;
  DECLARE cJobTitle BOOLEAN;
  DECLARE cClient BOOLEAN;
  DECLARE cClientName BOOLEAN;
  DECLARE cType BOOLEAN;
  DECLARE cHandler BOOLEAN;
  DECLARE cHandlerName BOOLEAN;
  DECLARE cDates BOOLEAN;
  DECLARE cPrice BOOLEAN;
  DECLARE cSalesP BOOLEAN;
  DECLARE cSalesPName BOOLEAN;
  DECLARE cInvoiceState BOOLEAN;


 // original options default to TRUE
 SET cStatus = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cStatus' AND U."USER" = 'GLOBAL'), TRUE) FROM #dummy);
 SET cJobRef = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cJobRef' AND U."USER" = 'GLOBAL'), TRUE) FROM #dummy);
 SET cJobTitle = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cJobTitle' AND U."USER" = 'GLOBAL'), TRUE) FROM #dummy);
 SET cClient = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cClient' AND U."USER" = 'GLOBAL'), false) FROM #dummy);
 SET cClientName = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cClientName' AND U."USER" = 'GLOBAL'), false) FROM #dummy);
 SET cType = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cType' AND U."USER" = 'GLOBAL'), false) FROM #dummy);
 SET cHandler = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cHandler' AND U."USER" = 'GLOBAL'), false) FROM #dummy);
 SET cHandlerName = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cHandlerName' AND U."USER" = 'GLOBAL'), false) FROM #dummy);
 SET cDates = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cDates' AND U."USER" = 'GLOBAL'), TRUE) FROM #dummy);
 SET cPrice = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cPrice' AND U."USER" = 'GLOBAL'), TRUE) FROM #dummy);
 SET cSalesP = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cSalesP' AND U."USER" = 'GLOBAL'), FALSE) FROM #dummy);
 SET cSalesPName = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cSalesPName' AND U."USER" = 'GLOBAL'), FALSE) FROM #dummy);
 SET cInvoiceState = (SELECT Coalesce((SELECT CAST(VALUE as Boolean) FROM USERSETTINGS U WHERE Section = 'trJobLog_Jobs' AND KEY = 'cInvoiceState' AND U."USER" = 'GLOBAL'), FALSE) FROM #dummy);


  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;

-- TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrew, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing);
-- TJobLogMeaning = (jlmCreated, jlmJobRefChange, jlmJobTitleChange, jlmJobStatushange, jlmJobDatesChange, jlmQuoteValueChange, jlmClient [6], jlmName [7], jlmtype [8], jlmHandler [9],jlmHanlderName [10],jlmSalesP [11],jlmSalesPName [12], jlmInvoiceState [13] ) ;
-- TStatusMonitor = (smInitialStatus, smOldStatus, smCurrentStatus);

  SET vLogGroup = 0;

  IF INSERTING THEN

    SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref,255));

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser,ChangeMeaning,xStatusMonitor)
    VALUES
    (n.Jobno, vNarrative ,'Jobs',0,n.Jobno,vLogGroup,vUserID,0,0);

  ELSEIF UPDATING THEN

    -- Job Ref change
  IF cJobRef THEN
    IF NOT EQUIVALENT(n.Job_Ref, o.Job_Ref) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB REF',255));

     SET vChangeInfo = 'Old Job Ref = ' + o.Job_Ref;
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Job Ref = ' + n.Job_Ref;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,1 );

    END IF;
  END IF;

    -- Job Title change
  IF cJobTitle THEN
    IF NOT EQUIVALENT(n.Job_Title, o.Job_Title) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB TITLE',255));

     SET vChangeInfo = 'Old Job Title = ' + o.Job_Title;
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Job Title = ' + n.Job_Title;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,2 );

    END IF;
  END IF;

    -- Job Client change

  IF cClient THEN
    IF NOT EQUIVALENT(n.Client, o.Client) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB CLIENT',255));

     SET vChangeInfo = 'Old Client = ' + CAST(o.Client as VARCHAR(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Client = ' + CAST(n.Client as VARCHAR(10));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,6 );

    END IF;
  END IF;

     -- Job Client Name change
  IF cClientName THEN
    IF NOT EQUIVALENT(n."Name", o."Name") THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB NAME',255));

     SET vChangeInfo = 'Old Name = ' + o."Name";
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Name = ' + n."Name";

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,7 );

    END IF;
  END IF;

      -- Job Type change
  IF cType THEN
    IF NOT EQUIVALENT(n."Type", o."Type") THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB TYPE',255));

     SET vChangeInfo = 'Old Type = ' + Cast(o."Type" as VarChar(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Type = ' + Cast(n."Type" as VarChar(10));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,8 );

    END IF;
  END IF;

      -- Job Handler change
  IF cHandler THEN
    IF NOT EQUIVALENT(n."Handler", o."Handler") THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB HANDLER',255));

     SET vChangeInfo = 'Old Handler = ' + Cast(o."handler" as VarChar(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Handler = ' + Cast(n."handler" as VarChar(10));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,9 );

    END IF;
  END IF;

      -- Job Handler Name change
  IF cHandlerName THEN
    IF NOT EQUIVALENT(n."Handler", o."Handler") THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB HANDLER NAME',255));

     SET vChangeInfo = 'Old Handler Name = ' + GetUserName(o."handler");
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Handler Name = ' +  GetUserName(n."handler");

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,10 );

    END IF;
  END IF;

       -- cSalesP change
  IF cSalesP THEN
    IF NOT EQUIVALENT(n."SalesPerson", o."SalesPerson") THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB SALES PERSON',255));

     SET vChangeInfo = 'Old Sales Person = ' + Cast(o."SalesPerson" as VarChar(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Sales Person = ' + Cast(n."SalesPerson" as VarChar(10));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,11 );

    END IF;
  END IF;

      -- cSalesP Name change
  IF cSalesPName THEN
    IF NOT EQUIVALENT(n."SalesPerson", o."SalesPerson") THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB SALES PERSON NAME',255));

     SET vChangeInfo = 'Old Sales Person Name = ' + GetUserName(o."SalesPerson");
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Sales Person Name = ' +  GetUserName(n."SalesPerson");

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,12 );

    END IF;
  END IF;

--  cInvoiceState change

  IF cInvoiceState THEN
    IF NOT EQUIVALENT(n."invoicestate", o."invoicestate") THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': JOB INVOICE STATE',255));

     SET vChangeInfo = 'Old Invoice State = ' + Cast(o."invoicestate" as VarChar(10));
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Invoice State = ' + Cast(n."invoicestate" as VarChar(10));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,13 );

    END IF;
  END IF;


    -- status change
  IF cStatus THEN
    IF n.status <> o.status THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': STATUS',255));

     SET vChangeInfo = 'Old Status = ' + GetJobStatusTextFromID(o.status);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Status = ' + GetJobStatusTextFromID(n.status);

     UPDATE JobLogs SET
     xStatusMonitor = 1
     WHERE
     xJob = n.Jobno
     AND
     xStatusMonitor IS NOT NULL
     AND
     vLogGroup = 0 ;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo,ChangeMeaning, xStatusMonitor)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,3, 2 );

    END IF;
  END IF;

    -- Dates change
   IF cDates THEN
    IF (n."Due Out" <> o."Due Out") or (n."Due Back" <> o."Due Back") THEN

     SET vNarrative =  TRIM(TOSTRINGLEN(n.Job_Ref + ': DATES',255));

     SET vChangeInfo = 'Old Date Out = ' + TOSTRINGLEN(o."Due Out",16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Date Out = ' + TOSTRINGLEN(n."Due Out",16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'Old Date Back = ' + TOSTRINGLEN(o."Due Back",16);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo +'New Date Back = ' + TOSTRINGLEN(n."Due Back",16);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo, 4 );

    END IF;
  END IF;

  IF cPrice THEN
    -- Quote value
    IF n.LastQuotedEquipment <> o.LastQuotedEquipment OR n.LastQuotedCrew <> o.LastQuotedCrew OR
       n.LastQuotedTransport <> o.LastQuotedTransport OR n.LastQuotedMiscCosts <> o.LastQuotedMiscCosts THEN

     SET vLogGroup = 8;
     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': NEW QUOTE GENERATED',255));
     SET vChangeInfo = 'Old Price = ' + TOSTRING(o.LastQuotedEquipment + o.LastQuotedCrew + o.LastQuotedTransport + o.LastQuotedMiscCosts );
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Price = ' + TOSTRING(n.LastQuotedEquipment + n.LastQuotedCrew + n.LastQuotedTransport + n.LastQuotedMiscCosts );

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo, 5 );

    END IF;
  END IF;

  -- changing Enhanced Crewing status
  IF NOT EQUIVALENT(n.NewCrewing, o.NewCrewing) THEN

     SET vNarrative = TRIM(TOSTRINGLEN(n.Job_Ref + ': ENHANCED CREWING CHANGES',255));

     IF o.NewCrewing IS NULL AND n.NewCrewing = FALSE THEN
        SET vChangeInfo = 'Upgraded Enhanced Crewing reverted to Legacy (should not be possible)';
     ELSEIF o.NewCrewing IS NULL AND n.NewCrewing = TRUE THEN
        SET vChangeInfo = 'Upgraded Enhanced Crewing converted to New Enhanced Crewing (should not be possible) ';
     ELSEIF o.NewCrewing = FALSE AND n.NewCrewing IS NULL THEN
        SET vChangeInfo = 'Legacy Crewing upgraded to Enhanced Crewing';
     ELSEIF o.NewCrewing = FALSE AND n.NewCrewing = TRUE THEN
        SET vChangeInfo = 'Legacy Crewing converted to New Enhanced Crewing (should not be possible)';
     ELSEIF o.NewCrewing = TRUE AND n.NewCrewing IS NULL THEN
        SET vChangeInfo = 'New Enhanced Crewing converted to Upgraded Enhanced Crewing (should not be possible)';
     ELSEIF o.NewCrewing = TRUE AND n.NewCrewing = FALSE THEN
        SET vChangeInfo = 'New Enhanced Crewing converted to Legacy Enhanced Crewing (should not be possible)';
     END IF;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo, ChangeMeaning)
     VALUES
     (n.Jobno, vNarrative,'Jobs',1,n.Jobno,vLogGroup,vUserID, vChangeInfo,1 );

  END IF;

  ELSEIF DELETING THEN

     SET vNarrative = TRIM(TOSTRINGLEN(o.Job_Ref,255));

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (o.Jobno, vNarrative ,'Jobs',2,o.Jobno,vLogGroup,vUserID);

  END IF;
END;

/* trJobLog_POrder */
CREATE TRIGGER trJobLog_POrder
AFTER INSERT, DELETE, UPDATE ON POrder
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INTEGER;
  DECLARE vLogGroup INTEGER;
  DECLARE vNarrative VARCHAR(255);
  DECLARE vChangeInfo VARCHAR(255);

  SET vUserID = GetUserID();

  IF vUserID = -1 THEN
   SET vUserID = CAST(NULL AS INTEGER);
  END IF;
-- TJobLogGroup = (jlgHeader, jlgEqlist, jlgSubhire, jlgCrew, jlgTransport, jlgMiscCosts, jlgDiary, jlgCorrespondence, jlgFinances, jlgWarehousing);
  SET vLogGroup = 8;

  -- TAccountsDocument = (adRentalInvoice, adRentalInvoiceCredit, adRentalOrder, adRentalOrderCredit, adSalesInvoice, adSalesInvoiceCredit, adSalesOrder, adSalesOrderCredit);
    IF n.DocType = 0 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Invoice: ' +n.Inv_no,255));
    ELSEIF n.DocType = 1 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Credit Note: ' +n.Inv_no,255));
    ELSEIF n.DocType = 2 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order: ' +n.Inv_no,255));
    ELSEIF n.DocType = 3 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order Cancellation: ' +n.Inv_no,255));
    END IF;

  IF INSERTING THEN

    INSERT INTO JobLogs
    (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
    VALUES
    (n.Job, vNarrative ,'POrder',0,n.Invoice_Count,vLogGroup,vUserID);

  ELSEIF UPDATING THEN

    -- New PO # being assigned
    IF n.Inv_no <> o.Inv_no OR o.Inv_no IS NULL THEN

     UPDATE JobLogs
     SET ChangeNarrative = vNarrative
     WHERE
     ChangedRecordID = n.Invoice_Count
     AND ChangedTableName =  'POrder'
     AND ChangeAction = 0;

    END IF;

    -- Credited status
    IF n.CreditedTotalEx <> o.CreditedTotalEx THEN

     SET vLogGroup = 8;
     SET vNarrative = TRIM(TOSTRINGLEN(n.Inv_no + ': CREDITED AMOUNT',255));
     SET vChangeInfo = 'Old Credited Amount = ' + TOSTRING(o.CreditedTotalEx);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Credited Amount = ' + TOSTRING(n.CreditedTotalEx);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.Job, vNarrative,'POrder',1,n.Invoice_Count,vLogGroup,vUserID, vChangeInfo );

    END IF;

    IF n.Authorised <> o.Authorised THEN

     SET vLogGroup = 8;
     SET vNarrative = TRIM(TOSTRINGLEN('AUTHORISATION CHANGE',255));
     SET vChangeInfo = 'Old Authorised Status = ' + TOSTRING(o.Authorised);
     SET vChangeInfo = vChangeInfo + CHR(13) + CHR(10);
     SET vChangeInfo = vChangeInfo + 'New Authorised Status = ' + TOSTRING(n.Authorised);

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser, ChangeInfo)
     VALUES
     (n.Job, vNarrative,'POrder',1,n.Invoice_Count,vLogGroup,vUserID, vChangeInfo );

    END IF;

  ELSEIF DELETING THEN

    IF o.DocType = 0 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Invoice: ' +o.Inv_no,255));
    ELSEIF o.DocType = 1 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Credit Note: ' +o.Inv_no,255));
    ELSEIF o.DocType = 2 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order: ' +o.Inv_no,255));
    ELSEIF o.DocType = 3 THEN
     SET vNarrative = TRIM(TOSTRINGLEN('Purchase Order Cancellation: ' +o.Inv_no,255));
    END IF;

     INSERT INTO JobLogs
     (xJob,ChangeNarrative,ChangedTableName,ChangeAction,ChangedRecordID,LogGroup,xUser)
     VALUES
     (o.Job, vNarrative ,'POrder',2,o.Invoice_Count,vLogGroup,vUserID);

  END IF;
END;

