/* trJobsAFTER */
CREATE TRIGGER trJobsAFTER
AFTER  DELETE ON Jobs
REFERENCING OLD AS o NEW AS n

BEGIN

-- deal with deletes that cannot be done by RI

// NoteBook
    UPDATE NoteBook SET ConvertedToJob = 0
     WHERE ConvertedToJob = o.Jobno;

// Documents
    DELETE FROM Documents
     WHERE  EnumRepositoryType = 'rtJobs'
     AND RepositoryRecordIdx = o.jobno;

 // EmailSentMessages
     DELETE FROM EmailSentMessages
     WHERE EmailSourceType = 'esJobRecord'
     AND EmailSourceIDX = o.jobno;

 -- UserJobs
    DELETE FROM UserJobs
     WHERE  xMyWorkID = o.jobno
     AND xMyWork = 0;

 -- CRMLeads
 -- TBookingType = (btCRM, btNoteBook, btJobBook);
    UPDATE crmLeads SET
    xJob = NULL,
    xBookingType = 0
    WHERE xJob = o.Jobno and xBookingType = 2;

--RestrictedUserAccess
    DELETE FROM RestrictedUserAccess
    WHERE
    xRecordID = o.Jobno and UserRestrictionType = 1; -- TUserRestrictionType = (urtNone, urtJobs)

END;

/* trJobsAFTERtag */
CREATE TRIGGER trJobsAFTERtag
AFTER INSERT, DELETE, UPDATE OF Client ON jobs
REFERENCING OLD AS o NEW AS n
BEGIN
IF DELETING THEN
  CALL DoTags('Jobs', o.jobno);
ELSE
  CALL DoTags('Jobs', n.jobno);
END IF;
END;

/* trJobsBEFORE */
CREATE TRIGGER trJobsBEFORE
BEFORE INSERT, UPDATE  ON Jobs
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vUserID INT;
DECLARE vAuthorisedForQuotingBy INT;
DECLARE vCompanyForFinances INT;

SET vUserID = GetUserID();

IF n.JobCommissionFromVenue THEN
	SET vCompanyForFinances = n.xMainVenue;
ELSE
	SET vCompanyForFinances = n.client;
END IF;

  IF INSERTING THEN

     -- JobRef
    SET n.Job_Ref = GetNewJobRef(n.Jobno,n.PrimarySite) ;
    SET n.xMainVenue = n.client;
    SET n.xTaxAddress = vCompanyForFinances;

    -- Users stuff
    IF vUserID > -1 THEN

	 --created by User
	 SET n.createdby = vUserID;

      --User Jobs
     CALL LogUserJobs(vUserID,n.Jobno,0);

      --Handler
     IF  EXISTS (SELECT COUNT(*) FROM UserTypesLkp
                 WHERE xUser = vUserID and xUserType = 2) THEN
        SET n.Handler = vUserID;
     END IF;

      --Salesperson
     IF  EXISTS (SELECT COUNT(*) FROM UserTypesLkp
                 WHERE xUser = vUserID and xUserType = 3) THEN
        SET n.Handler = vUserID;
     END IF;

    END IF;

     IF (SELECT QuotesRequireAuthorization FROM RULES WHERE SiteID = n.PrimarySite) THEN
        SET n.AuthorisedForQuotingLimit =
         CASE
           WHEN n.Currency = 0 THEN (SELECT QuotesAuthorizationLimitA FROM RULES WHERE SiteID = n.PrimarySite)
           WHEN n.Currency = 1 THEN (SELECT QuotesAuthorizationLimitB FROM RULES WHERE SiteID = n.PrimarySite)
           WHEN n.Currency = 2 THEN (SELECT QuotesAuthorizationLimitC FROM RULES WHERE SiteID = n.PrimarySite)
           WHEN n.Currency = 3 THEN (SELECT QuotesAuthorizationLimitD FROM RULES WHERE SiteID = n.PrimarySite)
         END;
     END IF;

     SET n.JobCommissionFromVenue = (SELECT JobCommissionFromVenue FROM RULES WHERE SiteID = n.PrimarySite);
     SET n.NewCrewing = (SELECT NewCrewing FROM RULES WHERE SiteID = n.PrimarySite);
  ELSEIF UPDATING THEN

-- user jobs
   IF vUserID > -1 THEN
     CALL LogUserJobs(vUserID,o.Jobno,0);
   END IF;

-- job authorization
  IF (NOT EQUIVALENT(o.AuthorisedForQuotingLimit,n.AuthorisedForQuotingLimit)) AND (vUserID > -1) THEN
     SET n.xAuthorisedForQuotingBy = vUserID;
     SET n.xAuthorisedForQuotingDate = CURRENT_TIMESTAMP;
  END IF;

-- Enhanced Crewing downgrade check
  IF (o.NewCrewing IS NULL) AND (n.NewCrewing = FALSE) THEN
     DECLARE vAllowEnhancedCrewingDowngrade BOOL;
     SET vAllowEnhancedCrewingDowngrade = (SELECT OPTION('AllowEnhancedCrewingDowngrade') = 'True' FROM #DUMMY);

     IF NOT vAllowEnhancedCrewingDowngrade THEN
        SIGNAL 'Enhanced Crewing is being changed to Legacy Crewing on this Job - how are you doing this?';
     END IF;
  END IF;

-- warehouse sites
  IF NOT EQUIVALENT(o.PrimarySite,n.PrimarySite) THEN
    SET n.WarehouseSites = (SELECT WarehouseSites FROM Sites WHERE IDX = n.PrimarySite);
  END IF;

-- users again
  IF vUserID > -1 THEN
     SET n.ModifiedBy = vUserID;
  END IF;

  SET n.ModifiedDate = Current_Timestamp;

 -- status  and  users
  IF o.status <> n.status THEN

    IF o.status < 3 and n.status > 2 THEN

      IF vUserID > -1 THEN
         IF UserHasFeatureAccess(vUserID,'spConfirmJobs') = 0 THEN
            SIGNAL 'You do not have permission to Confirm Jobs.';
         ELSE
            SET n.ConfirmedBy = n.ModIFiedBy;
         END IF;
      END IF;

      SET n.ConfirmedDate = Current_TimeStamp;

    ELSEIF o.status > 2 and n.status < 3 THEN

      SET n.ConfirmedBy = null;
      SET n.ConfirmedDate = null;

    END IF;
  END IF;  -- status  and  users

-- dates
  IF n."Due Out" <> o."Due Out"  AND n."Due Out" >= n."Due Back" THEN
    SET n."Due Back"  = cast(n."Due Back" as Double precision) + (cast(n."Due Out" as Double precision) - cast(o."Due Out" as Double precision)) ;
  END IF;

  IF n."Due Back" <> o."Due Back"  AND n."Due Back" <= n."Due Out" THEN
    SET n."Due Out"  = cast(n."Due Out" as Double precision) - (cast(o."Due Back" as Double precision) - cast(n."Due Back" as Double precision)) ;
  END IF;


-- client change

   IF (NOT EQUIVALENT(o.client, n.client)) THEN
          -- store single record in memory table for efficiency
     SELECT * INTO #tmp FROM Company WHERE CompanyCounter = n.client;

     SET n."Name" = (SELECT CompanyName FROM #tmp);
     SET n.Address1 = (SELECT Address1 FROM #tmp);
     SET n.Address2 = (SELECT Address2 FROM #tmp);
     SET n.Address3 = (SELECT Address3 FROM #tmp);
     SET n.Town = (SELECT Town FROM #tmp);
     SET n.PostCode = (SELECT PostCode FROM #tmp);
     SET n.County = (SELECT County FROM #tmp);
     SET n.Country = (SELECT Country FROM #tmp);
     SET n.Telephone = (SELECT MainTelephone FROM #tmp);
     SET n.Facsimile = (SELECT MainFax FROM #tmp);
     SET n.Cellular = (SELECT Cellular FROM #tmp);
     IF (o.Client IS NULL) THEN
       SET n.xMainVenue = n.client;
     END IF;

     -- sync eqlists
     UPDATE eqlists SET
     client_no = n.client
     WHERE
     job_no = n.jobno;

   END IF;

   IF (NOT EQUIVALENT(o.Client, n.Client)) OR
      (NOT EQUIVALENT(o.xMainVenue, n.xMainVenue)) OR
      (NOT EQUIVALENT(o.JobCommissionFromVenue, n.JobCommissionFromVenue)) THEN -- xMainVenue only changing
      SET n.xTaxAddress = vCompanyForFinances;
   END IF;

   DECLARE vSmallAmount DOUBLE PRECISION;

   SET vSmallAmount = (SELECT JobInvoicedToleranceAmount FROM RULES WHERE SiteID = n.PrimarySite);
-- Profit Fields

    SET n.PredictedQuoteStatusProfit = RoundToTwoDP(n.PredictedEquipmentQuoteIncome + n.PredictedCrewQuoteIncome + n.PredictedTransportQuoteIncome + n.PredictedMiscQuoteIncome
                                      -n.AnticpatedEquipmentQuoteCosts - n.AnticpatedCrewQuoteCosts - n.AnticpatedTransportQuoteCosts - n.AnticpatedMiscQuoteCosts) ;

    SET n.PredictedProvisionalStatusProfit = RoundToTwoDP( n.PredictedEquipmentProvisionalIncome + n.PredictedCrewProvisionalIncome + n.PredictedTransportProvisionalIncome + n.PredictedMiscProvisionalIncome
                                      -n.AnticpatedEquipmentProvisionalCosts - n.AnticpatedCrewProvisionalCosts - n.AnticpatedTransportProvisionalCosts - n.AnticpatedMiscProvisionalCosts) ;

    SET n.PredictedConfirmedPlusStatusProfit =  RoundToTwoDP(n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome
                                      -n.AnticpatedEquipmentConfirmedPlusCosts - n.AnticpatedCrewConfirmedPlusCosts - n.AnticpatedTransportConfirmedPlusCosts - n.AnticpatedMiscConfirmedPlusCosts) ;

    SET n.AccountingProfit = RoundToTwoDP(n.InvoicedEqlist + n.InvoicedCrew + n.InvoicedTransport + n.InvoicedMisc
                            -n.OrderedEqlist - n.OrderedCrew - n.OrderedTransport - n.OrderedMisc);

    --legacy Invoiced field
    IF (n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome) <> 0 THEN
      SET n.Invoiced = (n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome) -
                     (n.InvoicedEqlist + n.InvoicedCrew + n.InvoicedTransport + n.InvoicedMisc) <= vSmallAmount ;
      ELSE
      SET n.Invoiced = FALSE;
    END IF;

    -- new InvoiceState field ( TJobInvoiceState = (jisNothingToInvoice, jisDoNotInvoice,jisNothingInvoicedYet, jisPartiallyInvoiced, jisFullyInvoiced) )
    IF EQUIVALENT(o.InvoiceState,n.InvoiceState) OR (n.InvoiceState IS NULL) THEN  -- i.e. NOT use use manually setting it  or user is CLEARING it for auto reset

      SET n.InvoiceState =
       CASE
        WHEN n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome = 0 THEN 0

        WHEN (n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome <> 0)
              AND (n.InvoicedEqlist + n.InvoicedCrew + n.InvoicedTransport + n.InvoicedMisc = 0) THEN 2

        WHEN (n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome <> 0)
              AND (n.InvoicedEqlist + n.InvoicedCrew + n.InvoicedTransport + n.InvoicedMisc <> 0)
              AND RoundToTwoDP(ABS(
              (n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome) -
              (n.InvoicedEqlist + n.InvoicedCrew + n.InvoicedTransport + n.InvoicedMisc)
               )) > vSmallAmount THEN 3

        WHEN (n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome <> 0)
              AND (n.InvoicedEqlist + n.InvoicedCrew + n.InvoicedTransport + n.InvoicedMisc <> 0)
              AND RoundToTwoDP(ABS(
               (n.PredictedEquipmentConfirmedPlusIncome + n.PredictedCrewConfirmedPlusIncome + n.PredictedTransportConfirmedPlusIncome + n.PredictedMiscConfirmedPlusIncome) -
               (n.InvoicedEqlist + n.InvoicedCrew + n.InvoicedTransport + n.InvoicedMisc)
                )) <= vSmallAmount THEN 4
        END;
     END IF;

  END IF;   -- INSERTING / UPDATING

  -- Commissions

 IF (SELECT xVenueCommission FROM RULES WHERE SiteID = n.PrimarySite) IN (3,4) THEN  --  TVenueCommissionApplication = (vcaNever, vcaManual, vcaAutomatic, vcaPromptForJob, vcaAdvancedForJob);

    DECLARE vJobCommissionMode TINYINT;
    DECLARE vCompanyForCommissions INT;

    SET vJobCommissionMode = (SELECT JobCommissionMode FROM RULES WHERE SiteID = n.PrimarySite);

    IF ((vJobCommissionMode > 0) AND (NOT EQUIVALENT(o.xMainVenue,n.xMainVenue))) -- commission as purchase cost
       OR  --   commission as invoice discount
       ((NOT EQUIVALENT(o.client,n.client) AND (NOT n.JobCommissionFromVenue)) OR
        (NOT EQUIVALENT(o.xMainVenue,n.xMainVenue) AND (n.JobCommissionFromVenue)) OR
        (UPDATING AND NOT EQUIVALENT(o.JobCommissionFromVenue,n.JobCommissionFromVenue))) THEN
     -- get default commissions
     DECLARE vEqlistCommission DOUBLE PRECISION;
     SET vEqlistCommission = 0;

     IF vJobCommissionMode = 0 THEN -- TJobCommissionMode = (jcmAsInvoiceDiscount, jcmAsVenuePurchaseCost, jcmAsClientPurchaseCost)

        IF n.JobCommissionFromVenue THEN
           SET vCompanyForCommissions = n.xMainVenue;
           ELSE
           SET vCompanyForCommissions = n.client;
        END IF;

     ELSEIF vJobCommissionMode = 1 THEN
            SET vCompanyForCommissions = n.xMainVenue;
     ELSE
            SET vCompanyForCommissions = n.client;
     END IF;

     SELECT RentalVenueCommission,CrewVenueCommission,TransportVenueCommission, MiscVenueCommission
     INTO #DefaultCommissions
     FROM Company
     WHERE
     CompanyCounter = vCompanyForCommissions;

     SET vEqlistCommission = COALESCE((SELECT RentalVenueCommission FROM #DefaultCommissions),0);
          //   signal vEqlistCommission;
     SET n.RentalIncomeCommission = vEqlistCommission;
     SET n.RentalExpenditureCommission = vEqlistCommission;
     SET n.CrewIncomeCommission = COALESCE((SELECT CrewVenueCommission FROM #DefaultCommissions),0);
     SET n.CrewExpenditureCommission = COALESCE((SELECT CrewVenueCommission FROM #DefaultCommissions),0);
     SET n.TransportIncomeCommission = COALESCE((SELECT TransportVenueCommission FROM #DefaultCommissions),0);
     SET n.TransportExpenditureCommission = COALESCE((SELECT TransportVenueCommission FROM #DefaultCommissions),0);
     SET n.MiscIncomeCommission = COALESCE((SELECT MiscVenueCommission FROM #DefaultCommissions),0);
     SET n.MiscExpenditureCommission = COALESCE((SELECT MiscVenueCommission FROM #DefaultCommissions),0);

     -- sync eqlists
     UPDATE eqlists SET
     IncomeCommission = vEqlistCommission,
     ExpenditureCommission = vEqlistCommission
     WHERE
     job_no = n.jobno;
   END IF;
  END IF;
END;

