/* trName2AFTER */
CREATE TRIGGER "trName2AFTER"
AFTER INSERT, UPDATE ON "Name2"
REFERENCING OLD AS o NEW AS n
BEGIN
Declare FOUND Boolean;
SET FOUND = FALSE;
IF EXISTS
(
   SELECT TOP 1 IDX FROM "EmailAddressWareHouse"
   WHERE
   XLink=N.NameCounter
   AND  SourceTable='Name2'
   AND SourceField ='NameCounter'
)
   THEN
   SET FOUND = TRUE;
END IF;

IF NOT FOUND THEN
 IF COALESCE(n.Email,'') <> '' AND COALESCE(n.Fullname,'') <> '' THEN
  INSERT INTO "EmailAddressWareHouse"
  (FullName, Email, XLink, SourceTable, SourceField)
   VALUES
  (N.FullName, N.Email, N.NameCounter, 'Name2', 'NameCounter');
  END IF;
END IF;

IF FOUND THEN

  IF COALESCE(o.Email,'') <> ''  AND N.Email = '' THEN
    DELETE FROM EmailAddressWareHouse
    WHERE
    XLink=N.NameCounter
    AND  SourceTable='Name2'
    AND SourceField ='NameCounter';
  END IF;

  UPDATE "EmailAddressWareHouse"
   SET FullName =  N.FullName, Email= N.Email
  WHERE
   XLink=N.NameCounter
   AND  SourceTable='Name2'
   AND SourceField ='NameCounter';

END IF;

 IF UPDATING THEN

  IF N.Crew = FALSE AND O.Crew = True THEN
    DELETE FROM CrewPeopleLkp
     WHERE xPerson = o.NameCounter;
  END IF;

  IF NOT EQUIVALENT(o.Email, n.Email) THEN
     UPDATE Contacts SET
     Email = n.Email
     WHERE
     Person = N.NameCounter
     AND ((Email = o.Email) OR (Email IS NULL));
  END IF;

  IF NOT EQUIVALENT(o.Mobile, n.Mobile) THEN
     UPDATE Contacts SET
     MobileNumber = n.Mobile
     WHERE
     Person = N.NameCounter
     AND ((MobileNumber = o.Mobile) OR (MobileNumber IS NULL));
  END IF;

  IF NOT EQUIVALENT(o.Telephone, n.Telephone) THEN
     UPDATE Contacts SET
     TelephoneNumber = n.Telephone
     WHERE
     Person = N.NameCounter
     AND ((TelephoneNumber = o.Telephone) OR (TelephoneNumber IS NULL));
  END IF;


END IF;
END;

