/* trNoteBookBEFORE */
CREATE TRIGGER "trNoteBookBEFORE"
BEFORE INSERT,  UPDATE of OutDate, BackDate ON NoteBook
REFERENCING OLD AS o NEW AS n
BEGIN

IF INSERTING THEN

  DECLARE vExtraHireDays INT;

  SET vExtraHireDays = (SELECT CAST(ExtraHireDays AS TINYINT) FROM Rules WHERE SiteID = n.Site);  -- cast BOOL as 0 or 1

  SET n.OutDate = CURRENT_DATE + Interval '0' Day;
  SET n.backdate = n.OutDate + INTERVAL '47:59' HOUR TO MINUTE;
  SET n.RecordedDate = CURRENT_TIMESTAMP;
  SET n.NoteRef = 'NR' + CAST(n.idx AS VARCHAR(10));
  SET n.Days = DateDiff('dd', n.OutDate,n.backdate) + vExtraHireDays;

ELSEIF UPDATING THEN

  IF NOT EQUIVALENT(n.backdate , o.backdate) THEN
    SET n.backDate = CAST(CAST(n.backDate AS DATE) AS TIMESTAMP);
    SET n.backDate = n.backDate + INTERVAL '23:59' HOUR TO MINUTE;
  END IF ;

  IF NOT EQUIVALENT(n.OutDate , o.OutDate) THEN
    SET n.OutDate = CAST(CAST(n.OutDate AS DATE) AS TIMESTAMP);
  END IF;

  IF NOT EQUIVALENT(n.backdate , o.backdate) AND (n.backdate < n.OutDate) THEN
    SET n.OutDate = CAST(CAST(n.backdate - INTERVAL '1' DAY AS DATE) AS TIMESTAMP);
  END IF ;

  IF NOT EQUIVALENT(n.OutDate , o.OutDate) AND (n.backdate < n.OutDate) THEN
    SET n.backdate = n.OutDate  + INTERVAL '47:59' HOUR TO MINUTE;
  END IF ;

  IF DateDiff('dd', n.OutDate, n.backdate) = 0 THEN
    SET n.Days = 1;
  ELSE
    SET n.Days = DateDiff('dd', n.OutDate, n.backdate);
  END IF ;

END IF;

END;

