/* trOperationsDetailAFTER */
CREATE TRIGGER "trOperationsDetailAFTER"
AFTER INSERT,  DELETE, UPDATE OF Quantity  ON OperationsDetail
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vSuspendTriggers BOOL;
SET vSuspendTriggers = (SELECT OPTION('TriggerSuspend') = 'True' FROM #DUMMY);

IF (NOT vSuspendTriggers) THEN

DECLARE vAuditRefString VARCHAR(30);
DECLARE vSortLineRef INT;
DECLARE vOpsType INT;
DECLARE vCategory INT;
DECLARE vListType TINYINT;
DECLARE vEqlistClass TINYINT;
DECLARE vSite TINYINT;
DECLARE vWarehouse INT;
DECLARE vCurrency TINYINT;
DECLARE vStockInAuditKey INT;
DECLARE vStockOutAuditKey INT;
DECLARE vAuditLinksCount INT;
DECLARE vNewAuditID INT;
DECLARE vTransferFromAuditID INT;
DECLARE vNewWHAuditID INT;
DECLARE vTransferFromWHAuditID INT;
DECLARE vStockInQuantity INT;
DECLARE vStockOutQuantity INT;
DECLARE vDisposedQty INT;
DECLARE vChangedQty INT;
DECLARE vMaxChangedQty INT;
DECLARE vType INT;
DECLARE vNegativeMultiplier SHORTINT;
DECLARE vEqlistUnitPrice MONEY;
DECLARE vCurrentUnitCost MONEY;
DECLARE vTransferOwner BOOL;
DECLARE vSalesAllocationLine INT;
DECLARE vSalesAllocationQty INT;
DECLARE vGoodsInLineID INT;
DECLARE vDispatchLineID INT;
DECLARE vTrackChangedQty INT;

SET vNegativeMultiplier = -1;

IF INSERTING OR UPDATING THEN
	SET vSortLineRef = n.xEqlistLine;
	SET vOpsType = n.OpsType;
ELSE
	SET vSortLineRef = O.xEqlistLine;
	SET vOpsType = o.OpsType;
END IF;


IF INSERTING THEN
	--sync Splits
	IF n.IsASplit AND n.OpsType < 5 THEN
		UPDATE OperationsDetail SET
		IsASplit = TRUE
		WHERE
		xEqlistLine = vSortLineRef
		AND IsASplit = FALSE
		AND OpsType = n.OpsType;
	END IF;
END IF;


IF UPDATING THEN
	IF (n.OpsType IN (1,2,3,4)) AND (n.Quantity = 0) AND (O.CASEID <> '') THEN

		DECLARE vIsRoadCase BOOLEAN;

		SET vIsRoadCase =  COALESCE((SELECT COALESCE(H.RoadCase,FALSE) OR H.Category = 1
									FROM Sort S
									INNER JOIN Hetype H ON
									S.Type = H.Type
									WHERE
									S.LineRef = n.xEqlistLine
									AND S.Virt = FALSE),FALSE);

		IF vIsRoadCase THEN
			UPDATE OperationsDetail SET
			CASEID = ''
			WHERE
			xOperation = o.xOperation
			AND CASEID = o.CASEID
			AND IDX <> n.IDX;

    SET n.CASEID = '';
		END IF;

	END IF;
END IF;

-- sync Sort.nx1
IF NOT (DELETING AND o.Quantity = 0) THEN -- only if we are not clearing zero lines
	IF vOpsType = 1 THEN
		UPDATE "Sort" S SET S.CarnetQty = COALESCE((SELECT SUM(D.Quantity)
													FROM
													OperationsDetail D
													WHERE
													D.xEqlistLine =  vSortLineRef
													AND D.OpsType IN (1)),0)
													WHERE
													S.LineRef = vSortLineRef;

	ELSEIF vOpsType IN (2,3,4)  THEN
		UPDATE "Sort" S SET S.PreppedQty =
                          COALESCE((SELECT SUM(D.Quantity)
													FROM
													OperationsDetail D
													WHERE
													D.xEqlistLine =  vSortLineRef
													AND D.OpsType IN (2,3,4)),0)
													WHERE
			                    S.LineRef = vSortLineRef;

	ELSEIF vOpsType = 5  THEN
		UPDATE "Sort" S SET S."Out" =
                          COALESCE((SELECT SUM(D.Quantity)
													FROM
													OperationsDetail D
													WHERE
													D.xEqlistLine =  vSortLineRef
													AND D.OpsType IN (5)),0)
													WHERE
													S.LineRef = vSortLineRef;

	ELSEIF vOpsType = 6  THEN
		UPDATE "Sort" S SET S."Back" =
                          COALESCE((SELECT SUM(D.Quantity)
													FROM
													OperationsDetail D
													WHERE
													D.xEqlistLine =  vSortLineRef
													AND D.OpsType IN (6)),0)
													WHERE
													S.LineRef = vSortLineRef;

	ELSEIF vOpsType = 7  THEN
		UPDATE "Sort" S SET S."CheckedInQty" =
                          COALESCE((SELECT SUM(D.Quantity)
													FROM
													OperationsDetail D
													WHERE
													D.xEqlistLine =  vSortLineRef
													AND D.OpsType IN (7)),0)
                     +
                          COALESCE((SELECT SUM(W.Quantity)
                          FROM WhAudit W
                          WHERE
                          W.xOperationDetail = COALESCE(n.xMasterLine, o.xMasterLine)
                          AND W.KeepAuditType IN (1,3,6,7)
                          AND W.Quantity > 0),0)
/*
  TKeepAuditType =
  (katNone,
    katItemKeepLoan, // this is an explicit Keep on a Loan Return
    katItemSwap, // only on Loan Returns
    katTypeKeepLoan, // this is an explicit Keep on a Loan Return
    katTypeSwap,   // katTypeSwap must have been added for reasons of symmetry but it's a nonsensical option. You can't "swap" quantities. So do not use. Leaving in for legacy data in case we ever wrote it to the table
    katItemSwapKeep, // only on Loan Returns, this is the keep bit of the Swap
    katItemKeepHire, // a Warehouse mismatch on a Rental Return
    katTypeKeepHire // a Warehouse mismatch on a Rental Return
    );
*/

                          WHERE
													S.LineRef = vSortLineRef;
     END IF;
END IF;

/************* Rental Consumables, Sales, Sales Orders and Stock Transfers **************/

-- DELETES are covered by RI

IF (INSERTING OR UPDATING) THEN
	IF (SELECT COUNT(*) > 0
		FROM Sort
		WHERE
		LineRef = vSortLineRef
		AND (xCat < 0 OR ListType = 6)
		AND RecType IN (1,2,3,6,7,11,14)) THEN

    SELECT E.*
    INTO #Eqlists
    FROM Sort S
    INNER JOIN  Eqlists E
    ON S.Eqlno = E.Eql_no
    WHERE
    S.LineRef = vSortLineRef;

		SET vEqlistClass = GetEqlistClass((SELECT Eql_no FROM #Eqlists));
		SET vListType = (SELECT ListType FROM #Eqlists);
    SET vTransferOwner = (SELECT Archived FROM #Eqlists);

    IF  (vEqlistClass = 0) AND (vListType IN (3,4)) AND (n.OpsType IN (5,6)) THEN-- Loan records that are receiving in or sending back to/from borrowing warehouse
        SET vWarehouse = (SELECT xTransferInWarehouse FROM #Eqlists);
    ELSEIF (vListType = 6) AND (n.OpsType = 5) THEN --  Transfer List doing a Receive In
        SET vWarehouse = (SELECT xTransferInWarehouse FROM #Eqlists);
    ELSE
        SET vWarehouse = (SELECT MainSite FROM #Eqlists);
    END IF;

		SET vSite = GetSiteIDFromWarehouseID(vWarehouse);
	--	SET vCurrency = (SELECT xCurrency FROM Sites WHERE IDX = vSite);
		SET vCurrency = (SELECT PriceMode FROM #Eqlists);
		SET vChangedQty = n.Quantity - COALESCE(o.Quantity,0);
		SET vEqlistUnitPrice = (SELECT CASE WHEN ChargeQuantity > 0 THEN Price / ChargeQuantity ELSE Daily END FROM Sort WHERE LineRef = vSortLineRef);
    SET vCurrentUnitCost = (SELECT CurrentCostPrice FROM Sort WHERE LineRef = vSortLineRef);


		IF (vEqlistClass = 0 AND vListType IN (0,3,4) AND n.OpsType IN (2,5,6,7)) OR -- Rentals and Loans
       (vEqlistClass = 1 AND vListType IN (0,1,2) AND n.OpsType IN (5,6)) OR -- Sales and Sales Orders
       (vListType = 6) THEN -- Stock Transfers

			SET vType = (SELECT Type FROM Sort WHERE LineRef = vSortLineRef);

      /***************Stock Transfers***************/
		IF (vListType = 6) THEN
			IF n.OpsType = 2 THEN
				IF vEqlistClass = 0 THEN
					SET vAuditRefString = 'Rental Stock Transfer Out';
				ELSE
					SET vAuditRefString = 'Sales Stock Transfer Out';
				END IF;
			ELSE -- OpsType = 5
				IF vEqlistClass = 0 THEN
					SET vAuditRefString = 'Rental Stock Transfer In';
				ELSE
					SET vAuditRefString = 'Sales Stock Transfer In';
				END IF;
			END IF;

			SET vAuditLinksCount = (SELECT COUNT(*) FROM Audit A
									                WHERE
									                A.xWarehouseOpLine = n.IDX);

			IF vAuditLinksCount = 0 THEN --there is NO a record in the Audit trail, so STOCK OUT

				IF n.OpsType = 2 THEN
					IF vTransferOwner THEN
						SET vNewAuditID = CreateAuditRecord(vType, vNegativeMultiplier * vChangedQty, CURRENT_DATE, 0,'',vAuditRefString,vCurrency, 4, vSite, -1, -1,-1, n.IDX,1);
					ELSE
						SET vNewAuditID = CreateAuditRecord(vType, 0, CURRENT_DATE, 0,'',vAuditRefString,vCurrency, 3, vSite, -1, -1,-1, n.IDX,1);
					END IF;

					CreateWhAuditRecord(vType, vNegativeMultiplier * vChangedQty, vWarehouse, vSite ,3, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

				ELSEIF n.OpsType = 5 THEN
					SET vTransferFromAuditID = COALESCE((SELECT TOP 1 AuditKey FROM Audit A
                                                           INNER JOIN OperationsDetail O
                                                           ON A.xWarehouseOpLine = O.IDX
                                                           WHERE
                                                           O.xEqlistLine = vSortLineRef),-1);
					IF vTransferOwner THEN
						SET vNewAuditID = CreateAuditRecord(vType, vChangedQty, CURRENT_DATE, 0,'',vAuditRefString,vCurrency, 4, vSite, -1, -1,vTransferFromAuditID, n.IDX,0);
					ELSE
						SET vNewAuditID = CreateAuditRecord(vType, 0, CURRENT_DATE, 0,'',vAuditRefString,vCurrency, 3, vSite, -1, -1, vTransferFromAuditID, n.IDX,0);
					END IF;

					IF vTransferFromAuditID > -1 THEN
						UPDATE Audit SET xTransferTo = vNewAuditID
						WHERE
						AuditKey = vTransferFromAuditID;
					END IF;

					SET vTransferFromWHAuditID = COALESCE((SELECT TOP 1 IDX FROM WhAudit WHERE xAudit = vTransferFromAuditID),-1);

					SET vNewWHAuditID = CreateWhAuditRecord(vType, vChangedQty, vWarehouse, vSite ,3, -1, vTransferFromWHAuditID ,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

					IF vTransferFromWHAuditID > -1 THEN
						UPDATE WhAudit SET xTransferTo = vNewWHAuditID
						WHERE
						IDX = vTransferFromWHAuditID;
					END IF;

				END IF;

			ELSE -- user is Adjusting the Qty, so  increase or decrease the matching audit record accordking
				IF n.OpsType = 2 THEN
					SET vChangedQty = vChangedQty * vNegativeMultiplier;
				END IF;

				IF vTransferOwner THEN
					UPDATE AUDIT SET Quantity = Quantity + vChangedQty WHERE xWarehouseOpLine = n.IDX;
				END IF;

				UPDATE WhAUDIT SET Quantity = Quantity + vChangedQty WHERE xAudit = (SELECT AuditKey FROM AUDIT WHERE xWarehouseOpLine = n.IDX);

			END IF;

		END IF;

			/***************RENTAL Consumables***************/
		IF (vEqlistClass = 0) AND (vListType <> 6) THEN  -- no Transfers

			SET vAuditLinksCount = (SELECT COUNT(*) FROM Audit A
									WHERE
									A.xWarehouseOpLine = n.IDX);

			IF vListType IN (3,4) THEN	--loans
				IF n.OpsType = 2 THEN
					SET vAuditRefString = 'Consumable Loan Dispatch';
				ELSEIF  n.OpsType = 5 THEN
					SET vAuditRefString = 'Consumable Loan Receive';
				ELSEIF  n.OpsType = 6 THEN
					SET vAuditRefString = 'Consumable Loan Return';
				ELSEIF n.OpsType = 7 THEN
					SET vAuditRefString = 'Consumable Loan Back';
				END IF;
			ELSE
				IF n.OpsType = 5 THEN
					SET vAuditRefString = 'Consumable Dispatch';
				ELSE
					SET vAuditRefString = 'Consumable Return';
				END IF;
			END IF;

			IF (vListType IN (3,4) AND n.OpsType IN (2,6)) OR (vListType IN (0) AND n.OpsType = 5) THEN  -- Dispatch Loan or Rental

				IF vAuditLinksCount = 0 THEN --there is NO a record in the Audit trail, so STOCK OUT

					SET vNewAuditID = CreateAuditRecord(vType, vNegativeMultiplier * vChangedQty, CURRENT_DATE, vEqlistUnitPrice,'',vAuditRefString,vCurrency, 2, vSite, -1, -1,-1, n.IDX,6);
					CreateWhAuditRecord(vType, vNegativeMultiplier * vChangedQty, vWarehouse, vSite ,2, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

				ELSE -- user is Adjusting the Qty, so  increase or decrease the matching audit record accordking

					UPDATE AUDIT SET Quantity = Quantity + vNegativeMultiplier * vChangedQty WHERE xWarehouseOpLine = n.IDX;
					UPDATE WhAUDIT SET Quantity = Quantity + vNegativeMultiplier * vChangedQty WHERE xAudit = (SELECT AuditKey FROM AUDIT WHERE xWarehouseOpLine = n.IDX);

				END IF;

			ElSEIF (vListType IN (3,4) AND n.OpsType IN (5,7)) OR (vListType IN (0) AND n.OpsType = 6) THEN -- Return
				IF vAuditLinksCount = 0 THEN --there is NO a record in the Audit trail, so STOCK IN

					SET vNewAuditID = CreateAuditRecord(vType,  vChangedQty, CURRENT_DATE, vEqlistUnitPrice,'',vAuditRefString,vCurrency, 1, vSite, -1, -1,-1, n.IDX,0);
					CreateWhAuditRecord(vType, vChangedQty, vWarehouse, vSite ,1, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

				ELSE  -- user is Adjusting the Qty, so  increase or decrease the matching audit record accordking

					UPDATE AUDIT SET Quantity = Quantity + vChangedQty WHERE xWarehouseOpLine = n.IDX;
					UPDATE WhAUDIT SET Quantity = Quantity + vChangedQty WHERE xAudit = (SELECT AuditKey FROM AUDIT WHERE xWarehouseOpLine = n.IDX);

				END IF; -- of Audit link test

			END IF; -- Dispatch vs Return
		END IF; --RENTAL Consumables

			 /***************SALES Orders***************/
		IF (vEqlistClass = 1 AND vListType IN (1,2)) THEN

			SET vAuditLinksCount = (SELECT COUNT(*) FROM Audit A
									WHERE
									A.xWarehouseOpLine = n.IDX
									AND A.Quantity <> 0);

			IF n.OpsType = 5 THEN  -- (Stock IN)
				IF vAuditLinksCount = 0 THEN --there is NO a record in the Audit trail, so STOCK IN

					IF (SELECT COUNT(*) FROM SubData WHERE Subhline = n.xEqlistLine) > 0 THEN -- allocated Sales Order for Job
						DECLARE cSubData CURSOR FOR
						SELECT EqlLine, Q
						FROM SubData
						WHERE
						Subhline = n.xEqlistLine;

						OPEN cSubData;
            TRY

						FETCH FIRST FROM cSubData INTO vSalesAllocationLine, vSalesAllocationQty;

						WHILE @@FETCH_STATUS = 0 DO

              SET vSalesAllocationQty = GetMinInt(vSalesAllocationQty, vChangedQty);

              IF vSalesAllocationQty > 0 THEN
                 SET vNewAuditID = CreateAuditRecord(vType, vSalesAllocationQty, CURRENT_DATE, vEqlistUnitPrice,'','Sales Order Stock In',vCurrency, 1, vSite, -1, -1,-1, n.IDX,0);

							   UPDATE AUDIT SET
							   xSalesAllocationLine = vSalesAllocationLine
                 WHERE
				         AuditKey = vNewAuditID;

							   CreateWhAuditRecord(vType, vSalesAllocationQty, vWarehouse, vSite ,1, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);
              END IF;

							SET vChangedQty = vChangedQty - vSalesAllocationQty;

							FETCH NEXT FROM cSubData INTO vSalesAllocationLine, vSalesAllocationQty;
						END WHILE;

						CLOSE cSubData;

            CATCH TRUE
            CLOSE cSubData;
            SIGNAL ERROR_MESSAGE;
            END;

						-- if there are "unlinked" Qtys then create an audit record for that
						IF vChangedQty > 0 THEN
							SET vNewAuditID = CreateAuditRecord(vType, vChangedQty, CURRENT_DATE, vEqlistUnitPrice,'','Sales Order Stock In',vCurrency, 1, vSite, -1, -1,-1, n.IDX,0);
							CreateWhAuditRecord(vType, vChangedQty, vWarehouse, vSite ,1, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);
						END IF;

					ELSE

						SET vNewAuditID = CreateAuditRecord(vType, vChangedQty, CURRENT_DATE, vEqlistUnitPrice,'','Sales Order Stock In',vCurrency, 1, vSite, -1, -1,-1, n.IDX,0);
						CreateWhAuditRecord(vType, vChangedQty, vWarehouse, vSite ,1, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

					END IF;
				ELSE  -- user is Adjusting the Qty, so  increase or decrease the matching audit record accordking

					IF (SELECT Quantity + vChangedQty < DisposedQty FROM Audit WHERE xWarehouseOpLine = n.IDX) THEN
						SIGNAL 'Cannot reduce Sales Order Stock In Qty to a value lower than the Disposed Qty for the Audit record';
					END IF;

					UPDATE AUDIT SET Quantity = Quantity + vChangedQty WHERE xWarehouseOpLine = n.IDX;
					UPDATE WhAUDIT SET Quantity = Quantity + vChangedQty WHERE xAudit = (SELECT AuditKey FROM AUDIT WHERE xWarehouseOpLine = n.IDX);

				END IF;
			ElSE -- Order Rejection (Stock OUT)

				IF vAuditLinksCount = 0 THEN --there is NO a record in the Audit trail, so STOCK OUT

					 -- get all the Stock IN records so that we can link to them
					DECLARE cAuditRecords CURSOR FOR
					SELECT A.AuditKey, A.Quantity, A.DisposedQty FROM OperationsDetail O
					INNER JOIN Audit A
					ON O.IDX = A.xWarehouseOpLine
					WHERE
					O.xEqlistLine = vSortLineRef
					AND O.OpsType = 5
					AND A.DisposedQty < A.Quantity
					ORDER BY
					AuditKey DESC;

					OPEN cAuditRecords;
          TRY

					FETCH FIRST FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty ;

					IF @@FETCH_STATUS = 0 THEN -- Sales Order Stock In records found
						WHILE @@FETCH_STATUS = 0 AND vChangedQty > 0 DO

							SET vMaxChangedQty = GetMININT(vChangedQty, vStockInQuantity - vDisposedQty);
							SET vChangedQty = vChangedQty - vMaxChangedQty;
							SET vNewAuditID = CreateAuditRecord(vType, vNegativeMultiplier * vMaxChangedQty, CURRENT_DATE,vEqlistUnitPrice, '', 'Sales Order Send Back', vCurrency, 2, vSite, vStockInAuditKey, -1,-1, n.IDX,7);

							CreateWhAuditRecord(vType, vNegativeMultiplier * vMaxChangedQty, vWarehouse, vSite, 2, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

							FETCH NEXT FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty ;
						END WHILE;

					ELSE -- create "send back" records with no vStockInAuditKey link

						SET vNewAuditID = CreateAuditRecord(vType, vNegativeMultiplier * vChangedQty, CURRENT_DATE, vEqlistUnitPrice,'','Sales Order Send Back',vCurrency, 2, vSite, -1, -1,-1, n.IDX,7);
						CreateWhAuditRecord(vType, vNegativeMultiplier * vChangedQty, vWarehouse, vSite ,2, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

					END IF;

					CLOSE cAuditRecords;

          CATCH TRUE
          CLOSE cAuditRecords;
          SIGNAL ERROR_MESSAGE;
          END;

				ELSE  -- user is Adjusting the Qty, so  increase or decrease the matching audit record accordking

					UPDATE AUDIT SET Quantity = Quantity + vChangedQty WHERE xWarehouseOpLine = n.IDX;
					UPDATE WhAUDIT SET Quantity = Quantity + vChangedQty WHERE xAudit = (SELECT AuditKey FROM AUDIT WHERE xWarehouseOpLine = n.IDX);

				END IF;	-- Audit Link test
			END IF; -- Stock IN vs Goods Rejected
	    END IF; --SALES Orders

			 /***************SALES Lists***************/
		IF (vEqlistClass = 1 AND vListType IN (0)) THEN
			IF n.OpsType = 5 THEN -- Sales Dispatch
				IF vChangedQty > 0 THEN
						-- Stock Out

        IF UPDATING THEN
					IF ((SELECT COUNT(*) FROM SubData WHERE EqlLine = n.xEqlistLine) > 0) AND
						((SELECT COUNT(*) FROM OperationsDetail WHERE IDX = n.xMasterLine AND OpsType = 4) > 0) THEN -- from an allocated Sales Order for Job

						DECLARE cAuditRecords CURSOR FOR
							SELECT
							A1.AuditKey AS StockInAuditKey, A1.Quantity AS StockInQuantity, A1.DisposedQty AS StockInDisposedQty, A1.xWareHouseOpLine AS GoodsInLineID,
							A2.AuditKey AS StockOutAuditKey, COALESCE(A2.Quantity ,0) AS StockOutQuantity , A2.xWareHouseOpLine AS DispatchLineID
							FROM Audit A1
							LEFT OUTER JOIN Audit A2
							ON A2.xStockIn = A1.AuditKey
							INNER JOIN OperationsDetail O
							ON A1.xWareHouseOpLine = O.IDX
							INNER JOIN Sort S
							ON O.xEqlistLine = S.LineRef
							WHERE
				      A1.Type = vType
				      AND A1.DisposedQty < A1.Quantity
				      AND A1.StockManageOperation = 1
				      AND A1.Currency = vCurrency
							AND A1.xSalesAllocationLine = n.xEqlistLine
							AND S.ListType = 1 -- Job Subhire
				      ORDER BY
				      AuditKey ASC;
					ELSE

						DECLARE cAuditRecords CURSOR FOR
						    SELECT
							  A1.AuditKey AS StockInAuditKey, A1.Quantity AS StockInQuantity, A1.DisposedQty AS StockInDisposedQty, A1.xWareHouseOpLine AS GoodsInLineID,
							  A2.AuditKey AS StockOutAuditKey, COALESCE(A2.Quantity ,0) AS StockOutQuantity , A2.xWareHouseOpLine AS DispatchLineID
						    FROM Audit A1
						    LEFT OUTER JOIN Audit A2
						    ON A2.xStockIn = A1.AuditKey
						    WHERE
						    A1.Type = vType
						    AND A1.DisposedQty < A1.Quantity
						    AND A1.StockManageOperation = 1
						    AND A1.Currency = vCurrency
							  AND A1.xSalesAllocationLine IS NULL
						    ORDER BY
						    AuditKey ASC;

					END IF;

          OPEN cAuditRecords;
          TRY

          SET vTrackChangedQty = vChangedQty;
          -- update existing records in Audit for the OperationsDetail
					FETCH FIRST FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty, vGoodsInLineID,vStockOutAuditKey,  vStockOutQuantity, vDispatchLineID;

					WHILE @@FETCH_STATUS = 0 AND vChangedQty > 0 DO
						IF (vDispatchLineID = n.IDX) THEN
							SET vMaxChangedQty = GetMININT(vChangedQty, vStockInQuantity - vDisposedQty);
				      SET vChangedQty = vChangedQty - vMaxChangedQty;

							UPDATE AUDIT SET Quantity = Quantity - vMaxChangedQty  WHERE AuditKey = vStockOutAuditKey; -- reduce the Audit qty
							UPDATE WhAUDIT SET Quantity = Quantity - vMaxChangedQty WHERE xAudit = vStockOutAuditKey; -- reduce the Whaudit qty

						END IF;

						FETCH NEXT FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty, vGoodsInLineID,vStockOutAuditKey,  vStockOutQuantity, vDispatchLineID;
					END WHILE;

          CLOSE cAuditRecords;

          CATCH TRUE
          CLOSE cAuditRecords;
          SIGNAL ERROR_MESSAGE;
          END;

        END IF; -- UPDATING existing

					IF ((SELECT COUNT(*) FROM SubData WHERE EqlLine = n.xEqlistLine) > 0) AND
						((SELECT COUNT(*) FROM OperationsDetail WHERE IDX = n.xMasterLine AND OpsType = 4) > 0) THEN -- from an allocated Sales Order for Job

						DECLARE cAuditRecords CURSOR FOR
							SELECT
							A1.AuditKey AS StockInAuditKey, A1.Quantity AS StockInQuantity, A1.DisposedQty AS StockInDisposedQty, A1.xWareHouseOpLine AS GoodsInLineID
							FROM Audit A1
							INNER JOIN OperationsDetail O
							ON A1.xWareHouseOpLine = O.IDX
							INNER JOIN Sort S
							ON O.xEqlistLine = S.LineRef
							WHERE
				      A1.Type = vType
				      AND A1.DisposedQty < A1.Quantity
				      AND A1.StockManageOperation = 1
				      AND A1.Currency = vCurrency
							AND A1.xSalesAllocationLine = n.xEqlistLine
							AND S.ListType = 1 -- Job Subhire
				      ORDER BY
				      AuditKey ASC;
					ELSE

						DECLARE cAuditRecords CURSOR FOR
						    SELECT
							  A1.AuditKey AS StockInAuditKey, A1.Quantity AS StockInQuantity, A1.DisposedQty AS StockInDisposedQty, A1.xWareHouseOpLine AS GoodsInLineID
						    FROM Audit A1
						    WHERE
						    A1.Type = vType
						    AND A1.DisposedQty < A1.Quantity
						    AND A1.StockManageOperation = 1
						    AND A1.Currency = vCurrency
							  AND A1.xSalesAllocationLine IS NULL
						    ORDER BY
						    AuditKey ASC;
					END IF;

          OPEN cAuditRecords;
          TRY
          -- now test for available stock in matches for any remainder
          FETCH FIRST FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty, vGoodsInLineID;

					WHILE @@FETCH_STATUS = 0 AND vChangedQty > 0 DO
							SET vMaxChangedQty = GetMININT(vChangedQty, vStockInQuantity - vDisposedQty);
				      SET vChangedQty = vChangedQty - vMaxChangedQty;

				      SET vNewAuditID = CreateAuditRecord(vType, vNegativeMultiplier * vMaxChangedQty, CURRENT_DATE, vEqlistUnitPrice, '', 'Sales Dispatch', vCurrency, 2, vSite, vStockInAuditKey, -1,-1, n.IDX, 6);
						  CreateWhAuditRecord(vType, vNegativeMultiplier * vMaxChangedQty, vWarehouse , vSite, 2, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

						FETCH NEXT FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty, vGoodsInLineID;
					END WHILE;

					CLOSE cAuditRecords;

          CATCH TRUE
          CLOSE cAuditRecords;
          SIGNAL ERROR_MESSAGE;
          END;

					IF vChangedQty > 0 THEN -- create any remaining records.
            IF  (SELECT Quantity - DisposedQty <= 0 FROM Audit WHERE AuditKey = vStockInAuditKey) THEN
                SET vStockInAuditKey = NULL;
            END IF;

						SET vNewAuditID = CreateAuditRecord(vType, vNegativeMultiplier * vChangedQty, CURRENT_DATE, vEqlistUnitPrice, '', 'Sales Dispatch', vCurrency, 2, vSite, vStockInAuditKey, -1,-1, n.IDX, 6);
						CreateWhAuditRecord(vType, vNegativeMultiplier * vChangedQty, vWarehouse , vSite, 2, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);
					END IF;
				ELSE
					-- Undo Stock Outs
					DECLARE cAuditRecords CURSOR FOR

					SELECT
					A1.AuditKey AS StockInAuditKey, A1.Quantity AS StockInQuantity, A1.DisposedQty AS StockInDisposedQty, A1.xWareHouseOpLine AS GoodsInLineID,
					A2.AuditKey AS StockOutAuditKey, COALESCE(A2.Quantity ,0) AS StockOutQuantity , A2.xWareHouseOpLine AS DispatchLineID
					FROM Audit A1
					LEFT OUTER JOIN Audit A2
					ON A2.xStockIn = A1.AuditKey
					WHERE
					A1.Type = vType
					AND A1.StockManageOperation = 1
					AND A1.Currency = vCurrency
					ORDER BY
					AuditKey DESC; -- get the last one created first

					OPEN cAuditRecords;
          TRY

					FETCH FIRST FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty, vGoodsInLineID,vStockOutAuditKey,  vStockOutQuantity, vDispatchLineID;

					WHILE @@FETCH_STATUS = 0 AND vChangedQty < 0 DO

						IF vDispatchLineID = n.Idx THEN
							SET vMaxChangedQty = GetMININT(ABS(vChangedQty), vDisposedQty);
							SET vChangedQty = vChangedQty + vMaxChangedQty;

							UPDATE AUDIT SET Quantity = Quantity + vMaxChangedQty  WHERE AuditKey = vStockOutAuditKey; -- increase the Audit qty
							UPDATE WhAUDIT SET Quantity = Quantity + vMaxChangedQty WHERE xAudit = vStockOutAuditKey; -- increase the Whaudit qty
						END IF;

						FETCH NEXT FROM cAuditRecords INTO vStockInAuditKey, vStockInQuantity, vDisposedQty, vGoodsInLineID,vStockOutAuditKey,  vStockOutQuantity, vDispatchLineID;
					END WHILE;

					CLOSE cAuditRecords;

          CATCH TRUE
          CLOSE cAuditRecords;
          SIGNAL ERROR_MESSAGE;
          END;

				END IF; -- Sales Dispatch
				ELSE -- Sales Returns

					SET vAuditLinksCount = 	(SELECT COUNT(*) FROM Audit A
											WHERE
											A.xWarehouseOpLine = n.IDX
											AND A.Quantity <> 0);

					IF vAuditLinksCount = 0 THEN -- new Audit records needed

						SET vNewAuditID = CreateAuditRecord(vType, vChangedQty, CURRENT_DATE, vCurrentUnitCost, '', 'Sales Return', vCurrency, 1, vSite, vStockInAuditKey, -1,-1, n.IDX,0);
						CreateWhAuditRecord(vType, vChangedQty, vWarehouse, vSite, 1, -1, -1,vNewAuditID, CAST(NULL AS INTEGER), CAST(NULL AS INTEGER), 0);

					ELSE

						UPDATE AUDIT SET Quantity = Quantity + vChangedQty WHERE xWarehouseOpLine = n.IDX;
						UPDATE WhAUDIT SET Quantity = Quantity + vChangedQty WHERE xAudit = (SELECT AuditKey FROM AUDIT WHERE xWarehouseOpLine = n.IDX);

					END IF; -- of Audit link check

				END IF; -- Sales out/returned

			END IF;  -- SALES ONLY

			--Finally a cleanup of any 0 Qty linked Audit line
			IF vListType <> 6 THEN
				DELETE FROM Audit WHERE xWarehouseOpLine = n.IDX AND Quantity = 0;
			ELSE
				IF DELETING THEN
					DELETE FROM Audit WHERE xWarehouseOpLine = o.IDX AND Quantity = 0;
				END IF;
			END IF;

		END IF; -- Rentals and Loans,  Sales and Sales Orders, or Stock Transfers
	END IF;   -- of general test for Sales/Consumable
END IF; -- IF (INSERTING OR UPDATING) THEN

END IF;  -- suspend triggers check

END;

/* trOperationsDetailBEFORE */
CREATE TRIGGER "trOperationsDetailBEFORE"

BEFORE INSERT, UPDATE  ON OperationsDetail
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vSuspendTriggers BOOL;
SET vSuspendTriggers = (SELECT OPTION('TriggerSuspend') = 'True' FROM #DUMMY);

IF (NOT vSuspendTriggers) THEN

DECLARE vInsertingComposite BOOL;

SET vInsertingComposite = INSERTING AND CAST(n.ModifyDate AS INT) = 0;

IF UPDATING OR
   -- 'placeholder' records for composite masters or components need zero date so that they don't interfer with reconcilition code
  (INSERTING AND (NOT CAST(n.ModifyDate AS INT) = 0)) THEN
  SET n.ModifyDate = Current_Timestamp;
END IF;

IF n.Quantity < 0 THEN
  SET n.Quantity = 0;
END IF;

IF NOT (SELECT OPTION('TriggerWareshouseCheckSuspend') = 'True' FROM #DUMMY) THEN -- we set this flag when reconcilling composites and zero the Qty as part of the routine.
   IF n.Quantity = 0 AND o.Quantity > 0 AND n.CASEID <> '' AND n.OpsType < 5 THEN
     SET n.CASEID = '';
   END IF;
END IF;

IF UPDATING AND n.Quantity < n.ClassTransferredQty THEN
   SIGNAL 'Quantity cannot be less that the quantity stocked out and transferred to a different a diffent equipment Class';
END IF;

IF DELETING AND n.ClassTransferredQty > 0 THEN
   SIGNAL 'Cannot delete records that have a quantity stocked out and transferred to a different a diffent equipment Class';
END IF;

IF n.OpsType IN (5,7) THEN
  DECLARE vTotalDoneForMasterLine INT;
  DECLARE vTotalNeededForMasterLine INT;

  SET vTotalDoneForMasterLine = COALESCE((SELECT SUM(M.Quantity) FROM
                                          OperationsDetail M
                                          WHERE
                                          M.xMasterLine = n.xMasterLine
                                          AND
                                          M.OpsType = N.OpsType
                                          AND M.IDX <> N.IDX),0);

  SET vTotalNeededForMasterLine = (SELECT M.Quantity FROM
                                   OperationsDetail M
                                   WHERE
                                   M.IDX = n.xMasterLine
                                   AND M.OpsType = N.OpsType
                                   );

  IF (vTotalDoneForMasterLine  + n.Quantity) > vTotalNeededForMasterLine  THEN
    SIGNAL 'Only ' || TOSTRING(vTotalNeededForMasterLine - vTotalDoneForMasterLine) || ' required for this ops line';
  END IF;

END IF;

END IF;  -- suspend triggers check

END;

/* trOpScansAFTER */
CREATE TRIGGER trOpScansAFTER

AFTER INSERT, DELETE ON OpScans
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vEqlistLineID INT;
DECLARE vEqlistID INT;
DECLARE vLastScanID INT;
DECLARE vLastOp INT;
DECLARE vLastOpType TINYINT;
DECLARE vLastWarehouseBay TINYINT;
DECLARE vEqlistClass TINYINT;
DECLARE vListType TINYINT;
DECLARE vAuditRef INT;
DECLARE vWHAuditRef INT;

IF INSERTING THEN
     IF n.OpsType > 1 THEN
      -- sync last scan ID
         UPDATE Item SET
         LastOpScan = n.Idx
         WHERE
         ItemRef = n.xItemRef;

      -- get details for updating Item table
         SELECT E.*
         INTO #Eqlists
         FROM Sort S
         INNER JOIN  Eqlists E
         ON S.Eqlno = E.Eql_no
         WHERE
         S.LineRef = n.xEqlineRef;

         SET vEqlistClass = (SELECT EqlistClass FROM #Eqlists);
         SET vListType = (SELECT ListType FROM #Eqlists);

         IF (vEqlistClass = 1) OR (vListType = 6) THEN -- For Sales, Sales Orders or Stock Transfers

             SELECT TOP 1 *
             INTO #Audit
             FROM Audit
             WHERE
             xWarehouseOpLine = n.xOpLineRef
             ORDER BY
             AuditKey DESC;

             SET vAuditRef = (SELECT AuditKey FROM #Audit);
             SET vWHAuditRef = (SELECT IDX FROM WhAudit WHERE xAudit = vAuditRef);

             --  sync Item.nx
             IF (vListType = 0) THEN -- Sale
                IF (n.OpsType = 5) THEN -- Sale Dispatch, so dispose
                   UPDATE Item SET
                   xStockOut = vWHAuditRef,
                   CommissionStatus = 4, --bscDisposed
                   HoursUsed = vAuditRef
                   WHERE
                   itemRef = n.xItemRef
                   AND n.xOpLineRef IS NOT NULL;
                ELSEIF (n.OpsType = 6) THEN -- return so customer sending back
                   UPDATE Item SET
                   xStockOut = NULL,
                   CommissionStatus = 0, --bcsAvailable
                   HoursUsed = NULL
                   WHERE
                   itemRef = n.xItemRef
                   AND n.xOpLineRef IS NOT NULL;
                END IF;
             END IF;

             IF vListType IN (1,2) AND (n.OpsType = 6) THEN -- Order that is being sent back (stock ins are done in NX client)
                UPDATE Item SET
                xStockOut = vWHAuditRef,
                CommissionStatus = 4, --bscDisposed
                HoursUsed = vAuditRef
                WHERE
                itemRef = n.xItemRef
                AND n.xOpLineRef IS NOT NULL;
             END IF;

             IF vListType = 6 THEN-- Rental Stock Transfers
                IF (n.OpsType = 2) THEN -- Transfer Send
                   UPDATE Item SET
                   Int1 = CASE WHEN (SELECT Archived FROM #Eqlists) THEN (SELECT GetSiteIDFromWarehouseID(xTransferInWarehouse) FROM #Eqlists) ELSE Int1 END,
                   Homelocation = (SELECT xTransferInWarehouse FROM #Eqlists),
                   Lastservice = (SELECT xTransferInWarehouse FROM #Eqlists),
                   xStockOut = vWHAuditRef
                   WHERE
                   itemRef = n.xItemRef
                   AND n.xOpLineRef IS NOT NULL;
                ELSEIF  (n.OpsType = 5) THEN
                   UPDATE Item SET
                   xStockIn = vWHAuditRef
                   WHERE
                   itemRef = n.xItemRef
                   AND n.xOpLineRef IS NOT NULL;
                END IF;
             END IF;
         END IF;
       END IF;

ELSE  -- deleting
     IF O.OpsType > 1 THEN

  --		IF O.OpsType <> 6 THEN  -- not for stock transfers

      -- get details for updating Item table
         SELECT TOP 1 S.Idx, D.xOperation,  D.OpsType, D.IDx AS OpsLineID, S.xEqlineRef, S.WarehouseBay, COALESCE(I.xStockOut, 0) as xStockOut
         INTO #Tmp FROM Opscans S
         INNER JOIN  OperationsDetail D
         ON D.Idx = S.xOpLineRef
         INNER JOIN Item I
         ON I.ItemRef = S.xItemRef
         WHERE
         S.xItemRef = o.xItemRef
         AND S.OpsType > 1
         --AND S.Idx <> o.Idx
         ORDER BY
         S.idx DESC;

         SELECT DISTINCT T.*, W.xOperationDetail, T.xStockOut = W.Idx AS WasKept
         INTO #Ops
         FROM #Tmp T
         LEFT OUTER JOIN WhAudit W
         ON T.OpsLineID = W.xOperationDetail
         WHERE
         T.xStockOut = W.Idx
         AND (W.Quantity < 0 AND W.KeepAuditType IN (5,6)) OR (W.xOperationDetail IS NULL); -- (katItemSwapKeep,katItemKeepHire)

         DECLARE vWasKept BOOL;

         SET vWasKept = (SELECT (xOperationDetail IS NOT NULL) AND WasKept  FROM #Ops);

         SET vEqlistLineID = COALESCE((SELECT xEqlineRef FROM #Tmp),1);
         SET vLastOp = (SELECT xOperation FROM #Tmp);
         SET vLastOpType = COALESCE((SELECT OpsType FROM #Tmp),0) + CAST(vWasKept AS TINYINT);
         SET vLastWarehouseBay = COALESCE((SELECT WarehouseBay FROM #Tmp),0);
         SET vEqlistID = (SELECT eqlno FROM "sort" WHERE lineref = vEqlistLineID);
         SET vLastScanID = (SELECT Idx FROM #Tmp);

         --  sync Item.nx with previous scan
         UPDATE Item SET
         LCurrent = vEqlistLineID, CurrentJob = vEqlistID,  LastOperation = vLastOp, LastOpType =vLastOpType, LastWarehouseBay = vLastWarehouseBay, LastOpScan = vLastScanID
         WHERE
         itemRef = O.xItemRef;
         --AND O.xOpLineRef IS NOT NULL;   removed for 271.1

         IF o.WarehouseBay = 4 AND vLastWarehouseBay = 3 THEN -- undoing a Loan Receive In
            UPDATE Item SET
            lastService = HomeLocation
            WHERE
            itemRef = O.xItemRef
            AND O.xOpLineRef IS NOT NULL;
         END IF;

         SELECT E.*
         INTO #Eqlists
         FROM Sort S
         INNER JOIN  Eqlists E
         ON S.Eqlno = E.Eql_no
         WHERE
         S.LineRef = o.xEqlineRef;

         SET vEqlistID = (SELECT eql_no FROM #Eqlists); -- reset vEqlistID
         SET vEqlistClass = (SELECT EqlistClass FROM #Eqlists);
         SET vListType = (SELECT ListType FROM #Eqlists);

         IF (vEqlistClass = 1) OR (vListType = 6) THEN -- For Sales, Sales Orders or Stock Transfers

             SELECT TOP 1 *
             INTO #Audit
             FROM Audit
             WHERE
             xWarehouseOpLine = n.xOpLineRef
             ORDER BY
             AuditKey DESC;

             SET vAuditRef = (SELECT AuditKey FROM #Audit);
             SET vWHAuditRef = (SELECT IDX FROM WhAudit WHERE xAudit = vAuditRef);

           IF (vListType = 0) THEN -- Sale
                IF (o.OpsType = 5) THEN -- clearing a dispatch, so undispose
                   UPDATE Item SET
                   xStockOut = NULL,
                   CommissionStatus = 0, --bcsAvailable
                   HoursUsed = NULL
                   WHERE
                   itemRef = o.xItemRef
                   AND o.xOpLineRef IS NOT NULL;
                ELSEIF (o.OpsType = 6) THEN -- clearing return so customer NOT sending back
                   UPDATE Item SET
                   xStockOut = vWHAuditRef,
                   CommissionStatus = 4, --bscDisposed
                   HoursUsed = vAuditRef
                   WHERE
                   itemRef = o.xItemRef
                   AND o.xOpLineRef IS NOT NULL;
                END IF;
           END IF;

           IF vListType IN (1,2) AND (o.OpsType = 5) THEN -- clearing a Sales Order that is a StockIn. Delete the barcode which user has entered by mistake. RI will protect data from any problems this may cause
                TRY
                   DELETE FROM Item
                   WHERE
                   ItemRef = o.xItemRef;
                CATCH TRUE
               -- if PAT Test has been done then code will fail, so TRY stops an error that will halt the processing any other scans in a batch.
                END;
           END IF;

           IF vListType IN (1,2) AND (o.OpsType = 6) THEN -- clearing a Sales Order that is being sent back
                UPDATE Item SET
                xStockOut = NULL,
                CommissionStatus = 0, --bcsAvailable
                HoursUsed = NULL
                WHERE
                itemRef = o.xItemRef
                AND o.xOpLineRef IS NOT NULL;
           END IF;

           IF vListType = 6 THEN-- Rental Stock Transfers
                IF (o.OpsType = 2) THEN -- Transfer Send
                   UPDATE Item SET
                   Int1 = CASE WHEN (SELECT Archived FROM #Eqlists) THEN (SELECT GetSiteIDFromWarehouseID(MainSite) FROM #Eqlists) ELSE Int1 END,
                   Homelocation = (SELECT MainSite FROM #Eqlists),
                   Lastservice = (SELECT MainSite FROM #Eqlists),
                   xStockOut = NULL
                   WHERE
                   itemRef = o.xItemRef
                   AND o.xOpLineRef IS NOT NULL;
                ELSEIF  (o.OpsType = 5) THEN
                   UPDATE Item SET
                   xStockIn = null
                   WHERE
                   itemRef = o.xItemRef
                   AND o.xOpLineRef IS NOT NULL;
                END IF;
           END IF;

         END IF;
       END IF;

       -- sync OperationsDetail table
       UPDATE OperationsDetail SET
       Quantity = Quantity - 1
       WHERE
       idx = O.xOpLineRef
       AND O.KitStatus <> 2; -- ignore composite

END IF;

END ;

/* trOpScansBEFORE */
CREATE TRIGGER trOpScansBEFORE

BEFORE DELETE ON OpScans
REFERENCING OLD AS o NEW AS n
BEGIN
 --  TBarcodeCommissionStatus = (bcsAvailable, bcsCannotLocate, bcsInRepair, bscRetired, bscDisposed);
 IF (SELECT CommissionStatus = 4 FROM Item WHERE ItemRef = o.xItemRef) THEN
    SIGNAL 'Disposed / Class Transferred items cannot be removed from an operations note';
 END IF;
END ;

/* trOrdersBEFORE */
CREATE TRIGGER trOrdersBEFORE
BEFORE  INSERT, UPDATE OF Client, Authorised ON POrder
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vAddr VARCHAR(500);
  DECLARE vUserID INT;
  DECLARE vInvAddExists BOOL;

-- Users stuff
  SET vUserID = GetUserID();

  IF INSERTING THEN
    IF vUserID > -1 THEN
     SET n.CreatedBy = vUserID;
    END IF;

  ELSEIF UPDATING THEN
    IF vUserID > -1 THEN
     SET n.ModifiedBy =vUserID;        -- actually handled in client now as  UPDATE OF is now limited in the fields it monitors
    END IF;

    IF n.ModifiedDate IS NULL THEN
      SET n.ModifiedDate = CURRENT_TIMESTAMP;
    END IF;

    IF (NOT EQUIVALENT(n.Authorised , o.Authorised)) THEN
     IF n.Authorised THEN
       SET n.xAuthorisedBy = vUserID;
     ELSE
       SET n.xAuthorisedBy = CAST(NULL AS INT);
     END IF;

    END IF;

  END IF;


  IF INSERTING OR (NOT EQUIVALENT(n.Client , o.Client)) THEN
     -- store single record in memory table for efficiency
      IF n.company THEN
        SELECT * into #tmp FROM Company WHERE CompanyCounter = n.Client ;

        SET n."Name" =(SELECT CompanyName FROM #tmp);
        SET n.Telephone = (SELECT MainTelephone FROM #tmp);
        SET n.Facsimile = (SELECT MainFax FROM #tmp);
        SET n.Terms = (SELECT PurchaseTerms FROM #tmp);
        SET n.HirePercentage =(SELECT Ourdiscount FROM #tmp);
        SET n.Disc_percent = (SELECT Ourdiscount FROM #tmp);
        SET vInvAddExists = (SELECT InvAdd1<> '' FROM #tmp);
      ELSE
       SELECT * into #tmp FROM Name2 WHERE NameCounter = n.Client;

       SET n."Name" =(SELECT FullName FROM #tmp);
       SET n.Telephone = (SELECT Telephone FROM #tmp);
       SET n.Facsimile = (SELECT Facsimile FROM #tmp);
       SET n.Terms = (SELECT PurchaseTerms FROM #tmp);
       SET n.HirePercentage =(SELECT "Our discount" FROM #tmp);
       SET n.Disc_percent = (SELECT "Our discount" FROM #tmp);
       SET vInvAddExists = False;
      END IF;

      IF vInvAddExists AND n.company = True THEN
       SET n.Address1 = (SELECT InvAdd1 FROM #tmp);
       SET n.Address2 = (SELECT InvAdd2 FROM #tmp);
       SET n.Address3 = (SELECT InvAdd3 FROM #tmp);
       SET n.Town = (SELECT Invtown FROM #tmp);
       SET n.Postcode = (SELECT InvPostcode FROM #tmp);
       SET n.County = (SELECT InvCounty FROM #tmp);
       SET n.Country = (SELECT InvCountry FROM #tmp);
      ELSE
       SET n.Address1 = (SELECT Address1 FROM #tmp);
       SET n.Address2 = (SELECT Address2 FROM #tmp);
       SET n.Address3 = (SELECT Address3 FROM #tmp);
       SET n.Town = (SELECT Town FROM #tmp);
       SET n.Postcode = (SELECT PostCode FROM #tmp);
       SET n.County = (SELECT County FROM #tmp);
       SET n.Country = (SELECT Country FROM #tmp);
      END IF;

     END IF;

END;

/* trOrderTotalsAFTER */
CREATE TRIGGER "trOrderTotalsAFTER"
AFTER DELETE, UPDATE OF TotalEx ON POrder
REFERENCING OLD AS o NEW AS n
BEGIN
/*
 TRowType =
   (rtEqlistCostCentreHeader, rtEqlistHeader, rtEqlistSectionHeader, rtEqlistMCatHeader, rtEqlistCatHeader, rtEqlistData, rtEqlistMarkupHeader, rtEqlistMarkupData,
    rtCrewCostCentreHeader, rtCrewHeader, rtCrewData,
    rtTransportCostCentreHeader, rtTransportHeader, rtTransportData,
    rtMiscCostCentreHeader, rtMiscHeader, rtMiscData,
    rtSummaryHeader); */

DECLARE vInvID INT;
DECLARE vJobID INT;
DECLARE vNewCrewing BOOL;

SET vInvID = COALESCE(n.Invoice_Count, o.Invoice_Count);
SET vJobID = COALESCE(n.Job, o.Job);

SET  vNewCrewing = (SELECT COALESCE(NewCrewing,TRUE) FROM Jobs WHERE Jobno = vJobID);

SELECT  D.SortLink, D.xGeneralCostCentre, D.SubCostCentre, D.LineTotal, D.RowType
INTO #TmpInvSummary
FROM POrder I
INNER JOIN POData D
ON I.Invoice_Count = D.InvNo
WHERE
I.Job = vJobID
AND RowType IN (5,7,10,13,16);

SELECT
 CASE
 WHEN T.RowType = 5 THEN S.Eqlno
 WHEN T.RowType = 7 THEN E.xEqlno
 WHEN T.RowType = 10 THEN
  CASE
   WHEN vNewCrewing THEN
        CASE WHEN T.SubCostCentre < 5 THEN
             (SELECT P.xCrewRequest FROM CrewShifts S INNER JOIN CrewPositions P ON S.xPosition = P.IDX  WHERE S.IDX = T.SortLink)
             ELSE
             T.SortLink
        END
   ELSE
    (SELECT C.JobRef FROM CrewJobs C WHERE C.Counter = T.SortLink)
   END
 ELSE
 T.SortLink
 END AS SortLink ,
 T.xGeneralCostCentre,
 T.SubCostCentre,
 T.LineTotal,
 T.RowType
 INTO #InvSummary
 FROM #TmpInvSummary T
 LEFT OUTER JOIN Sort S
 ON T.SortLink = S.LineRef AND T.Rowtype = 5
 LEFT OUTER JOIN EqlistMarkUps E
 ON T.SortLink = E.IDX AND T.Rowtype = 7;



 DROP TABLE IF EXISTS #Tmp;

 CREATE TABLE #tmp (
  IDX integer,
  xGeneralCostCentre  TINYINT,
  SubCostCentre  TINYINT,
  Total  MONEY,
  PRIMARY KEY (idx, xGeneralCostCentre, SubCostCentre) );

 INSERT INTO #tmp
 (IDX, xGeneralCostCentre, SubCostCentre, Total )
 SELECT
 COALESCE(SortLink,0), xGeneralCostCentre, SubCostCentre, Sum(LineTotal)
 FROM #InvSummary
 GROUP BY
 xGeneralCostCentre, SortLink, SubCostCentre;

 UPDATE JobFinances J
 SET J.ActualPrice = COALESCE((SELECT T.Total FROM #Tmp T WHERE
                       T.IDX = J.xCostCentreID
                       AND T.xGeneralCostCentre = J.xGeneralCostCentre
                       AND T.SubCostCentre = J.SubCostCentre),0)
 WHERE
 J.IsIncome = False
 AND
 J.xJob = vJobID;

    -- TAccountsDocument = (adRentalInvoice, adRentalInvoiceCredit, adRentalOrder, adRentalOrderCredit, adSalesInvoice, adSalesInvoiceCredit, adSalesOrder, adSalesOrderCredit);
 IF n.DocType = 3 THEN-- credit note

     SELECT
     COALESCE(SUM(TotalEx),0) as TotalEx,
     COALESCE(SUM(TotalInc),0) as TotalInc
     INTO #OrdTotals
     FROM POrder
     WHERE xOrder = n.xOrder;

     UPDATE POrder SET
     CreditedTotalEx = (SELECT TOP 1 TotalEx from #OrdTotals),
     CreditedTotalInc = (SELECT TOP 1 TotalInc from #OrdTotals)
     WHERE
     Invoice_Count = n.xOrder;

 END IF; -- Credit note stuff

END;

