/* trPat_ResAFTER */
CREATE TRIGGER "trPat_ResAFTER"
AFTER INSERT ON Pat_Res
REFERENCING OLD AS o NEW AS n
BEGIN

IF n.OverallPass THEN
     SELECT I.ItemRef, T.PatJobs, T.RigJobs
     INTO #Tmp
     FROM
     Item I
     INNER JOIN Pat_Type T
     ON I."Type" = T."TypeRef"
     WHERE
     I.ItemRef = n.ItemNumber;

     UPDATE Pat_Item PI SET
     PI.ELastJob = (SELECT I.CurrentJob FROM Item I WHERE I.ItemRef = n.ItemNumber),
     PI.FailedJob = False
     WHERE
     PI.ItemRef IN (SELECT ItemRef FROM #Tmp WHERE PatJobs = TRUE);

     UPDATE Pat_Item PI SET
     PI.RLastJob = (SELECT I.CurrentJob FROM Item I WHERE I.ItemRef = n.ItemNumber),
     PI.FailedJob = False
     WHERE
     PI.ItemRef IN (SELECT ItemRef FROM #Tmp WHERE RigJobs = TRUE);
END IF;

END;

