/* trPODataAFTER */
CREATE TRIGGER "trPODataAFTER"
AFTER INSERT, DELETE, UPDATE OF LineTotal ON POData
REFERENCING OLD AS o NEW AS n
BEGIN

     DECLARE vSubCostCentre BYTE;
     DECLARE vMasterRecord INT;
     DECLARE vCrewAccomAmount MONEY;
     DECLARE vOrderStatus TINYINT;

     SET vSubCostCentre = COALESCE(n.SubCostCentre, o.SubCostCentre);
     SET vMasterRecord = COALESCE(n.SortLink, o.SortLink);

     --TSubCostCentre = (sccCrewOld, sccCrewMainAmount, sccCrewPDsAmount, sccCrewTravelAmount, sccCrewOvertimeAmount, sccCrewAccommodationAmount);
     IF vSubCostCentre IN (1,2,3,4) THEN
        CALL SyncCrewShiftOrderStatus(vMasterRecord, TRUE);
     END IF;

     IF vSubCostCentre = 5 THEN
        SET vCrewAccomAmount = (SELECT Charge FROM CrewAccommodation WHERE IDX = vMasterRecord);
        SET vOrderStatus = CalcCrewAccomodationOrderStatus(vMasterRecord,vCrewAccomAmount);
        UPDATE CrewAccommodation SET
        OrderStatus =  vOrderStatus
        WHERE
        IDX = vMasterRecord;
     END IF;

END;

