/* trPrePackInstancesAFTER */
CREATE TRIGGER trPrePackInstancesAFTER
AFTER INSERT, DELETE, UPDATE ON PrePackInstances
REFERENCING OLD AS o NEW AS n
BEGIN
  SELECT
  SUM(Quantity) AS Total,
  COUNT(*) AS Required
  INTO #Summary
  FROM PrePackInstances
  WHERE
  xMasterItem = COALESCE(n.xMasterItem, o.xMasterItem);

  --TPrePackCompletion = (ppcNotApplicable, ppcNone, ppcPartial, ppcFull)
 UPDATE Item SET PrePackCompletion = CASE
                                     WHEN (SELECT Total = 0 FROM #Summary) THEN 1
                                     WHEN (SELECT Total > 0 AND Total < Required FROM #Summary) THEN 2
                                     WHEN (SELECT Total = Required FROM #Summary) THEN 3
                                     ELSE
                                     0
                                     END

 WHERE
 ItemRef = COALESCE(n.xMasterItem, o.xMasterItem);
END;

/* trPrePackInstancesBEFORE */
CREATE TRIGGER trPrePackInstancesBEFORE
BEFORE INSERT, UPDATE OF Quantity, xLinkedType, xLinkedItem ON PrePackInstances
REFERENCING OLD AS o NEW AS n
BEGIN
  -- create a separate record of Qty of 1
  IF (n.Quantity > 1) THEN
    DECLARE vQty INT;

    SET vQty = n.Quantity - 1;
    SET n.Quantity = 1;

        REPEAT
             INSERT INTO PrePackInstances
             (xMasterItem, xLinkedType, Required, Quantity)
             VALUES
             (n.xMasterItem,n.xLinkedType, n.Required, 1);

             SET vQty = vQty - 1;

        UNTIL vQty = 0
        END REPEAT;

  END IF;

  -- changing type, clear barcode
  IF NOT EQUIVALENT(n.xLinkedType, o.xLinkedType) AND (o.xLinkedType IS NOT NULL) THEN

     SET n.xLinkedItem = NULL;

  END IF;

  -- sync Quantity with barcode assignment
  IF NOT EQUIVALENT(n.xLinkedItem, o.xLinkedItem) THEN

    SET n.Quantity = CAST((n.xLinkedItem IS NOT NULL) AS TINYINT);

  END IF;

END;

