/* trPRICEDAT_BEFORE */
CREATE TRIGGER  "trPRICEDAT_BEFORE"
BEFORE Update,DELETE ON PRICEDAT
REFERENCING OLD AS o NEW AS n
BEGIN
DECLARE vLookupCount integer;

IF UPDATING THEN

 IF n.D6 > n.D5 And n.D5 = 0 THEN
  SET n.D6 = 0;
END IF;

 IF n.D5 > n.D4 And n.D4 = 0 THEN
  SET n.D5 = 0;
END IF;

 IF n.D4 > n.D3 And n.D3 = 0 THEN
  SET n.D4 = 0;
END IF;

 IF n.D3 > n.D2 And n.D2 = 0 THEN
  SET n.D3 = 0;
END IF;

 IF n.D2 > n.D1 And n.D1= 0 THEN
  SET n.D2 = 0;
END IF;

ELSEIF DELETING THEN

-- Equipment Validation
   SET vLookupCount = (select count(*) from Hetype
                                    where
                                    weekly = o.Counter or
                                    weekly2 = o.Counter or
                                    weekly3 = o.Counter or
                                    weekly4 = o.Counter);

   IF  vLookupCount > 0 THEN
       Signal 'This price scheme has been asssigned to one or more equipment types so it cannot be deleted.';
   END IF;

   SET vLookupCount = (select count(*)  from Ext_PriceMode
                                    where weekly =  o.Counter);

   IF  vLookupCount > 0 THEN
     Signal 'This price scheme has been asssigned to one or more equipment types so it cannot be deleted.';
   END IF;

   -- Crew Validation
   SET  vLookupCount = (SELECT count(*) FROM Crew
                     WHERE SingleCrewRef = o.Counter);

   IF  vLookupCount > 0 THEN
     Signal 'This price scheme has been asssigned to Crew bookings so it cannot be deleted.';
   END IF;

    -- Crew Validation
   SET  vLookupCount = (SELECT count(*) FROM CrewShifts
                     WHERE (ChargeMethod = o.Counter) OR (PayMethod = o.Counter));

   IF  vLookupCount > 0 THEN
     Signal 'This price scheme has been asssigned to Crew Shifts so it cannot be deleted.';
   END IF;

END IF;
END;

/* trPriceDat_LOG */
CREATE TRIGGER  trPriceDat_LOG
AFTER INSERT, DELETE, UPDATE ON PriceDat
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vIDX INTEGER;

  IF INSERTING THEN
   INSERT INTO Lookups_LOG
    (TableName, MasterID, ActionID)
   VALUES
   ('PriceDat', n."Counter", 0);

  ELSEIF UPDATING THEN

   SET vIDX = LookupsLog_RecordExists('PriceDat', o."Counter", 1) ;

   IF vIDX > -1 THEN
     UPDATE Lookups_LOG
      SET EditDate = CURRENT_TIMESTAMP
     WHERE IDX = vIDX;
   ELSE
     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('PriceDat',n."Counter", 1);
   END IF;  -- vIDX

  ELSEIF DELETING THEN

     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('PriceDat',o."Counter", 2);

  END IF; -- DELETING
END;

