/* trProjectBefore */
CREATE TRIGGER trProjectBefore
BEFORE INSERT, DELETE, UPDATE ON Project
REFERENCING OLD AS o NEW AS n
BEGIN
DECLARE vUserID INT;

  IF INSERTING THEN

    Set vUserID = GetUserID();

     if vUserID > -1 then
     set n.xUser = vUserID;
     END IF;

     Set n.Proj_Ref = 'PR' + cast(n.idx as varchar(10));
     Set n.Proj_start = CURRENT_Date;
     Set n.Proj_End = CURRENT_Date + INTERVAL '1' MONTH;

       ELSEIF UPDATING THEN

          IF (NOT EQUIVALENT(O.Proj_Start,N.Proj_Start)) AND (N.Proj_Start > N.Proj_End ) THEN
            SET N.Proj_End = N.Proj_Start + INTERVAL '1' MONTH;
          END IF;

          IF (NOT EQUIVALENT(O.Proj_End,N.Proj_End)) AND (N.Proj_Start > N.Proj_End ) THEN
            SET N.Proj_Start = N.Proj_End - INTERVAL '1' MONTH;
          END IF;

          IF (NOT EQUIVALENT(O.Proj_Stock,N.Proj_Stock)) AND (N.Proj_Stock = False ) THEN
             DELETE FROM warehouses WHERE idx = o.xVirtualWarehouse;
          END IF;

           SELECT Address1,
           	Address2,
           	Address3,
           	Town,
           	Postcode,
           	Country
           INTO #tmp
           FROM Company
           WHERE CompanyCounter = n.Proj_xVenue;

           SET n.Proj_addr1 = (
           		SELECT TOP 1 Address1
           		FROM #tmp
           		);
           SET n.Proj_addr2 = (
           		SELECT TOP 1 Address2
           		FROM #tmp
           		);
           SET n.Proj_addr3 = (
           		SELECT TOP 1 Address3
           		FROM #tmp
           		);
           SET n.Proj_Town = (
           		SELECT TOP 1 Town
           		FROM #tmp
           		);
           SET n.Proj_PostCode = (
           		SELECT TOP 1 Postcode
           		FROM #tmp
           		);
           SET n.Proj_Country = (
           		SELECT TOP 1 Country
           		FROM #tmp
           		);


          ELSEIF DELETING THEN

            IF  o.xVirtualWarehouse < 0 THEN
              DELETE FROM Eqlists WHERE MainSite = o.xVirtualWarehouse;
              DELETE FROM Eqlists WHERE xTransferInWarehouse = o.xVirtualWarehouse;
              DELETE FROM warehouses WHERE idx = o.xVirtualWarehouse;
            END IF;

         END IF;

END;

