/* trProjJobBefore */
CREATE TRIGGER trProjJobBefore
BEFORE INSERT, DELETE On ProjJob
REFERENCING OLD AS o NEW AS n
BEGIN

     IF INSERTING THEN

        DECLARE vVenueID INT;
        SET vVenueID = (SELECT Proj_xVenue FROM Project WHERE Idx = n.xProject);

        IF vVenueID IS NOT NULL THEN
           UPDATE Jobs SET xMainVenue =  vVenueID WHERE Jobno = n.xJob;
        END IF;

     ELSE -- Deleting
          DECLARE vVirtualWarehouse INT;
