/* trQBEBefore */
CREATE TRIGGER trQBEBefore
BEFORE DELETE, UPDATE OF DefaultItem, Form ON QBE
REFERENCING OLD AS o NEW AS n
BEGIN

     IF (NOT EQUIVALENT(o.Form, n.Form)) AND  (o.DefaultItem) THEN
       SIGNAL 'Changing Form results in no DEFAULT entry for the QBEs assigned to Form "' || o.FORM ||'" Your changes will be cancelled.';
     END IF;

     DECLARE vOldDefaultID INTEGER;

     IF NOT DELETING THEN

        IF n.DefaultItem = TRUE THEN

           SET n.Published = TRUE;

           TRY

              SET vOldDefaultID = (SELECT IDX FROM QBE WHERE FORM = o.FORM and QueryType = o.QueryType AND DefaultItem = TRUE);

              IF vOldDefaultID > 0 THEN
                 UPDATE QBE
                 SET DefaultItem = FALSE
                 WHERE
                 IDX = vOldDefaultID;
                 END IF;

           CATCH POSITION( 'Scalar sub-query expected' IN ERROR_MESSAGE ) <> 0
                SIGNAL ('Multiple "DEFAULT = TRUE" assigned to the same Form. Your changes will be cancelled.');

           END;

        END IF;

    ELSEIF DELETING THEN

           IF o.System THEN
              SIGNAL 'System QBEs cannot be deleted';
           END IF;

    END IF;

END;

