/* trRepair */
CREATE TRIGGER trRepair
AFTER INSERT, DELETE, UPDATE ON servdata
REFERENCING OLD AS o NEW AS n
BEGIN

-- CommissionStatus : 0 = Available, 1=Cannot Find, 2 = In Repair, 3 = Retired, 4 = Disposed

  IF INSERTING THEN

   IF n.ItemRef IS NOT NULL AND n.xRepairLineRef IS NOT NULL THEN
    UPDATE Item I SET
    I.CommissionStatus = 2
    WHERE
    I.ItemRef = n.ItemRef;
   END IF;

  ELSEIF UPDATING THEN

   IF o.ItemRef IS NOT NULL AND n.ItemRef IS NULL AND n.xRepairLineRef IS NOT NULL THEN
     UPDATE Item I SET
     I.CommissionStatus = 0
     WHERE
     I.ItemRef = O.ItemRef;
   END IF;

   IF o.ItemRef IS NULL and n.ItemRef IS NOT NULL AND n.xRepairLineRef IS NOT NULL THEN
     UPDATE Item I SET
     I.CommissionStatus = 2
     WHERE
     I.ItemRef = n.ItemRef;
   END IF;

  ELSEIF DELETING THEN
   IF  o.xRepairLineRef IS NOT NULL THEN
     UPDATE Item I SET
     I.CommissionStatus = 0
     WHERE
     I.ItemRef = o.ItemRef;
   END IF;

  END IF;
END;

