/* trReportsBEFORE */
CREATE TRIGGER trReportsBEFORE
BEFORE INSERT, UPDATE of FileName,  rbTemplate ON Reports
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vReportAlreadyExists  BOOL;

IF n.FileName <> o.FileName THEN
 SET vReportAlreadyExists = (SELECT COUNT(*) > 0
                             FROM Reports
                             WHERE
                             ReportType = 1
                             AND FileName = n.FileName);
END IF;

If vReportAlreadyExists THEN
  SIGNAL n.FileName + ' already exists. Report Builder reports must have a unique filename. Rename or hit ESC to Cancel';
END IF;

IF n.MenuName IS NULL THEN
 SET   n.MenuName = n.FileName;
END IF;

IF UPDATING THEN
  IF (n.xMasterRecord < 0) THEN // its not a linked report so check if it has records that are linked to it and set their modified date so they seem to be in sync
    UPDATE Reports SET
    rbModified = CURRENT_TIMESTAMP
    WHERE
    xMasterRecord = n.MenuNo;
  END IF;
END IF;

END;

