IF INSERTING THEN
  -- create a default warehouse for the site
  INSERT INTO warehouses
  (warehousename, xSite, isDefault)
  VALUES
  (n.SiteName +  ': Main Warehouse', n.idx , TRUE);

  -- RULES
  INSERT INTO  Rules
  (SiteID)
  VALUES
  (n.idx);

  -- Config1
  INSERT INTO  Config1
  (Link)
  VALUES
  (n.idx);

  -- whLevel
  INSERT INTO Whlevel
  (xSite, TypeIDX)
  SELECT
  n.idx, "Type"
  FROM Hetype;

ELSEIF DELETING THEN

  --warehouses
  DELETE FROM warehouses
  WHERE xSite = o.IDX;

  --Rules
  DELETE FROM Rules
  WHERE SiteID = o.IDX;

  --Config1
  DELETE FROM Config1
  WHERE Link = o.IDX;

  --whLevel
  DELETE FROM Whlevel
  WHERE xSite = o.IDX;

END IF;

END;

