/* trSmartTagsAFTER */
CREATE TRIGGER trSmartTagsAFTER
AFTER  DELETE ON SmartTags
REFERENCING OLD AS o NEW AS n
BEGIN
    IF o.xParentTag = 0 THEN
    IF o.Original = TRUE THEN
     UPDATE SmartTags Set Original = TRUE WHERE Tag = o.Tag AND xParentTag = 0 AND NOT Original = TRUE; //used so we hit index
    END IF;
    END IF;
END;

/* trSmartTagsBEFORE */
CREATE TRIGGER trSmartTagsBEFORE
BEFORE INSERT, DELETE, UPDATE ON SmartTags
REFERENCING OLD AS o NEW AS n
BEGIN
DECLARE Mandatory INTEGER;
DECLARE Equal INTEGER;
DECLARE OptionTag INTEGER;
DECLARE vUserID INT;
DECLARE NEWParent INT;
SET vUserID = GetUserID();
  IF INSERTING OR UPDATING THEN
    SET Mandatory = POSITION('=>' IN n.Tag);
    SET OptionTag = POSITION('=!' IN n.Tag);
    SET Equal = POSITION('=' IN n.Tag);
    IF Mandatory > 0 THEN
      SET n.TagValue = SUBSTRING(n.Tag FROM Mandatory +2);
    ELSEIF OptionTag > 0 THEN
       SET n.TagValue = SUBSTRING(n.Tag FROM OptionTag +2);
    ELSEIF Equal > 0 THEN
     SET n.TagValue = SUBSTRING(n.Tag FROM Equal +1);
    END IF;
    IF UPPER(COALESCE(o.Tag, '')) <> UPPER(n.Tag) THEN
    -- Check if the new tag already exists in SmartTags
    IF NOT EXISTS (SELECT 1 FROM SmartTags WHERE UPPER(Tag) = UPPER(n.Tag) AND xParentTag = 0 AND Original = TRUE) THEN
        SET n.Original = TRUE;
    ELSE
        SET n.Original = FALSE;
        SET n.xParentTag = (SELECT TOP 1 idx FROM SmartTags WHERE UPPER(Tag) = UPPER(n.Tag) AND Original = TRUE);
    END IF;
   END IF;
       IF INSERTING THEN
         IF n.original THEN
          SET n.xCreatedBy = vUserID;
         END IF;
       END IF;

  ELSEIF DELETING THEN
    IF o.xParentTag = 0 THEN
    -- deleting Original tag so update everything else
    SET NEWParent = (SELECT TOP 1 Idx FROM SmartTags WHERE xParentTag = o.Idx Order by Idx asc);
    UPDATE SmartTags SET Original = TRUE, xParentTag = 0, xCreatedBy = (SELECT coalesce(xCreatedBy, -1) FROM smartTags WHERE Idx = o.Idx) WHERE Idx = NEWParent;
    UPDATE SmartTags SET xParentTag = NEWParent WHERE xParentTag = o.Idx;
--    DELETE FROM SmartTags WHERE xParentTag = o.Idx;
    END IF;
  END IF;
END;

/* trSortAFTER */
CREATE TRIGGER trSortAFTER
AFTER DELETE ON "Sort"
REFERENCING OLD AS o NEW AS n
BEGIN
 -- freetext

 IF o.xFreeText > 0 THEN
    DELETE FROM FreeText
    WHERE
    IDX = o.xFreeText;
 END IF;

 -- deal with headers for JOB loans
 --  TWarehouseActivity = (waHire, waJobSubhire, waGlobalSubhire, waJobTransfer, waGlobalTransfer, waVirtualWarehouseBuild);
 IF o.ListType = 3 THEN

   DECLARE vListCount INT;

   SET vListCount = (SELECT COUNT(*)
                     FROM "Sort"
                     WHERE Eqlno = o.Eqlno);

   IF vListCount = 0 THEN
    DELETE FROM Eqlists
    WHERE Eql_No = o.Eqlno;
   END IF;

 END IF;

END;

/* trSortAFTERtag */
CREATE TRIGGER trSortAFTERtag
AFTER INSERT, DELETE, UPDATE OF "type"  ON "sort"
REFERENCING OLD AS o NEW AS n
WHEN (((EQUIVALENT(o.Flagged,n.Flagged) AND EQUIVALENT(o.SortOrder,n.SortOrder))))
BEGIN
IF DELETING THEN
  CALL DoTags('sort', o.lineref);
ELSE
  CALL DoTags('sort', n.lineref);
END IF;
END;

/* trSortBEFORE */
CREATE TRIGGER "trSortBEFORE"
  BEFORE INSERT, DELETE, UPDATE
  ON SORT REFERENCING NEW AS n OLD AS o
  WHEN (INSERTING OR DELETING OR ((EQUIVALENT(o.Flagged,n.Flagged) AND EQUIVALENT(o.SortOrder,n.SortOrder))))  -- don't fire if these fields are being changed
BEGIN

DECLARE vIsComposite BOOLEAN;
--DECLARE vLateReturnsListiD INTEGER;
DECLARE vComponentRecType INTEGER;
DECLARE vNewAuditID INTEGER;
DECLARE vConsumableQty INTEGER;
DECLARE vMaxConsumableQty INTEGER;
DECLARE vCurrency INTEGER;
DECLARE vSite INTEGER;
DECLARE vEqlistClass TINYINT;
DECLARE vAuditKey INT;
DECLARE vQuantity INT;
DECLARE vDisposedQty INT;
DECLARE vIsExtension BOOL;
DECLARE vExtensionType TINYINT; --TEqlistExtensionType = (eetNone, eetEarlyReturn, eetLateReturnStandard, eetLateReturnExtended);
/*
 TEqlistRecordType = (
    etFreeText = 0,
    etNormal = 1,
    etNormalReminder = 2, etNormalReminderNoCharge = 3, etCompositeReminder = 4, etCompositeReminderNoCharge = 5,
    etNormalAliasPart = 6, etNormalPricedAliasPart = 7, etCompositeAliasPart = 8, etCompositPricedAliasPart = 9,
    etComposite = 10, etCompositeComponent = 11,
    etAlias = 12, etPricedAlias = 13, etNormalAliasPartNoCharge = 14, etCompositeAliasPartNoCharge = 15);
 */

SET vComponentRecType = 11;

DECLARE vSuspendWarehouseQtyChecks BOOL;
SET vSuspendWarehouseQtyChecks = (SELECT OPTION('TriggerWareshouseCheckSuspend') = 'True' FROM #DUMMY);

IF INSERTING OR UPDATING THEN
  SET vIsComposite =  RecTypeIsComposite(n.RecType);
  SET vEqlistClass = GetEqlistClass(n.Eqlno);

  SET vIsExtension = n.ListType = 0 and n.xTransferToLine IS NOT NULL;
  IF vIsExtension THEN
     SET vExtensionType = (SELECT ExtensionType FROM Eqlists WHERE Eql_no = n.eqlno);
  ELSE
     SET vExtensionType = 0;
  END IF;

   DECLARE vUserID integer;

   SET vUserID = GetUserID();

   IF vUserID > -1 THEN
     SET n.xLastModifiedBy = vUserID;
   END IF;

   SET n.lastModified = CURRENT_TIMESTAMP;

ELSE
  SET vIsComposite =  RecTypeIsComposite(o.RecType);
  SET vEqlistClass = GetEqlistClass(o.Eqlno);
  SET vIsExtension = o.ListType = 0 and o.xTransferToLine IS NOT NULL;
  IF vIsExtension THEN
     SET vExtensionType = (SELECT ExtensionType FROM Eqlists WHERE Eql_no = o.eqlno);
  ELSE
     SET vExtensionType = 0;
  END IF;
END IF;



-- Dates
IF NOT DELETING THEN
  IF NOT EQUIVALENT(n.D1, o.D1) AND n.D1 > n.D2 THEN
    SET n.D2 = n.D1 + INTERVAL '1' DAY;
  END IF;

  IF NOT EQUIVALENT(n.D2, o.D2) AND n.D1 > n.D2 THEN
    SET n.D1 = n.D2 - INTERVAL '1' DAY;
  END IF;
END IF;

IF INSERTING THEN -- INSERT

 -- make sure consumables can't be loaned
 /* IF (n.xCat < 0) and (N.ListType IN (3, 4)) THEN
   SIGNAL 'Consumable types cannot be loaned. Use the Stock Transfer facility instead';
 END IF;     */

   IF (N.ListType IN (3, 4)) AND (n.xTransferInWarehouse < 1) THEN
    SIGNAL 'Invalid destination warehouse specified for a loan';
   END IF;

-- deal with normal records and composite master
 IF n.Linecode IS NULL THEN
  SET n.linecode = n.lineref;
 END IF;

 SET n.alloc =  CAST(n.Discount * 100 AS INTEGER );

 /*
 IF N.OldLineRef IS NULL THEN  -- Cloned lines have the value of their "originator line" stored here. So we need to respect the cloned value of  n.ChargeQuantity
      SET n.ChargeQuantity = n.Quant;
 END IF;
 */

-- deal with components
 IF vIsComposite THEN
  INSERT INTO "sort"
  (Linecode,Quant,"Type", XCat, virt, eqlno, D1, D2, Defcon, LoansInQty, sectionID, rectype, subhire, xGUID, slink1,  xTransferInWarehouse, listType)
  SELECT
    n.LineRef,
    N.Quant * C.Quantity,
    C.ComponentType,
    N.XCat,
    True,
    n.eqlno,
    n.D1,
    n.D2,
    n.defcon,
    n.LoansInQty * C.Quantity,
    n.sectionID,
    vComponentRecType,
    n.subhire,
    NEWGUID,
    n.slink1,
    n.xTransferInWarehouse,
    n.ListType
  FROM Composit C
  WHERE
  C.MasterType = n."type"
  ORDER BY C.SortID;

  IF n.xTransferToLine > 0 THEN
    UPDATE "Sort" S SET
    S.xTransferToLine = (SELECT S2.LineRef
                         FROM "Sort" S2
                         WHERE
                         S2.LineCode = n.xTransferToLine
                         AND S2."Type" = S."Type" )
    WHERE
    S.LineCode = n.LineRef
    AND
    S.LineRef <> n.LineRef ;
  END IF;

 END IF;



 ELSEIF UPDATING THEN -- UPDATE

  -- check if its invoiced

    IF (n.InvoicedTotal > 0) AND (n.ListType NOT IN (1,2)) THEN -- we now allow Subhires to have cost less than ordered so that orders can be recreated
    -- +ve invoicing
      IF ((NOT EQUIVALENT(O.Price,n.Price)) OR (NOT EQUIVALENT(O.InvoicedTotal,n.InvoicedTotal))) AND (n.Price <  n.InvoicedTotal) THEN
        IF n.ListType NOT IN (1,2) THEN
          SIGNAL 'The Invoice Amount ' +  CAST(n.InvoicedTotal AS VARCHAR(18)) + ' for line ' + CAST(N.LineRef AS VARCHAR(10)) + ' is greater than the line price of ' + CAST(n.Price AS VARCHAR(18));
        ELSE
          SIGNAL 'The Order Amount ' +  CAST(n.InvoicedTotal AS VARCHAR(18)) + ' for line ' + CAST(N.LineRef AS VARCHAR(10)) + ' is greater than the line price of ' + CAST(n.Price AS VARCHAR(18));

        END IF;
      END IF;

    END IF;

    IF (n.InvoicedTotal < 0) AND (n.ListType NOT IN (1,2)) THEN -- we now allow Subhires to have cost less than ordered so that orders can be recreated

      IF ((NOT EQUIVALENT(O.Price,n.Price)) OR (NOT EQUIVALENT(O.InvoicedTotal,n.InvoicedTotal))) AND (n.Price >  n.InvoicedTotal) THEN
        IF n.ListType NOT IN (1,2) THEN
          SIGNAL 'The negative Invoice Amount ' +  CAST(n.InvoicedTotal AS VARCHAR(18)) + ' for line ' + CAST(N.LineRef AS VARCHAR(10)) + ' is less than the line price of ' + CAST(n.Price AS VARCHAR(18));
        ELSE
          SIGNAL 'The negative Order Amount ' +  CAST(n.InvoicedTotal AS VARCHAR(18)) + ' for line ' + CAST(N.LineRef AS VARCHAR(10)) + ' is less than the line price of ' + CAST(n.Price AS VARCHAR(18));
        END IF;
      END IF;

    END IF;

    -- deal with Job Transfers.
    -- THIS IS NOW DEALT WITH IN trEqlistAFTER
/*    IF (n.LoansINQTY > 0)  AND (NOT EQUIVALENT(N.defcon , O.Defcon)) THEN

     UPDATE "Eqlists" SET
     defcon = n.defcon
     WHERE
     eql_no IN  (SELECT DISTINCT S.eqlno
                 FROM "Sort" S
                 WHERE
                 S.xTransferToLine = n.LineRef);

    END IF; */

   -- movements, subhires and loans validation
    IF NOT EQUIVALENT(O.Quant,n.Quant) THEN

       IF vExtensionType = 1 THEN --  make Early Return movements fields the same as booked Qty
          SET n."PreppedQty" = n.Quant;
          SET n."OUT" = n.Quant;
          SET n."Back" = n.Quant;
          SET n."CheckedInQty" = n.Quant;
       END IF;

       IF  n.Quant <  n.PreppedQTY THEN
         SIGNAL 'Quantity cannot be less than what has been ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),1, True);
       END IF;

       IF  n.Quant <  n.SubhiredQty THEN
         SIGNAL 'Quantity cannot be less than what has been Subhired/Ordered';
       END IF;

       IF  n.Quant <  n.LoansInQty THEN
         SIGNAL 'Quantity cannot be less than what has been Loaned';
       END IF;

    END IF;


    IF (NOT EQUIVALENT(O.PreppedQTY,n.PreppedQTY)) THEN
      IF n.PreppedQTY > n.Quant THEN
         IF vSuspendWarehouseQtyChecks THEN
            SET n.PreppedQTY = n.Quant;
         ELSE
             SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' has been fully ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),1, True) || '. Refresh your form to see changes made by other users';
         END IF;
      END IF;
       -- Do not auto-corret if lower than next stage
      IF (n.PreppedQTY <  n."Out") AND (NOT vSuspendWarehouseQtyChecks)  THEN
        SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' has been fully ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),2, True) || '. Refresh your form to see changes made by other users';
      END IF;
    END IF;

	IF (NOT EQUIVALENT(O."Out",n."Out")) THEN
      IF n."Out" > n.PreppedQTY THEN
         IF vSuspendWarehouseQtyChecks THEN
            SET n."Out" = n.PreppedQTY;
         ELSE
             SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' has been fully ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),2, True) || '. Refresh your form to see changes made by other users';
	       END IF;
      END IF;
       -- Do not auto-corret if lower than next stage
      IF (n."Out"  <  n.Back) AND (NOT vSuspendWarehouseQtyChecks) THEN
        SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' has been fully ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),3, True) || '. Refresh your form to see changes made by other users';
      END IF;
	END IF;


    IF (NOT EQUIVALENT(O.Back,n.Back)) THEN
      IF n.Back >  n."Out" THEN
          IF vSuspendWarehouseQtyChecks THEN
             SET n.Back =  n."Out";
          ELSE
              SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' has been fully ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),3, True) || '. Refresh your form to see changes made by other users';
		      END IF;
      END IF;
       -- Do not auto-corret if lower than next stage
      IF (n.Back <  n.CheckedInQty) AND (NOT vSuspendWarehouseQtyChecks) THEN
             SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' has been fully ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),4, True) || '. Refresh your form to see changes made by other users';
      END IF;

      IF (n.Back < o.Back) AND (NOT vSuspendWarehouseQtyChecks) THEN-- reducing Qty Returned
         IF n.Back < COALESCE((SELECT SUM(Quant) FROM Sort WHERE xTransferToLine = n.LineRef AND ListType = 0), n.Back) THEN -- cannot be lower than the Qty on a linked Early Return
            SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' is linked to an Early Return list and it''s Return Qty cannot be reduced';
         END IF;
      END IF;
    END IF;

	IF (NOT EQUIVALENT(O.CheckedInQty,n.CheckedInQty)) THEN
      IF n.CheckedInQty >  n.Back  THEN
        IF vSuspendWarehouseQtyChecks THEN
           SET n.CheckedInQty =  n.Back;
        ELSE
            SIGNAL 'Eqlist line ' || CAST(n.LineRef AS VARCHAR(10)) || ' has been fully ' || GetWarehouseStageText(n.ListType, GetEqlistClass(n.eqlno),3, True) || '. Refresh your form to see changes made by other users';
        END IF;
      END IF;
	END IF;
--END IF; --IF NOT vSuspendWarehouseQtyChecks THEN

    -- maintain NotBack
    SET n.NotBack = (n."Out" - n.CheckedInQty > 0);

   -- old discount field
    SET n.alloc =  CAST(n.Discount * 100 AS INTEGER );

   -- sync components with field changes to master
 ---    SET vIsComposite = n."Type" IN (SELECT h."Type" FROM Hetype H WHERE H."Type" = N."Type" AND H.virt = True) ;


    IF vIsComposite
       AND (
           (NOT EQUIVALENT(n.Quant, o.Quant) AND (n.recType <> 17 ))   -- etCompositePrepModified = 17
         --   OR (NOT EQUIVALENT(n.SubhiredQty, o.SubhiredQty))
            OR (NOT EQUIVALENT(n.LoansInQty, o.LoansInQty))
            OR (NOT EQUIVALENT(n.D1, o.D1))
            OR (NOT EQUIVALENT(n.D2, o.D2))
            OR (NOT EQUIVALENT(n.Defcon, o.Defcon))
            OR (NOT EQUIVALENT(n.Xcat, o.Xcat))
            OR (NOT EQUIVALENT(n.Slink1, o.Slink1))
            OR (NOT EQUIVALENT(n.xTransferInWarehouse, o.xTransferInWarehouse))
            OR (NOT EQUIVALENT(n.sectionID, o.sectionID))
            OR (NOT EQUIVALENT(n.xTransferToLine, o.xTransferToLine))
            ) THEN


     UPDATE "sort" S1
      SET

        S1.Quant = CASE WHEN S1.Quant = 0 THEN (SELECT Quantity * n.Quant
                                                FROM Composit
                                                WHERE MasterType = N.Type
                                                AND ComponentType = S1.Type)
                   ELSE  ROUND(S1.Quant * IntToFrac(n.Quant, o.Quant))
                   END,

        S1.ChargeQuantity = CASE WHEN S1.ChargeQuantity = 0 THEN (SELECT Quantity * n.Quant
                                                FROM Composit
                                                WHERE MasterType = N.Type
                                                AND ComponentType = S1.Type)
                   ELSE  ROUND(S1.ChargeQuantity * IntToFrac(n.Quant, o.Quant))
                   END,
    /*  This is now managed via trSubDataAFTER

        S1.SubhiredQty = n.SubhiredQty * (SELECT C.Quantity
                                     FROM Composit C
                                     WHERE
                                     C.MasterType = n."type"
                                     AND C.ComponentType = S1."Type"), */
        S1.LoansInQty = COALESCE(n.LoansInQty * (SELECT C.Quantity
                                     FROM Composit C
                                     WHERE
                                     C.MasterType = n."type"
                                     AND C.ComponentType = S1."Type"),0),
        S1.D1 = n.D1,
        S1.D2 = n.D2,
        S1.Defcon = n.Defcon,
      	S1.Xcat = n.Xcat,
      	S1.Slink1 = n.Slink1,
	      S1.xTransferInWarehouse = n.xTransferInWarehouse,
      	S1.sectionID = n.sectionID,
      	S1.xTransferToLine = xTransferToLine
        WHERE
        S1.LineCode = O.LineRef
	      AND S1.lineRef <> O.LineRef;

    END IF;

 ELSEIF DELETING THEN  -- DELETE

   -- block deleting if Carnets
   IF o.CarnetQty > 0 THEN
    SIGNAL 'Equipment lines cannot be deleted if the Carnet Quantity for them is greater than zero';
   END IF;


   -- block deleting if Prepped
   IF o.PreppedQty > 0 AND o.eqlno <> 0 AND vExtensionType <> 1 THEN   -- 0 is a Repair list
    SIGNAL GetWarehouseStageText(o.ListType, GetEqlistClass(o.eqlno),1, True) || ' equipment lines cannot be deleted';
   END IF;

   IF vExtensionType = 1 THEN -- deleting an Early Returns list/line
      UPDATE Sort SET
      ChargeQuantity = ChargeQuantity + O.ChargeQuantity
      WHERE
      LineRef = o.xTransferToLine;
   END IF;

   -- block deleting if invoiced, but only if record hasn't been marked as being "replaced"
   -- The marking of a replaced line is done my setting OldLineRef = -1. This allows us to delete the line in Sort then update the references in InvData or POData.
   IF ((o.InvoicedTotal <> 0) OR (o.Invoiced)) AND (COALESCE(o.OldLineRef,0) <> -1) THEN
      SIGNAL 'This record is linked to a financial document and cannot be deleted.';
    END IF;

  -- block deleting if price locked list
   IF (SELECT Int2 = 1
       FROM Eqlists
       WHERE
       Eql_no = o.eqlno) THEN
         IF (NOT EXISTS (SELECT "Type"
                        FROM Hetype
                        WHERE
                        EquipmentType > 3 AND
                        Visibility = 0 AND
                        "Type" = o."Type"))
             AND (COALESCE(o.OldLineRef,0) <> -1)
             AND (o.Virt =FALSE) THEN
            SIGNAL 'You cannot delete lines from a "Price Locked" list';
         END IF;
   END IF;

 -- clear component records
  IF  vIsComposite THEN
      DELETE FROM "sort"
      WHERE
      LineCode = O.LineRef
      AND lineRef <> O.LineRef;
  END IF;

  -- delete from subdata  - Only if a Subhire. RI blocks Sort Delete if subhire line has been allocated.
   IF o.Subhire = True THEN
      DELETE FROM Subdata
      WHERE
      subhline = O.LineRef;
   END IF;

   -- delete Loans
   IF (o.ListType = 0) AND (NOT o.Virt) THEN

     IF o.LoansInQty > 0 AND o.xTransferToLine IS NULL THEN -- it's a regular hire not an extension
        DELETE FROM Sort
        WHERE
        xTransferToLine = o.LineRef
        AND ListType = 3; -- only for job loan lists, not extensions.
     ELSE   -- we are deleting an Extension's line
       IF o.LoansInQty > 0 THEN -- reset the loans link back to the original hire list
          UPDATE Sort SET
          xTransferToLine = o.xTransferToLine
          WHERE
          xTransferToLine = o.LineRef;
       END IF;

     /*  because of RI restrictions do this bit in trEqlistsBEFORE

        IF o.SubhiredQty > 0 THEN -- reset the subhire link back to the original hire list
          UPDATE SubData SET
          EqlLine = o.xTransferToLine
          WHERE
          EqlLine = o.LineRef;
       END IF;
     */
     END IF;
   END IF;


END IF; -- db state checking

END;

/* trStockTakeDetailsBefore */
CREATE TRIGGER trStockTakeDetailsBefore
BEFORE INSERT, UPDATE OF xAction, xUserProcessed , xUserActioned ON StockTakeDetails
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;

  IF INSERTING  THEN
    SET vUserID = GetUserID();

    IF vUserID > -1 then
      SET n.xUserSeen = vUserID;
    END IF;
  END IF;

  IF UPDATING THEN
    IF (o.xAction > 1) AND (NOT EQUIVALENT(o.xAction, n.xAction)) THEN
     SET n.xActionLookup = NULL;
    END IF;

    IF  NOT EQUIVALENT(o.xUserProcessed, n.xUserProcessed) THEN
      IF NOT n.xUserProcessed IS NULL THEN
        SET n.ProcessedDate = CURRENT_TIMESTAMP;
      ELSE
        SET n.ProcessedDate = NULL;
      END IF;
    END IF;

    IF  NOT EQUIVALENT(o.xUserActioned, n.xUserActioned) THEN
      IF NOT n.xUserActioned IS NULL THEN
       SET n.ActionedDate = CURRENT_TIMESTAMP;
      ELSE
       SET n.ActionedDate = NULL;
       SET n.xActioned = NULL;
       SET n.xActionedLookup = NULL;
      END IF;
    END IF;

  END IF;

END;

/* trStockTakesBEFORE */
CREATE TRIGGER trStockTakesBEFORE
BEFORE INSERT, UPDATE OF Active ON StockTakes
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;
  SET vUserID = GetUserID();

  IF vUserID > -1 then
     SET n.xcreatedby = vUserID;
  END IF;

  IF UPDATING THEN
    IF  n.Active = FALSE THEN
      SET n.InActiveDate = CURRENT_TIMESTAMP;
    ELSE
      SET n.InActiveDate = NULL;
    END IF;
  END IF;

      UPDATE StockTakes SET
    Active = FALSE
    WHERE
    xWarehouse = n.xWarehouse
    AND Active = TRUE
    AND IDX <> n.IDX;

END;

/* trSubcode_AFTER */
CREATE TRIGGER trSubcode_AFTER
AFTER UPDATE ON Subcode
REFERENCING OLD AS o NEW AS n
WHEN (NOT EQUIVALENT(o.BarcodeComponentState, n.BarcodeComponentState) )
BEGIN
  --TBarcodeComponentState = (bcsReadyToGo, bcsReturned, bcsUnreturned, bcsDetached);
  DECLARE vNoIndependentScans BOOL;
  SET vNoIndependentScans = CASE
                            WHEN n.BarcodeComponentState = 0 THEN TRUE
                            WHEN n.BarcodeComponentState = 3 THEN FALSE
                            ELSE CAST(NULL AS BOOL) -- early returned or unreturned from Composite
                            END;

  UPDATE Item SET
  NoIndependentScans = vNoIndependentScans
  WHERE
  ItemRef = n.SubItem
  AND NOT EQUIVALENT(NoIndependentScans , vNoIndependentScans) ;

END;

/* trSubcode_BEFORE */
CREATE TRIGGER trSubcode_BEFORE
BEFORE INSERT, DELETE, UPDATE OF Masteritem, Subitem, Mastertype, Subtype, xComposite ON Subcode
REFERENCING OLD AS o NEW AS n
BEGIN
-- editing of BarcodeComponentState allowed regardless of master item being out.

  DECLARE vIsOnAnOpsNote BOOL;
  DECLARE vItemID INT;
  DECLARE vOpsRef VARCHAR(50);
  DECLARE vBarcode VARCHAR(20);

  IF DELETING THEN
    SET vItemID = o.MasterItem;
  ELSE
    SET vItemID = n.MasterItem;
  END IF;

  IF INSERTING THEN
    UPDATE Item SET
    NoIndependentScans = TRUE
    WHERE
    ItemRef = n.SubItem;
  ELSEIF DELETING THEN
    UPDATE Item SET
    NoIndependentScans = FALSE
    WHERE
    ItemRef = o.SubItem
    AND NoIndependentScans = TRUE;
  END IF;



  SET vIsOnAnOpsNote = COALESCE((SELECT (COALESCE(LastOpType,0) NOT IN (0,7)) AND (COALESCE(LastWarehouseBay,0) NOT IN (9,10)) -- allow if last action was transfer or class transfer
                                 FROM Item
                                 WHERE
                                 ItemRef = vItemID),FALSE);

  IF vIsOnAnOpsNote THEN
     SET vOpsRef = COALESCE((SELECT O.Reference
                             FROM Item I
                             INNER JOIN OperationsHeader O
                             ON I.LastOperation = O.Idx
                             WHERE
                             ItemRef = vItemID),'UNKNOWN');

     SET vBarcode = (SELECT I.Barcode
                     FROM Item I
                     WHERE
                     ItemRef = vItemID);


     SIGNAL 'Composite items cannot be changed because Master Barcode ' || vBarcode || ' is  currently on Ops Note ' || vOpsRef;

  END IF;


END;

/* trSubcode_LOG */
CREATE TRIGGER  trSubcode_LOG
AFTER INSERT, DELETE, UPDATE ON Subcode
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vIDX INTEGER;

  IF INSERTING THEN
   INSERT INTO Lookups_LOG
    (TableName, MasterID, ActionID)
   VALUES
   ('Subcode', n."IDX", 0);

  ELSEIF UPDATING THEN

   SET vIDX = LookupsLog_RecordExists('Subcode', o."IDX", 1) ;

   IF vIDX > -1 THEN
     UPDATE Lookups_LOG
      SET EditDate = CURRENT_TIMESTAMP
     WHERE IDX = vIDX;
   ELSE
     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('Subcode',n."IDX", 1);
   END IF;  -- vIDX

  ELSEIF DELETING THEN

     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('Subcode',o."IDX", 2);

  END IF; -- DELETING
END;

/* trSubDataAFTER */
CREATE TRIGGER "trSubDataAFTER"
AFTER INSERT, DELETE, UPDATE ON SubData
REFERENCING OLD AS o NEW AS n
BEGIN

 DECLARE vLineRef INT;

 IF DELETING THEN
  SET vLineRef = o.EqlLine;
 ELSE
  SET vLineRef = n.EqlLine;
 END IF;

 UPDATE "Sort" S
 SET S.SubHiredQty = COALESCE((
			SELECT SUM(Q)
			FROM Subdata
			WHERE EqlLine = vLineRef
			), 0)
 WHERE
 S.LineRef = vLineRef;

END;

/* trSubDataBEFORE */
CREATE TRIGGER "trSubDataBEFORE"
BEFORE INSERT, DELETE, UPDATE OF Q ON SubData
REFERENCING OLD AS o NEW AS n
BEGIN

 DECLARE vEqLineRef INT;
 DECLARE vIsComposite BOOL;
 DECLARE vJobPrepped INT DEFAULT 0;
 IF DELETING THEN
  SET vEqLineRef = o.EqlLine;
 ELSE
  SET vEqLineRef = n.EqlLine;
 END IF;



 If DELETING OR UPDATING THEN

    SET vJobPrepped = COALESCE((SELECT SUM(O.Quantity) FROM OperationsDetail O WHERE O.xEqlistLine = vEqLineRef AND O.OpsType = 4),0);

    IF  (DELETING AND vJobPrepped > 0) OR (UPDATING AND vJobPrepped >= n.Q) THEN
        SIGNAL 'Cannot DELETE nor set Allocated Qty to less than Subhired Prepped Qty (' || ToString(vJobPrepped) ||') for subhire linked record.';
    END IF;

 END IF;

 IF INSERTING THEN
    SET vIsComposite =  (SELECT RecTypeIsComposite(RecType)
                         FROM "Sort"
                         WHERE
                         LineRef = vEqLineRef);

    IF vIsComposite THEN

       INSERT INTO SubData
       (Subhline,EqlLine,Sublistno,Eqlno,Q)
       SELECT
       (SELECT S.LineRef
       FROM "Sort" S
       WHERE
       S.LineCode = n.Subhline
       AND
       S.Type = C.ComponentType),
       (SELECT S.LineRef
       FROM "Sort" S
        WHERE
        S.LineCode = vEqLineRef
        AND
        S.Type = C.ComponentType),
        n.Sublistno,
        n.Eqlno,
        n.Q * C.Quantity
        FROM Composit C
        WHERE
        C.MasterType = (SELECT S.Type
                       FROM "Sort" S
                       WHERE
                       S.LineRef = vEqLineRef);

    END IF; -- if composite

 END IF;

END;

