/* trTranplanBEFORE */
CREATE TRIGGER trTranplanBEFORE
BEFORE  INSERT,  DELETE , UPDATE ON Tranplan
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vUserID INT;
  DECLARE vAutoCost MONEY;

  SET vUserID = GetUserID();

  -- DATES
  IF n.startdate IS NULL THEN
         Set n.StartDate = GetJobStartDate(n.Job_number);
         SET n.EndDate =  n.startdate + INTERVAL '1' HOUR;
  END IF;

       -- legacy
  SET n."date" = CAST(n.startdate AS DATE);
      --  SET n.BeforeAfter = '@';
  SET n."Time" =  CAST(n.startdate AS TIME);


  IF NOT EQUIVALENT(n.startdate ,  o.startdate) THEN

    --   IF n.TripMode < 2 THEN
       --     SET n.EndDate =  n.startdate + INTERVAL '1' HOUR;
    --   END IF;

       IF n.startdate > n.Enddate THEN
           SET n.Enddate = CAST(CAST(n.Enddate AS DOUBLE PRECISION) +
           CAST(n.startdate AS DOUBLE PRECISION) - CAST(o.startdate AS DOUBLE PRECISION) AS TIMESTAMP);
       END IF ;

  END IF;  -- END n.startdate <>  o.startdate THEN

  IF n.EndDate IS NULL THEN
     SET n.EndDate =  n.startdate + INTERVAL '1' HOUR;
  END IF;


  IF NOT EQUIVALENT(n.EndDate, o.EndDate) THEN
     IF n.startdate > n.Enddate THEN
        SET n.startdate = CAST(CAST(n.startdate AS DOUBLE PRECISION) +
         CAST(n.Enddate AS DOUBLE PRECISION) - CAST(o.Enddate AS DOUBLE PRECISION) AS TIMESTAMP);
      END IF ;
  END IF;  -- END IF n.EndDate <>  o.EndDate THEN

  IF n.TripMode = 2  AND ((NOT EQUIVALENT(n.TripMode, o.TripMode)) OR (NOT EQUIVALENT(n.StartDate, o.StartDate)) OR (NOT EQUIVALENT(n.EndDate, o.EndDate))) THEN
      IF (n.Period IS NULL) OR  (n.Period = o.Period)  THEN  -- user hasn't modified field so autocalc
        SET n.Period = CAST(n.EndDate as integer) - CAST(n.startdate AS INT) + 1;
      END IF;
  END IF;

  IF (n.xStatus <> o.xstatus) AND (n.QtyAlloc > 0) AND (GetStatusFunction(n.xstatus) = 0) THEN
      SIGNAL 'Cannot demote to this status while vehicles allocated';
  END IF;


  IF NOT EQUIVALENT(n.TripMode, o.TripMode) AND n.TripMode < 2  THEN
     --     SET n.EndDate =  n.startdate + INTERVAL '1' HOUR;
          SET n.Period = 1 ;
  END IF;

  IF  n.Period = 0 THEN
      SET n.Period = 1;
  END IF;

     -- UNIT PRICES
  IF (n.TripMode = 2)-- its a period price
        AND (NOT EQUIVALENT(n.Vehicle_Type , o.Vehicle_Type) OR NOT EQUIVALENT(n.TripMode , o.TripMode))
        AND (n.PeriodUnitPrice = 0 OR EQUIVALENT(n.PeriodUnitPrice , o.PeriodUnitPrice)) THEN
             SET n.PeriodUnitPrice = COALESCE(GetTransportDailyRate(n.Job_number, n.Vehicle_Type),0);
  END IF;


  IF (n.DistanceChargeMode = 1) AND  (NOT EQUIVALENT(n.distance , o.distance) OR NOT EQUIVALENT(n.DistanceChargeMode , o.DistanceChargeMode))  THEN -- its a flat distance price
      SET n.DistanceUnitPrice = COALESCE(GetFlatTransportDistanceRate(n.Job_number, n.Vehicle_Type),0);
  END IF;

  IF  (NOT EQUIVALENT(n.distance , o.distance) OR NOT EQUIVALENT(n.DistanceChargeMode , o.DistanceChargeMode)) AND (n.DistanceChargeMode = 2) THEN -- its a banded distance price
      SET n.DistanceUnitPrice = COALESCE(GetBandedTransportDistanceRate(n.Job_number, n.Vehicle_Type, n.Distance),0);
  END IF;

     -- ACTUAL CHARGES

  SET n.Charge = COALESCE(( n.Qty * n.Period * n.PeriodUnitPrice ),0) + COALESCE(( n.Qty * n.distance * n.DistanceUnitPrice ),0) ;

  IF FunctionExists('CustomTransportDiscounting') THEN
     SET n.Charge = CustomTransportDiscounting(n.Job_number, n.TransportCounter,n.Charge, FALSE);
  END IF;

  IF n.Supplier IS NULL THEN
       SET vAutoCost =  COALESCE(( n.Qty * n.Period * GetDailyInternalCost(n.Job_number,n.Vehicle_Type) ),0) + COALESCE(( n.Qty * n.distance * GetDistanceInternalCost(n.Job_number,n.Vehicle_Type) ),0) ;
       IF vAutoCost > 0 THEN
         SET n.Cost = vAutoCost;
       END IF;
  END IF;


  -- DATABASE ACTIONS CODE
  IF INSERTING THEN

   -- users
    IF vUserID > -1 then
      SET n.createdby = vUserID;
     END IF;

    IF n.xTransportTask IS NULL THEN
      SET n.xStatus = (SELECT xStatus FROM TranplanHeader WHERE IDX = n.xHeader);
    END IF;


    IF n.CollectAddress IS NULL THEN
      SET n.CollectAddress = (SELECT TOP 1 Venue_no
                            FROM Eqlists
                            WHERE
                            Job_no = n.Job_Number
                            AND ListType = 0);
    END IF;

  ELSEIF UPDATING THEN
      -- user
    IF vUserID > -1 THEN
       SET n.modifiedby = vUserID;
       SET n.ModifiedDate = CURRENT_TIMESTAMP;
    END IF;

      --check if its invoiced
    IF n.Charge < 0 THEN
       IF n.Charge >  n.InvoicedTotal THEN
          SIGNAL 'This line has already been negatively invoiced for more than the new line price.';
       END IF;
    ELSE
        IF n.Charge <  n.InvoicedTotal THEN
           SIGNAL 'This line has already been invoiced for more than the new line price.';
        END IF;
    END IF;

    IF n.Qty <  n.QtyAlloc THEN
       SIGNAL 'Quantity booked cannot be reduced below Allocated Quantity.';
    END IF;

  ELSEIF DELETING THEN

     -- block deleting if invoiced
      IF (o.InvoicedTotal > 0) OR (o.Invoiced) THEN
        SIGNAL 'This line has been Invoiced and cannot be deleted.';
      END IF;

     -- block deleting if vehicles allocated
      IF o.Allocated = TRUE OR o.QtyAlloc > 0 THEN
       SIGNAL 'Tranport requests with allocated vehicles cannot be deleted. De-allocate first.';
      END IF;

     -- block deleting if PO raised against supplier
      IF o.Purchased > 0 THEN
       SIGNAL 'This line has been Ordered and cannot be deleted.';
      END IF;

     IF FunctionExists('CustomTransportDiscounting') THEN
      CustomTransportDiscounting(o.Job_number, o.TransportCounter,o.Charge, TRUE);
     END IF;

  END IF;

  -- DeliveryAddressType
  IF (INSERTING OR UPDATING) AND (NOT EQUIVALENT(o.CollectAddress, n.CollectAddress)) THEN
     IF n.CollectAddress IS NULL THEN
        SET n.DeliveryAddressType = NULL;
     ELSEIF COALESCE((SELECT DelAdd1 FROM Company WHERE CompanyCounter = n.CollectAddress),'') <> '' THEN
        SET n.DeliveryAddressType = 2;
     ELSE
        SET n.DeliveryAddressType = 0;
     END IF;


  END IF;

END;

/* trTranplanHeaderBEFORE */
CREATE TRIGGER trTranplanHeaderBEFORE
BEFORE  INSERT, UPDATE ON TranplanHeader
REFERENCING OLD AS o NEW AS n
BEGIN

DECLARE vUserID integer;

SET vUserID = GetUserID();

IF INSERTING THEN

  IF vUserID > -1 then
    SET n.createdby = vUserID;
  END IF;

  ELSEIF UPDATING THEN

  IF vUserID > -1 then
    SET n.modifiedby = vUserID;
  END IF;

  SET n.ModifiedDate = Current_Timestamp;

  IF NOT EQUIVALENT(n.xStatus, o.xStatus) THEN
    UPDATE Tranplan
    SET xStatus = n.xStatus
    WHERE  xHeader = n.IDX ;
  END IF;

       -- Finances table

   SELECT DISTINCT
   T.TransportCounter
   INTO #Tranplan
   FROM Tranplan T
   WHERE
   T.xheader = n.IDX;

   UPDATE JobFinances SET
   Title = n."Description"
   WHERE
   xCostCentreID IN (SELECT TransportCounter FROM #Tranplan)
   AND xGeneralCostCentre = 2;

 END IF;

END;

