/* trTransportTotalsAFTER */
CREATE TRIGGER trTransportTotalsAFTER
AFTER  INSERT, DELETE, UPDATE of LastQuotedTotal, Charge, Cost, xStatus,QuoteCount,  Supplier ON Tranplan
REFERENCING OLD AS o NEW AS n
BEGIN

 --TGeneralCostCentre  = (gccEquipment = 0, gccCrew = 1, gccTransport = 2, gccMisc = 3);
 --TInternalCostCentre = (iccNone = 0, iccPayment = 1, iccEqUsage = 2, iccPrep = 3, iccTransport = 4);

  DECLARE vLastQuotedDate Timestamp;

 -- QuoteDate
 IF NOT EQUIVALENT(o.QuoteCount , n.QuoteCount) THEN
   SET vLastQuotedDate = Current_TimeStamp;
 ELSE
   SET vLastQuotedDate = NULL;
 END IF;

  IF INSERTING AND n.Job_number IS NOT NULL THEN

   -- INCOME
--  IF n.Charge > 0 THEN
    insert into JobFinances
    (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus, LastQuotedDate, QuotedPrice, ActualPrice,Reference, Title)
    values
    (n.Job_number, True, n.TransportCounter, 2 , n.xStatus, vLastQuotedDate, n.LastQuotedTotal, n.Charge, GetTransportFunctionNameFromHeaderID(n.xHeader), GetTransportTitleFromHeaderID(n.xHeader));
--  END IF;

  -- EXPENDITURE
  IF /*(n.Cost > 0) and */(n.supplier is not null) THEN
    insert into JobFinances
    (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus, QuotedPrice,Reference, Title)
    values
    (n.Job_number, False, n.TransportCounter, 2 , n.xStatus, n.Cost, GetTransportFunctionNameFromHeaderID(n.xHeader), GetTransportTitleFromHeaderID(n.xHeader));

  END IF;

  -- INTERNAL COSTS
  IF (n.Cost > 0) and (n.supplier is null) THEN
    INSERT INTO Costs
    (xJob,     xCostCentreID,      xInternalCostCentre, isIncome, xStatus, Title, xSupplier, xPaymentType, AnticipatedPrice, ActualPrice, Selected)
    VALUES
    (n.Job_number, n.TransportCounter, 4,                   FALSE,    n.xStatus, GetTransportTitleFromHeaderID(n.xHeader), -1, 4, n.Cost , n.Cost, FALSE);
  END IF;

  ELSEIF (UPDATING) AND (n.Job_number IS NOT NULL) THEN -- not a TASK

    -- INCOME
    IF  COALESCE((SELECT COUNT(xCostCentreID) FROM  JobFinances WHERE xGeneralCostCentre = 2 and xCostCentreID = n.TransportCounter and IsIncome = TRUE),0) = 0 THEN

      INSERT into JobFinances
      (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus, LastQuotedDate, QuotedPrice, ActualPrice,Reference, Title)
       VALUES
      (n.Job_number, True, n.TransportCounter, 2 , n.xStatus, vLastQuotedDate, coalesce(n.LastQuotedTotal,0), n.Charge, GetTransportFunctionNameFromHeaderID(n.xHeader), GetTransportTitleFromHeaderID(n.xHeader));

    ELSE

      UPDATE JobFinances SET
      xStatus = n.xStatus,
      LastQuotedDate =
      CASE
      WHEN vLastQuotedDate IS NOT NULL THEN vLastQuotedDate
      ELSE
      LastQuotedDate
      END,
      QuotedPrice = COALESCE(n.LastQuotedTotal,0),
      ActualPrice = n.Charge
      WHERE
      xCostCentreID = n.TransportCounter
      and IsIncome = True
      and xGeneralCostCentre = 2;
      END IF;

    -- EXPENDITURE

    IF (o.supplier IS NOT NULL AND n.supplier is NULL)/* OR (n.Cost = 0) */THEN -- removing supplier or setting Cost to zero so no longer an external cost.
      DELETE FROM JobFinances
      WHERE xCostCentreID = n.TransportCounter
      AND xGeneralCostCentre = 2
      AND IsIncome = FALSE;
    END IF;

    IF (n.Cost > 0) and (n.supplier is not null)  THEN  -- external Cost
      IF COALESCE((SELECT COUNT(xCostCentreID) FROM  JobFinances WHERE xGeneralCostCentre = 2 and xCostCentreID = n.TransportCounter and IsIncome = False),0) = 0 THEN

      INSERT INTO JobFinances
      (xJob, IsIncome, xCostCentreID, xGeneralCostCentre, xStatus, QuotedPrice, Reference, Title)
      VALUES
      (n.Job_number, False, n.TransportCounter, 2 , n.xStatus, n.Cost, GetTransportFunctionNameFromHeaderID(n.xHeader), GetTransportTitleFromHeaderID(n.xHeader));

      ELSE

      UPDATE JobFinances SET
      xStatus = n.xStatus,
      LastQuotedDate =
      CASE
      WHEN vLastQuotedDate IS NOT NULL THEN vLastQuotedDate
      ELSE
      LastQuotedDate
      END,
      QuotedPrice = n.Cost
      WHERE
      xCostCentreID = n.TransportCounter
      AND IsIncome = False
      AND xGeneralCostCentre = 2;
      END IF;

    END IF;

  -- INTERNAL COSTS

    --add
  IF ((n.Cost > 0) AND (n.supplier IS NULL)) THEN
    IF COALESCE((SELECT COUNT(xCostCentreID) FROM  Costs WHERE xCostCentreID = n.TransportCounter),0) = 0 THEN

      INSERT INTO Costs
      (xJob,     xCostCentreID,      xInternalCostCentre, IsIncome, xStatus, AnticipatedPrice, ActualPrice, Title, xSupplier, xPaymentType, Selected)
      VALUES
      (n.Job_number, n.TransportCounter, 4,                   FALSE,    n.xStatus, n.Cost, n.Cost, GetTransportTitleFromHeaderID(n.xHeader), -1, 4, FALSE);

    ELSE

      UPDATE Costs SET
      xStatus = n.xStatus,
      AnticipatedPrice = n.Cost,
      ActualPrice = n.Cost
      WHERE
      xCostCentreID = n.TransportCounter
      AND xInternalCostCentre = 4;
    END IF;
  END IF;

   --remove if setting cost to 0 or assigning a supplier
  IF ((n.Cost = 0) AND (n.supplier IS NULL)) OR (n.supplier IS NOT NULL) THEN

    DELETE FROM Costs
    WHERE
     xCostCentreID = n.TransportCounter
     AND xInternalCostCentre = 4;

  END IF;

   --JOBS UPDATE
    IF o.QuoteCount <> n.QuoteCount then
      UPDATE Jobs SET LastQuotedTransport = (SELECT SUM(LastQuotedTotal) FROM Tranplan where Job_number = n.Job_number and Selected = True) WHERE Jobno = n.Job_number ;
    END IF;


  ELSEIF DELETING AND o.Job_number IS NOT NULL THEN

    DELETE FROM JobFinances
    WHERE
     xCostCentreID = o.TransportCounter
     AND xGeneralCostCentre = 2;

    DELETE FROM Costs
    WHERE
     xCostCentreID = o.TransportCounter
     AND xInternalCostCentre = 4;

    UPDATE Jobs SET LastQuotedTransport = (SELECT SUM(LastQuotedTotal) FROM Tranplan
                                            WHERE
                                             Job_number = o.Job_number
                                             AND Selected = TRUE)
     WHERE Jobno = o.Job_number ;

  END IF;

END;

