/* trUpdatesAFTER */
CREATE TRIGGER trUpdatesAFTER
AFTER INSERT, UPDATE ON Updates
REFERENCING OLD AS o NEW AS n
BEGIN

IF n.UpdateVersion_No THEN
	UPDATE hiretrack_version H
	SET H.Version_No = (
			SELECT MAX(VerID)
			FROM (
				SELECT MAX(DBVersion) AS VerID
				FROM Updates

				UNION ALL

				SELECT MAX(Version_No) AS VerID
				FROM hiretrack_version
				)
			);
	END IF ;


END;

/* trUsersBEFORE */
CREATE TRIGGER trUsersBEFORE
BEFORE INSERT, UPDATE ON Users
REFERENCING OLD AS o NEW AS n
BEGIN
 SET n.UserSites = BITOR(COALESCE(n.UserSites,n.DefaultSite),CAST(POWER(2,n.DefaultSite - 1) + 0.5 AS BIGINT));

 SET n.OneTimeLogin = NEWGUID;

 IF UPDATING AND (o.RestrictionType > n.RestrictionType) THEN  -- removing a restrictiontype

    DECLARE vMaxUserRestrictionType INT DEFAULT 1 ; -- TUserRestrictionType = (urtNone, urtJobs)
    DECLARE vPowerUserRestrictionType INT;
    DECLARE vCounter TINYINT DEFAULT 0;

    WHILE vCounter <= vMaxUserRestrictionType DO

          SET  vPowerUserRestrictionType = CAST(POWER(2,vCounter) + 0.5 AS INT);

          IF BITAND(n.RestrictionType ,vPowerUserRestrictionType ) <> vPowerUserRestrictionType THEN
             IF vPowerUserRestrictionType = 1 THEN -- urtJobs has been REMOVED from user restrictions

                DELETE FROM RestrictedUserAccess
                WHERE
                xUserID = n.UID;

             END IF;
          END IF;

          SET vCounter = vCounter + 1;

    END WHILE;

 END IF;

  IF UPDATING AND (n.RestrictionType > o.RestrictionType) THEN  -- adding a restrictiontype

    DECLARE vMaxUserRestrictionType INT DEFAULT 1 ; -- TUserRestrictionType = (urtNone, urtJobs)
    DECLARE vPowerUserRestrictionType INT;
    DECLARE vCounter TINYINT DEFAULT 0;

    WHILE vCounter <= vMaxUserRestrictionType DO

          SET  vPowerUserRestrictionType = CAST(POWER(2,vCounter) + 0.5 AS INT);

          IF BITAND(n.RestrictionType ,vPowerUserRestrictionType ) = vPowerUserRestrictionType THEN
             IF vPowerUserRestrictionType = 1 THEN -- urtJobs has been added to user restrictions

                DELETE FROM UserJobs
                WHERE
                xUser = n.UID
                AND xMyWork = 0;  --TMyWork = (mwJobs, mwProjects, mwCRM);

             END IF;
          END IF;

          SET vCounter = vCounter + 1;

    END WHILE;

 END IF;

END;

