/* trWarehousesAFTER */
CREATE TRIGGER trWarehousesAFTER
  AFTER INSERT
  ON Warehouses REFERENCING NEW AS n OLD AS o
BEGIN

IF  n.idx > 0 THEN

 // deal with warehouse transit times
 INSERT into WarehouseTransitTimes
 (WarehouseFrom, WarehouseTo)
 SELECT idx,  n.idx
 FROM Warehouses
 WHERE
 Virtual = FALSE
 AND idx <>  n.idx
 UNION
 SELECT n.idx,  idx
 FROM Warehouses
 WHERE
 Virtual = FALSE
 AND n.idx <>  idx;

END IF;

END;

/* trWarehousesBEFORE */
CREATE TRIGGER trWarehousesBEFORE
  BEFORE INSERT, DELETE, UPDATE OF IsDefault
  ON Warehouses REFERENCING NEW AS n OLD AS o
BEGIN

 DECLARE oldxDefaultRec INTEGER;
 DECLARE maxVirtualSite INTEGER;

 Set oldxDefaultRec = 0;

 IF INSERTING THEN
  IF n.virtual = false then
   SET n.idx =  coalesce((select max(W.idx) from warehouses W),0) + 1 ;
   SET n.WhlevelColumn = (select coalesce(max(W.WhlevelColumn), 0) from warehouses W where xSite = n.xSite and virtual = false ) + 1 ;
   SET n.DefaultDonorWH = (select top 1 W.idx from warehouses W where  xSite = n.xSite and virtual = false);

   IF n.WhlevelColumn = 64 THEN
     Signal 'Maximum number of warehouses per site is 63';
   END IF;

  ELSE
   SET  maxVirtualSite =  (select min(W.idx) from warehouses W) - 1;

   IF  maxVirtualSite = 0 THEN
     SET  maxVirtualSite = -1;
   END IF;

   SET n.idx = maxVirtualSite;
  END IF;


 ELSEIF UPDATING THEN

// clear old Default if setting new one
  IF n.IsDefault = true THEN
   // get the the last Default Warehouse record
   SET oldxDefaultRec = (SELECT IDX from warehouses W WHERE W.xSite = o.xSite AND W.IsDefault = True) ;
   IF oldxDefaultRec > 0  THEN
      UPDATE warehouses W2 SET W2.IsDefault = false WHERE W2.idx = oldxDefaultRec;
   END IF;
  END IF;

 ELSEIF DELETING THEN

  IF n.IsDefault = False THEN
   SIGNAL 'Re-assign DEFAULT fields before deleting';
  END IF;

 END IF;
END;

