/* trWhAuditAFTER */
CREATE TRIGGER trWhAuditAFTER
AFTER INSERT, DELETE, UPDATE ON WhAudit
REFERENCING OLD AS o NEW AS n
--WHEN (EQUIVALENT(o.keepAuditType, n.keepAuditType))
BEGIN

DECLARE vSuspendTriggers BOOL;
DECLARE vTot INT;
DECLARE vLineRef INT;

SET vSuspendTriggers = (SELECT OPTION('TriggerSuspend') = 'True' FROM #DUMMY);

IF (NOT vSuspendTriggers) THEN

  IF INSERTING OR UPDATING THEN
     -- WHLevel

     IF INSERTING THEN
      CALL SyncStockLevelForType( n.xType ,n.xWarehouse);
     END IF;

     IF UPDATING AND (((NOT EQUIVALENT(n.xWarehouse,o.xWarehouse)) OR (NOT EQUIVALENT(n.xType,o.xType)) OR (NOT EQUIVALENT(n.Quantity,o.Quantity)))) THEN
        CALL SyncStockLevelForType( o.xType ,o.xWarehouse);
        CALL SyncStockLevelForType( n.xType ,n.xWarehouse);
     END IF;

	    -- Sort.CheckedIN for ops transfers
    IF (n.xOperationDetail IS NOT NULL) AND (COALESCE(o.Quantity,0) <=0 AND n.Quantity <=0) AND (n.KeepAuditType IN (1,3,6,7))   THEN
                          --katItemKeepLoan, katTypeKeepLoan, katItemKeepHire, katTypeKeepHire)

      SET vLineRef = (SELECT xEqlistLine FROM OperationsDetail WHERE IDX = n.xOperationDetail);

      SET vTot = COALESCE(o.Quantity,0) -  n.Quantity;

      UPDATE "SORT" S SET
      S.CheckedInQty = S.CheckedInQty + vTot
      WHERE
      S.LineRef = vLineRef;

      IF (SELECT Virt FROM Sort WHERE LineRef = vLineRef) THEN
         DECLARE vCompTot INT;
         DECLARE vLineCode INT;

         SET vLineCode = (SELECT LineCode FROM Sort WHERE LineRef = vLineRef);

         SET vCompTot = HowManyCompositesCanBeMadeFromWarehouseStage(vLineCode,6);

         UPDATE "SORT" S SET
         S.Back = vCompTot
         WHERE
         S.LineRef = vLineCode;

         SET vCompTot = HowManyCompositesCanBeMadeFromWarehouseStage(vLineCode,7);

         UPDATE "SORT" S SET
         S.CheckedInQty = vCompTot
         WHERE
         S.LineRef = vLineCode;

      END IF;

     END IF;


  ELSEIF DELETING THEN
      -- WHLevel

     CALL SyncStockLevelForType( O.xType ,O.xWarehouse);

  END IF;

 END IF;
END;

