/* trWhlevel */
CREATE TRIGGER trWhlevel
BEFORE UPDATE
ON Whlevel
REFERENCING OLD AS o NEW AS n
BEGIN


 // can't specify UPDATE OF...list beause too many fields for nexus $Triggers table column : TRIGGER_FOR_UPDATE_OF_COLUMN_LIST
 // so stop recursion with this IF...
 IF (o.SiteStockLevel = n.SiteStockLevel) THEN

 set n.SiteStockLevel =
 n.LOC1+n.LOC2+n.LOC3+n.LOC4+n.LOC5+n.LOC6+n.LOC7+n.LOC8+n.LOC9+n.LOC10+n.LOC11+n.LOC12+n.LOC13+n.LOC14+n.LOC15+n.LOC16+n.LOC17+n.LOC18+n.LOC19
 +n.LOC20+n.LOC21+n.LOC22+n.LOC23+n.LOC24+n.LOC25+n.LOC26+n.LOC27+n.LOC28+n.LOC29+n.LOC30+n.LOC31+n.LOC32+n.LOC33+n.LOC34+n.LOC35+n.LOC36+n.LOC37
 +n.LOC38+n.LOC39+n.LOC40+n.LOC41+n.LOC42+n.LOC43+n.LOC44+n.LOC45+n.LOC46+n.LOC47+n.LOC48+n.LOC49+n.LOC50+n.LOC51+n.LOC52+n.LOC53+n.LOC54+n.LOC55
 +n.LOC56+n.LOC57+n.LOC58+n.LOC59+n.LOC60+n.LOC61+n.LOC62+n.LOC63;

