/* trWhlevel_LOG */
CREATE TRIGGER  trWhlevel_LOG
AFTER INSERT, DELETE, UPDATE ON Whlevel
REFERENCING OLD AS o NEW AS n
BEGIN

  DECLARE vIDX INTEGER;

  IF INSERTING THEN
   INSERT INTO Lookups_LOG
    (TableName, MasterID, ActionID)
   VALUES
   ('Whlevel', n."IDX", 0);

  ELSEIF UPDATING THEN

   SET vIDX = LookupsLog_RecordExists('Whlevel', o."IDX", 1) ;

   IF vIDX > -1 THEN
     UPDATE Lookups_LOG
      SET EditDate = CURRENT_TIMESTAMP
     WHERE IDX = vIDX;
   ELSE
     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('Whlevel',n."IDX", 1);
   END IF;  -- vIDX

  ELSEIF DELETING THEN

     INSERT INTO Lookups_LOG
      (TableName, MasterID, ActionID)
      VALUES
      ('Whlevel',o."IDX", 2);

  END IF; -- DELETING
END;

/* trWorkFlowInstancesBEFORE */
CREATE TRIGGER trWorkFlowInstancesBEFORE
BEFORE INSERT, UPDATE ON WorkFlowInstances
REFERENCING OLD AS o NEW AS n
BEGIN
    DECLARE vUserID INT;
    SET vUserID = GetUserID();

    IF vUserID > -1 THEN
       SET n.xRunBy = vUserID;
    END IF;

    SET n.RunDate = CURRENT_TIMESTAMP;

     IF INSERTING THEN

        UPDATE WorkFlowTemplates SET Status = 3 --wftsPublishedUsed
        WHERE
        IDX = n.xWorkflowTemplate
        AND
        Status = 2; -- wftsPublishedUnused

     END IF;

END;

/* trWorkFlowsBEFORE */
CREATE TRIGGER trWorkFlowsBEFORE
BEFORE INSERT, UPDATE ON WorkFlows
REFERENCING OLD AS o NEW AS n
BEGIN
    DECLARE vUserID INT;
    SET vUserID = GetUserID();

    IF vUserID > -1 THEN
       SET n.xCreatedBy = vUserID;
    END IF;
END;

/* trWorkFlowTemplatesAFTER */
CREATE TRIGGER trWorkFlowTemplatesAFTER
AFTER INSERT, DELETE ON WorkFlowTemplates
REFERENCING OLD AS o NEW AS n
BEGIN

     UPDATE Workflows SET
     Version = (SELECT COUNT(*) FROM WorkFlowTemplates WHERE xWorkflow = COALESCE(o.xWorkflow, n.xWorkflow))
     WHERE
     IDX =  COALESCE(o.xWorkflow, n.xWorkflow);

END;

/* trWorkFlowTemplatesBEFORE */
CREATE TRIGGER trWorkFlowTemplatesBEFORE
BEFORE INSERT, DELETE, UPDATE ON WorkFlowTemplates
REFERENCING OLD AS o NEW AS n
BEGIN

     IF NOT DELETING THEN
        DECLARE vUserID INT;
        SET vUserID = GetUserID();

        IF vUserID > -1 THEN
           SET n.xModifiedBy = vUserID;
           END IF;

        SET n.ModifiedDate = CURRENT_TIMESTAMP;

        ELSE
        IF o.Status >= 3 THEN  -- TWorkFlowTemplateStatus = (wftsDesigningValidated, wftsDesigningNotValidated, wftsPublishedUnused, wftsPublishedUsed, wftsSuperceded)
           SIGNAL 'Workflows that have been used cannot be deleted';
        END IF;

     END IF;

     IF INSERTING THEN

        UPDATE WorkFlowTemplates SET Status = 4 --wftsSuperceded
        WHERE
        xWorkflow = n.xWorkflow
        AND
        Status = 3; -- wftsPublishedUsed

     END IF;

END;
